/* Source transcription from uploaded JVVNL-JA-IncomeTax-QuestionBank-437Q PDF. Original wording/keys preserved except audit flags are metadata only. */
window.INCOME_TAX_DEEP_BANK = [{"id":1,"stem":"For income-tax purposes in India, the financial year in which income is EARNED is called the:","options":[{"key":"A","text":"Previous year"},{"key":"B","text":"Accounting year"},{"key":"C","text":"Tax deduction year"},{"key":"D","text":"Assessment year"}],"answer":"A","explanation":"Income is earned in the previous year and assessed to tax in the immediately following assessment year. Residential status is also tested with reference to the previous year.","source":"Source label not detected","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":2,"stem":"The assessment year is the period of 12 months:","options":[{"key":"A","text":"Beginning on 1 January and ending on 31 December of the same year"},{"key":"B","text":"In which the income is actually earned by the assessee - that is, the previous year itself, and not the year of assessment"},{"key":"C","text":"Immediately FOLLOWING the previous year, in which the income of the previous year is assessed and taxed"},{"key":"D","text":"Ending on 31 March of the same year in which the income is earned"}],"answer":"C","explanation":"AY 2026-27 (1-4-2026 to 31-3-2027) assesses the income of the previous year 2025-26 (1-4-2025 to 31-3-2026).","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The assessment year is the period of 12 months:","options":["Starting from 1 January","In which income is earned","Immediately FOLLOWING the previous year, in which the income of the previous year is assessed and taxed","Ending on 31 March of the earning year"],"answer":2,"explanation":"AY 2026-27 (1-4-2026 to 31-3-2027) assesses the income of the previous year 2025-26 (1-4-2025 to 31-3-2026).","revision":"original","contentSignature":"f0aa7902f504a5851e3f78d172f7997b29aa34f45b3a1abe41d9bc23b55d5dcb"}]},{"id":3,"stem":"A \"person\" under Section 2(31) of the Income-tax Act, 1961 includes all EXCEPT:","options":[{"key":"A","text":"A DECEASED person estate after probate is complete"},{"key":"B","text":"An individual and a Hindu Undivided Family"},{"key":"C","text":"A local authority and every artificial juridical person"},{"key":"D","text":"A company, a firm and an association of persons"}],"answer":"A","explanation":"Section 2(31) lists seven categories: individual, HUF, company, firm, AOP/BOI, local authority and every artificial juridical person. An estate is taxed through the legal representative/executor, not as a separate \"person\" category.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":4,"stem":"\"Assessee\" under Section 2(7) means a person:","options":[{"key":"A","text":"By whom any tax or any other sum of money is payable under the Act - and includes every person in respect of whom any proceeding has been taken"},{"key":"B","text":"Only salaried individuals who draw income above the basic exemption limit in the previous year, and no other category of person at all"},{"key":"C","text":"Only a person whose total income exceeds the maximum amount not chargeable to tax in the relevant previous year, and no one else at all"},{"key":"D","text":"Only a person who has filed his return of income for the relevant assessment year within the time allowed under Section 139(1) of the Act"}],"answer":"A","explanation":"Every assessee is a person, but every person is not an assessee - a person becomes an assessee only when a liability or a proceeding under the Act attaches to him.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"\"Assessee\" under Section 2(7) means a person:","options":["By whom any tax or any other sum of money is payable under the Act - and includes every person in respect of whom any proceeding has been taken","Only salaried individuals","Only a person whose income exceeds the exemption limit","Who has filed his return"],"answer":0,"explanation":"Every assessee is a person, but every person is not an assessee - a person becomes an assessee only when a liability or a proceeding under the Act attaches to him.","revision":"original","contentSignature":"e8b30c0454ae549768560f84124396dc4bead70f4bb02c5c91dc49e2a18c0b62"}]},{"id":5,"stem":"\"Income\" under Section 2(24) is:","options":[{"key":"A","text":"An INCLUSIVE definition - covering profits and gains, dividends, perquisites, capital gains, winnings and the other listed receipts"},{"key":"B","text":"Only income earned or received within the territory of India during the previous year, and nothing earned or arising outside India at all"},{"key":"C","text":"Limited to receipts of a revenue nature only, excluding every receipt of a capital nature, however regularly it may be received"},{"key":"D","text":"Only money actually received in cash during the year, excluding every receipt in kind, by cheque, or by book adjustment at all"}],"answer":"A","explanation":"Section 2(24) begins \"income includes\" - an inclusive (not exhaustive) definition covering both cash and kind, legal and illegal, recurring and one-time receipts.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"\"Income\" under Section 2(24) is:","options":["An INCLUSIVE definition - covering profits and gains, dividends, perquisites, capital gains, winnings and the other listed receipts","Only income earned in India","Limited to revenue receipts","Only money received in cash"],"answer":0,"explanation":"Section 2(24) begins \"income includes\" - an inclusive (not exhaustive) definition covering both cash and kind, legal and illegal, recurring and one-time receipts.","revision":"original","contentSignature":"94b8600705945ef9b94baba84f01ba3dc41bbd441fa28da7f0d6ed2cef5de31b"}]},{"id":6,"stem":"Income earned in previous year 2025-26 is taxable in assessment year:","options":[{"key":"A","text":"2025-26"},{"key":"B","text":"2027-28"},{"key":"C","text":"2026-27"},{"key":"D","text":"2024-25"}],"answer":"C","explanation":"AY = PY + 1. Income of PY 2025-26 is assessed in AY 2026-27.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":7,"stem":"The rates of income tax for an assessment year are fixed by:","options":[{"key":"A","text":"The circulars issued by the CBDT each year"},{"key":"B","text":"The Income-tax Act, 1961 itself, without more"},{"key":"C","text":"The annual FINANCE ACT passed by Parliament"},{"key":"D","text":"The President of India, by an annual order"}],"answer":"C","explanation":"The Finance Act of the year prescribes the rates; the Income-tax Act lays down the machinery for levy, computation and collection.","source":"Source label not detected","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The rates of income tax for an assessment year are fixed by:","options":["The CBDT circulars","The Income-tax Act, 1961 itself","The annual FINANCE ACT passed by Parliament","The President of India"],"answer":2,"explanation":"The Finance Act of the year prescribes the rates; the Income-tax Act lays down the machinery for levy, computation and collection.","revision":"original","contentSignature":"ba3926031f9d576b7a8e389d1ca83089c15bc11ee713e9373a301ab3087cfa01"}]},{"id":8,"stem":"The Central Board of Direct Taxes (CBDT) functions under the:","options":[{"key":"A","text":"Ministry of Finance (Department of Revenue)"},{"key":"B","text":"The Reserve Bank of India, as a wing of it"},{"key":"C","text":"The Ministry of Corporate Affairs, Government of India"},{"key":"D","text":"NITI Aayog, the national policy think tank"}],"answer":"A","explanation":"The CBDT administers direct taxes under the Department of Revenue, Ministry of Finance, and issues rules, notifications and circulars.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The Central Board of Direct Taxes (CBDT) functions under the:","options":["Ministry of Finance (Department of Revenue)","Reserve Bank of India","Ministry of Corporate Affairs","NITI Aayog"],"answer":0,"explanation":"The CBDT administers direct taxes under the Department of Revenue, Ministry of Finance, and issues rules, notifications and circulars.","revision":"original","contentSignature":"d8411497c5479721ddbb3b7cb52f563e8a02485a4ec44a728b3a457bd01047fb"}]},{"id":9,"stem":"Which of the following is NOT a source for understanding income-tax law and procedure?","options":[{"key":"A","text":"The Income-tax Act, 1961 and Income-tax Rules, 1962"},{"key":"B","text":"Judicial decisions of courts"},{"key":"C","text":"SEBI listing regulations"},{"key":"D","text":"Notifications and circulars of the CBDT"}],"answer":"C","explanation":"Tax law rests on the Act, the Rules, CBDT subordinate legislation and case law; SEBI regulations govern securities markets, not income tax.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":10,"stem":"Gross total income means:","options":[{"key":"A","text":"The income that is exempt under Section 10 of the Income-tax Act, 1961, only"},{"key":"B","text":"Only the salary income of the assessee for the previous year, and no other head"},{"key":"C","text":"Income remaining after all the Chapter VI-A deductions are given effect to"},{"key":"D","text":"The aggregate of income computed under the FIVE heads, BEFORE Chapter VI-A deductions"}],"answer":"D","explanation":"Section 80B(5): gross total income = total income computed under the five heads after clubbing and set-off, before deductions under Chapter VI-A (80C to 80U).","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Gross total income means:","options":["Income exempt under Section 10","Only salary income","Income after all Chapter VI-A deductions","The aggregate of income computed under the FIVE heads, BEFORE Chapter VI-A deductions"],"answer":3,"explanation":"Section 80B(5): gross total income = total income computed under the five heads after clubbing and set-off, before deductions under Chapter VI-A (80C to 80U).","revision":"original","contentSignature":"bb8a87e654c1d74cb2af34856bde8ac01784e625f84dc3bb62967e0cd0ea1e90"}]},{"id":11,"stem":"The five heads of income under Section 14 do NOT include:","options":[{"key":"A","text":"Income from salaries"},{"key":"B","text":"Income from house property"},{"key":"C","text":"Income from LOTTERY and speculation as a separate head"},{"key":"D","text":"Profits and gains of business or profession"}],"answer":"C","explanation":"The five heads are: salaries, house property, business/profession, capital gains, and other sources. Lottery winnings fall under income from other sources - they are not a separate head.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":12,"stem":"Total income is arrived at by:","options":[{"key":"A","text":"Adding all the receipts of the year, whether of revenue or of capital nature, and whether taxable or not"},{"key":"B","text":"Multiplying the gross income by the applicable slab rate of tax for that assessment year"},{"key":"C","text":"Deducting Chapter VI-A deductions (80C-80U) from gross total income and rounding off under s.288A"},{"key":"D","text":"Deducting the tax deducted at source from the gross total income of the relevant previous year"}],"answer":"C","explanation":"GTI minus VI-A deductions = total income, rounded off to the nearest ten rupees (s.288A); tax is then computed on it.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Total income is arrived at by:","options":["Adding all receipts of the year","Multiplying gross income by the slab rate","Deducting Chapter VI-A deductions (80C-80U) from gross total income and rounding off under s.288A","Deducting TDS from gross total income"],"answer":2,"explanation":"GTI minus VI-A deductions = total income, rounded off to the nearest ten rupees (s.288A); tax is then computed on it.","revision":"original","contentSignature":"9bbe147bcc91be17a6185d01eccd0fb6a181d7b152d6c9a0cb7ba328e1f37542"}]},{"id":13,"stem":"Agricultural income in India is:","options":[{"key":"A","text":"EXEMPT under Section 10(1), but used for rate purposes (partial integration) for non-corporate assessees"},{"key":"B","text":"Taxable as business income under the head profits and gains of business or profession, like any other business"},{"key":"C","text":"Fully taxable at the flat rate of 30% for every assessee in India, without any exemption whatsoever"},{"key":"D","text":"Exempt only in the hands of companies, and fully taxable for every other assessee"}],"answer":"A","explanation":"Agricultural income is exempt, but where it exceeds Rs.5,000 it is added to non-agricultural income to fix the slab RATE on the non-agricultural income (partial integration).","source":"Source label not detected","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Agricultural income in India is:","options":["EXEMPT under Section 10(1), but used for rate purposes (partial integration) for non-corporate assessees","Taxable as business income","Fully taxable at 30%","Exempt only for companies"],"answer":0,"explanation":"Agricultural income is exempt, but where it exceeds Rs.5,000 it is added to non-agricultural income to fix the slab RATE on the non-agricultural income (partial integration).","revision":"original","contentSignature":"c1a6f3620c7a4ab23a148794f6e3bc13fa17cc0024b1680f9f1112c0d7d66510"}]},{"id":14,"stem":"Which of the following is AGRICULTURAL income?","options":[{"key":"A","text":"Rent or revenue derived from land situated in India and used for agricultural purposes"},{"key":"B","text":"Income from a dairy farm as such, without any agricultural operations on land"},{"key":"C","text":"Salary received by a farm manager for managing the agricultural operations of the farm"},{"key":"D","text":"Income from selling wild grass of spontaneous growth without any cultivation at all"}],"answer":"A","explanation":"Section 2(1A): rent/revenue from agricultural land, income from agricultural operations, and income from farm buildings are agricultural. Dairy/poultry income and spontaneous growth are not.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which of the following is AGRICULTURAL income?","options":["Rent or revenue derived from land situated in India and used for agricultural purposes","Income from a dairy farm as such","Salary received by a farm manager","Income from selling wild grass of spontaneous growth without cultivation"],"answer":0,"explanation":"Section 2(1A): rent/revenue from agricultural land, income from agricultural operations, and income from farm buildings are agricultural. Dairy/poultry income and spontaneous growth are not.","revision":"original","contentSignature":"a863720238f9bf785cac0fa5baa394ee6be90af91f3e6c1c96d17bade3e134dd"}]},{"id":15,"stem":"Income from growing and manufacturing TEA in India is split between agricultural and business income in the ratio:","options":[{"key":"A","text":"60% agricultural : 40% business"},{"key":"B","text":"40% agricultural : 60% business"},{"key":"C","text":"75% agricultural : 25% business"},{"key":"D","text":"50% : 50%"}],"answer":"A","explanation":"Rule 8 of the Income-tax Rules: 60% of tea-growing-cum-manufacturing income is agricultural and 40% is business income taxable under the Act.","source":"Source label not detected","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":16,"stem":"Coffee grown and cured by the assessee in India is split as (agricultural : business):","options":[{"key":"A","text":"50% : 50%"},{"key":"B","text":"60% : 40%"},{"key":"C","text":"65% : 35%"},{"key":"D","text":"75% : 25%"}],"answer":"D","explanation":"Rule 7B: coffee grown and cured = 75% agricultural, 25% business; coffee also roasted and ground = 60% agricultural, 40% business.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":17,"stem":"Rubber grown and manufactured by the assessee in India is treated as business income to the extent of:","options":[{"key":"A","text":"40%"},{"key":"B","text":"25%"},{"key":"C","text":"35%"},{"key":"D","text":"60%"}],"answer":"C","explanation":"Rule 7A: 35% of rubber income is business income and 65% is agricultural income.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":18,"stem":"Residential status of an assessee is determined with reference to the:","options":[{"key":"A","text":"Assessment year"},{"key":"B","text":"PREVIOUS YEAR (the year of earning)"},{"key":"C","text":"Calendar year"},{"key":"D","text":"Year of assessment completion"}],"answer":"B","explanation":"Section 6 applies the stay tests for each previous year separately; status can change from year to year.","source":"Source label not detected","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":19,"stem":"An individual is RESIDENT in India in a previous year if he is in India for:","options":[{"key":"A","text":"At least 365 days in that previous year alone, without any alternative condition based on earlier years at all"},{"key":"B","text":"Exactly 90 days during that year, neither more nor less than that, with no alternative condition at all"},{"key":"C","text":"At least 182 days during that year, OR 60 days in that year plus 365 days in the 4 preceding years"},{"key":"D","text":"At least 30 days during that year, whether continuous or in parts, with no alternative condition at all"}],"answer":"C","explanation":"Section 6(1) has the two alternative tests: 182 days, or 60 days + 365 days in four preceding years (60 becomes 182 for citizens leaving for employment/crew and certain visitors).","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"An individual is RESIDENT in India in a previous year if he is in India for:","options":["365 days in the previous year only","Exactly 90 days","At least 182 days during that year, OR 60 days in that year plus 365 days in the 4 preceding years","At least 30 days"],"answer":2,"explanation":"Section 6(1) has the two alternative tests: 182 days, or 60 days + 365 days in four preceding years (60 becomes 182 for citizens leaving for employment/crew and certain visitors).","revision":"original","contentSignature":"42f32527a9b51067b2be6755e0b1019d4fa05317f8c0387b158896f4029746b6"}]},{"id":20,"stem":"The \"60 days\" in the second residential test is extended to 182 days for:","options":[{"key":"A","text":"All foreign tourists visiting India for any purpose whatsoever during the previous year, whether for recreation, business or employment, and irrespective of their stay in the earlier years"},{"key":"B","text":"All companies incorporated outside India"},{"key":"C","text":"No one - the 60-day rule applies uniformly"},{"key":"D","text":"Indian citizens who leave India for employment abroad or as crew of an Indian ship, and Indian citizens/PIOs visiting India (subject to the 120-day rule for high-income visitors)"}],"answer":"D","explanation":"Explanation 1 to s.6(1) relaxes the 60-day condition to 182 days for these categories; for citizens/PIOs with Indian income above Rs.15 lakh, the 60 days becomes 120 days (from AY 2021-22).","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The \"60 days\" in the second residential test is extended to 182 days for:","options":["All foreign tourists","All companies","No one","Indian citizens who leave India for employment abroad or as crew of an Indian ship, and Indian citizens/PIOs visiting India (subject to the 120-day rule for high-income visitors)"],"answer":3,"explanation":"Explanation 1 to s.6(1) relaxes the 60-day condition to 182 days for these categories; for citizens/PIOs with Indian income above Rs.15 lakh, the 60 days becomes 120 days (from AY 2021-22).","revision":"original","contentSignature":"770981bb92ba35b9acb78588bbb019700adbd6eff4edb36166c254fe5c21c553"}]},{"id":21,"stem":"An Indian citizen having total income (other than foreign sources) exceeding Rs.15 lakh, who is NOT liable to tax in any other country by reason of domicile or residence, is:","options":[{"key":"A","text":"Always non-resident, whatever the period of his stay in India may be"},{"key":"B","text":"DEEMED to be RESIDENT in India under Section 6(1A) - and taxed as RNOR"},{"key":"C","text":"Exempt from Indian tax on all of his income, Indian and foreign alike"},{"key":"D","text":"A person of Indian origin, and hence always a resident and ordinary resident"}],"answer":"B","explanation":"Section 6(1A) (from AY 2021-22) targets stateless-income individuals; such deemed residents are treated as not ordinarily resident.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"An Indian citizen having total income (other than foreign sources) exceeding Rs.15 lakh, who is NOT liable to tax in any other country by reason of domicile or residence, is:","options":["Always non-resident","DEEMED to be RESIDENT in India under Section 6(1A) - and taxed as RNOR","Exempt from Indian tax","A person of Indian origin"],"answer":1,"explanation":"Section 6(1A) (from AY 2021-22) targets stateless-income individuals; such deemed residents are treated as not ordinarily resident.","revision":"original","contentSignature":"58d6afed2614625e541ae79ada15c20a0915339683170ebc936fbc1fe4e61a7f"}]},{"id":22,"stem":"A resident individual is \"not ordinarily resident\" (RNOR) if he:","options":[{"key":"A","text":"Is above 60 years of age at any time during the relevant previous year, whatever the period of his stay in India in earlier years"},{"key":"B","text":"Owns no property of any kind in India during the relevant previous year, whatever the period of his stay in India in earlier years"},{"key":"C","text":"Is a non-resident in 9 out of the 10 preceding years OR has been in India for 729 days or less during the 7 preceding years"},{"key":"D","text":"Has never been outside India at any time in his life before the relevant previous year, whatever the period of his stays abroad thereafter"}],"answer":"C","explanation":"Section 6(6): either of the two conditions makes a resident \"not ordinarily resident\"; deemed residents under s.6(1A) are always RNOR.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A resident individual is \"not ordinarily resident\" (RNOR) if he:","options":["Is above 60 years of age","Owns no property in India","Is a non-resident in 9 out of the 10 preceding years OR has been in India for 729 days or less during the 7 preceding years","Has never been outside India"],"answer":2,"explanation":"Section 6(6): either of the two conditions makes a resident \"not ordinarily resident\"; deemed residents under s.6(1A) are always RNOR.","revision":"original","contentSignature":"0dccd43de18a074ffd51890347d873c55d025ee367bef7b1b02bb97c0d8c9cb8"}]},{"id":23,"stem":"A Hindu Undivided Family (HUF) is resident in India unless:","options":[{"key":"A","text":"It owns any property of any kind outside India during the relevant previous year"},{"key":"B","text":"Its karta is a citizen of a foreign country at any time during the relevant previous year"},{"key":"C","text":"The control and management of its affairs is situated WHOLLY OUTSIDE India during the year"},{"key":"D","text":"It earns any income from a source outside India during the relevant previous year"}],"answer":"C","explanation":"For HUF, firm, AOP and companies (turnover test aside), the control-and-management test applies: wholly outside India means non-resident.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Review note: company residency test is POEM, not control-and-management.","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A Hindu Undivided Family (HUF) is resident in India unless:","options":["It owns property abroad","Its karta is a foreign citizen","The control and management of its affairs is situated WHOLLY OUTSIDE India during the year","It has foreign income"],"answer":2,"explanation":"For HUF, firm, AOP and companies (turnover test aside), the control-and-management test applies: wholly outside India means non-resident.","revision":"original","contentSignature":"6478554ec1c7238effca3121a69dd19cef7632319e5335c7b8ed4aa1c8ed80fe"}]},{"id":24,"stem":"A COMPANY is resident in India if:","options":[{"key":"A","text":"It pays or declares any dividend within India during the relevant previous year, in India"},{"key":"B","text":"All its directors are Indian citizens resident in India during the year"},{"key":"C","text":"It is an Indian company, OR its place of effective management (POEM) is in India during the year"},{"key":"D","text":"It is listed on the National Stock Exchange of India at any time during the relevant previous year"}],"answer":"C","explanation":"Section 6(3): Indian companies are always resident; other companies are resident if their POEM is in India (POEM = where key management and commercial decisions are made in substance).","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A COMPANY is resident in India if:","options":["It pays dividend in India","All its directors are Indians","It is an Indian company, OR its place of effective management (POEM) is in India during the year","It is listed on the NSE"],"answer":2,"explanation":"Section 6(3): Indian companies are always resident; other companies are resident if their POEM is in India (POEM = where key management and commercial decisions are made in substance).","revision":"original","contentSignature":"b5fb13e59d4b9238a52a9564d71f834f9b3e716d75ae8aed920fb636268f8607"}]},{"id":25,"stem":"The total income of a RESIDENT AND ORDINARILY RESIDENT (ROR) individual includes:","options":[{"key":"A","text":"Only the salary income earned by the individual during the previous year, whether the services are rendered in India or abroad"},{"key":"B","text":"Only the income actually received in India during the previous year, and no income accruing or arising outside India at all"},{"key":"C","text":"Income received/deemed received in India + income accruing or arising in India + income accruing OUTSIDE India (world income)"},{"key":"D","text":"Only the income from sources situated in India during the previous year, and no income from any foreign source at all"}],"answer":"C","explanation":"Section 5(1): a ROR is taxed on world income. RNOR and NR are taxed on Indian income plus foreign income only if from a business controlled or profession set up in India.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The total income of a RESIDENT AND ORDINARILY RESIDENT (ROR) individual includes:","options":["Only salary income","Only income received in India","Income received/deemed received in India + income accruing or arising in India + income accruing OUTSIDE India (world income)","Only Indian-source income"],"answer":2,"explanation":"Section 5(1): a ROR is taxed on world income. RNOR and NR are taxed on Indian income plus foreign income only if from a business controlled or profession set up in India.","revision":"original","contentSignature":"5ab3fcfa601c55ce7db3f9507d8dcd4bc93345500e0f6397909f4003b0ff7a0b"}]},{"id":26,"stem":"A NON-RESIDENT is taxable in India on:","options":[{"key":"A","text":"Foreign salary credited in a foreign bank account for services rendered wholly outside India"},{"key":"B","text":"Income received or deemed received in India and income accruing or arising or deemed to accrue or arise in India"},{"key":"C","text":"Income from a foreign business which is controlled and managed wholly from outside India, with no operations in India at all"},{"key":"D","text":"His world income, exactly as for a resident and ordinarily resident individual, including every foreign-source receipt"}],"answer":"B","explanation":"Section 5(2): non-residents pay Indian tax only on India-linked income - received in India or deemed to accrue or arise here (s.9).","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A NON-RESIDENT is taxable in India on:","options":["Foreign salary credited abroad","Income received or deemed received in India and income accruing or arising or deemed to accrue or arise in India","Income from a foreign business controlled abroad","His world income"],"answer":1,"explanation":"Section 5(2): non-residents pay Indian tax only on India-linked income - received in India or deemed to accrue or arise here (s.9).","revision":"original","contentSignature":"7608169a78e4cc940f0e91e70918cf9135378dd01b2efefb4d49652a562689c1"}]},{"id":27,"stem":"Which of the following incomes is DEEMED TO ACCRUE OR ARISE IN INDIA under Section 9(1)?","options":[{"key":"A","text":"Income from a property situated abroad"},{"key":"B","text":"Income from any business connection in India, and salary earned in India"},{"key":"C","text":"Salary of a non-resident earned wholly for services outside India"},{"key":"D","text":"Agricultural income from land in Sri Lanka"}],"answer":"B","explanation":"Section 9(1) deems Indian accrual for business-connection income, Indian property income, asset transfers in India and salary EARNED in India (services rendered here).","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":28,"stem":"Salary payable by the Government of India to an Indian citizen for services rendered OUTSIDE India is:","options":[{"key":"A","text":"Taxed only in the foreign country where the services are actually rendered, and wholly exempt from income tax in India"},{"key":"B","text":"Exempt from Indian tax altogether, being earned wholly outside the country, for every Government servant posted abroad"},{"key":"C","text":"DEEMED to accrue in India and taxable in India (though allowances/perquisites for foreign service are exempt u/s 10(7))"},{"key":"D","text":"Treated as agricultural income and exempt under Section 10(1) of the Income-tax Act, as if it were farm income"}],"answer":"C","explanation":"Section 9(1)(iii): Government salary for services abroad is deemed to accrue in India; the foreign allowances of such government servants are exempt under s.10(7).","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Salary payable by the Government of India to an Indian citizen for services rendered OUTSIDE India is:","options":["Taxed only in the foreign country","Exempt from Indian tax","DEEMED to accrue in India and taxable in India (though allowances/perquisites for foreign service are exempt u/s 10(7))","Treated as agricultural income"],"answer":2,"explanation":"Section 9(1)(iii): Government salary for services abroad is deemed to accrue in India; the foreign allowances of such government servants are exempt under s.10(7).","revision":"original","contentSignature":"dabe6340476d01cb613eebc99599711b8de9dea0ec245de10652951e32a34713"}]},{"id":29,"stem":"Income RECEIVED in India is taxable:","options":[{"key":"A","text":"Only for companies, and not for other assessees"},{"key":"B","text":"Never taxable in India for any assessee at all"},{"key":"C","text":"Only for residents, and not for non-residents"},{"key":"D","text":"In the hands of ALL assessees - resident or non-resident"}],"answer":"D","explanation":"Receipt basis applies to everyone: income first received in India is chargeable for every status category.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Review note: clarify that income is first received in India; later remittance alone is not receipt.","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Income RECEIVED in India is taxable:","options":["Only for companies","Never","Only for residents","In the hands of ALL assessees - resident or non-resident"],"answer":3,"explanation":"Receipt basis applies to everyone: income first received in India is chargeable for every status category.","revision":"original","contentSignature":"0e0f5dae8b856c6f400374808fb99752a9c3e3960736b14f07a7220f33790897"}]},{"id":30,"stem":"Which of the following receipts is CAPITAL in nature and generally NOT taxable as income?","options":[{"key":"A","text":"Compensation for cancellation of a contract resulting in termination of the whole source of income"},{"key":"B","text":"Monthly rent received from a tenant for the let-out house property during the previous year, month after month"},{"key":"C","text":"Interest on fixed deposits held with a scheduled bank in India, credited by the bank from time to time"},{"key":"D","text":"Monthly salary received from the employer for the services rendered during each month of the year"}],"answer":"A","explanation":"A receipt replacing the very source of income (sterilising the profit-making apparatus) is capital; recurring receipts for services or use of assets are revenue.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which of the following receipts is CAPITAL in nature and generally NOT taxable as income?","options":["Compensation for cancellation of a contract resulting in termination of the whole source of income","Monthly rent","Interest on bank deposits","Monthly salary"],"answer":0,"explanation":"A receipt replacing the very source of income (sterilising the profit-making apparatus) is capital; recurring receipts for services or use of assets are revenue.","revision":"original","contentSignature":"f63c3f77bcc6a8fd2b51c061d15dc98996aa0ebc54d318edf586356bba4a9ffc"}]},{"id":31,"stem":"Income earned by a minor child is generally:","options":[{"key":"A","text":"CLUBBED with the income of the parent having the higher income (s.64(1A)), except income from the child own skill/manual work"},{"key":"B","text":"Taxed separately as the child's own income, with no clubbing"},{"key":"C","text":"Taxed at a flat rate of 30%, whatever its nature"},{"key":"D","text":"Always exempt, since a minor has no legal capacity to earn"}],"answer":"A","explanation":"Clubbing applies except where the income arises from the child own manual work or specialised skill; the parent gets a s.10(32) exemption of Rs.1,500 per child.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Income earned by a minor child is generally:","options":["CLUBBED with the income of the parent having the higher income (s.64(1A)), except income from the child own skill/manual work","Taxed separately as the child own income in all cases","Taxed at 30% flat","Always exempt"],"answer":0,"explanation":"Clubbing applies except where the income arises from the child own manual work or specialised skill; the parent gets a s.10(32) exemption of Rs.1,500 per child.","revision":"original","contentSignature":"d71e58f45ff2544b18560d93b315df60ac8447ab1ae51e3a1e1c69eccd944fcf"}]},{"id":32,"stem":"Which of the following is EXEMPT from income tax?","options":[{"key":"A","text":"Arrears of salary received during the relevant previous year, at any time"},{"key":"B","text":"Interest on fixed deposits held with a scheduled bank in India, yearly"},{"key":"C","text":"Agricultural income (s.10(1)) and receipts covered by Section 10 exemptions"},{"key":"D","text":"Winnings from lotteries, crossword puzzles and horse races, etc."}],"answer":"C","explanation":"Section 10 lists exempt incomes - agricultural income, HUF member share, certain allowances, gratuity within limits, etc. Interest and lottery are fully taxable.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which of the following is EXEMPT from income tax?","options":["Salary arrears","Interest on fixed deposits","Agricultural income (s.10(1)) and receipts covered by Section 10 exemptions","Lottery winnings"],"answer":2,"explanation":"Section 10 lists exempt incomes - agricultural income, HUF member share, certain allowances, gratuity within limits, etc. Interest and lottery are fully taxable.","revision":"original","contentSignature":"fe13d1f5ac2215ed6412d1c66dc7a2e79abbd6cdc2d70d639f91840c5cbb46e1"}]},{"id":33,"stem":"The share of profit received by a partner from his partnership firm is:","options":[{"key":"A","text":"Taxable as business income at the flat rate of 30% in his hands"},{"key":"B","text":"Taxable as salary income in the hands of the partner concerned"},{"key":"C","text":"Partly exempt - 50% of the share of profit is exempt from tax"},{"key":"D","text":"EXEMPT in the partner hands under Section 10(2A) (the firm pays tax on it)"}],"answer":"D","explanation":"The firm is taxed as a separate entity; the partner share of post-tax profit is exempt to avoid double taxation. Partner salary and interest from the firm are taxable as PGBP.","source":"Source label not detected","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The share of profit received by a partner from his partnership firm is:","options":["Taxable as business income at 30%","Taxable as salary","Partly exempt at 50%","EXEMPT in the partner hands under Section 10(2A) (the firm pays tax on it)"],"answer":3,"explanation":"The firm is taxed as a separate entity; the partner share of post-tax profit is exempt to avoid double taxation. Partner salary and interest from the firm are taxable as PGBP.","revision":"original","contentSignature":"36e947958d0621229211d1b398ac85239622f9c30205bd6f12c34f36bf18687f"}]},{"id":34,"stem":"Income-tax in India is levied by the:","options":[{"key":"A","text":"The State Governments under Entry 46 of the State List"},{"key":"B","text":"The Reserve Bank of India, as the monetary authority of India"},{"key":"C","text":"The local municipalities, under their own taxation powers only"},{"key":"D","text":"UNION (Central) Government under Entry 82 of the Union List"}],"answer":"D","explanation":"Taxes on income other than agricultural income fall in the Union List; agricultural income tax is a State subject.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Income-tax in India is levied by the:","options":["State Governments","Reserve Bank of India","Local municipalities","UNION (Central) Government under Entry 82 of the Union List"],"answer":3,"explanation":"Taxes on income other than agricultural income fall in the Union List; agricultural income tax is a State subject.","revision":"original","contentSignature":"69936052abeb750b4c772f6ce576243f0c88ae07bb87c237ac0db3e079b41ddd"}]},{"id":35,"stem":"A \"domestic company\" for income-tax purposes means:","options":[{"key":"A","text":"Any company carrying on operations of any kind within the territory of India, whether it is incorporated in India or in any foreign country"},{"key":"B","text":"A multinational corporation having subsidiaries or branches in several countries of the world, including one or more in India"},{"key":"C","text":"Only a company whose shares are listed on a recognised stock exchange in India, and no other company of any kind"},{"key":"D","text":"An INDIAN company, or any other company which has made prescribed arrangements for declaration and payment of dividends in India"}],"answer":"D","explanation":"Section 2(22A): Indian companies plus companies with prescribed dividend-payment arrangements in India are domestic companies.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A \"domestic company\" for income-tax purposes means:","options":["Any company operating in India","A multinational corporation","A listed company only","An INDIAN company, or any other company which has made prescribed arrangements for declaration and payment of dividends in India"],"answer":3,"explanation":"Section 2(22A): Indian companies plus companies with prescribed dividend-payment arrangements in India are domestic companies.","revision":"original","contentSignature":"eec0dfaddf198fae14469204d348a4046167810a690167db133149ad000ede2b"}]},{"id":36,"stem":"Which of the following BEST describes \"gross total income\" minus \"total income\"?","options":[{"key":"A","text":"The income exempt under Section 10 of the Act"},{"key":"B","text":"Deductions under Chapter VI-A (Sections 80C to 80U)"},{"key":"C","text":"The tax deducted at source on the income of the year"},{"key":"D","text":"The advance tax paid during the previous year"}],"answer":"B","explanation":"GTI - Chapter VI-A deductions = total income on which slab rates are applied.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which of the following BEST describes \"gross total income\" minus \"total income\"?","options":["Exempt income under Section 10","Deductions under Chapter VI-A (Sections 80C to 80U)","TDS deducted at source","Advance tax paid"],"answer":1,"explanation":"GTI - Chapter VI-A deductions = total income on which slab rates are applied.","revision":"original","contentSignature":"240915aca5eee4d7421b27b0cb86461bb5d23cca13b0fb4d8b4ce1e3cdbd1f2b"}]},{"id":37,"stem":"\"Marginal relief\" in income-tax ensures that:","options":[{"key":"A","text":"The surcharge on income-tax is abolished for every assessee in India, whatever the level of his total income"},{"key":"B","text":"The increase in tax payable when income crosses a threshold does NOT exceed the excess income over that threshold"},{"key":"C","text":"No one is required to pay any income-tax at all, whatever the level of total income earned during the previous year"},{"key":"D","text":"Agricultural income is fully taxed like any other income of the previous year, without the Section 10(1) exemption"}],"answer":"B","explanation":"Marginal relief caps the tax (or tax-plus-surcharge) jump at the amount by which income exceeds the rebate/surcharge threshold - preventing a small income rise from causing a large tax rise.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"\"Marginal relief\" in income-tax ensures that:","options":["Surcharge is abolished","The increase in tax payable when income crosses a threshold does NOT exceed the excess income over that threshold","No one pays any tax","Agricultural income is taxed"],"answer":1,"explanation":"Marginal relief caps the tax (or tax-plus-surcharge) jump at the amount by which income exceeds the rebate/surcharge threshold - preventing a small income rise from causing a large tax rise.","revision":"original","contentSignature":"f2674013d7eff196fb856391b3fed6a28b3f920af14b9b33914be6a34b8e305e"}]},{"id":38,"stem":"Rounding off of total income under Section 288A is done to the nearest multiple of:","options":[{"key":"A","text":"One rupee"},{"key":"B","text":"Ten rupees"},{"key":"C","text":"Hundred rupees"},{"key":"D","text":"Thousand rupees"}],"answer":"B","explanation":"Total income is rounded to the nearest Rs.10; tax, interest and refunds are similarly rounded (s.288B).","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":39,"stem":"Which of the following statements is TRUE about the previous year for a NEW business?","options":[{"key":"A","text":"It begins on the date the business is set up and ends on the following 31 March - it can be shorter than 12 months"},{"key":"B","text":"It can exceed 12 months and run up to 15 months in the first year of the business, at the option of the assessee"},{"key":"C","text":"It is fixed by the Assessing Officer separately in each individual case, depending on the size of the new business"},{"key":"D","text":"It must always be a full period of 12 months, without any exception, even for a business set up late in the year"}],"answer":"A","explanation":"For a newly set up business or a new source of income, the first previous year runs from the start date to the next 31 March.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which of the following statements is TRUE about the previous year for a NEW business?","options":["It begins on the date the business is set up and ends on the following 31 March - it can be shorter than 12 months","It can exceed 12 months","It is fixed by the Assessing Officer","It must always be a full 12 months"],"answer":0,"explanation":"For a newly set up business or a new source of income, the first previous year runs from the start date to the next 31 March.","revision":"original","contentSignature":"9add8dbdb0521d345dda26059a4bb2068e58dc88b3c32a87cf43654c2005c724"}]},{"id":40,"stem":"Income of which person is TAXABLE even if it is received or accrued to another person (clubbing principle)?","options":[{"key":"A","text":"Salary of an independent spouse earned by her own skill and professional effort"},{"key":"B","text":"Income transferred without transferring the ASSET (s.60) - taxed in the transferor hands"},{"key":"C","text":"Income of a major married daughter living separately from her parents, earned by her"},{"key":"D","text":"A major son-in-law income from his own independent business or profession, always"}],"answer":"B","explanation":"Section 60 revives tax in the transferor where income is diverted without transferring the asset itself; independent earnings of major family members are not clubbed.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Income of which person is TAXABLE even if it is received or accrued to another person (clubbing principle)?","options":["Salary of an independent spouse earned by her skill","Income transferred without transferring the ASSET (s.60) - taxed in the transferor hands","Income of a major married daughter","A major son-in-law income from his own business"],"answer":1,"explanation":"Section 60 revives tax in the transferor where income is diverted without transferring the asset itself; independent earnings of major family members are not clubbed.","revision":"original","contentSignature":"a8bc78888987ba88789b87ae30ddb1d23b39215dba8273c0013b2af770db96e6"}]},{"id":41,"stem":"The Income-tax Act, 1961 came into force with effect from:","options":[{"key":"A","text":"1 April 2001"},{"key":"B","text":"1 April 1956"},{"key":"C","text":"15 August 1947"},{"key":"D","text":"1 April 1962"}],"answer":"D","explanation":"The 1961 Act replaced the Indian Income-tax Act, 1922 with effect from 1 April 1962.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":42,"stem":"Which of the following is an example of an artificial juridical person included in \"person\"?","options":[{"key":"A","text":"A minor child assessed through his natural guardian under the Act"},{"key":"B","text":"A partnership firm assessed under Section 2(31) of the Act"},{"key":"C","text":"A deity of a temple (e.g. an idol assessed through its shebait)"},{"key":"D","text":"A chartered accountant practising in his own individual name"}],"answer":"C","explanation":"Idols/deities, universities and statutory corporations are artificial juridical persons - a residual s.2(31)(vii) category.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which of the following is an example of an artificial juridical person included in \"person\"?","options":["A minor child","A partnership firm","A deity of a temple (e.g. an idol assessed through its shebait)","A chartered accountant"],"answer":2,"explanation":"Idols/deities, universities and statutory corporations are artificial juridical persons - a residual s.2(31)(vii) category.","revision":"original","contentSignature":"aa1676e6fe6b9661c89087b70e1cdc51e1bf8d5b9a3fa8d27142984c6384e03b"}]},{"id":43,"stem":"Where an assessee has agricultural income of Rs.6,000 and non-agricultural total income of Rs.4,00,000 (old regime), the final tax is:","options":[{"key":"A","text":"Tax on Rs.4,06,000 at the slab rates applicable for the assessment year, without any rebate under Section 87A"},{"key":"B","text":"Nil - because partial integration only fixes the RATE; on these facts tax works out to nil after rebate/limits"},{"key":"C","text":"Tax only on the agricultural income of Rs.6,000, and nothing at all on the non-agricultural income of Rs.4,00,000"},{"key":"D","text":"A flat 30% tax on the Rs.6,000 of agricultural income, and no tax at all on the non-agricultural income"}],"answer":"B","explanation":"Partial integration (old regime): tax on (4,00,000 + 6,000) = 7,800 (5% of 1,56,000); tax on (6,000 + 2,50,000) = 300; difference = 7,500 - fully wiped out by the 87A rebate (total income Rs.4 lakh is within Rs.5 lakh), so the final tax is NIL.","source":"Source label not detected","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Where an assessee has agricultural income of Rs.6,000 and non-agricultural total income of Rs.4,00,000 (old regime), the final tax is:","options":["Tax on Rs.4,06,000 at slab rates","Nil - because partial integration only fixes the RATE; on these facts tax works out to nil after rebate/limits","Tax only on agricultural income","30% flat on Rs.6,000"],"answer":1,"explanation":"Partial integration (old regime): tax on (4,00,000 + 6,000) = 7,800 (5% of 1,56,000); tax on (6,000 + 2,50,000) = 300; difference = 7,500 - fully wiped out by the 87A rebate (total income Rs.4 lakh is within Rs.5 lakh), so the final tax is NIL.","revision":"original","contentSignature":"c835dcd8d6ac3499031547ab9bb9c457a12f05adb45c008cc011881ed8ac57b0"}]},{"id":44,"stem":"Income is taxable under the head \"Salaries\" (Section 15) only when there exists a:","options":[{"key":"A","text":"A dealer-customer relationship between the payer and the payee concerned"},{"key":"B","text":"A buyer-seller relationship between the payer and the payee concerned"},{"key":"C","text":"A creditor-debtor relationship between the payer and the payee concerned"},{"key":"D","text":"MASTER-SERVANT (employer-employee) relationship between the payer and the payee"}],"answer":"D","explanation":"The master-servant relationship is the essence of salary; without it the receipt falls under other heads (e.g. PGBP or other sources).","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Income is taxable under the head \"Salaries\" (Section 15) only when there exists a:","options":["Dealer-customer relationship","Buyer-seller relationship","Creditor-debtor relationship","MASTER-SERVANT (employer-employee) relationship between the payer and the payee"],"answer":3,"explanation":"The master-servant relationship is the essence of salary; without it the receipt falls under other heads (e.g. PGBP or other sources).","revision":"original","contentSignature":"76485856cf6f8f1cf0facd3d614ecfad22952ca669ca59befc33d1ce5affb355"}]},{"id":45,"stem":"Under Section 15, salary is chargeable to tax on:","options":[{"key":"A","text":"Receipt basis only, in every possible case"},{"key":"B","text":"DUE or RECEIPT basis, WHICHEVER IS EARLIER"},{"key":"C","text":"Due basis only, in every possible case"},{"key":"D","text":"Cash basis only, after the retirement of the employee"}],"answer":"B","explanation":"Salary is taxed when it becomes due or is received, whichever happens first - arrears are taxed in the year of receipt if not taxed earlier, with relief u/s 89.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Under Section 15, salary is chargeable to tax on:","options":["Receipt basis only","DUE or RECEIPT basis, WHICHEVER IS EARLIER","Due basis only","Cash basis after retirement"],"answer":1,"explanation":"Salary is taxed when it becomes due or is received, whichever happens first - arrears are taxed in the year of receipt if not taxed earlier, with relief u/s 89.","revision":"original","contentSignature":"3916605dd55a98b130758fd61bb4e3f138addd071b40d73d8f27af60bd3c274a"}]},{"id":46,"stem":"Relief on arrears or advance salary is claimed under:","options":[{"key":"A","text":"Section 80C, within its overall limit"},{"key":"B","text":"Section 89, by filing Form 10E"},{"key":"C","text":"Section 87A, as a rebate of tax"},{"key":"D","text":"Section 10(5), as leave travel concession"}],"answer":"B","explanation":"Section 89 spreads arrears/advance salary over the years to which they relate; Form 10E must be filed to claim the relief.","source":"Source label not detected","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Relief on arrears or advance salary is claimed under:","options":["Section 80C","Section 89, by filing Form 10E","Section 87A","Section 10(5)"],"answer":1,"explanation":"Section 89 spreads arrears/advance salary over the years to which they relate; Form 10E must be filed to claim the relief.","revision":"original","contentSignature":"922ee1b5592ff8a4b09f04ca860e161cf01d9ae76b04cd90685e598443ba6cc8"}]},{"id":47,"stem":"\"Profits in lieu of salary\" under Section 17(3) includes:","options":[{"key":"A","text":"Agricultural income from land situated in India and used for agricultural purposes, together with every receipt exempt under Section 10(1) of the Act in the hands of the recipient employee during the previous year"},{"key":"B","text":"Compensation received on termination of employment, and payments from an employer-employee provident/other fund (to the extent of employer contributions and interest thereon)"},{"key":"C","text":"Only the cash salary paid by the employer"},{"key":"D","text":"Interest on bank deposits of the employee"}],"answer":"B","explanation":"Section 17(3) sweeps in retrenchment/termination compensation and similar payments connected with employment.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"\"Profits in lieu of salary\" under Section 17(3) includes:","options":["Agricultural income","Compensation received on termination of employment, and payments from an employer-employee provident/other fund (to the extent of employer contributions and interest thereon)","Only cash salary","Bank interest"],"answer":1,"explanation":"Section 17(3) sweeps in retrenchment/termination compensation and similar payments connected with employment.","revision":"original","contentSignature":"09957004630db4ca03190eb43a297885f62700d2c31ead1570c9fcd66d8ef9dc"}]},{"id":48,"stem":"\"Salary\" for tax purposes includes:","options":[{"key":"A","text":"Only the basic pay drawn by the employee during the year, and no allowance, perquisite or profit of any kind"},{"key":"B","text":"Basic wages, dearness allowance, bonus, commission, fees, perquisites and profits in lieu of salary"},{"key":"C","text":"Only the pension drawn after retirement from the service, and nothing earned during the period of employment"},{"key":"D","text":"Only the amounts actually received in cash by the employee during the year, excluding every benefit in kind"}],"answer":"B","explanation":"Section 17(1) gives an inclusive definition - wages, annuity/pension, gratuity, fees/commission/perquisites/profits in lieu, advance salary, leave encashment and employer fund contributions.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"\"Salary\" for tax purposes includes:","options":["Only basic pay","Basic wages, dearness allowance, bonus, commission, fees, perquisites and profits in lieu of salary","Only pension","Only cash received"],"answer":1,"explanation":"Section 17(1) gives an inclusive definition - wages, annuity/pension, gratuity, fees/commission/perquisites/profits in lieu, advance salary, leave encashment and employer fund contributions.","revision":"original","contentSignature":"d58af45bc722b96f15abb38e9894cfd9f0020d824ce3ee3665860c3882117a46"}]},{"id":49,"stem":"Pension received regularly by a retired employee is:","options":[{"key":"A","text":"A capital receipt, and hence wholly exempt from income tax"},{"key":"B","text":"Taxable as income under the head business or profession"},{"key":"C","text":"Fully exempt under Section 10 of the Income-tax Act, 1961"},{"key":"D","text":"Taxable under the head SALARIES as income from the former employer"}],"answer":"D","explanation":"Uncommuted (periodic) pension is salary income; only commuted pension gets partial/full exemption under s.10(10A).","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Pension received regularly by a retired employee is:","options":["A capital receipt - exempt","Taxable as business income","Fully exempt u/s 10","Taxable under the head SALARIES as income from the former employer"],"answer":3,"explanation":"Uncommuted (periodic) pension is salary income; only commuted pension gets partial/full exemption under s.10(10A).","revision":"original","contentSignature":"01a3bdd5ffe4b30fdc5d0b0e91459a5eaa83a2e03c372cb2fcd1fcd34aae5c0c"}]},{"id":50,"stem":"Commuted (lump-sum) pension received by a GOVERNMENT employee is:","options":[{"key":"A","text":"Taxable at the flat rate of 30%"},{"key":"B","text":"Fully taxable as salary in his hands"},{"key":"C","text":"Taxable at half the normal slab rates"},{"key":"D","text":"Fully EXEMPT under Section 10(10A)(i)"}],"answer":"D","explanation":"Government employees (Centre/State/local authority) enjoy full exemption on commuted pension.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Commuted (lump-sum) pension received by a GOVERNMENT employee is:","options":["Taxable at 30%","Fully taxable","Taxable at half rate","Fully EXEMPT under Section 10(10A)(i)"],"answer":3,"explanation":"Government employees (Centre/State/local authority) enjoy full exemption on commuted pension.","revision":"original","contentSignature":"7607d5d2f51449dc89a0d974e8a1777f04df110d12d69bd675b61fb64a4711e8"}]},{"id":51,"stem":"For a NON-government employee who also receives GRATUITY, the exempt portion of commuted pension is:","options":[{"key":"A","text":"One-THIRD of the commuted value"},{"key":"B","text":"Nil"},{"key":"C","text":"Full amount"},{"key":"D","text":"One-half of the commuted value"}],"answer":"A","explanation":"Non-government employees: 1/3 of commuted value exempt if gratuity is also received; 1/2 if no gratuity is received (s.10(10A)(ii)).","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":52,"stem":"Gratuity received by a CENTRAL/STATE Government employee on retirement is:","options":[{"key":"A","text":"FULLY EXEMPT under Section 10(10)(i)"},{"key":"B","text":"Fully taxable as salary in his hands"},{"key":"C","text":"Exempt only up to Rs.10 lakh in aggregate"},{"key":"D","text":"Exempt only up to Rs.3 lakh in aggregate"}],"answer":"A","explanation":"Government and local-authority employees get full gratuity exemption; the Rs.20 lakh ceiling applies to private-sector employees.","source":"Source label not detected","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Gratuity received by a CENTRAL/STATE Government employee on retirement is:","options":["FULLY EXEMPT under Section 10(10)(i)","Fully taxable","Exempt up to Rs.10 lakh","Exempt up to Rs.3 lakh"],"answer":0,"explanation":"Government and local-authority employees get full gratuity exemption; the Rs.20 lakh ceiling applies to private-sector employees.","revision":"original","contentSignature":"cd68b002733ea04e3bfb972f41879f51b2336736a9ee6dfb041ec9cd16913938"}]},{"id":53,"stem":"For a private-sector employee COVERED by the Payment of Gratuity Act, exempt gratuity is the LEAST of: (i) actual gratuity received, (ii) Rs.20 lakh, (iii):","options":[{"key":"A","text":"15 days salary (last drawn) for every completed year of service (or part over 6 months)"},{"key":"B","text":"One month salary for every completed year of service, without any proportion"},{"key":"C","text":"The average salary of the 10 months preceding retirement, without more"},{"key":"D","text":"The basic salary multiplied by 5, without any other factor"}],"answer":"A","explanation":"The three limits: actual, Rs.20,00,000 (notified limit), and 15/26 x last drawn salary x completed years (part > 6 months rounded up).","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"For a private-sector employee COVERED by the Payment of Gratuity Act, exempt gratuity is the LEAST of: (i) actual gratuity received, (ii) Rs.20 lakh, (iii):","options":["15 days salary (last drawn) for every completed year of service (or part over 6 months)","One month salary for every year of service","Average salary of 10 months","Basic salary x 5"],"answer":0,"explanation":"The three limits: actual, Rs.20,00,000 (notified limit), and 15/26 x last drawn salary x completed years (part > 6 months rounded up).","revision":"original","contentSignature":"c0d01666da0c7bdc361a64d896a8901e1069425a9398d1f3d13ceed4dae0f125"}]},{"id":54,"stem":"The current notified exemption limit for gratuity of private-sector employees under Section 10(10) is:","options":[{"key":"A","text":"Rs.25 lakh"},{"key":"B","text":"Rs.10 lakh"},{"key":"C","text":"Rs.3.5 lakh"},{"key":"D","text":"Rs.20 lakh"}],"answer":"D","explanation":"The limit was raised from Rs.10 lakh to Rs.20 lakh w.e.f. 29-3-2018 and remains Rs.20 lakh for AY 2026-27.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":55,"stem":"Leave encashment received by a GOVERNMENT employee at retirement is:","options":[{"key":"A","text":"Exempt only up to Rs.3 lakh in aggregate"},{"key":"B","text":"Fully EXEMPT under Section 10(10AA)(i)"},{"key":"C","text":"Fully taxable as salary in his hands"},{"key":"D","text":"Taxable under the head income from other sources"}],"answer":"B","explanation":"Government employees pay no tax on leave encashment at retirement; during service it is taxable for everyone.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Leave encashment received by a GOVERNMENT employee at retirement is:","options":["Exempt up to Rs.3 lakh","Fully EXEMPT under Section 10(10AA)(i)","Taxable fully","Taxable as other sources"],"answer":1,"explanation":"Government employees pay no tax on leave encashment at retirement; during service it is taxable for everyone.","revision":"original","contentSignature":"5eb96e0941d194c05e3584c826d31784ef72e24b0bb3bafa2cbfbf00833743a7"}]},{"id":56,"stem":"For NON-government employees, leave encashment at retirement is exempt up to the least of several limits, the monetary ceiling being:","options":[{"key":"A","text":"Rs.25 lakh"},{"key":"B","text":"Rs.10 lakh"},{"key":"C","text":"Rs.50 lakh"},{"key":"D","text":"Rs.3 lakh"}],"answer":"A","explanation":"The Rs.3,00,000 ceiling was raised to Rs.25,00,000 by notification in 2023 (effective FY 2023-24) and holds for AY 2026-27.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":57,"stem":"Voluntary retirement compensation under Section 10(10C) is exempt up to:","options":[{"key":"A","text":"Rs.10 lakh"},{"key":"B","text":"Rs.20 lakh"},{"key":"C","text":"Rs.1 lakh"},{"key":"D","text":"Rs.5 lakh"}],"answer":"D","explanation":"VRS compensation is exempt up to Rs.5 lakh, subject to the scheme conditions; relief u/s 89 can alternatively be claimed, not both.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":58,"stem":"Retrenchment compensation under Section 10(10B) is exempt up to the least of actual amount, Rs.5 lakh, and:","options":[{"key":"A","text":"15 days average pay for every completed year of service (and part over 6 months)"},{"key":"B","text":"10 days average pay for every completed year of service (and part over 6 months), subject to the Rs.5 lakh ceiling"},{"key":"C","text":"Three months salary in aggregate, for the entire period of service, subject to the Rs.5 lakh ceiling"},{"key":"D","text":"One full year salary in aggregate, for the entire period of service, subject to the Rs.5 lakh ceiling"}],"answer":"A","explanation":"Retrenchment compensation exemption mirrors the Industrial Disputes Act formula: 15 days average pay per completed year, capped at Rs.5 lakh.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Retrenchment compensation under Section 10(10B) is exempt up to the least of actual amount, Rs.5 lakh, and:","options":["15 days average pay for every completed year of service (and part over 6 months)","10 days average pay per year of service","Three months salary","One year salary"],"answer":0,"explanation":"Retrenchment compensation exemption mirrors the Industrial Disputes Act formula: 15 days average pay per completed year, capped at Rs.5 lakh.","revision":"original","contentSignature":"c6382b27bc5d5ffc6813f87674600948adb3c06c400cf004e4108f3eeee83dd9"}]},{"id":59,"stem":"House Rent Allowance (HRA) exemption under Section 10(13A) is the LEAST of: actual HRA received, rent paid minus 10% of salary, and:","options":[{"key":"A","text":"20% of the salary, whether the city is a metro or not"},{"key":"B","text":"50% of salary (metro) or 40% (other cities)"},{"key":"C","text":"100% of the salary, whether the city is a metro or not"},{"key":"D","text":"25% of the salary, whether the city is a metro or not"}],"answer":"B","explanation":"Rule 2A: the three-limb test; the 50%/40% limb depends on whether the rented house is in Mumbai/Kolkata/Delhi/Chennai or elsewhere.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"House Rent Allowance (HRA) exemption under Section 10(13A) is the LEAST of: actual HRA received, rent paid minus 10% of salary, and:","options":["20% of salary","50% of salary (metro) or 40% (other cities)","100% of salary","25% of salary"],"answer":1,"explanation":"Rule 2A: the three-limb test; the 50%/40% limb depends on whether the rented house is in Mumbai/Kolkata/Delhi/Chennai or elsewhere.","revision":"original","contentSignature":"2f9c6d17cee5baa6306f2fcc01ff71a59ca60adb4b4805dd90a4f384c7b799a3"}]},{"id":60,"stem":"A salaried person living in DELHI receives HRA Rs.1,20,000 p.a., pays rent Rs.1,00,000 p.a.; basic salary Rs.3,00,000 p.a. HRA exemption is:","options":[{"key":"A","text":"Rs.1,20,000"},{"key":"B","text":"Rs.70,000"},{"key":"C","text":"Rs.50,000"},{"key":"D","text":"Rs.90,000"}],"answer":"B","explanation":"Least of: (i) 1,20,000, (ii) rent - 10% of salary = 1,00,000 - 30,000 = 70,000, (iii) 50% of salary = 1,50,000. Exemption = Rs.70,000.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":61,"stem":"Dearness allowance is counted as part of \"salary\" for HRA and retirement-benefit purposes only when:","options":[{"key":"A","text":"It exceeds Rs.5,000 per month at any time during the year, whatever the terms of the employment may provide"},{"key":"B","text":"It forms part of salary under the terms of employment (e.g. counts for retirement benefits)"},{"key":"C","text":"Never counted as part of salary at all, whatever the terms of the employment may provide for it"},{"key":"D","text":"The employee requests the employer to count it as part of salary, whatever the terms of the employment"}],"answer":"B","explanation":"Only DA entering into pay for retirement-benefit purposes counts as salary for HRA exemption and gratuity computations.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Dearness allowance is counted as part of \"salary\" for HRA and retirement-benefit purposes only when:","options":["It exceeds Rs.5,000 p.m.","It forms part of salary under the terms of employment (e.g. counts for retirement benefits)","Never","The employee requests it"],"answer":1,"explanation":"Only DA entering into pay for retirement-benefit purposes counts as salary for HRA exemption and gratuity computations.","revision":"original","contentSignature":"7e3e73e51f392eecdf33f01489278c3b7c5dc85e59d1bc16abc5b60081620490"}]},{"id":62,"stem":"Transport allowance exemption for commuting between home and office is now available to:","options":[{"key":"A","text":"All salaried employees without exception, whether disabled or not"},{"key":"B","text":"Pensioners only, to the exclusion of every serving employee, whatever the nature of the commuting expense actually incurred"},{"key":"C","text":"NO general exemption - it is taxable (exemption survives only for blind/deaf-dumb/orthopaedically handicapped employees at Rs.3,200 p.m.)"},{"key":"D","text":"Government employees only, to the exclusion of every private-sector employee, whatever the nature of the commuting expense actually incurred"}],"answer":"C","explanation":"The general Rs.1,600 p.m. transport allowance exemption was withdrawn from AY 2019-20 when standard deduction was introduced; the handicapped-employee exemption (Rs.3,200 p.m.) continues.","source":"Source label not detected","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Transport allowance exemption for commuting between home and office is now available to:","options":["All salaried employees","Pensioners only","NO general exemption - it is taxable (exemption survives only for blind/deaf-dumb/orthopaedically handicapped employees at Rs.3,200 p.m.)","Government employees only"],"answer":2,"explanation":"The general Rs.1,600 p.m. transport allowance exemption was withdrawn from AY 2019-20 when standard deduction was introduced; the handicapped-employee exemption (Rs.3,200 p.m.) continues.","revision":"original","contentSignature":"7fdf0b7fb18ce191dc49b5f2e1514f1eda63798557b6892f1ae2e110a75cdb1a"}]},{"id":63,"stem":"Children education allowance is exempt up to:","options":[{"key":"A","text":"Rs.1,000 per month per child"},{"key":"B","text":"Rs.200 per month per child (max 2 children)"},{"key":"C","text":"Rs.300 per month per child"},{"key":"D","text":"Rs.100 per month per child, up to two children"}],"answer":"D","explanation":"Section 10(14) read with Rule 2BB: Rs.100 p.m. per child (max two children); hostel expenditure allowance Rs.300 p.m. per child (max two).","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":64,"stem":"Tribal area allowance exemption (for specified tribal/agency areas) is:","options":[{"key":"A","text":"Fully exempt"},{"key":"B","text":"Rs.1,000 per month"},{"key":"C","text":"Rs.200 per month"},{"key":"D","text":"Rs.3,200 per month"}],"answer":"C","explanation":"Rule 2BB: tribal area allowance is exempt up to Rs.200 per month for employees posted in specified tribal areas of listed States (MP, UP, Karnataka, Tripura, Assam, WB, Bihar, Odisha, Tamil Nadu).","source":"Source label not detected","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":65,"stem":"Entertainment allowance deduction under Section 16(ii) is available to:","options":[{"key":"A","text":"All private-sector employees, whatever the amount of the entertainment allowance drawn during the year"},{"key":"B","text":"Bank employees only, to the exclusion of every other category of employee, public or private alike"},{"key":"C","text":"All employees of every kind, up to a maximum of Rs.10,000"},{"key":"D","text":"GOVERNMENT employees only - least of actual allowance, Rs.5,000, or 1/5 of basic salary"}],"answer":"D","explanation":"Entertainment allowance is first included in salary for all; only government employees get the s.16(ii) deduction capped at Rs.5,000. Private employees get NIL deduction.","source":"Source label not detected","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Entertainment allowance deduction under Section 16(ii) is available to:","options":["All private-sector employees","Bank employees only","All employees up to Rs.10,000","GOVERNMENT employees only - least of actual allowance, Rs.5,000, or 1/5 of basic salary"],"answer":3,"explanation":"Entertainment allowance is first included in salary for all; only government employees get the s.16(ii) deduction capped at Rs.5,000. Private employees get NIL deduction.","revision":"original","contentSignature":"2fdb3cae23d2196d19d21a29854c7ea08a91ee93c96e43abce5a93240e2d3187"}]},{"id":66,"stem":"A private-sector employee gets Rs.30,000 p.m. basic salary and Rs.1,500 p.m. entertainment allowance. Deduction u/s 16(ii) is:","options":[{"key":"A","text":"Rs.18,000"},{"key":"B","text":"Rs.5,000"},{"key":"C","text":"NIL"},{"key":"D","text":"Rs.72,000"}],"answer":"C","explanation":"Section 16(ii) applies only to Government employees; a private employee gets no deduction for entertainment allowance.","source":"Source label not detected","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":67,"stem":"Standard deduction under Section 16(ia) for AY 2026-27 is:","options":[{"key":"A","text":"Rs.40,000 for all"},{"key":"B","text":"Rs.1,00,000 for all"},{"key":"C","text":"Rs.75,000 under the NEW regime and Rs.50,000 under the OLD regime"},{"key":"D","text":"Rs.50,000 under the NEW regime and Rs.75,000 under the OLD regime"}],"answer":"C","explanation":"Standard deduction is Rs.75,000 in the new regime (from FY 2024-25) and Rs.50,000 in the old regime.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":68,"stem":"Deduction for professional tax paid under Section 16(iii) is:","options":[{"key":"A","text":"Allowed up to Rs.5,000 under the new regime of Section 115BAC"},{"key":"B","text":"Available only in the OLD regime (not allowed under the new regime 115BAC)"},{"key":"C","text":"Available under both the old and the new tax regimes alike, without any difference of treatment"},{"key":"D","text":"Never allowed as a deduction under any regime at all, old or new"}],"answer":"B","explanation":"Professional tax (max Rs.2,500 levied by States) is deductible u/s 16(iii) only in the old regime; the new regime permits only s.16(ia) standard deduction.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Deduction for professional tax paid under Section 16(iii) is:","options":["Allowed up to Rs.5,000 in new regime","Available only in the OLD regime (not allowed under the new regime 115BAC)","Available in both regimes","Never allowed"],"answer":1,"explanation":"Professional tax (max Rs.2,500 levied by States) is deductible u/s 16(iii) only in the old regime; the new regime permits only s.16(ia) standard deduction.","revision":"original","contentSignature":"07a1d6b8cbafd71e8bcdf31c47d13825145f7b2b7a06c6e92a89fe01401a0efd"}]},{"id":69,"stem":"A \"specified employee\" for perquisite valuation under Section 17(2)(iii) includes all EXCEPT:","options":[{"key":"A","text":"A GAZETTED Government officer"},{"key":"B","text":"An employee whose salary income (net of certain deductions) exceeds Rs.50,000"},{"key":"C","text":"A director of the company"},{"key":"D","text":"An employee having substantial interest (20%+ voting power) in the employer company"}],"answer":"A","explanation":"The three specified-employee tests: director, substantial interest holder, or monetary limit of Rs.50,000. Government officers are employees; \"gazetted\" status is irrelevant.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":70,"stem":"Which of the following is a PERQUISITE taxable under Section 17(2)?","options":[{"key":"A","text":"Free or concessional residential accommodation, interest-free/concessional loans above Rs.20,000, and employer-provided car facility"},{"key":"B","text":"Agricultural land inherited by the employee from his ancestors and used for agricultural purposes only, with no employer connection of any kind"},{"key":"C","text":"A monthly railway pass bought by the employee himself out of his own salary, with no contribution or reimbursement from the employer of any kind"},{"key":"D","text":"A cash gift of Rs.500 received by the employee from a personal friend on a private occasion, with no employer connection of any kind"}],"answer":"A","explanation":"Rent-free accommodation, concessional loans above Rs.20,000, car facility, ESOP, free domestic servants etc. are perquisites taxed in the hands of the employee (specified employees for s.17(2)(iii) items).","source":"Source label not detected","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which of the following is a PERQUISITE taxable under Section 17(2)?","options":["Free or concessional residential accommodation, interest-free/concessional loans above Rs.20,000, and employer-provided car facility","Agricultural land inherited","Monthly railway pass bought by the employee himself","A cash gift of Rs.500 from a friend"],"answer":0,"explanation":"Rent-free accommodation, concessional loans above Rs.20,000, car facility, ESOP, free domestic servants etc. are perquisites taxed in the hands of the employee (specified employees for s.17(2)(iii) items).","revision":"original","contentSignature":"1ae3710888248da0f7d2498275bcfeb575a328373b90ecb8175fb582f5238ee1"}]},{"id":71,"stem":"Medical facilities in employer-maintained hospitals and the annual health insurance premium paid by the employer (u/s 17(2) proviso/Rule 3A) are:","options":[{"key":"A","text":"Taxable at a flat rate of 30%, like a cash allowance"},{"key":"B","text":"EXEMPT - employer-paid medical insurance premium and treatment in employer/government/approved hospitals are not taxable perquisites"},{"key":"C","text":"Fully taxable as perquisites, like a cash allowance"},{"key":"D","text":"Taxable only to the extent the cost exceeds Rs.15,000 in a year, whatever the nature of the facility or the premium paid by the employer on the policy"}],"answer":"B","explanation":"Employer-paid group medical premium and treatment in specified hospitals are exempt; the Rs.15,000 cap was removed long ago.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Medical facilities in employer-maintained hospitals and the annual health insurance premium paid by the employer (u/s 17(2) proviso/Rule 3A) are:","options":["Taxable at 30%","EXEMPT - employer-paid medical insurance premium and treatment in employer/government/approved hospitals are not taxable perquisites","Fully taxable perquisites","Taxable above Rs.15,000 only"],"answer":1,"explanation":"Employer-paid group medical premium and treatment in specified hospitals are exempt; the Rs.15,000 cap was removed long ago.","revision":"original","contentSignature":"dcbe815a0fcecc64bd3cc33f60fcd5a7cbe7d75a0951bdfe2b892613d0bec442"}]},{"id":72,"stem":"Employer contribution to an employee NPS account is deductible in the employee hands under Section 80CCD(2) up to:","options":[{"key":"A","text":"No deduction available in the hands of the employee"},{"key":"B","text":"10% of basic + DA (old regime); 14% of basic + DA (new regime)"},{"key":"C","text":"20% of gross salary under both the old and the new regimes alike"},{"key":"D","text":"A flat Rs.50,000 under both the regimes alike"}],"answer":"B","explanation":"From FY 2024-25, the new-regime cap on employer NPS contribution (private sector too) is 14% of basic+DA; the old regime keeps 10%. This is over and above the 80CCE limit.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Review note: old-regime employer NPS limit depends on employer/category; question needs a qualifier.","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Employer contribution to an employee NPS account is deductible in the employee hands under Section 80CCD(2) up to:","options":["No deduction available","10% of basic + DA (old regime); 14% of basic + DA (new regime)","20% of gross salary in both regimes","Rs.50,000 flat"],"answer":1,"explanation":"From FY 2024-25, the new-regime cap on employer NPS contribution (private sector too) is 14% of basic+DA; the old regime keeps 10%. This is over and above the 80CCE limit.","revision":"original","contentSignature":"2ec5d57c3d9d610630aa63a9f9e10fc15565d37418c32b3934b8c7e4d16d557d"}]},{"id":73,"stem":"Employer contribution to recognised provident fund is EXEMPT up to:","options":[{"key":"A","text":"Rs.1.5 lakh a year, irrespective of the salary drawn"},{"key":"B","text":"No limit at all on the exemption"},{"key":"C","text":"12% of salary; interest credited up to 9.5% p.a. is exempt"},{"key":"D","text":"15% of salary; interest credited up to 9.5% p.a. is exempt"}],"answer":"C","explanation":"RPF: employer contribution beyond 12% of salary is taxable, and interest above 9.5% p.a. is taxable; additionally, interest on employee contributions above Rs.2.5 lakh a year is taxable (2021 change).","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Employer contribution to recognised provident fund is EXEMPT up to:","options":["Rs.1.5 lakh only","No limit","12% of salary; interest credited up to 9.5% p.a. is exempt","15% of salary"],"answer":2,"explanation":"RPF: employer contribution beyond 12% of salary is taxable, and interest above 9.5% p.a. is taxable; additionally, interest on employee contributions above Rs.2.5 lakh a year is taxable (2021 change).","revision":"original","contentSignature":"8681b3fd0f13dcdc4ea7ce6a47b06b8647f65bd7915a44ad41d34a6875620d34"}]},{"id":74,"stem":"A lump-sum payment received from a RECOGNISED provident fund on retirement after 5 years of continuous service is:","options":[{"key":"A","text":"Taxable at the rate of 20%, like any other lump-sum receipt"},{"key":"B","text":"Fully taxable as salary in his hands"},{"key":"C","text":"EXEMPT under Section 10(12)"},{"key":"D","text":"Half of it taxable as salary in his hands"}],"answer":"C","explanation":"Accumulated RPF balance is exempt after 5 years of continuous service (with exceptions for permitted early withdrawals).","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A lump-sum payment received from a RECOGNISED provident fund on retirement after 5 years of continuous service is:","options":["Taxable at 20%","Fully taxable","EXEMPT under Section 10(12)","Half taxable"],"answer":2,"explanation":"Accumulated RPF balance is exempt after 5 years of continuous service (with exceptions for permitted early withdrawals).","revision":"original","contentSignature":"5fc48d1893f76636e983e736b8a8774c8ccbdead68d73a63701efbd3ae6e6a69"}]},{"id":75,"stem":"Approved superannuation fund - employer contribution is taxable as perquisite if it exceeds:","options":[{"key":"A","text":"Rs.7.5 lakh per year"},{"key":"B","text":"Rs.1.5 lakh per year"},{"key":"C","text":"Rs.1 lakh per year"},{"key":"D","text":"Rs.2 lakh per year"}],"answer":"B","explanation":"Employer contribution to an approved superannuation fund above Rs.1,50,000 a year is a taxable perquisite.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":76,"stem":"Death-cum-retirement gratuity received by the LEGAL HEIR of a deceased government employee is:","options":[{"key":"A","text":"Fully exempt under s.10(10)"},{"key":"B","text":"Taxable as capital gains"},{"key":"C","text":"Taxable at slab rates"},{"key":"D","text":"Taxable as income from other sources"}],"answer":"A","explanation":"Gratuity received on death is exempt in the hands of the family/legal heirs, same as retirement gratuity of government employees.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":77,"stem":"Salary in lieu of notice period received on termination is:","options":[{"key":"A","text":"Agricultural income"},{"key":"B","text":"Tax-free up to Rs.1 lakh"},{"key":"C","text":"A capital receipt - exempt"},{"key":"D","text":"Taxable under the head SALARIES"}],"answer":"D","explanation":"Payments connected with the employment relationship, including notice-pay, are salary income.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":78,"stem":"Bonus or commission received by an employee from the employer is taxable under the head:","options":[{"key":"A","text":"Capital gains"},{"key":"B","text":"Profits and gains of business"},{"key":"C","text":"Income from other sources"},{"key":"D","text":"Salaries"}],"answer":"D","explanation":"All receipts flowing from the employer-employee relationship - bonus, commission, overtime pay - are salary income.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":79,"stem":"Advance salary received is taxed:","options":[{"key":"A","text":"In the year to which the salary actually relates, and not before, without any relief whatsoever"},{"key":"B","text":"In the year of RECEIPT (due or receipt, whichever earlier), with s.89 relief where applicable"},{"key":"C","text":"Never taxed at any time, however large the advance"},{"key":"D","text":"Only after the retirement of the employee from service, and not before that event"}],"answer":"B","explanation":"Section 15 brings advance salary to tax on receipt; s.89(1) relief mitigates bunching.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Advance salary received is taxed:","options":["In the year to which it relates","In the year of RECEIPT (due or receipt, whichever earlier), with s.89 relief where applicable","Never","Only after retirement"],"answer":1,"explanation":"Section 15 brings advance salary to tax on receipt; s.89(1) relief mitigates bunching.","revision":"original","contentSignature":"997fbe8227f764186a131d19b175c99d0b009362a119f0d5211087134661787c"}]},{"id":80,"stem":"An employee stock option plan (ESOP) is taxed as a perquisite:","options":[{"key":"A","text":"On the date of grant of the option by the employer, measured by the difference between the then market value and the grant price fixed"},{"key":"B","text":"On the date of ALLOTMENT of shares - the difference between fair market value on exercise date and the amount paid by the employee"},{"key":"C","text":"On the date of vesting of the option in the employee, measured by the difference between the then market value and the exercise price payable"},{"key":"D","text":"Never taxed as a perquisite at all, and taxed only as capital gains on the sale of the shares"}],"answer":"B","explanation":"Perquisite value = FMV on the exercise date minus the exercise price, taxed in the year of allotment; later sale attracts capital gains.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"An employee stock option plan (ESOP) is taxed as a perquisite:","options":["On the date of grant","On the date of ALLOTMENT of shares - the difference between fair market value on exercise date and the amount paid by the employee","On the date of vesting","Never"],"answer":1,"explanation":"Perquisite value = FMV on the exercise date minus the exercise price, taxed in the year of allotment; later sale attracts capital gains.","revision":"original","contentSignature":"9b9c499b251f9c6fa63d789687087c4be83053e608ae78b1987b37d0191ecd4f"}]},{"id":81,"stem":"Free education of the employee children provided by the employer is:","options":[{"key":"A","text":"A taxable perquisite - except where the institution is maintained by the employer, in which case cost up to Rs.1,000 per month per child is exempt"},{"key":"B","text":"Always fully exempt, whatever the nature of the institution and however high the actual cost to the employer may be per child"},{"key":"C","text":"Fully exempt in the hands of all employees, without any monetary limit and whatever the nature of the institution attended by the child"},{"key":"D","text":"Taxed at a flat rate of 30%, irrespective of the cost to the employer"}],"answer":"A","explanation":"Rule 3: if the employer runs the school, value above Rs.1,000 p.m. per child is a perquisite; elsewhere the employer-borne cost is taxable.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Free education of the employee children provided by the employer is:","options":["A taxable perquisite - except where the institution is maintained by the employer, in which case cost up to Rs.1,000 per month per child is exempt","Always fully exempt","Fully exempt for all employees","Taxed at flat 30%"],"answer":0,"explanation":"Rule 3: if the employer runs the school, value above Rs.1,000 p.m. per child is a perquisite; elsewhere the employer-borne cost is taxable.","revision":"original","contentSignature":"5c353af22f298f26f26f921994d01ddf369359591571fd274f302da66f47d02b"}]},{"id":82,"stem":"The exemption for interest-free or concessional loans applies only when the loan to the employee exceeds:","options":[{"key":"A","text":"Rs.50,000"},{"key":"B","text":"Rs.1,00,000"},{"key":"C","text":"Rs.20,000"},{"key":"D","text":"Rs.5,000"}],"answer":"C","explanation":"Loans up to Rs.20,000 in aggregate (and loans for treatment of specified diseases) are not taxed as perquisites.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":83,"stem":"Salary received by a PARTNER from his partnership firm is assessed under the head:","options":[{"key":"A","text":"Income from other sources, in his hands"},{"key":"B","text":"Profits and gains of business or profession"},{"key":"C","text":"Exempt income, in his hands"},{"key":"D","text":"Salaries, in his hands"}],"answer":"B","explanation":"A partner is not an employee of the firm; partner salary/interest is business income (the firm gets a s.40(b) deduction within limits).","source":"Source label not detected","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Salary received by a PARTNER from his partnership firm is assessed under the head:","options":["Income from other sources","Profits and gains of business or profession","Exempt income","Salaries"],"answer":1,"explanation":"A partner is not an employee of the firm; partner salary/interest is business income (the firm gets a s.40(b) deduction within limits).","revision":"original","contentSignature":"9445ab17176f5f2228898620f86a6911faeed8c51a1d8e5fb4e19e826930c82b"}]},{"id":84,"stem":"HRA exemption is NOT available to an employee who:","options":[{"key":"A","text":"Pays rent for the house to his own parents"},{"key":"B","text":"Lives in a rented house in the same city"},{"key":"C","text":"Lives in a metro city like Delhi or Mumbai"},{"key":"D","text":"Lives in his own house / pays no rent"}],"answer":"D","explanation":"Exemption needs actual rent paid above 10% of salary; an owner-occupier gets no HRA exemption.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"HRA exemption is NOT available to an employee who:","options":["Pays rent to his parents","Lives in a rented house","Lives in a metro city","Lives in his own house / pays no rent"],"answer":3,"explanation":"Exemption needs actual rent paid above 10% of salary; an owner-occupier gets no HRA exemption.","revision":"original","contentSignature":"a6516c28ac72c33ec217126ed3b36558c0b9fe0c82bc461689b0b2513f0596f3"}]},{"id":85,"stem":"Which of the following allowances is FULLY taxable for all employees?","options":[{"key":"A","text":"Tribal area allowance, within the limits prescribed under Rule 2BB, only to that extent"},{"key":"B","text":"House rent allowance, to its full extent and without the Section 10(13A) exemption"},{"key":"C","text":"Dearness allowance (non-retirement portion), city compensatory allowance, overtime allowance"},{"key":"D","text":"Children education allowance, within the limits prescribed under Rule 2BB, only to that extent"}],"answer":"C","explanation":"DA, CCA and overtime are fully taxable; only the specifically exempt allowances (HRA, education, tribal area etc.) get limited exemptions.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which of the following allowances is FULLY taxable for all employees?","options":["Tribal area allowance within limits","HRA","Dearness allowance (non-retirement portion), city compensatory allowance, overtime allowance","Children education allowance within limits"],"answer":2,"explanation":"DA, CCA and overtime are fully taxable; only the specifically exempt allowances (HRA, education, tribal area etc.) get limited exemptions.","revision":"original","contentSignature":"58c1a59af2357ebe63d3e8f5a4a6c853c48db73d2bf1cd555d2bce432dc2d1fc"}]},{"id":86,"stem":"Leave encashment received DURING the period of service is:","options":[{"key":"A","text":"Fully TAXABLE for all employees (government and private)"},{"key":"B","text":"Taxable at the flat rate of 10% only"},{"key":"C","text":"Fully exempt for all employees, government and private"},{"key":"D","text":"Exempt up to Rs.25 lakh, like encashment at retirement is"}],"answer":"A","explanation":"The s.10(10AA) exemption applies only to encashment at retirement (or on resignation/termination), not to in-service encashment.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Leave encashment received DURING the period of service is:","options":["Fully TAXABLE for all employees (government and private)","Taxable at 10%","Fully exempt","Exempt up to Rs.25 lakh"],"answer":0,"explanation":"The s.10(10AA) exemption applies only to encashment at retirement (or on resignation/termination), not to in-service encashment.","revision":"original","contentSignature":"8b75fb587218bca48fa68672c3f3668d2a12dc575f55c086dac6d8c59a74bd89"}]},{"id":87,"stem":"Annuity (annual payment) received from a present employer under an employment contract is taxed as:","options":[{"key":"A","text":"Salary"},{"key":"B","text":"Capital gains"},{"key":"C","text":"Exempt income"},{"key":"D","text":"Casual income"}],"answer":"A","explanation":"Annuity from an employer is salary; annuity from other sources (e.g. an insurance policy) goes to income from other sources.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":88,"stem":"The taxability of \"profits in lieu of salary\" and termination compensation is dealt with in:","options":[{"key":"A","text":"Section 17(3)"},{"key":"B","text":"Section 10"},{"key":"C","text":"Section 24"},{"key":"D","text":"Section 80C"}],"answer":"A","explanation":"Section 17(3) specifically taxes compensation for termination or modification of employment terms as profits in lieu of salary.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":89,"stem":"For HRA exemption, \"salary\" means:","options":[{"key":"A","text":"The gross salary, including every allowance of whatever nature, whether or not it counts for any employment purpose"},{"key":"B","text":"Only the basic pay, with no allowance or commission added"},{"key":"C","text":"The take-home pay after all deductions from salary, including tax and provident fund contributions"},{"key":"D","text":"Basic + DA (if part of retirement-benefit terms) + commission as a fixed percentage of turnover"}],"answer":"D","explanation":"Rule 2A uses the narrow salary definition: basic plus qualifying DA plus fixed-percentage commission on turnover.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"For HRA exemption, \"salary\" means:","options":["Gross salary including all allowances","Only basic pay always","Take-home pay","Basic + DA (if part of retirement-benefit terms) + commission as a fixed percentage of turnover"],"answer":3,"explanation":"Rule 2A uses the narrow salary definition: basic plus qualifying DA plus fixed-percentage commission on turnover.","revision":"original","contentSignature":"cd7eb448018ede8a65e97cc435c59ff3cd89e2239003906a323d77af903e6b85"}]},{"id":90,"stem":"Compensation received by an employee under a voluntary retirement scheme (VRS) is exempt under s.10(10C) subject to all EXCEPT:","options":[{"key":"A","text":"The recipient must not be re-employed in the same/another company of the same management"},{"key":"B","text":"The scheme applies to all employees (except directors)"},{"key":"C","text":"The exemption is capped at Rs.5 lakh"},{"key":"D","text":"The employee can claim BOTH s.10(10C) exemption AND s.89 relief in the same year"}],"answer":"D","explanation":"Section 10(10C) and s.89 relief cannot be claimed together for the same compensation; the employee must choose one.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":91,"stem":"A lump sum received from an UNRECOGNISED provident fund on retirement is taxed as:","options":[{"key":"A","text":"Only the interest credited on the contributions is taxable; both the employee and the employer contributions are exempt, and both interest streams are taxed alike"},{"key":"B","text":"Fully taxable at a flat rate of 30%, including both contributions and all interest"},{"key":"C","text":"Employee own contributions exempt; employer contributions plus interest thereon taxed as salary; interest on employee contributions taxed as other sources"},{"key":"D","text":"Fully exempt in his hands, including both contributions and all interest"}],"answer":"C","explanation":"URPF: the employee contributions are tax-free (no deduction was claimed); employer contributions and interest on employer share are salary, and interest on the employee share is other-sources income.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A lump sum received from an UNRECOGNISED provident fund on retirement is taxed as:","options":["Only interest is taxable","Fully taxable at 30%","Employee own contributions exempt; employer contributions plus interest thereon taxed as salary; interest on employee contributions taxed as other sources","Fully exempt"],"answer":2,"explanation":"URPF: the employee contributions are tax-free (no deduction was claimed); employer contributions and interest on employer share are salary, and interest on the employee share is other-sources income.","revision":"original","contentSignature":"2c3c01fc873491b479817e1bc0fd5adbfc86ee023da473ae3b24e61b1e504f3b"}]},{"id":92,"stem":"Which of the following is DEDUCTIBLE from gross salary under Section 16 (old regime)?","options":[{"key":"A","text":"The principal repaid on a housing loan during the year, as a deduction from gross salary"},{"key":"B","text":"Standard deduction, entertainment allowance (government employees) and professional tax"},{"key":"C","text":"The income-tax paid by the employee during the year, as a deduction from gross salary"},{"key":"D","text":"Entertainment allowance drawn by a private-sector employee"}],"answer":"B","explanation":"Section 16 permits only three deductions: 16(ia) standard deduction, 16(ii) entertainment allowance (government), and 16(iii) professional/employment tax.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which of the following is DEDUCTIBLE from gross salary under Section 16 (old regime)?","options":["Home loan principal","Standard deduction, entertainment allowance (government employees) and professional tax","Income tax paid","Entertainment allowance to a private employee"],"answer":1,"explanation":"Section 16 permits only three deductions: 16(ia) standard deduction, 16(ii) entertainment allowance (government), and 16(iii) professional/employment tax.","revision":"original","contentSignature":"68a2d99c5d2c5b182151c942ac1933d2bedc64c7c7788835dcce64780ce8aa60"}]},{"id":93,"stem":"Rent-free accommodation provided by the employer is valued (non-government employees, per Rule 3 as revised) at:","options":[{"key":"A","text":"The municipal tax paid on the accommodation during the year, whatever the city of posting and whoever owns the property"},{"key":"B","text":"A flat 30% of salary, whatever the city of posting, its population, and whoever owns the property"},{"key":"C","text":"15%/10%/7.5% of salary depending on city population (cities above 40 lakh, 15-40 lakh, below 15 lakh respectively)"},{"key":"D","text":"Nil, irrespective of the city of posting or the ownership of the property"}],"answer":"C","explanation":"The 2023 CBDT revision set 15% (population above 40 lakh), 10% (15-40 lakh) and 7.5% (below 15 lakh) of salary as the value of unfurnished rent-free accommodation for non-government employees.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Rent-free accommodation provided by the employer is valued (non-government employees, per Rule 3 as revised) at:","options":["The municipal tax paid","A flat 30% of salary","15%/10%/7.5% of salary depending on city population (cities above 40 lakh, 15-40 lakh, below 15 lakh respectively)","Nil always"],"answer":2,"explanation":"The 2023 CBDT revision set 15% (population above 40 lakh), 10% (15-40 lakh) and 7.5% (below 15 lakh) of salary as the value of unfurnished rent-free accommodation for non-government employees.","revision":"original","contentSignature":"0eefc609d108a4bc6291011e7a0dddaeb8318f202fc276cb8eae0007ec5ab679"}]},{"id":94,"stem":"Surrender of salary to the Central Government under s.2 of the Voluntary Surrender of Salaries (Exemption from Taxation) Act, 1961 is:","options":[{"key":"A","text":"EXEMPT - genuinely surrendered salary is not included in income"},{"key":"B","text":"Taxed at the rate of 20% in his hands"},{"key":"C","text":"Clubbed with the income of his spouse under Section 64"},{"key":"D","text":"Taxable in his hands nevertheless, as if not surrendered"}],"answer":"A","explanation":"A true voluntary surrender to the Government is exempt under that specific 1961 statute; a mere application of salary after accrual would still be taxed.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Surrender of salary to the Central Government under s.2 of the Voluntary Surrender of Salaries (Exemption from Taxation) Act, 1961 is:","options":["EXEMPT - genuinely surrendered salary is not included in income","Taxed at 20%","Clubbed with spouse income","Taxable nevertheless"],"answer":0,"explanation":"A true voluntary surrender to the Government is exempt under that specific 1961 statute; a mere application of salary after accrual would still be taxed.","revision":"original","contentSignature":"7de47d65b784806e19b6195a29f6773267656f7d5566ffa41bb03cb3b2b85fb1"}]},{"id":95,"stem":"Arrears of pension received by the family of a deceased employee (family pension) are taxable under the head:","options":[{"key":"A","text":"Capital gains, in the hands of the family"},{"key":"B","text":"Income from OTHER SOURCES"},{"key":"C","text":"Fully exempt, in the hands of the family"},{"key":"D","text":"Salaries, in the hands of the family"}],"answer":"B","explanation":"Family pension is taxed under other sources, with a deduction of 1/3rd or Rs.15,000 (old regime) / Rs.25,000 (new regime), whichever is lower.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Arrears of pension received by the family of a deceased employee (family pension) are taxable under the head:","options":["Capital gains","Income from OTHER SOURCES","Exempt fully","Salaries"],"answer":1,"explanation":"Family pension is taxed under other sources, with a deduction of 1/3rd or Rs.15,000 (old regime) / Rs.25,000 (new regime), whichever is lower.","revision":"original","contentSignature":"73ed7c7142c38bfa3a7d205d81abf4216a06c7fd80adaf248323b36c51c4fabd"}]},{"id":96,"stem":"Which receipt is NOT part of salary income?","options":[{"key":"A","text":"Bonus paid by the employer during the year, in cash or kind"},{"key":"B","text":"Advance salary paid by the employer during the year, on request"},{"key":"C","text":"Scholarship received by the employee child from an independent trust on merit"},{"key":"D","text":"Gratuity in excess of the exemption limits under Section 10(10), paid on retirement"}],"answer":"C","explanation":"A merit scholarship to the child from an independent body has no employer-employee nexus; it is exempt under s.10(16) in the child hands.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which receipt is NOT part of salary income?","options":["Bonus","Advance salary","Scholarship received by the employee child from an independent trust on merit","Gratuity in excess of exemption limits"],"answer":2,"explanation":"A merit scholarship to the child from an independent body has no employer-employee nexus; it is exempt under s.10(16) in the child hands.","revision":"original","contentSignature":"774812fd84498c76d32dd084da89ff5185589ce39bbe6abec5d94dc399c3a4b5"}]},{"id":97,"stem":"\"Perquisite\" under Section 17(2) is charged:","options":[{"key":"A","text":"For all employees in respect of s.17(2)(i)/(ii) items (rent-free accommodation, employer obligations paid), and for SPECIFIED employees in respect of s.17(2)(iii) fringe benefits"},{"key":"B","text":"Only for government employees, and only in respect of the s.17(2)(i) and (ii) items"},{"key":"C","text":"Never charged to tax at all, whether the employee is a government servant or a private employee, and whatever the item of benefit conferred by the employer may be"},{"key":"D","text":"Only for employees who are directors of the company, to the exclusion of every other employee, and only in respect of the s.17(2)(i) and (ii) items at that"}],"answer":"A","explanation":"Sections 17(2)(i) and (ii) apply to every employee; 17(2)(iii) benefits (car, servants, utilities etc.) are taxed only for specified employees.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"\"Perquisite\" under Section 17(2) is charged:","options":["For all employees in respect of s.17(2)(i)/(ii) items (rent-free accommodation, employer obligations paid), and for SPECIFIED employees in respect of s.17(2)(iii) fringe benefits","Only for government employees","Never","Only for directors"],"answer":0,"explanation":"Sections 17(2)(i) and (ii) apply to every employee; 17(2)(iii) benefits (car, servants, utilities etc.) are taxed only for specified employees.","revision":"original","contentSignature":"0d6b6edfa9a067473ddec32841b521cec88b8c2aaff80fb2ca49d38783f05074"}]},{"id":98,"stem":"Salary due from a foreign employer for services rendered in India, received outside India, is taxable in India in the hands of a resident because:","options":[{"key":"A","text":"Only NRIs pay tax on it, and no one else, whatever the place where the services are actually rendered"},{"key":"B","text":"It is received abroad, so it escapes Indian tax altogether, whatever the place where the services are actually rendered"},{"key":"C","text":"It is exempt under Section 10 of the Act, whatever the place where the services are actually rendered"},{"key":"D","text":"It is income ACCRUING in India - the place of accrual of salary is where the services are RENDERED"}],"answer":"D","explanation":"Salary accrues where services are performed; for a resident, world income is taxable in any case (s.5(1)).","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Salary due from a foreign employer for services rendered in India, received outside India, is taxable in India in the hands of a resident because:","options":["Only NRIs pay tax on it","It is received abroad","It is exempt","It is income ACCRUING in India - the place of accrual of salary is where the services are RENDERED"],"answer":3,"explanation":"Salary accrues where services are performed; for a resident, world income is taxable in any case (s.5(1)).","revision":"original","contentSignature":"c4a071ea7a42a4441f70d5162d0fb481e93c0491363837e4cbf0bd95c38343a9"}]},{"id":99,"stem":"The maximum deduction for entertainment allowance of a government employee under s.16(ii) per annum is:","options":[{"key":"A","text":"Rs.18,000"},{"key":"B","text":"1/4 of gross salary"},{"key":"C","text":"Rs.10,000"},{"key":"D","text":"Rs.5,000"}],"answer":"D","explanation":"Least of actual allowance, Rs.5,000, or one-fifth of basic salary - the Rs.5,000 statutory cap usually binds.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":100,"stem":"Which of the following items is NOT taxed as salary?","options":[{"key":"A","text":"Remuneration received by a partner from his firm"},{"key":"B","text":"Overtime payments made by the employer during the year"},{"key":"C","text":"Monthly pension paid by the former employer"},{"key":"D","text":"Fees and commission paid by the employer to the employee"}],"answer":"A","explanation":"Partner remuneration lacks the master-servant relationship and is taxed as business income, not salary.","source":"Source label not detected","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which of the following items is NOT taxed as salary?","options":["Remuneration received by a partner from his firm","Overtime payments","Monthly pension","Fees and commission from the employer"],"answer":0,"explanation":"Partner remuneration lacks the master-servant relationship and is taxed as business income, not salary.","revision":"original","contentSignature":"eeb5b54a217134079a4e96a15bd2186d0574c97eb8b159c85257cdcd103715cd"}]},{"id":101,"stem":"Under the NEW tax regime (115BAC), which salary-related deduction/exemption IS still available?","options":[{"key":"A","text":"The HRA exemption under Section 10(13A), as under the old regime"},{"key":"B","text":"The entertainment allowance deduction under Section 16(ii), as under the old regime"},{"key":"C","text":"Standard deduction u/s 16(ia) and employer NPS contribution u/s 80CCD(2)"},{"key":"D","text":"The professional tax deduction under Section 16(iii), as under the old regime"}],"answer":"C","explanation":"The new regime bars HRA, LTC, 16(ii)/(iii) and most Chapter VI-A deductions, but allows the standard deduction (Rs.75,000), employer NPS 80CCD(2), family pension deduction (Rs.25,000) and 80JJAA.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Under the NEW tax regime (115BAC), which salary-related deduction/exemption IS still available?","options":["HRA exemption","Entertainment allowance deduction","Standard deduction u/s 16(ia) and employer NPS contribution u/s 80CCD(2)","Professional tax deduction"],"answer":2,"explanation":"The new regime bars HRA, LTC, 16(ii)/(iii) and most Chapter VI-A deductions, but allows the standard deduction (Rs.75,000), employer NPS 80CCD(2), family pension deduction (Rs.25,000) and 80JJAA.","revision":"original","contentSignature":"73bbbc199d1253125b6131866b28977ff99de3c57112f67cd8e5e4bb50229c5e"}]},{"id":102,"stem":"Income is chargeable under \"Income from house property\" only when the assessee is the ________ of a building or land appurtenant thereto:","options":[{"key":"A","text":"OWNER"},{"key":"B","text":"Mortgagee"},{"key":"C","text":"Tenant"},{"key":"D","text":"Caretaker"}],"answer":"A","explanation":"Ownership of the building (with land appurtenant) is the basis of charge; a sub-letting tenant income goes to other sources, not house property.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified"},{"id":103,"stem":"The annual value of a LET-OUT house property is:","options":[{"key":"A","text":"Nil for every rented property, whatever the municipal value, the fair rent, the standard rent and the actual rent received or receivable for the previous year may be, and whatever the period for which the property was actually let out during the year"},{"key":"B","text":"Always the actual rent received or receivable, without any comparison with the municipal value, the fair rent or the standard rent of the property at all, even where the property is clearly under-rented or is lying vacant for a part of the year"},{"key":"C","text":"The higher of municipal value or fair rent, restricted to standard rent (if rent control applies), and compared with ACTUAL RENT received/receivable - whichever of these (expected rent vs actual rent) is HIGHER"},{"key":"D","text":"Only the municipal value of the property, without any comparison with the fair rent, the standard rent or the actual rent received or receivable at all"}],"answer":"C","explanation":"Section 23(1): expected rent = higher of municipal value and fair rent (capped at standard rent); annual value = higher of expected rent and actual rent received/receivable.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The annual value of a LET-OUT house property is:","options":["Nil for rented property","Actual rent always","The higher of municipal value or fair rent, restricted to standard rent (if rent control applies), and compared with ACTUAL RENT received/receivable - whichever of these (expected rent vs actual rent) is HIGHER","Municipal value only"],"answer":2,"explanation":"Section 23(1): expected rent = higher of municipal value and fair rent (capped at standard rent); annual value = higher of expected rent and actual rent received/receivable.","revision":"original","contentSignature":"97b5ef1f4b3e19537c6943183728f5f778ba08a6ee3fa9c1f03323eb0d2bd020"}]},{"id":104,"stem":"Municipal taxes are deductible from gross annual value only when they are:","options":[{"key":"A","text":"Actually PAID by the OWNER during the previous year (any year payment allowed)"},{"key":"B","text":"Merely due from the owner, whether actually paid or not, in any year"},{"key":"C","text":"Paid by the TENANT of the property, not by the owner himself"},{"key":"D","text":"Paid in advance for the next 10 years only, and in no other manner"}],"answer":"A","explanation":"Municipal taxes (including service taxes to local bodies) are deductible on payment basis if borne and paid by the owner; tenant-paid taxes are ignored.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Municipal taxes are deductible from gross annual value only when they are:","options":["Actually PAID by the OWNER during the previous year (any year payment allowed)","Merely due","Paid by the TENANT","Paid in advance for 10 years only"],"answer":0,"explanation":"Municipal taxes (including service taxes to local bodies) are deductible on payment basis if borne and paid by the owner; tenant-paid taxes are ignored.","revision":"original","contentSignature":"0238b0525a575978a79e72b38126ffe72b06d86dcaf8dc6729b2f08a14976cb6"}]},{"id":105,"stem":"From the net annual value, a STANDARD DEDUCTION is allowed under Section 24(a) at:","options":[{"key":"A","text":"30% of net annual value (no proof of expense needed)"},{"key":"B","text":"A flat Rs.30,000, whatever the net annual value"},{"key":"C","text":"10% of the net annual value, without proof of expense"},{"key":"D","text":"Only the actual repairs incurred, on production of proof"}],"answer":"A","explanation":"A flat 30% of NAV covers repairs and all other expenses - allowed even if actual expenditure is less, for let-out as well as deemed let-out property.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"From the net annual value, a STANDARD DEDUCTION is allowed under Section 24(a) at:","options":["30% of net annual value (no proof of expense needed)","Rs.30,000 flat","10% of NAV","Actual repairs incurred"],"answer":0,"explanation":"A flat 30% of NAV covers repairs and all other expenses - allowed even if actual expenditure is less, for let-out as well as deemed let-out property.","revision":"original","contentSignature":"0bc2abad6bfbdb48ef967a99a0d51fc88f63ba6a2d7054919bb0c75562f7d9d5"}]},{"id":106,"stem":"Interest on borrowed capital for acquisition/construction of a LET-OUT property is deductible under s.24(b):","options":[{"key":"A","text":"Deductible only up to Rs.2 lakh per year in the aggregate, whatever the actual interest paid or payable on the borrowed capital for the let-out property during the year"},{"key":"B","text":"Deductible only up to Rs.30,000 per year in the aggregate, whatever the actual interest paid or payable on the borrowed capital for the let-out property during the year"},{"key":"C","text":"In FULL, without any monetary limit (though the house-property loss set-off against other heads is capped at Rs.2 lakh)"},{"key":"D","text":"Not deductible at all under Section 24(b), whatever the actual interest paid or payable on the borrowed capital for the let-out property during the year"}],"answer":"C","explanation":"For let-out property the whole interest is deductible; the Rs.2 lakh cap applies to set-off of the resulting loss against other heads (s.71(3A)).","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Interest on borrowed capital for acquisition/construction of a LET-OUT property is deductible under s.24(b):","options":["Up to Rs.2 lakh only","Up to Rs.30,000","In FULL, without any monetary limit (though the house-property loss set-off against other heads is capped at Rs.2 lakh)","Not deductible"],"answer":2,"explanation":"For let-out property the whole interest is deductible; the Rs.2 lakh cap applies to set-off of the resulting loss against other heads (s.71(3A)).","revision":"original","contentSignature":"511ba78b4fd8321c2d7023cfe28b75edab80c75365042858ff4b1006547551d8"}]},{"id":107,"stem":"For a SELF-OCCUPIED property, the deduction for interest on borrowed capital (loan taken on/after 1-4-1999 for acquisition/construction completed within 5 years) is capped at:","options":[{"key":"A","text":"Rs.30,000 per year (old regime)"},{"key":"B","text":"Nil in all the regimes alike"},{"key":"C","text":"Rs.2,00,000 per year (old regime)"},{"key":"D","text":"Rs.5,00,000 per year (old regime)"}],"answer":"C","explanation":"Old regime: Rs.2 lakh for self-occupied (Rs.30,000 if the loan is pre-1-4-1999 or for repair/renovation). Under the NEW regime, self-occupied interest is NOT deductible at all.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"For a SELF-OCCUPIED property, the deduction for interest on borrowed capital (loan taken on/after 1-4-1999 for acquisition/construction completed within 5 years) is capped at:","options":["Rs.30,000","Nil in all regimes","Rs.2,00,000 per year (old regime)","Rs.5,00,000"],"answer":2,"explanation":"Old regime: Rs.2 lakh for self-occupied (Rs.30,000 if the loan is pre-1-4-1999 or for repair/renovation). Under the NEW regime, self-occupied interest is NOT deductible at all.","revision":"original","contentSignature":"cb0a0a77a5bd4ba3da67a96827bb14004b010979cb776ba4642bcb6231c0b713"}]},{"id":108,"stem":"From AY 2025-26, the number of houses an individual/HUF can treat as SELF-OCCUPIED (annual value nil) is:","options":[{"key":"A","text":"TWO"},{"key":"B","text":"Three"},{"key":"C","text":"One"},{"key":"D","text":"Unlimited"}],"answer":"A","explanation":"The Finance Act 2025 removed the s.23(2) conditionalities - up to two houses can have nil annual value; additional houses are deemed let out.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified"},{"id":109,"stem":"Pre-construction period interest is deductible:","options":[{"key":"A","text":"Fully in the year of acquisition or completion itself, in one single deduction, within the overall s.24(b) limits applicable for that year"},{"key":"B","text":"Never deductible under s.24(b) at all, in any year, within or outside the overall s.24(b) limits applicable for that year"},{"key":"C","text":"Over TEN equal annual instalments beginning from the year of acquisition or completion, within the overall s.24(b) limits applicable for that year"},{"key":"D","text":"In FIVE equal annual instalments beginning from the year of acquisition/completion, within the overall s.24(b) limits"}],"answer":"D","explanation":"Interest for the period before the year of completion is aggregated and allowed in five equal instalments from the completion year.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Pre-construction period interest is deductible:","options":["Fully in the year of completion","Never","Over 10 years","In FIVE equal annual instalments beginning from the year of acquisition/completion, within the overall s.24(b) limits"],"answer":3,"explanation":"Interest for the period before the year of completion is aggregated and allowed in five equal instalments from the completion year.","revision":"original","contentSignature":"deae5f561cbd81c3087e12a0123e3bb023b1a959e1a8e8b0def1ea858ccfab53"}]},{"id":110,"stem":"Under the NEW tax regime (s.115BAC), interest on borrowed capital for a LET-OUT house property is:","options":[{"key":"A","text":"Deductible only up to Rs.2 lakh per year, and the resulting loss can be set off against other heads"},{"key":"B","text":"Allowed only for one house property, and the resulting loss can be set off against other heads"},{"key":"C","text":"Fully disallowed, so no deduction for such interest is available at all under the new regime"},{"key":"D","text":"Deductible, but the resulting house-property loss CANNOT be set off against other heads nor carried forward"}],"answer":"D","explanation":"The new regime permits let-out interest deduction, but any house-property loss cannot be set off against other heads and cannot be carried forward.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Under the NEW tax regime (s.115BAC), interest on borrowed capital for a LET-OUT house property is:","options":["Deductible up to Rs.2 lakh","Allowed only for one house","Fully disallowed","Deductible, but the resulting house-property loss CANNOT be set off against other heads nor carried forward"],"answer":3,"explanation":"The new regime permits let-out interest deduction, but any house-property loss cannot be set off against other heads and cannot be carried forward.","revision":"original","contentSignature":"c2feb0898daafa1a05d006509f534d6ab707d1b48fd812f2b07e4bc9777f8573"}]},{"id":111,"stem":"Under the NEW tax regime, interest on borrowed capital for a SELF-OCCUPIED house is:","options":[{"key":"A","text":"Fully deductible"},{"key":"B","text":"NOT deductible at all"},{"key":"C","text":"Deductible up to Rs.30,000"},{"key":"D","text":"Deductible up to Rs.2 lakh"}],"answer":"B","explanation":"Section 115BAC(2) bars the s.24(b) deduction for self-occupied property; let-out interest remains deductible.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified"},{"id":112,"stem":"A owns a house: municipal value Rs.1,80,000, fair rent Rs.2,00,000, standard rent Rs.1,92,000, actual rent Rs.17,000 p.m. Gross annual value is:","options":[{"key":"A","text":"Rs.1,92,000"},{"key":"B","text":"Rs.2,00,000"},{"key":"C","text":"Rs.2,04,000"},{"key":"D","text":"Rs.1,80,000"}],"answer":"C","explanation":"Expected rent = higher of MV (1,80,000) and FR (2,00,000), capped at SR = 1,92,000. Actual rent = 17,000 x 12 = 2,04,000. GAV = higher of the two = Rs.2,04,000.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified"},{"id":113,"stem":"Net annual value of the above house (municipal taxes paid by owner Rs.12,000) is:","options":[{"key":"A","text":"Rs.1,80,000"},{"key":"B","text":"Rs.1,92,000"},{"key":"C","text":"Rs.2,00,000"},{"key":"D","text":"Rs.2,04,000"}],"answer":"B","explanation":"NAV = GAV 2,04,000 - municipal taxes paid by owner 12,000 = Rs.1,92,000.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified"},{"id":114,"stem":"Income from the above house (interest on loan for the year Rs.1,50,000) is:","options":[{"key":"A","text":"Rs.1,92,000"},{"key":"B","text":"(-) Rs.15,600"},{"key":"C","text":"Rs.42,000"},{"key":"D","text":"Rs.57,600"}],"answer":"B","explanation":"NAV 1,92,000 - 30% standard deduction 57,600 - interest 1,50,000 = (-) Rs.15,600 (a loss).","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified"},{"id":115,"stem":"A house property remains UNOCCUPIED for the whole year because of the owner employment/business at another place - its annual value is taken as:","options":[{"key":"A","text":"The municipal value of the property, as for any let-out house"},{"key":"B","text":"The fair rent of the property, as for any let-out house"},{"key":"C","text":"The standard rent of the property, as for any let-out house"},{"key":"D","text":"NIL - treated as self-occupied (one of the two permitted houses)"}],"answer":"D","explanation":"Section 23(2): a house that cannot be occupied owing to employment/business elsewhere is treated as self-occupied with nil annual value.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A house property remains UNOCCUPIED for the whole year because of the owner employment/business at another place - its annual value is taken as:","options":["Municipal value","Fair rent","Standard rent","NIL - treated as self-occupied (one of the two permitted houses)"],"answer":3,"explanation":"Section 23(2): a house that cannot be occupied owing to employment/business elsewhere is treated as self-occupied with nil annual value.","revision":"original","contentSignature":"0e8cc8bf20bd1f5b6a69ae7abbe9867c2648aa9cd6c9dd933d003fb92c0c1187"}]},{"id":116,"stem":"Deemed ownership for house property tax does NOT arise for:","options":[{"key":"A","text":"A holder of an impartible estate"},{"key":"B","text":"A member of a co-operative society to whom the building is allotted"},{"key":"C","text":"Transfer to a spouse (otherwise than for adequate consideration) or to a minor child (not being a married daughter)"},{"key":"D","text":"A LANDLORD who lets out his own building"}],"answer":"D","explanation":"Section 27 deems certain non-owners to be owners (transfers to spouse/minor child, impartible estate holder, co-op members, s.53A part-performance possessors). An ordinary owner-landlord is the actual, not deemed, owner.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified"},{"id":117,"stem":"Property used by the assessee for his OWN business or profession is:","options":[{"key":"A","text":"Taxed under the head capital gains every year, on a notional basis, as if the property were sold and repurchased at its market value at the end of each previous year"},{"key":"B","text":"Taxed under the head income from house property on its notional rent, exactly as if the property had been let out to a tenant at the market rent for the whole of the year"},{"key":"C","text":"Taxed under this head on its notional annual value, with a flat deduction of 30% towards repairs"},{"key":"D","text":"EXCLUDED from house-property tax - its value is not taxed under this head (the business gets no notional rent deduction either)"}],"answer":"D","explanation":"Section 22 excludes property occupied for the assessee own business/profession from the house-property head.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Property used by the assessee for his OWN business or profession is:","options":["Taxed as capital gains","Taxed under house property","Taxed at 30% flat","EXCLUDED from house-property tax - its value is not taxed under this head (the business gets no notional rent deduction either)"],"answer":3,"explanation":"Section 22 excludes property occupied for the assessee own business/profession from the house-property head.","revision":"original","contentSignature":"6e1b4c5a1e29357d378dd2ac62b4e0f006572762bb7dcc076778187936d03d24"}]},{"id":118,"stem":"Unrealised rent is deducted from actual rent while computing GAV only if:","options":[{"key":"A","text":"Prescribed Rule 4 conditions are met - tenancy bona fide, defaulting tenant vacated/steps taken to compel vacation, not occupying any other property of the assessee, and legal recovery steps taken or proof that they are futile"},{"key":"B","text":"The tenant is poor and unable to pay the rent"},{"key":"C","text":"The owner waives the rent informally, without any legal recovery steps"},{"key":"D","text":"Never deductible from actual rent in any case whatsoever"}],"answer":"A","explanation":"Rule 4 lists strict conditions for excluding unrealised rent; later recovery is taxed in the year of receipt (s.25A) after a flat 30% deduction.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Unrealised rent is deducted from actual rent while computing GAV only if:","options":["Prescribed Rule 4 conditions are met - tenancy bona fide, defaulting tenant vacated/steps taken to compel vacation, not occupying any other property of the assessee, and legal recovery steps taken or proof that they are futile","The tenant is poor","The owner waives it informally","Never deductible"],"answer":0,"explanation":"Rule 4 lists strict conditions for excluding unrealised rent; later recovery is taxed in the year of receipt (s.25A) after a flat 30% deduction.","revision":"original","contentSignature":"c9687e1a74d760d22cd142b371291d10cef854910aad6b87e729939771ca915b"}]},{"id":119,"stem":"Arrears of rent and unrealised rent RECOVERED subsequently are taxed (s.25A/25AA):","options":[{"key":"A","text":"Never taxed at all, in any year, since the ownership of the property has ceased by the time the arrears or the unrealised rent are actually recovered by the former owner"},{"key":"B","text":"In the year of receipt, but under the head capital gains"},{"key":"C","text":"In the year of RECEIPT, as income from house property, after a flat 30% deduction - even if the assessee no longer owns the property"},{"key":"D","text":"In the year to which they actually relate, by reopening the assessment of that earlier year and recomputing the income from house property of that year with the recovered amount"}],"answer":"C","explanation":"Subsequent recovery is taxed on receipt under house property (s.25A) or other sources for non-owners, with a 30% flat deduction.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Arrears of rent and unrealised rent RECOVERED subsequently are taxed (s.25A/25AA):","options":["Never taxed","As capital gains","In the year of RECEIPT, as income from house property, after a flat 30% deduction - even if the assessee no longer owns the property","In the year to which they relate"],"answer":2,"explanation":"Subsequent recovery is taxed on receipt under house property (s.25A) or other sources for non-owners, with a 30% flat deduction.","revision":"original","contentSignature":"b84f289426cd6b3e4144adf24dd5a887e75d1cfe8417ffa6507fd82cac317a42"}]},{"id":120,"stem":"Composite rent (rent for building PLUS services like lift, security, electricity) is split and taxed as:","options":[{"key":"A","text":"Entirely under the head income from house property, including the portion attributable to services like lift, security and electricity, with no splitting of the composite rent at all"},{"key":"B","text":"Entirely under the head salaries, in the hands of the recipient, as if the composite rent were remuneration for personal services rendered during the year"},{"key":"C","text":"Entirely exempt from tax, being a composite receipt that the Act cannot attribute to any single head of income"},{"key":"D","text":"House property for the building portion; the SERVICES portion under other sources or business income"}],"answer":"D","explanation":"Composite letting is severable: rent attributable to the building is house property; charges for amenities/services are taxed separately.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Composite rent (rent for building PLUS services like lift, security, electricity) is split and taxed as:","options":["Entirely house property","Entirely salary","Entirely exempt","House property for the building portion; the SERVICES portion under other sources or business income"],"answer":3,"explanation":"Composite letting is severable: rent attributable to the building is house property; charges for amenities/services are taxed separately.","revision":"original","contentSignature":"4af00868d0e7ceff39d889ca8fe1529a9e1921f2fd41b29de3e4b4202c5a6364"}]},{"id":121,"stem":"The annual value of one SELF-OCCUPIED house is taken as:","options":[{"key":"A","text":"Fair rent"},{"key":"B","text":"Standard rent"},{"key":"C","text":"Municipal value"},{"key":"D","text":"NIL"}],"answer":"D","explanation":"Section 23(2): the annual value of a self-occupied house (up to two houses) is nil; only the interest deduction (old regime) can produce a loss.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified"},{"id":122,"stem":"A house owned by a person is let out for part of the year and self-occupied for part - the annual value is computed:","options":[{"key":"A","text":"As if the property were two separate houses, one let out and one self-occupied, each with its own annual value computed for the full year"},{"key":"B","text":"At double the actual rent received for the let period, as a penalty for the mixed use of the property during the year"},{"key":"C","text":"As if the property were fully self-occupied for the whole year, with a nil annual value, ignoring the let period altogether"},{"key":"D","text":"As if let out for the WHOLE year, but considering only the actual rent for the let period (benefit of self-occupation preserved)"}],"answer":"D","explanation":"Section 23(3): where a single house is let for part and self-occupied for part, the expected rent for the whole year is compared with actual rent for the let period.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A house owned by a person is let out for part of the year and self-occupied for part - the annual value is computed:","options":["As two separate houses","At double rent","As fully self-occupied","As if let out for the WHOLE year, but considering only the actual rent for the let period (benefit of self-occupation preserved)"],"answer":3,"explanation":"Section 23(3): where a single house is let for part and self-occupied for part, the expected rent for the whole year is compared with actual rent for the let period.","revision":"original","contentSignature":"da7d0d76c8f58a6cfcc9561b5b795f04659ecd32d8bbbe14095b8d6f69f59219"}]},{"id":123,"stem":"Which of the following losses can be set off against SALARY income in the same year?","options":[{"key":"A","text":"House property loss up to Rs.2,00,000"},{"key":"B","text":"Business loss of a discontinued business"},{"key":"C","text":"Capital loss"},{"key":"D","text":"Speculation loss"}],"answer":"A","explanation":"Inter-head set-off of house-property loss against any other head is capped at Rs.2 lakh per year (s.71(3A)); the excess carries forward for 8 years.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified"},{"id":124,"stem":"Loss from house property can be carried forward for:","options":[{"key":"A","text":"Indefinitely, until fully set off, against any head of income"},{"key":"B","text":"4 assessment years, to be set off against any head of income"},{"key":"C","text":"8 assessment years, to be set off only against house-property income"},{"key":"D","text":"Cannot be carried forward at all; it lapses at once"}],"answer":"C","explanation":"Section 71B: unabsorbed house-property loss (mainly interest) carries forward for 8 AYs and sets off only against house-property income.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Loss from house property can be carried forward for:","options":["Indefinitely","4 years","8 assessment years, to be set off only against house-property income","Cannot be carried forward"],"answer":2,"explanation":"Section 71B: unabsorbed house-property loss (mainly interest) carries forward for 8 AYs and sets off only against house-property income.","revision":"original","contentSignature":"7bac33e6bcdcf816f47690b3ecbb16c32c53105711c6a83bf7f096ec4089e3c9"}]},{"id":125,"stem":"Rent received for a plot of LAND (no building) is taxed under:","options":[{"key":"A","text":"Income from OTHER SOURCES (house property tax needs a building)"},{"key":"B","text":"Income from house property, like rent for a building"},{"key":"C","text":"Agricultural income, without any further conditions"},{"key":"D","text":"Capital gains, on a notional basis every year"}],"answer":"A","explanation":"Section 22 requires a building or land APPURTENANT to a building; bare land rent falls under other sources.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Rent received for a plot of LAND (no building) is taxed under:","options":["Income from OTHER SOURCES (house property tax needs a building)","Income from house property","Agricultural income always","Capital gains"],"answer":0,"explanation":"Section 22 requires a building or land APPURTENANT to a building; bare land rent falls under other sources.","revision":"original","contentSignature":"8bccffc6a28c1ffe87cfb5c252d7f8b8d1ec80d69eccd434f4a92c7fe009e75f"}]},{"id":126,"stem":"Income of a farm house used as a dwelling by the receiver of agricultural income is:","options":[{"key":"A","text":"Taxed at the flat rate of 30% as ordinary income"},{"key":"B","text":"Treated as AGRICULTURAL income (s.2(1A)(c)), subject to conditions"},{"key":"C","text":"Clubbed with the income of the spouse under Section 64"},{"key":"D","text":"Taxed under the head income from house property on its full annual value, without any reference to the agricultural character of the land on which it stands"}],"answer":"B","explanation":"A farm building used as a dwelling/store by a cultivator or rent-receiver, near the land, qualifies as agricultural income.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Income of a farm house used as a dwelling by the receiver of agricultural income is:","options":["Taxed at 30%","Treated as AGRICULTURAL income (s.2(1A)(c)), subject to conditions","Clubbed with spouse","Taxed as house property"],"answer":1,"explanation":"A farm building used as a dwelling/store by a cultivator or rent-receiver, near the land, qualifies as agricultural income.","revision":"original","contentSignature":"d181cb504ae01e8e5535be6e714bc40992a6f2b5415caed55faff0b966019b38"}]},{"id":127,"stem":"Municipal value of a property is determined by:","options":[{"key":"A","text":"The seller of the property, in his sale documents"},{"key":"B","text":"The bank that has financed the purchase of the property"},{"key":"C","text":"The Income Tax Officer, in his assessment records for the year"},{"key":"D","text":"The MUNICIPAL/local authority for levying municipal taxes"}],"answer":"D","explanation":"Municipal valuation for local-body taxes is the starting figure for expected rent.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Municipal value of a property is determined by:","options":["The seller","The bank","The Income Tax Officer","The MUNICIPAL/local authority for levying municipal taxes"],"answer":3,"explanation":"Municipal valuation for local-body taxes is the starting figure for expected rent.","revision":"original","contentSignature":"92107f39d4c680477626f8d4a0f64213f355287b222209352ab5b97e0dffa1c4"}]},{"id":128,"stem":"Interest on a FRESH loan taken to repay an earlier home loan is:","options":[{"key":"A","text":"Not deductible under s.24(b) at all, since the loan is a fresh one and not the original borrowing for acquisition or construction of the property"},{"key":"B","text":"Treated as principal repayment of the new loan, and dealt with only under Section 80C"},{"key":"C","text":"DEDUCTIBLE under s.24(b) as interest on borrowed capital"},{"key":"D","text":"Deductible only where the property is self-occupied, and not where it is let out"}],"answer":"C","explanation":"Interest on a loan raised to repay the original acquisition/construction loan qualifies for deduction.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Interest on a FRESH loan taken to repay an earlier home loan is:","options":["Not deductible","Treated as principal","DEDUCTIBLE under s.24(b) as interest on borrowed capital","Deductible only for self-occupied"],"answer":2,"explanation":"Interest on a loan raised to repay the original acquisition/construction loan qualifies for deduction.","revision":"original","contentSignature":"1922af9ad9db1f2c1908be0d4eb4ae7cabe5fbf5c503fa6797aa6875c90395e6"}]},{"id":129,"stem":"Income under \"Profits and gains of business or profession\" is charged under Section:","options":[{"key":"A","text":"28"},{"key":"B","text":"14"},{"key":"C","text":"45"},{"key":"D","text":"56"}],"answer":"A","explanation":"Section 28 is the charging section for business/profession income; ss.30-44D allow/deny deductions in computing it.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":130,"stem":"Which of the following is an essential feature of \"business\" income?","options":[{"key":"A","text":"It must involve manufacturing activity only, and trading, services or other organised commercial activity can never amount to business"},{"key":"B","text":"A continuous, organised activity carried on with a PROFIT MOTIVE (though profit is not necessary in every year)"},{"key":"C","text":"It must be an illegal activity, since lawful activity is taxed under other heads"},{"key":"D","text":"It must be carried on from a fixed office premises, and activity carried on from home or in the field is never business"}],"answer":"B","explanation":"Business implies a course of dealings with a profit motive; even a single adventure in the nature of trade can be business income.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which of the following is an essential feature of \"business\" income?","options":["It must involve manufacturing only","A continuous, organised activity carried on with a PROFIT MOTIVE (though profit is not necessary in every year)","It must be illegal","It must be carried on from an office"],"answer":1,"explanation":"Business implies a course of dealings with a profit motive; even a single adventure in the nature of trade can be business income.","revision":"original","contentSignature":"6b65ee844c5bdc074f89ae7e2fc3186afe60006bceabc8a9696257413d3537c1"}]},{"id":131,"stem":"Depreciation under Section 32 is allowed on:","options":[{"key":"A","text":"The replacement cost of the asset, asset by asset, whatever the written down value of the block may be, and whatever the method prescribed for the undertaking"},{"key":"B","text":"The straight line method for all the assets, block or no block"},{"key":"C","text":"The WRITTEN DOWN VALUE (WDV) method on a BLOCK OF ASSETS (SLM only for power-generating undertakings)"},{"key":"D","text":"The market value of each individual asset, computed separately"}],"answer":"C","explanation":"Section 32 mandates WDV on blocks of assets; power generation/distribution undertakings may opt for SLM. Units-of-production and sum-of-digits methods are NOT prescribed.","source":"Source label not detected","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Depreciation under Section 32 is allowed on:","options":["Replacement cost","The straight line method for all assets","The WRITTEN DOWN VALUE (WDV) method on a BLOCK OF ASSETS (SLM only for power-generating undertakings)","Market value of each asset"],"answer":2,"explanation":"Section 32 mandates WDV on blocks of assets; power generation/distribution undertakings may opt for SLM. Units-of-production and sum-of-digits methods are NOT prescribed.","revision":"original","contentSignature":"ef5b8c780851fdfdbcb5ad39f194b63eea04b2732e86c064155cbcd0adfe2082"}]},{"id":132,"stem":"\"Block of assets\" means:","options":[{"key":"A","text":"A group of assets of the same class (tangible or intangible) in respect of which the SAME RATE of depreciation is prescribed"},{"key":"B","text":"A group of buildings situated in one city, whatever their class and whatever the rate of depreciation prescribed for them, and including every other asset of the assessee in that city"},{"key":"C","text":"Only items of plant and machinery, whatever the rate of depreciation prescribed for them, and never buildings, furniture or intangible assets of any kind whatever"},{"key":"D","text":"All the assets of the company, whatever their class, whether tangible or intangible, and whatever the rate of depreciation prescribed for them under the Rules"}],"answer":"A","explanation":"Section 2(11): assets of the same class carrying the same rate form one block; depreciation is computed block-wise, not asset-wise.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"\"Block of assets\" means:","options":["A group of assets of the same class (tangible or intangible) in respect of which the SAME RATE of depreciation is prescribed","A group of buildings in one city","Only plant and machinery","All assets of the company"],"answer":0,"explanation":"Section 2(11): assets of the same class carrying the same rate form one block; depreciation is computed block-wise, not asset-wise.","revision":"original","contentSignature":"4eef3319359387a668770fb61f7e10064066d95bd237d16e399271f08d656143"}]},{"id":133,"stem":"The general rate of depreciation on PLANT AND MACHINERY (WDV) is:","options":[{"key":"A","text":"40%"},{"key":"B","text":"10%"},{"key":"C","text":"25%"},{"key":"D","text":"15%"}],"answer":"D","explanation":"The general P&M block carries 15%; computers and computer software carry 40%.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":134,"stem":"Depreciation rate on COMPUTERS including computer software (WDV) is:","options":[{"key":"A","text":"15%"},{"key":"B","text":"40%"},{"key":"C","text":"25%"},{"key":"D","text":"60%"}],"answer":"B","explanation":"Computers, peripherals and software are depreciated at 40% WDV.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":135,"stem":"Depreciation rate on FURNITURE and FITTINGS (WDV) is:","options":[{"key":"A","text":"15%"},{"key":"B","text":"10%"},{"key":"C","text":"20%"},{"key":"D","text":"5%"}],"answer":"B","explanation":"Furniture and fittings (including electrical fittings) are depreciated at 10% WDV.","source":"Source label not detected","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":136,"stem":"Depreciation on buildings (other than purely temporary erections) is allowed at:","options":[{"key":"A","text":"5% for residential buildings and 10% for other buildings (WDV)"},{"key":"B","text":"15% for all buildings alike, whether residential or not (WDV)"},{"key":"C","text":"Nil - buildings are not depreciable at all, whatever their use"},{"key":"D","text":"20% for all buildings alike, whether residential or not (WDV)"}],"answer":"A","explanation":"Residential buildings 5%, non-residential buildings 10%, purely temporary structures 40%.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Depreciation on buildings (other than purely temporary erections) is allowed at:","options":["5% for residential buildings and 10% for other buildings (WDV)","15% for all","Nil","20% for all"],"answer":0,"explanation":"Residential buildings 5%, non-residential buildings 10%, purely temporary structures 40%.","revision":"original","contentSignature":"c7a9182d8938fb408e306f730e0a5612f6f215d80123e19f35c95cff454dce4f"}]},{"id":137,"stem":"INTANGIBLE assets like patents, trademarks, licences, know-how, franchises and goodwill (acquired) are depreciated at:","options":[{"key":"A","text":"25%"},{"key":"B","text":"10%"},{"key":"C","text":"40%"},{"key":"D","text":"Nil"}],"answer":"A","explanation":"Section 32(1)(ii) allows 25% WDV depreciation on specified intangible assets; self-generated goodwill gets none. (Post Finance Act 2021, goodwill of a business is NOT a depreciable asset and is removed from the block.)","source":"Source label not detected","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":138,"stem":"An asset purchased and put to use for LESS THAN 180 days in the year of acquisition gets depreciation of:","options":[{"key":"A","text":"Nil"},{"key":"B","text":"HALF of the normal rate"},{"key":"C","text":"Full year rate"},{"key":"D","text":"Double rate"}],"answer":"B","explanation":"The 180-day rule: assets used for less than 180 days in the year of acquisition earn only half the normal depreciation.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":139,"stem":"If all assets of a block are sold and the sale proceeds are LESS than the WDV of the block, the difference is:","options":[{"key":"A","text":"A short-term CAPITAL LOSS (terminal loss) - the block ceases to exist"},{"key":"B","text":"Treated as deemed profit under Section 41 in that year, as if a deduction were recovered"},{"key":"C","text":"Treated as a revenue loss of the business in that year, set off like any other loss"},{"key":"D","text":"Ignored altogether, with no tax effect at all in any year"}],"answer":"A","explanation":"When the block ceases to exist with a deficit, the shortfall is a capital loss; if proceeds exceed WDV, the excess is short-term capital gain u/s 50.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"If all assets of a block are sold and the sale proceeds are LESS than the WDV of the block, the difference is:","options":["A short-term CAPITAL LOSS (terminal loss) - the block ceases to exist","Treated as deemed profit u/s 41","Treated as revenue loss","Ignored"],"answer":0,"explanation":"When the block ceases to exist with a deficit, the shortfall is a capital loss; if proceeds exceed WDV, the excess is short-term capital gain u/s 50.","revision":"original","contentSignature":"35b424556852f18332f79bec38e4d4ba418eed0f5cabbc36b7b5dbc80e8281ee"}]},{"id":140,"stem":"Unabsorbed depreciation is carried forward:","options":[{"key":"A","text":"Never carried forward at all - it lapses in the very year it arises, like a speculation loss"},{"key":"B","text":"For 4 assessment years only, and then it lapses, like a speculation loss"},{"key":"C","text":"For 8 assessment years only, and then it lapses, like a business loss"},{"key":"D","text":"INDEFINITELY, and can be set off against any head (except salary) in later years"}],"answer":"D","explanation":"Section 32(2): unabsorbed depreciation carries forward without time limit; it is deemed part of current depreciation. In set-off priority, current depreciation comes before brought-forward business loss.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Unabsorbed depreciation is carried forward:","options":["Never","For 4 years","For 8 years","INDEFINITELY, and can be set off against any head (except salary) in later years"],"answer":3,"explanation":"Section 32(2): unabsorbed depreciation carries forward without time limit; it is deemed part of current depreciation. In set-off priority, current depreciation comes before brought-forward business loss.","revision":"original","contentSignature":"7ee3196cd18a1d831ace5ba74e68821108919193997b4d8a5befb56bf181dadb"}]},{"id":141,"stem":"ADDITIONAL DEPRECIATION under Section 32(1)(iia) for new plant and machinery installed by a manufacturing concern is:","options":[{"key":"A","text":"10% of the actual cost of the asset in the year of its installation and use"},{"key":"B","text":"Nil - additional depreciation has been withdrawn for all undertakings"},{"key":"C","text":"50% of the actual cost of the asset"},{"key":"D","text":"20% of actual cost (35% in notified backward areas of specified States)"}],"answer":"D","explanation":"Additional depreciation of 20% (35% for notified backward areas) applies to new P&M for manufacturing/production undertakings; half rate if used less than 180 days, balance next year.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"ADDITIONAL DEPRECIATION under Section 32(1)(iia) for new plant and machinery installed by a manufacturing concern is:","options":["10%","Nil","50%","20% of actual cost (35% in notified backward areas of specified States)"],"answer":3,"explanation":"Additional depreciation of 20% (35% for notified backward areas) applies to new P&M for manufacturing/production undertakings; half rate if used less than 180 days, balance next year.","revision":"original","contentSignature":"674341e870557622e7f584984eacb9d816a987d40b25b43951922a4b10a9cfdf"}]},{"id":142,"stem":"Section 35 allows a 100% deduction (weighted deduction withdrawn) for:","options":[{"key":"A","text":"Capital expenditure on decorating the office premises of the business, even where it has nothing to do with any research activity of the assessee at all"},{"key":"B","text":"The personal medical expenses of the proprietor and his family, even where they have nothing to do with any research activity of the assessee at all"},{"key":"C","text":"Revenue and capital expenditure on SCIENTIFIC RESEARCH related to the business (in-house research for approved companies)"},{"key":"D","text":"All donations of whatever kind made by the assessee, even where they have nothing to do with any research activity of the assessee at all"}],"answer":"C","explanation":"In-house scientific research expenditure (revenue and capital, except land) related to the business is deductible at 100%; approved-Institution weighted deductions have been withdrawn.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Section 35 allows a 100% deduction (weighted deduction withdrawn) for:","options":["Capital expenditure on office decoration","Personal medical expenses","Revenue and capital expenditure on SCIENTIFIC RESEARCH related to the business (in-house research for approved companies)","All donations"],"answer":2,"explanation":"In-house scientific research expenditure (revenue and capital, except land) related to the business is deductible at 100%; approved-Institution weighted deductions have been withdrawn.","revision":"original","contentSignature":"08038e7b4a5305a189e97edddff798a07d549ffe512f78bf47b8000519b29251"}]},{"id":143,"stem":"Deduction under Section 40(a)(ia) is DENIED to the extent of ________ where TDS is not deducted/deposited on payments to residents:","options":[{"key":"A","text":"100% of the expense, permanently disallowed even if the TDS is deducted and paid later"},{"key":"B","text":"30% of the expense (allowed in the year the TDS is deducted and paid)"},{"key":"C","text":"Nil - the deduction is never denied for a TDS default of any kind"},{"key":"D","text":"50% of the expense, however serious the TDS default"}],"answer":"B","explanation":"Resident payments: 30% of the expense is disallowed in the year of default and allowed in the year TDS compliance happens; non-resident TDS default disallows 100%.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Deduction under Section 40(a)(ia) is DENIED to the extent of ________ where TDS is not deducted/deposited on payments to residents:","options":["100% of the expense","30% of the expense (allowed in the year the TDS is deducted and paid)","Nil","50%"],"answer":1,"explanation":"Resident payments: 30% of the expense is disallowed in the year of default and allowed in the year TDS compliance happens; non-resident TDS default disallows 100%.","revision":"original","contentSignature":"0a3bfb86751f52a103f9a3ea6db7100b4626e59346f811c5b85eed897782f2fd"}]},{"id":144,"stem":"Salary and interest paid by a firm to its PARTNERS are deductible under Section 40(b) subject to:","options":[{"key":"A","text":"Any amount the partnership deed fixes, without any ceiling on interest or salary at all, so long as the payment is authorised by the deed and made to a working partner"},{"key":"B","text":"Interest up to 10% p.a. and salary without any monetary limit at all, so long as the payment is authorised by the deed and made to a working partner"},{"key":"C","text":"No limits at all on either interest or salary, so long as the payment is authorised by the deed and made to a working partner"},{"key":"D","text":"Interest up to 12% p.a. simple, and salary limited to: first Rs.3,00,000 of book profit - Rs.1,50,000 or 90% whichever is more; on the balance - 60%"}],"answer":"D","explanation":"Section 40(b): interest on partner capital capped at 12% p.a. simple; working-partner remuneration within the book-profit slabs (first Rs.3L: Rs.1.5L or 90%, balance 60%).","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Salary and interest paid by a firm to its PARTNERS are deductible under Section 40(b) subject to:","options":["Any amount the deed fixes","10% interest and unlimited salary","No limits","Interest up to 12% p.a. simple, and salary limited to: first Rs.3,00,000 of book profit - Rs.1,50,000 or 90% whichever is more; on the balance - 60%"],"answer":3,"explanation":"Section 40(b): interest on partner capital capped at 12% p.a. simple; working-partner remuneration within the book-profit slabs (first Rs.3L: Rs.1.5L or 90%, balance 60%).","revision":"original","contentSignature":"684feac129c4e11e19c622a27bd236b8f09cf1bced954e2c2e37bcaccd3f53a1"}]},{"id":145,"stem":"Book profit for Section 40(b) means:","options":[{"key":"A","text":"Net profit as per P&L increased by partner remuneration debited (if already deducted) and adjusted as per s.28-44D"},{"key":"B","text":"The profit remaining after charging the income-tax paid for the year, without adding back any partner remuneration debited or making any adjustment under Sections 28 to 44D at all"},{"key":"C","text":"The gross turnover or gross receipts of the firm for the year, without adding back any partner remuneration debited or making any adjustment under Sections 28 to 44D at all"},{"key":"D","text":"The capital employed in the firm as at the year end, without adding back any partner remuneration debited or making any adjustment under Sections 28 to 44D at all"}],"answer":"A","explanation":"Book profit is the s.28-44D computed profit before partner remuneration; the salary limits apply to that figure.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Book profit for Section 40(b) means:","options":["Net profit as per P&L increased by partner remuneration debited (if already deducted) and adjusted as per s.28-44D","Tax paid profit","Gross turnover","Capital employed"],"answer":0,"explanation":"Book profit is the s.28-44D computed profit before partner remuneration; the salary limits apply to that figure.","revision":"original","contentSignature":"9ac0b8d755adf1fc63614c3ded566d0eb3e6cfa098bfce135e01c1ce9357953d"}]},{"id":146,"stem":"A firm has book profit of Rs.4,00,000 (before partner remuneration). The maximum deductible remuneration to working partners under s.40(b) is:","options":[{"key":"A","text":"Rs.3,60,000"},{"key":"B","text":"Rs.2,40,000"},{"key":"C","text":"Rs.2,70,000"},{"key":"D","text":"Rs.3,30,000"}],"answer":"D","explanation":"First Rs.3,00,000 of book profit: 90% = Rs.2,70,000 (more than the Rs.1,50,000 floor); balance Rs.1,00,000 at 60% = Rs.60,000. Total = 2,70,000 + 60,000 = Rs.3,30,000.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":147,"stem":"Which of the following is DEDUCTIBLE only on ACTUAL PAYMENT under Section 43B?","options":[{"key":"A","text":"Rent paid in cash for the business premises - always deductible on accrual, without any reference to the year of actual payment or the due date of filing the return of income"},{"key":"B","text":"Tax/duty/cess, PF/ESI contributions, bonus to employees, interest on bank loans - allowed only in the year of ACTUAL payment (or before the due date of filing the return)"},{"key":"C","text":"Salaries paid to the staff of the business - always deductible on accrual, without any reference to the year of actual payment or the due date of filing the return of income"},{"key":"D","text":"Depreciation on the assets of the business - always deductible on accrual, without any reference to the year of actual payment or the due date of filing the return of income"}],"answer":"B","explanation":"Section 43B enforces payment-basis deduction for statutory dues and specified items, regardless of the mercantile system followed.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which of the following is DEDUCTIBLE only on ACTUAL PAYMENT under Section 43B?","options":["Rent paid in cash","Tax/duty/cess, PF/ESI contributions, bonus to employees, interest on bank loans - allowed only in the year of ACTUAL payment (or before the due date of filing the return)","Salaries to staff","Depreciation"],"answer":1,"explanation":"Section 43B enforces payment-basis deduction for statutory dues and specified items, regardless of the mercantile system followed.","revision":"original","contentSignature":"63937220d9858157ca0134e5f233d168abe9fee2c5147f8a77b31d53084f022b"}]},{"id":148,"stem":"Section 43B(h) (Finance Act 2023) disallows amounts payable to MICRO and SMALL enterprises unless paid within the time limit in Section 15 of the MSMED Act, which is:","options":[{"key":"A","text":"180 days as agreed (no agreed date: 180 days)"},{"key":"B","text":"90 days as agreed (no agreed date: 90 days)"},{"key":"C","text":"One year as agreed (no agreed date: one year)"},{"key":"D","text":"15 or 45 days as agreed (no agreed date: 15 days)"}],"answer":"D","explanation":"MSMED s.15: payment within the agreed date, which cannot exceed 45 days; without a written agreement, within 15 days. Delay means the deduction moves to the year of actual payment (no return-due-date relief).","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Section 43B(h) (Finance Act 2023) disallows amounts payable to MICRO and SMALL enterprises unless paid within the time limit in Section 15 of the MSMED Act, which is:","options":["180 days","90 days","One year","15 or 45 days as agreed (no agreed date: 15 days)"],"answer":3,"explanation":"MSMED s.15: payment within the agreed date, which cannot exceed 45 days; without a written agreement, within 15 days. Delay means the deduction moves to the year of actual payment (no return-due-date relief).","revision":"original","contentSignature":"32fbad2dda80d5911b01e76f0da281426060e8ad1b545a598da53e9b96a1a96e"}]},{"id":149,"stem":"Cash payments exceeding Rs.________ to a single person in a day are disallowed as expenditure under Section 40A(3):","options":[{"key":"A","text":"2,000 (Rs.5,000 for payments to transport contractors for plying or hiring goods carriages)"},{"key":"B","text":"10,000 (Rs.35,000 for payments to transport contractors for plying/hiring goods carriages)"},{"key":"C","text":"1,00,000 (Rs.2,00,000 for payments to transport contractors for plying or hiring goods carriages)"},{"key":"D","text":"20,000 (Rs.50,000 for payments to transport contractors for plying or hiring goods carriages)"}],"answer":"B","explanation":"Section 40A(3) disallows cash payments above Rs.10,000 (Rs.35,000 for goods-carriage contractors); payment must be by account-payee cheque/draft or electronic mode.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Cash payments exceeding Rs.________ to a single person in a day are disallowed as expenditure under Section 40A(3):","options":["2,000","10,000 (Rs.35,000 for payments to transport contractors for plying/hiring goods carriages)","1,00,000","20,000"],"answer":1,"explanation":"Section 40A(3) disallows cash payments above Rs.10,000 (Rs.35,000 for goods-carriage contractors); payment must be by account-payee cheque/draft or electronic mode.","revision":"original","contentSignature":"70e6678cbca4f789738f0a109493a26cc28e19bcc39b6c6136e229be1a70334c"}]},{"id":150,"stem":"Expenditure of a PERSONAL nature is dealt with under Section:","options":[{"key":"A","text":"Section 44 - partially allowable, as a deemed deduction of the year, without any reference to the personal character of the spending or the wholly-and-exclusively test"},{"key":"B","text":"Section 37(1) - allowable in full, like any other business expense of the year"},{"key":"C","text":"37(1) - NOT allowable, since only expenses wholly and exclusively for business are deductible"},{"key":"D","text":"28 - taxable as business income of the year"}],"answer":"C","explanation":"Section 37(1) is the residuary deduction provision: any revenue expense laid out wholly and exclusively for business (not personal, not capital, not specifically covered) is allowed.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Expenditure of a PERSONAL nature is dealt with under Section:","options":["44 - partial","37 - allowed fully","37(1) - NOT allowable, since only expenses wholly and exclusively for business are deductible","28 - taxable"],"answer":2,"explanation":"Section 37(1) is the residuary deduction provision: any revenue expense laid out wholly and exclusively for business (not personal, not capital, not specifically covered) is allowed.","revision":"original","contentSignature":"9549ea2cb8539ad19591ad2dd7404327099a8ebf9566f0a291eeea84177a584f"}]},{"id":151,"stem":"Which of the following is NOT deductible under Section 37(1)?","options":[{"key":"A","text":"Fines and penalties for BREACH OF LAW (Explanation 1 - expenses for an offence or prohibited by law, and Explanation 3 - penalties for violation of foreign law)"},{"key":"B","text":"Legal expenses incurred on litigation connected with the business, including defending proceedings for breach of contract and resisting demands for tax arising from the business itself"},{"key":"C","text":"Expenditure on the welfare of the staff of the business, including canteen and medical facilities provided at the place of work"},{"key":"D","text":"Expenditure on the advertisement of the products of the business, in print or electronic media of any kind"}],"answer":"A","explanation":"Fines/penalties for infraction of law and expenditure for a purpose that is an offence or prohibited by law are expressly non-deductible.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which of the following is NOT deductible under Section 37(1)?","options":["Fines and penalties for BREACH OF LAW (Explanation 1 - expenses for an offence or prohibited by law, and Explanation 3 - penalties for violation of foreign law)","Legal expenses for business litigation","Staff welfare expense","Advertisement expense"],"answer":0,"explanation":"Fines/penalties for infraction of law and expenditure for a purpose that is an offence or prohibited by law are expressly non-deductible.","revision":"original","contentSignature":"e6fd2c2f845cde037e02a44e40b8897c2810e8f680266773cd0f3effde612b00"}]},{"id":152,"stem":"Corporate social responsibility (CSR) expenditure under s.135 of the Companies Act is:","options":[{"key":"A","text":"NOT deductible under Explanation 2 to Section 37(1)"},{"key":"B","text":"Deductible at 150% of the amount actually spent"},{"key":"C","text":"Treated as fully exempt income of the company"},{"key":"D","text":"Deductible in full under Section 37(1) itself"}],"answer":"A","explanation":"Explanation 2 to s.37(1) bars deduction for CSR spend; it is an application of income, not a business expense.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Corporate social responsibility (CSR) expenditure under s.135 of the Companies Act is:","options":["NOT deductible under Explanation 2 to Section 37(1)","Deductible at 150%","Fully exempt income","Deductible u/s 37(1)"],"answer":0,"explanation":"Explanation 2 to s.37(1) bars deduction for CSR spend; it is an application of income, not a business expense.","revision":"original","contentSignature":"bb9cb5c03285d0bd8331204ed592d29917250934bdc085b898ae9f45f436bc9b"}]},{"id":153,"stem":"Section 44AD presumptive taxation applies to eligible RESIDENT assessees (individuals, HUF, firms other than LLP) with turnover up to:","options":[{"key":"A","text":"Rs.2 crore (Rs.3 crore where cash receipts do not exceed 5% of total receipts)"},{"key":"B","text":"Rs.5 crore (Rs.6 crore where cash receipts do not exceed 5% of total receipts)"},{"key":"C","text":"Rs.50 lakh (Rs.75 lakh where cash receipts do not exceed 5% of total receipts)"},{"key":"D","text":"Rs.1 crore (Rs.2 crore where cash receipts do not exceed 5% of total receipts)"}],"answer":"A","explanation":"The Finance Act 2023 raised the 44AD ceiling to Rs.3 crore where cash receipts are within 5%; otherwise Rs.2 crore.","source":"Source label not detected","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Section 44AD presumptive taxation applies to eligible RESIDENT assessees (individuals, HUF, firms other than LLP) with turnover up to:","options":["Rs.2 crore (Rs.3 crore where cash receipts do not exceed 5% of total receipts)","Rs.5 crore","Rs.50 lakh","Rs.1 crore"],"answer":0,"explanation":"The Finance Act 2023 raised the 44AD ceiling to Rs.3 crore where cash receipts are within 5%; otherwise Rs.2 crore.","revision":"original","contentSignature":"f67eb11619d1d4c735839442bf558432bf42a91150f6690f79c7e9169a5b7e54"}]},{"id":154,"stem":"Under Section 44AD, the presumptive income of an eligible business is:","options":[{"key":"A","text":"5% of the turnover, for every mode of receipt"},{"key":"B","text":"8% of turnover - 6% for receipts by account-payee cheque/draft/electronic clearing received during the year"},{"key":"C","text":"50% of the turnover, for every mode of receipt"},{"key":"D","text":"10% of the turnover, for every mode of receipt"}],"answer":"B","explanation":"8% of turnover/gross receipts is deemed profit, reduced to 6% for digital/banking-channel receipts (digital receipts up to the return due date count).","source":"Source label not detected","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Under Section 44AD, the presumptive income of an eligible business is:","options":["5% of turnover","8% of turnover - 6% for receipts by account-payee cheque/draft/electronic clearing received during the year","50% of turnover","10% of turnover"],"answer":1,"explanation":"8% of turnover/gross receipts is deemed profit, reduced to 6% for digital/banking-channel receipts (digital receipts up to the return due date count).","revision":"original","contentSignature":"d037b4c3b97df147c41cd3e43a2b9e0befcb7c3fe8ad50f43fa3822e82ac35ff"}]},{"id":155,"stem":"Professionals covered by Section 44ADA declare presumptive income of:","options":[{"key":"A","text":"50% of gross receipts, for gross receipts up to Rs.50 lakh (Rs.75 lakh where cash receipts are within 5%)"},{"key":"B","text":"A flat Rs.50 lakh of income, whatever the actual gross receipts of the profession and whatever the mode of receipt of those receipts"},{"key":"C","text":"8% of gross receipts, like an eligible business under Section 44AD, whatever the actual gross receipts and the mode of receipt"},{"key":"D","text":"25% of gross receipts, whatever the actual gross receipts of the profession and whatever the mode of receipt of those receipts"}],"answer":"A","explanation":"Section 44ADA: 50% of gross receipts deemed profit for specified professionals (legal, medical, engineering, architectural, accountancy, technical consultancy, interior decoration etc.).","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Professionals covered by Section 44ADA declare presumptive income of:","options":["50% of gross receipts, for gross receipts up to Rs.50 lakh (Rs.75 lakh where cash receipts are within 5%)","Rs.50 lakh flat","8% of receipts","25% of receipts"],"answer":0,"explanation":"Section 44ADA: 50% of gross receipts deemed profit for specified professionals (legal, medical, engineering, architectural, accountancy, technical consultancy, interior decoration etc.).","revision":"original","contentSignature":"e00272b6aa225a8b5c291f125aa62b942846f042b71979ff0cf8646f3892d455"}]},{"id":156,"stem":"Section 44AE (goods carriage business) deems income at:","options":[{"key":"A","text":"Rs.5,000 per month per vehicle for every class of goods carriage, whatever its gross vehicle weight, for up to 10 vehicles owned by the assessee at any time during the year"},{"key":"B","text":"Rs.7,500 per month per vehicle (heavy goods vehicle: Rs.1,000 per ton of gross vehicle weight per month), for up to 10 vehicles"},{"key":"C","text":"8% of the freight actually received, like a 44AD business"},{"key":"D","text":"1% of the gross receipts of the carriage business"}],"answer":"B","explanation":"44AE: light vehicles Rs.7,500/vehicle/month; heavy vehicles Rs.1,000 per ton per month; limited to assessees owning not more than 10 goods carriages.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Section 44AE (goods carriage business) deems income at:","options":["Rs.5,000 per vehicle","Rs.7,500 per month per vehicle (heavy goods vehicle: Rs.1,000 per ton of gross vehicle weight per month), for up to 10 vehicles","8% of freight","1% of receipts"],"answer":1,"explanation":"44AE: light vehicles Rs.7,500/vehicle/month; heavy vehicles Rs.1,000 per ton per month; limited to assessees owning not more than 10 goods carriages.","revision":"original","contentSignature":"f37f59268bac0abfe9aba723bb2d34ff41ac014bfe0ce8bc8cfbf0ddc755c977"}]},{"id":157,"stem":"Tax audit under Section 44AB is compulsory for a BUSINESS when turnover exceeds:","options":[{"key":"A","text":"Rs.5 crore"},{"key":"B","text":"Rs.20 lakh"},{"key":"C","text":"Rs.40 lakh"},{"key":"D","text":"Rs.1 crore (Rs.10 crore where cash receipts AND cash payments are each within 5% of total)"}],"answer":"D","explanation":"Business audit threshold Rs.1 crore, raised to Rs.10 crore for low-cash businesses (5% test on both receipts and payments); professions: Rs.50 lakh.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Tax audit under Section 44AB is compulsory for a BUSINESS when turnover exceeds:","options":["Rs.5 crore always","Rs.20 lakh","Rs.40 lakh","Rs.1 crore (Rs.10 crore where cash receipts AND cash payments are each within 5% of total)"],"answer":3,"explanation":"Business audit threshold Rs.1 crore, raised to Rs.10 crore for low-cash businesses (5% test on both receipts and payments); professions: Rs.50 lakh.","revision":"original","contentSignature":"402292b185a785878bfee55ea9e16774ecdff27ad3a79f8fca154d5848f7470f"}]},{"id":158,"stem":"A person opting for presumptive taxation under 44AD is:","options":[{"key":"A","text":"Required to get his accounts audited under Section 44AB every year, whatever the turnover and however the income is declared, and to pay advance tax in four quarterly instalments like any other assessee"},{"key":"B","text":"Relieved from maintaining books (s.44AA) and tax audit (s.44AB) if income is declared at 8%/6% and advance tax paid in ONE instalment by 15 March"},{"key":"C","text":"Always required to maintain books of account under Section 44AA, whatever the turnover, and to pay advance tax in four quarterly instalments like any other assessee"},{"key":"D","text":"Exempt from advance tax entirely, though the obligation to maintain books of account under Section 44AA and to get them audited under Section 44AB remains in full"}],"answer":"B","explanation":"Presumptive taxpayers skip books and audit; their advance tax is payable in a single 15-March instalment.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A person opting for presumptive taxation under 44AD is:","options":["Required to get accounts audited","Relieved from maintaining books (s.44AA) and tax audit (s.44AB) if income is declared at 8%/6% and advance tax paid in ONE instalment by 15 March","Always required to maintain books","Exempt from advance tax entirely"],"answer":1,"explanation":"Presumptive taxpayers skip books and audit; their advance tax is payable in a single 15-March instalment.","revision":"original","contentSignature":"a2e5480e0592684e796a5aad506b700cf91fca08a87ed7787717b705481bb19c"}]},{"id":159,"stem":"Speculation business loss can be set off only against:","options":[{"key":"A","text":"House property income of the same year, and of later years"},{"key":"B","text":"Any business income, speculative or not, of the same year"},{"key":"C","text":"Speculation business PROFIT (carried forward 4 years)"},{"key":"D","text":"Salary income of the same year, and of later years"}],"answer":"C","explanation":"Section 73: speculation losses are ring-fenced - set off only against speculation profits, with a 4-year carry forward.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Speculation business loss can be set off only against:","options":["House property income","Any business income","Speculation business PROFIT (carried forward 4 years)","Salary income"],"answer":2,"explanation":"Section 73: speculation losses are ring-fenced - set off only against speculation profits, with a 4-year carry forward.","revision":"original","contentSignature":"271f5e3b20ee2451a1a59130eff48471b56fa82db6b2e8aea20230c9bfd6d9a5"}]},{"id":160,"stem":"Income from letting out PLANT, MACHINERY or FURNITURE (not as a business) is taxed under:","options":[{"key":"A","text":"Capital gains, as if the letting were a transfer of the asset"},{"key":"B","text":"Income from house property, like the letting of a building"},{"key":"C","text":"Income from OTHER SOURCES (s.56(2)(iii)) with depreciation deduction"},{"key":"D","text":"Salaries, as if the hire charges were remuneration"}],"answer":"C","explanation":"Casual letting of machinery/furniture goes to other sources with depreciation and repair deductions; systematic letting as a business activity goes to PGBP.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Income from letting out PLANT, MACHINERY or FURNITURE (not as a business) is taxed under:","options":["Capital gains","House property","Income from OTHER SOURCES (s.56(2)(iii)) with depreciation deduction","Salaries"],"answer":2,"explanation":"Casual letting of machinery/furniture goes to other sources with depreciation and repair deductions; systematic letting as a business activity goes to PGBP.","revision":"original","contentSignature":"d62eaf698836722d6a32b48a956762d2e5d3c6fc47b0c2c83a87f364240a5099"}]},{"id":161,"stem":"Deemed profit under Section 41(1) arises when:","options":[{"key":"A","text":"A new asset is purchased for the business during the year, at any price, whether or not any deduction was ever claimed or granted in respect of it"},{"key":"B","text":"A capital asset is sold during the year, at a profit or a loss, whether or not any deduction was ever claimed or granted in respect of it"},{"key":"C","text":"Dividend is received on shares held as investment during the year, whether or not any deduction was ever claimed or granted in respect of them"},{"key":"D","text":"An allowance/deduction earlier granted is RECOVERED in a later year (e.g. a trading liability is remitted)"}],"answer":"D","explanation":"Section 41(1) claws back earlier deductions when the corresponding liability/expense is recovered or remitted.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Deemed profit under Section 41(1) arises when:","options":["A new asset is purchased","Property is sold","Dividend is received","An allowance/deduction earlier granted is RECOVERED in a later year (e.g. a trading liability is remitted)"],"answer":3,"explanation":"Section 41(1) claws back earlier deductions when the corresponding liability/expense is recovered or remitted.","revision":"original","contentSignature":"799fecbbfbb7a6ff99d836551a36fa3164b688acf1df2a540932fa6b4e5bbf58"}]},{"id":162,"stem":"Bad debts written off are deductible under Section 36(1)(vii) when:","options":[{"key":"A","text":"Any debt is written off in the accounts, whether or not it was ever taken into income and whether or not the business is a money-lending one, with no requirement of actual irrecoverability"},{"key":"B","text":"The debt was taken into income earlier (or lent in money-lending business) and is actually WRITTEN OFF as irrecoverable in the accounts"},{"key":"C","text":"Only if a court decree declaring the debt irrecoverable is first obtained, whatever the nature of the debt and the accounts"},{"key":"D","text":"Only for banks and financial institutions, and never for an ordinary trading or manufacturing business"}],"answer":"B","explanation":"The debt must have been included in income (or be a money-lending advance) and must be written off in the books; a mere provision is not enough (except banks/NBFCs within limits).","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Bad debts written off are deductible under Section 36(1)(vii) when:","options":["Any debt is written off","The debt was taken into income earlier (or lent in money-lending business) and is actually WRITTEN OFF as irrecoverable in the accounts","Only if a court decree is obtained","Only for banks"],"answer":1,"explanation":"The debt must have been included in income (or be a money-lending advance) and must be written off in the books; a mere provision is not enough (except banks/NBFCs within limits).","revision":"original","contentSignature":"b09737e81fdacf1cff8df8d33529b3499651df6d210e448afd0120ce4cd8267e"}]},{"id":163,"stem":"A general provision for doubtful debts created by a trader is:","options":[{"key":"A","text":"Deductible up to Rs.1 lakh per year in the hands of every trader, whether or not any debt has actually been written off in the accounts during the year"},{"key":"B","text":"NOT deductible - only debts actually written off qualify (provisions allowed only to scheduled banks/NBFCs within s.36(1)(viia) limits)"},{"key":"C","text":"Deductible at 50% of the provision created, in the hands of every trader, whether or not any debt has actually been written off in the accounts during the year"},{"key":"D","text":"Fully deductible in the hands of every trader, whether or not any debt has actually been written off in the accounts during the year"}],"answer":"B","explanation":"Section 36(1)(vii) requires actual write-off; general provisions are disallowed for ordinary assessees.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A general provision for doubtful debts created by a trader is:","options":["Deductible up to Rs.1 lakh","NOT deductible - only debts actually written off qualify (provisions allowed only to scheduled banks/NBFCs within s.36(1)(viia) limits)","Deductible at 50%","Fully deductible"],"answer":1,"explanation":"Section 36(1)(vii) requires actual write-off; general provisions are disallowed for ordinary assessees.","revision":"original","contentSignature":"23ac1b494e3f7c3e29da6d3fff5cee6e0900abaa923d4099060be48a4769d714"}]},{"id":164,"stem":"Which of the following is expressly ALLOWED under Section 36(1)?","options":[{"key":"A","text":"Personal drawings of the proprietor from the business during the year, together with his household expenses met out of the business account, whatever their amount and whatever the nature of the business carried on"},{"key":"B","text":"Income-tax paid by the business during the year, whatever its amount"},{"key":"C","text":"Insurance premium on stocks/stores (36(1)(i)), bonus/commission to employees (36(1)(ii)), interest on borrowed capital (36(1)(iii)), employer contribution to RPF/approved funds (36(1)(iv)/(va))"},{"key":"D","text":"Wealth-tax paid by the business during the year, whatever its amount"}],"answer":"C","explanation":"Section 36(1) lists specific deductions: insurance of stocks/employees health, employee bonus/commission, borrowing interest, employer fund contributions, animal replacement, bad debts etc.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which of the following is expressly ALLOWED under Section 36(1)?","options":["Personal drawings of proprietor","Income tax paid","Insurance premium on stocks/stores (36(1)(i)), bonus/commission to employees (36(1)(ii)), interest on borrowed capital (36(1)(iii)), employer contribution to RPF/approved funds (36(1)(iv)/(va))","Wealth tax paid"],"answer":2,"explanation":"Section 36(1) lists specific deductions: insurance of stocks/employees health, employee bonus/commission, borrowing interest, employer fund contributions, animal replacement, bad debts etc.","revision":"original","contentSignature":"716820f6d4c1e23d7d01a8b5a274405e2a22fd9cd1f2c159071ac6bb19c66459"}]},{"id":165,"stem":"Interest on capital borrowed for business purposes is deductible under Section:","options":[{"key":"A","text":"Section 43B only, on actual payment, and never on accrual, whatever the purpose of the borrowing and the period for which the interest relates"},{"key":"B","text":"Section 24(b), as if the borrowing were for a house property, whatever the actual purpose of the borrowing in the hands of the business"},{"key":"C","text":"36(1)(iii) - on accrual basis, except interest for the period before the asset is first put to use (capitalised to the asset cost)"},{"key":"D","text":"Section 80C, as if the payment were a qualifying investment, whatever the actual nature of the payment"}],"answer":"C","explanation":"Section 36(1)(iii) allows borrowing interest for business; pre-commencement interest on asset loans is capitalised, not expensed.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Interest on capital borrowed for business purposes is deductible under Section:","options":["43B only","24(b)","36(1)(iii) - on accrual basis, except interest for the period before the asset is first put to use (capitalised to the asset cost)","80C"],"answer":2,"explanation":"Section 36(1)(iii) allows borrowing interest for business; pre-commencement interest on asset loans is capitalised, not expensed.","revision":"original","contentSignature":"8b018d2b72c1c2a787ef6e8968cebacb1f4f4dd451b3f6f1ec3273f16ad68ed3"}]},{"id":166,"stem":"Employer contributions to employee provident/ESI funds are deductible under s.36(1)(va) read with s.43B only if:","options":[{"key":"A","text":"Paid at any time within the same assessment year, whatever the due date under the statute"},{"key":"B","text":"Never deductible in the hands of the employer at all"},{"key":"C","text":"Credited to the employee account on or before the DUE DATE under the relevant welfare statute"},{"key":"D","text":"Paid at any time at all, before or after the due date"}],"answer":"C","explanation":"Employee welfare fund contributions must reach the fund by the statutory due date; the s.43B return-filing-date relief does NOT apply to employee contributions (Supreme Court in Checkmate Services).","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Employer contributions to employee provident/ESI funds are deductible under s.36(1)(va) read with s.43B only if:","options":["Paid within the same assessment year","Never deductible","Credited to the employee account on or before the DUE DATE under the relevant welfare statute","Paid at any time"],"answer":2,"explanation":"Employee welfare fund contributions must reach the fund by the statutory due date; the s.43B return-filing-date relief does NOT apply to employee contributions (Supreme Court in Checkmate Services).","revision":"original","contentSignature":"3fda6c0b8d5d0951c55821fd06db6d2924dd92f19895136ff26318f6ff9c3230"}]},{"id":167,"stem":"Scientific research capital expenditure (other than on land) for the assessee own business is:","options":[{"key":"A","text":"Allowed at 50% of the expenditure in the year incurred, the balance being lost forever"},{"key":"B","text":"Not deductible at all, being of a capital nature, in any year"},{"key":"C","text":"Depreciated over 10 years at the normal rates, like a building"},{"key":"D","text":"Fully deductible in the year incurred under s.35(1)(iv)/(2)"}],"answer":"D","explanation":"Capital expenditure on scientific research (except land) related to the business is allowed in full; revenue expenditure is allowed under s.35(1)(i).","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Scientific research capital expenditure (other than on land) for the assessee own business is:","options":["Allowed at 50%","Not deductible","Depreciated over 10 years","Fully deductible in the year incurred under s.35(1)(iv)/(2)"],"answer":3,"explanation":"Capital expenditure on scientific research (except land) related to the business is allowed in full; revenue expenditure is allowed under s.35(1)(i).","revision":"original","contentSignature":"7290cae667f21215933cce729e2d3f3236380bcbc1ec88a1f4c9520ba9edb610"}]},{"id":168,"stem":"Which expense is DISALLOWED under Section 40(a)?","options":[{"key":"A","text":"Salary paid by account payee cheque to an employee resident in India, on which the applicable TDS has been deducted and deposited within the time allowed under the Act"},{"key":"B","text":"Audit fees paid to a chartered accountant resident in India, on which the applicable TDS has been deducted and deposited within the time allowed under the Act"},{"key":"C","text":"Telephone expenses of the office paid during the year, being routine business expenditure subject to no TDS default"},{"key":"D","text":"Interest, royalty, fees for technical services payable outside India on which TDS was not deducted/deposited (100% disallowance, s.40(a)(i))"}],"answer":"D","explanation":"Non-deduction/deposit of TDS on non-resident payments disallows the entire expense; for resident payments, 30% is disallowed under s.40(a)(ia).","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which expense is DISALLOWED under Section 40(a)?","options":["Salary paid by account payee cheque","Audit fees","Telephone expenses","Interest, royalty, fees for technical services payable outside India on which TDS was not deducted/deposited (100% disallowance, s.40(a)(i))"],"answer":3,"explanation":"Non-deduction/deposit of TDS on non-resident payments disallows the entire expense; for resident payments, 30% is disallowed under s.40(a)(ia).","revision":"original","contentSignature":"28bb2a32721e257ba5ba00234ddb51598274bfb4c390419cdfac09e5ef817df3"}]},{"id":169,"stem":"Section 40A(2) empowers the Assessing Officer to disallow excessive/unreasonable payments made to:","options":[{"key":"A","text":"Banks and financial institutions, in respect of interest paid on loans"},{"key":"B","text":"RELATED PERSONS (specified relatives and concerns having substantial interest)"},{"key":"C","text":"Any vendor at all, whether related or unrelated"},{"key":"D","text":"Government departments, in respect of statutory payments"}],"answer":"B","explanation":"Payments to specified related persons above fair market value are disallowed to the extent considered excessive or unreasonable.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Section 40A(2) empowers the Assessing Officer to disallow excessive/unreasonable payments made to:","options":["Banks","RELATED PERSONS (specified relatives and concerns having substantial interest)","Any vendor","Government departments"],"answer":1,"explanation":"Payments to specified related persons above fair market value are disallowed to the extent considered excessive or unreasonable.","revision":"original","contentSignature":"dfcf4c8544388c37cfff011e3ceef92b556797a86c6e23fc6819a592f235c91c"}]},{"id":170,"stem":"The \"eligible business\" for Section 44AD does NOT include:","options":[{"key":"A","text":"Small civil contractors whose turnover is within the Section 44AD ceiling, so long as they do not earn commission or brokerage"},{"key":"B","text":"Persons carrying on agency business, persons earning commission/brokerage, and professions referred to in s.44AA(1)"},{"key":"C","text":"Small manufacturers whose turnover is within the Section 44AD ceiling, so long as they do not earn commission or brokerage"},{"key":"D","text":"Retail traders whose turnover is within the Section 44AD ceiling, so long as they do not earn commission or brokerage"}],"answer":"B","explanation":"Agency, commission/brokerage businesses and specified professions are excluded from 44AD; LLPs are also excluded from the eligible-assessee list.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The \"eligible business\" for Section 44AD does NOT include:","options":["Civil contractors (small)","Persons carrying on agency business, persons earning commission/brokerage, and professions referred to in s.44AA(1)","Small manufacturers","Retail traders"],"answer":1,"explanation":"Agency, commission/brokerage businesses and specified professions are excluded from 44AD; LLPs are also excluded from the eligible-assessee list.","revision":"original","contentSignature":"9f5d22b68b05626e72600813daadac332b0c5ce6a1b082206b3ffde070597093"}]},{"id":171,"stem":"Compensation received on termination of an agency contract is:","options":[{"key":"A","text":"Exempt up to Rs.5 lakh in aggregate, only the balance being taxable, whatever the nature of the contract"},{"key":"B","text":"Agricultural income, exempt under Section 10(1), whatever the nature of the contract"},{"key":"C","text":"Always a capital receipt, and hence wholly exempt from tax, whatever the nature of the contract"},{"key":"D","text":"Taxable as business income (s.28(ii)) where it relates to the business structure"}],"answer":"D","explanation":"Section 28(ii) taxes compensation for terminating/modifying any managing agency or other business agreement as business income.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Compensation received on termination of an agency contract is:","options":["Exempt up to Rs.5 lakh","Agricultural income","Always a capital receipt - exempt","Taxable as business income (s.28(ii)) where it relates to the business structure"],"answer":3,"explanation":"Section 28(ii) taxes compensation for terminating/modifying any managing agency or other business agreement as business income.","revision":"original","contentSignature":"384e2381ada4ba9893f96a4491c43ba3575551e2612d35bfa121a69a02fdc582"}]},{"id":172,"stem":"Export incentives like duty drawback and cash compensatory support are:","options":[{"key":"A","text":"Exempt under Section 10 as incentives for exports"},{"key":"B","text":"Business income taxable under s.28 (duty drawback u/s 28(iiia), profit on sale of DEPB u/s 28(iiid))"},{"key":"C","text":"Capital receipts, outside the scope of income tax altogether, whatever their nature and however they are computed or received by the exporter"},{"key":"D","text":"Income from other sources, and never business income, whatever their nature and however they are computed or received by the exporter"}],"answer":"B","explanation":"Export incentives are expressly taxed as business profits - duty drawback, DEPB sale profits and cash assistance are listed in s.28.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Export incentives like duty drawback and cash compensatory support are:","options":["Exempt under s.10","Business income taxable under s.28 (duty drawback u/s 28(iiia), profit on sale of DEPB u/s 28(iiid))","Capital receipts","Other sources income"],"answer":1,"explanation":"Export incentives are expressly taxed as business profits - duty drawback, DEPB sale profits and cash assistance are listed in s.28.","revision":"original","contentSignature":"3fd2d4740fc6d950258f5e6313f82d6b484413c4e6e23b3f1a414a666b9a9734"}]},{"id":173,"stem":"Fees, technical services and consultancy income of an individual practising a profession fall under:","options":[{"key":"A","text":"Profits and gains of business or profession"},{"key":"B","text":"Exempt income, under Section 10"},{"key":"C","text":"Salaries, as if an employer-employee relation existed"},{"key":"D","text":"Income from other sources, under Section 56"}],"answer":"A","explanation":"Professional earnings are PGBP; \"profession\" includes vocation and notified professions under s.44AA(1).","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Fees, technical services and consultancy income of an individual practising a profession fall under:","options":["Profits and gains of business or profession","Exempt income","Salaries","Income from other sources"],"answer":0,"explanation":"Professional earnings are PGBP; \"profession\" includes vocation and notified professions under s.44AA(1).","revision":"original","contentSignature":"9e12ce2aed6abf9324e62627960cd865637bc9047fdc8eaef1bec3905f53b9c4"}]},{"id":174,"stem":"Maintenance of books of account under Section 44AA is compulsory for a specified profession when gross receipts exceed:","options":[{"key":"A","text":"Rs.1,50,000 in ANY of the three preceding years (and expected to exceed in a new profession)"},{"key":"B","text":"Rs.25 lakh in ANY of the three preceding years (and expected to exceed in a new profession)"},{"key":"C","text":"Rs.1 lakh in ANY of the three preceding years (and expected to exceed in a new profession)"},{"key":"D","text":"Rs.10 lakh in ANY of the three preceding years (and expected to exceed in a new profession)"}],"answer":"A","explanation":"Specified professions (medicine, law, engineering, architecture, accountancy, technical consultancy, interior decoration, film artists, authorised representatives) must keep books if receipts top Rs.1.5 lakh in any of the 3 preceding years.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Maintenance of books of account under Section 44AA is compulsory for a specified profession when gross receipts exceed:","options":["Rs.1,50,000 in ANY of the three preceding years (and expected to exceed in a new profession)","Rs.25 lakh","Rs.1 lakh in any of the 3 preceding years","Rs.10 lakh"],"answer":0,"explanation":"Specified professions (medicine, law, engineering, architecture, accountancy, technical consultancy, interior decoration, film artists, authorised representatives) must keep books if receipts top Rs.1.5 lakh in any of the 3 preceding years.","revision":"original","contentSignature":"f3e5b24a49930baba67c2fd1f63bd7ddb071b26df573c1a0a1ec6b0e5c7db320"}]},{"id":175,"stem":"Animal (used for business but not as stock) that dies or becomes permanently useless is dealt with under Section 36(1)(vi) as:","options":[{"key":"A","text":"Depreciation on the animal at the normal rates for the block, as if it were plant, whatever the difference between its actual cost and the amount realised"},{"key":"B","text":"No tax treatment at all - the entire cost of the animal is simply lost, whatever the difference between its actual cost and the amount realised"},{"key":"C","text":"Deduction of the difference between the actual cost and the amount realised on sale/carcass"},{"key":"D","text":"A capital loss under Section 45 on the death of the animal, whatever the difference between its actual cost and the amount realised"}],"answer":"C","explanation":"Section 36(1)(vi) allows the shortfall (cost minus realisation) of permanently useless/dead working animals as a deduction.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Animal (used for business but not as stock) that dies or becomes permanently useless is dealt with under Section 36(1)(vi) as:","options":["Depreciation","No treatment","Deduction of the difference between the actual cost and the amount realised on sale/carcass","Capital loss"],"answer":2,"explanation":"Section 36(1)(vi) allows the shortfall (cost minus realisation) of permanently useless/dead working animals as a deduction.","revision":"original","contentSignature":"e4f697d1e192d5220778fd96fd6ee7b40417eb3176927247141af3b12f970e97"}]},{"id":176,"stem":"Which of the following receipts is TAXABLE as business income of a trade/professional association?","options":[{"key":"A","text":"Specific services rendered to MEMBERS for a charge (s.28(iii))"},{"key":"B","text":"Pure mutual concern receipts from members, without any charge for specific services"},{"key":"C","text":"Donations received from members and non-members alike"},{"key":"D","text":"Subscription from members (exempt by the principle of mutuality)"}],"answer":"A","explanation":"Section 28(iii) taxes income of trade/professional associations from specific services to members; pure mutuality receipts are not income.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which of the following receipts is TAXABLE as business income of a trade/professional association?","options":["Specific services rendered to MEMBERS for a charge (s.28(iii))","Pure mutual concern receipts","Donations received","Subscription from members (exempt by mutuality)"],"answer":0,"explanation":"Section 28(iii) taxes income of trade/professional associations from specific services to members; pure mutuality receipts are not income.","revision":"original","contentSignature":"4758e9ceb2f9f715bdbcd03e87bccda9664762824a357e92a8ded2464c077055"}]},{"id":177,"stem":"Where an assessee follows mercantile accounting, income is taxed on:","options":[{"key":"A","text":"The due date of filing the return of income for the year, as the taxing point"},{"key":"B","text":"ACCRUAL basis - when the right to receive arises, regardless of actual receipt"},{"key":"C","text":"Cash basis - only when the income is actually received by him"},{"key":"D","text":"Whichever of accrual or receipt gives the lower income for the year"}],"answer":"B","explanation":"Mercantile/accrual books tax income when it accrues; cash basis taxes on receipt - the assessee must follow one regularly (s.145).","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Where an assessee follows mercantile accounting, income is taxed on:","options":["Due date of return","ACCRUAL basis - when the right to receive arises, regardless of actual receipt","Cash basis","Whichever is lower"],"answer":1,"explanation":"Mercantile/accrual books tax income when it accrues; cash basis taxes on receipt - the assessee must follow one regularly (s.145).","revision":"original","contentSignature":"b9b186ace8630242ee668446d1757f078b4b337f19aa0cf3a30a58f239c0b1c3"}]},{"id":178,"stem":"Capital gains are charged under Section ________ of the Income-tax Act:","options":[{"key":"A","text":"45"},{"key":"B","text":"28"},{"key":"C","text":"56"},{"key":"D","text":"14"}],"answer":"A","explanation":"Section 45 is the charging section: profits or gains arising from the TRANSFER of a capital asset are taxable as capital gains in the year of transfer.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified"},{"id":179,"stem":"A \"capital asset\" under Section 2(14) does NOT include:","options":[{"key":"A","text":"Land and building, whether situated in urban or rural India, and whether held as investment or used for residence - these are always capital assets, and the same is true of every other kind of immovable property, every security and unit, every item of jewellery, and every other movable asset held for personal use or investment, with none of the exclusions for stock, personal effects, rural agricultural land or specified Gold Bonds applying to them at all"},{"key":"B","text":"Stock-in-trade, raw materials and consumables held for business; personal effects (movable wearing apparel, furniture); agricultural land in RURAL India; and specified Gold Bonds"},{"key":"C","text":"Shares and securities, whether listed or unlisted, held as investment"},{"key":"D","text":"Jewellery, whether or not for personal use"}],"answer":"B","explanation":"Stock-in-trade, personal effects (excluding jewellery, art, archaeological collections, drawings, paintings, sculptures), rural agricultural land and 6.5%/7% Gold Bonds are excluded from \"capital asset\".","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A \"capital asset\" under Section 2(14) does NOT include:","options":["Land and building","Stock-in-trade, raw materials and consumables held for business; personal effects (movable wearing apparel, furniture); agricultural land in RURAL India; and specified Gold Bonds","Shares and securities","Jewellery"],"answer":1,"explanation":"Stock-in-trade, personal effects (excluding jewellery, art, archaeological collections, drawings, paintings, sculptures), rural agricultural land and 6.5%/7% Gold Bonds are excluded from \"capital asset\".","revision":"original","contentSignature":"73bac80a30e3e1506e8c74de677b4dc98b0be85126c57a2d050a77b7ec721420"}]},{"id":180,"stem":"Jewellery, archaeological collections, drawings, paintings, sculptures and any work of art are treated as:","options":[{"key":"A","text":"Exempt assets, outside the charge to capital gains altogether, and never treated as capital assets"},{"key":"B","text":"CAPITAL ASSETS (specifically carved out of the personal-effects exclusion)"},{"key":"C","text":"Personal effects, and hence not capital assets at all, like wearing apparel"},{"key":"D","text":"Stock-in-trade, and hence never capital assets"}],"answer":"B","explanation":"The personal-effects exclusion does NOT cover jewellery and art/collection items - their sale attracts capital gains tax.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Jewellery, archaeological collections, drawings, paintings, sculptures and any work of art are treated as:","options":["Exempt assets","CAPITAL ASSETS (specifically carved out of the personal-effects exclusion)","Personal effects - not capital assets","Stock-in-trade always"],"answer":1,"explanation":"The personal-effects exclusion does NOT cover jewellery and art/collection items - their sale attracts capital gains tax.","revision":"original","contentSignature":"03190dc74d1e5b6d75e5563f0121d905d7fa60bdd6817c6cc680e7fd6f1580ba"}]},{"id":181,"stem":"For assets acquired on/after 23-7-2024, the holding period to qualify as LONG-TERM is:","options":[{"key":"A","text":"36 months for all the assets without exception of any kind, whether listed or unlisted, securities or immovable property"},{"key":"B","text":"12 months for all the assets without exception"},{"key":"C","text":"12 months for listed securities/units and 24 months for all OTHER assets (only two categories survive)"},{"key":"D","text":"48 months for immovable property, and 12 months for every other asset, listed or unlisted alike"}],"answer":"C","explanation":"The Finance Act 2024 collapsed the three-tier holding structure into two: 12 months (listed securities, equity/preference shares, units of equity-oriented funds/business trusts) and 24 months (all other assets).","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"For assets acquired on/after 23-7-2024, the holding period to qualify as LONG-TERM is:","options":["36 months for all assets","12 months for all assets","12 months for listed securities/units and 24 months for all OTHER assets (only two categories survive)","48 months for property"],"answer":2,"explanation":"The Finance Act 2024 collapsed the three-tier holding structure into two: 12 months (listed securities, equity/preference shares, units of equity-oriented funds/business trusts) and 24 months (all other assets).","revision":"original","contentSignature":"6827d4e4cd9360b87c6ac735e0b2c1015dbbccdcafece87bb3d1ceafb307ad13"}]},{"id":182,"stem":"Listed equity shares sold after 15 months of holding give rise to:","options":[{"key":"A","text":"Short-term capital gain, since the holding is under 24 months"},{"key":"B","text":"Exempt income, since STT is paid on the sale"},{"key":"C","text":"Business income, as if the shares were stock-in-trade"},{"key":"D","text":"LONG-TERM capital gain (holding exceeds 12 months)"}],"answer":"D","explanation":"Listed securities held for more than 12 months are long-term; 12 months or less is short-term (s.2(42A)).","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Listed equity shares sold after 15 months of holding give rise to:","options":["Short-term capital gain","Exempt income","Business income","LONG-TERM capital gain (holding exceeds 12 months)"],"answer":3,"explanation":"Listed securities held for more than 12 months are long-term; 12 months or less is short-term (s.2(42A)).","revision":"original","contentSignature":"55f7ef2af1a7b89dfef1161016bec8f18b345addcd5afd425824f8526ed37853"}]},{"id":183,"stem":"An immovable property (land/building) held for 20 months and then sold yields:","options":[{"key":"A","text":"Long-term capital gain, since the holding exceeds 12 months"},{"key":"B","text":"SHORT-TERM capital gain (the threshold is 24 months)"},{"key":"C","text":"No gain at all, the sale being outside the tax net"},{"key":"D","text":"Deemed income from other sources, not capital gains"}],"answer":"B","explanation":"Immovable property (and other non-listed assets) needs more than 24 months of holding to be long-term.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"An immovable property (land/building) held for 20 months and then sold yields:","options":["Long-term capital gain","SHORT-TERM capital gain (the threshold is 24 months)","No gain","Deemed income"],"answer":1,"explanation":"Immovable property (and other non-listed assets) needs more than 24 months of holding to be long-term.","revision":"original","contentSignature":"d8157f69aec16f4ffc14997b835d645865b51164a7ccea3792ead56bad770de6"}]},{"id":184,"stem":"Long-term capital gains on listed equity shares and equity-oriented mutual fund units (s.112A) are taxed at:","options":[{"key":"A","text":"Nil - the gain is fully exempt"},{"key":"B","text":"10% above Rs.1 lakh per year, without indexation, as before"},{"key":"C","text":"20% with indexation, without any threshold exemption at all"},{"key":"D","text":"12.5% above Rs.1.25 lakh per year (from 23-7-2024), without indexation"}],"answer":"D","explanation":"Section 112A: LTCG above Rs.1,25,000 a year on listed equity/equity-oriented funds (STT paid) is taxed at 12.5%; the exemption threshold was raised from Rs.1 lakh to Rs.1.25 lakh by the Finance Act 2024.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Long-term capital gains on listed equity shares and equity-oriented mutual fund units (s.112A) are taxed at:","options":["Nil - fully exempt","10% above Rs.1 lakh","20% with indexation","12.5% above Rs.1.25 lakh per year (from 23-7-2024), without indexation"],"answer":3,"explanation":"Section 112A: LTCG above Rs.1,25,000 a year on listed equity/equity-oriented funds (STT paid) is taxed at 12.5%; the exemption threshold was raised from Rs.1 lakh to Rs.1.25 lakh by the Finance Act 2024.","revision":"original","contentSignature":"705f0351d5ff0060408dfd9c3bf78e8ac2e9d582548cdadeae7d2f6643ea05e7"}]},{"id":185,"stem":"Short-term capital gains on listed equity shares/equity-oriented funds (STT paid) under Section 111A are taxed at:","options":[{"key":"A","text":"30% flat (from 23-7-2024)"},{"key":"B","text":"10% flat (from 23-7-2024)"},{"key":"C","text":"20% (from 23-7-2024)"},{"key":"D","text":"15% flat (from 23-7-2024)"}],"answer":"C","explanation":"Section 111A rate rose from 15% to 20% for transfers on or after 23-7-2024.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Short-term capital gains on listed equity shares/equity-oriented funds (STT paid) under Section 111A are taxed at:","options":["30%","10%","20% (from 23-7-2024)","15%"],"answer":2,"explanation":"Section 111A rate rose from 15% to 20% for transfers on or after 23-7-2024.","revision":"original","contentSignature":"edb2c2cd344541c641c942db2af75ee66f574c8a9aa9d498874ca2f530cdd48c"}]},{"id":186,"stem":"The general LTCG rate (Section 112) for other assets (property, unlisted shares, gold) for transfers on/after 23-7-2024 is:","options":[{"key":"A","text":"20% WITH indexation, with no option of any other rate"},{"key":"B","text":"10% WITHOUT indexation"},{"key":"C","text":"30% WITHOUT indexation"},{"key":"D","text":"12.5% WITHOUT indexation (resident individuals/HUF selling pre-23-7-2024-acquired land or building may opt for 20% with indexation)"}],"answer":"D","explanation":"The Finance Act 2024 replaced 20%-with-indexation by 12.5%-without-indexation; a grandfathering choice (20% with indexation) exists for resident individuals/HUF on land/building acquired before 23-7-2024.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The general LTCG rate (Section 112) for other assets (property, unlisted shares, gold) for transfers on/after 23-7-2024 is:","options":["20% WITH indexation","10%","30%","12.5% WITHOUT indexation (resident individuals/HUF selling pre-23-7-2024-acquired land or building may opt for 20% with indexation)"],"answer":3,"explanation":"The Finance Act 2024 replaced 20%-with-indexation by 12.5%-without-indexation; a grandfathering choice (20% with indexation) exists for resident individuals/HUF on land/building acquired before 23-7-2024.","revision":"original","contentSignature":"11b0a5e722a511c4ec3b2692359501df6e863c600a1de410ad489b1219c698c6"}]},{"id":187,"stem":"The Cost Inflation Index (CII) base year under the fourth proviso to Section 48 is:","options":[{"key":"A","text":"1981-82 = 100"},{"key":"B","text":"2011-12 = 100"},{"key":"C","text":"2001-02 = 100"},{"key":"D","text":"1991-92 = 100"}],"answer":"C","explanation":"The base year shifted from 1981-82 to 2001-02 = 100; assets acquired before 1-4-2001 use FMV as on 1-4-2001 as cost option.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified"},{"id":188,"stem":"The \"full value of consideration\" in capital gains computation means:","options":[{"key":"A","text":"The indexed cost of acquisition of the asset transferred, computed under the second proviso to Section 48 where indexation applies"},{"key":"B","text":"What the transferor RECEIVES or is entitled to receive in respect of the transfer (not necessarily the market value)"},{"key":"C","text":"Always the stamp duty value adopted for stamp purposes, whatever the consideration the transferor receives or is entitled to receive"},{"key":"D","text":"The cost of the asset to the transferor himself, whether historical or indexed under the applicable computation"}],"answer":"B","explanation":"Section 48 uses actual consideration received/receivable; ss.50C/50CA substitute stamp-duty/valuation figures for land-building/unlisted shares where consideration is understated.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The \"full value of consideration\" in capital gains computation means:","options":["Indexed cost","What the transferor RECEIVES or is entitled to receive in respect of the transfer (not necessarily the market value)","Stamp duty value always","The cost of the asset"],"answer":1,"explanation":"Section 48 uses actual consideration received/receivable; ss.50C/50CA substitute stamp-duty/valuation figures for land-building/unlisted shares where consideration is understated.","revision":"original","contentSignature":"bbe2291fbbedda7c875d02b7b692c75a913326982533135690aae31ffa88c9c5"}]},{"id":189,"stem":"If the stamp duty value of a land/building exceeds the stated sale consideration, capital gains are computed using the stamp duty value, provided it exceeds the consideration by more than:","options":[{"key":"A","text":"5% of the consideration (the tolerance band being 5% of the consideration under s.50C as amended in 2020, and no more)"},{"key":"B","text":"Any excess of the stamp duty value, however small, since there is no tolerance band at all under s.50C as amended in 2020"},{"key":"C","text":"10% of consideration (and Rs.50,000... the tolerance band is 10% of the consideration under s.50C as amended in 2020)"},{"key":"D","text":"1% of the consideration (the tolerance band being 1% of the consideration under s.50C as amended in 2020, and no more)"}],"answer":"C","explanation":"Section 50C/56(2)(x) safe harbour: stamp duty value is adopted only where it exceeds 110% of the actual consideration.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"If the stamp duty value of a land/building exceeds the stated sale consideration, capital gains are computed using the stamp duty value, provided it exceeds the consideration by more than:","options":["5% of consideration","Any excess","10% of consideration (and Rs.50,000... the tolerance band is 10% of the consideration under s.50C as amended in 2020)","1%"],"answer":2,"explanation":"Section 50C/56(2)(x) safe harbour: stamp duty value is adopted only where it exceeds 110% of the actual consideration.","revision":"original","contentSignature":"6fe4996a0f8fcddca261d5683e9e79c87fde37efeb49bd9d3d2de4a6f1b4733b"}]},{"id":190,"stem":"Cost of acquisition for an asset acquired by INHERITANCE or gift is:","options":[{"key":"A","text":"The cost to the PREVIOUS OWNER (and indexation, where applicable, runs from the previous owner acquisition)"},{"key":"B","text":"Its fair market value on the date of inheritance or gift in all cases, and indexation, where applicable, runs only from that date, whatever the cost to the previous owner"},{"key":"C","text":"Its insured value on the date of inheritance or gift, whatever the cost to the previous owner"},{"key":"D","text":"Nil, since nothing was paid for the asset by the assessee"}],"answer":"A","explanation":"Section 49(1): for inheritance/gift/devolution, the deemed cost is the cost to the previous owner; the holding period also includes the previous owner period.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Cost of acquisition for an asset acquired by INHERITANCE or gift is:","options":["The cost to the PREVIOUS OWNER (and indexation, where applicable, runs from the previous owner acquisition)","Its FMV on the date of inheritance in all cases","Its insured value","Nil"],"answer":0,"explanation":"Section 49(1): for inheritance/gift/devolution, the deemed cost is the cost to the previous owner; the holding period also includes the previous owner period.","revision":"original","contentSignature":"6023b9a66252825592387efe166f878bcca896c510576c8cd419125bc245f836"}]},{"id":191,"stem":"Improvement cost incurred by the assessee or the previous owner is:","options":[{"key":"A","text":"Never deductible in computing capital gains, whether incurred by the assessee or the previous owner, and whether the improvement is indexed or not under the applicable computation"},{"key":"B","text":"Added to cost of acquisition and indexed from the year of improvement (for pre-23-7-2024 computations where indexation applies)"},{"key":"C","text":"Treated as a revenue expense of the year in which it is incurred, and never added to the cost of the asset"},{"key":"D","text":"Deducted from the sale price as a transfer expense, and never added to the cost of the asset"}],"answer":"B","explanation":"Section 48/55: cost of improvement enhances the cost base; indexed cost of improvement uses the CII of the improvement year (where indexation survives).","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Improvement cost incurred by the assessee or the previous owner is:","options":["Never deductible","Added to cost of acquisition and indexed from the year of improvement (for pre-23-7-2024 computations where indexation applies)","Treated as revenue expense","Deducted from sale price"],"answer":1,"explanation":"Section 48/55: cost of improvement enhances the cost base; indexed cost of improvement uses the CII of the improvement year (where indexation survives).","revision":"original","contentSignature":"5e465e7f27e4ee079bf3763112cf26ae10c04238d5afc377d0aa69e8cfd6dda9"}]},{"id":192,"stem":"Expenses wholly and exclusively in connection with the transfer (brokerage, legal fees, stamp duty by seller) are:","options":[{"key":"A","text":"Not allowed at all in the capital gains computation"},{"key":"B","text":"Capitalised as part of the cost of acquisition of the asset"},{"key":"C","text":"DEDUCTED from full value of consideration under s.48(i)"},{"key":"D","text":"Added to the cost of acquisition of the asset"}],"answer":"C","explanation":"Transfer expenses reduce the sale consideration for capital gains computation (but STT is not deductible for share transactions).","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Expenses wholly and exclusively in connection with the transfer (brokerage, legal fees, stamp duty by seller) are:","options":["Not allowed","Capitalised","DEDUCTED from full value of consideration under s.48(i)","Added to cost"],"answer":2,"explanation":"Transfer expenses reduce the sale consideration for capital gains computation (but STT is not deductible for share transactions).","revision":"original","contentSignature":"3313b399ec439dbdf89eff714536d7b9addc3995186bed25d4d03404503344cc"}]},{"id":193,"stem":"Section 54 exempts LTCG on sale of a RESIDENTIAL HOUSE if the gain is invested in:","options":[{"key":"A","text":"Shares of any company, Indian or foreign, within the Section 54 timelines - purchased 1 year before or 2 years after the transfer, with no monetary cap at all on the exemption"},{"key":"B","text":"Any commercial property in India - purchased 1 year before or 2 years after the transfer, or constructed within 3 years, with no monetary cap at all on the exemption"},{"key":"C","text":"ONE (or two, where gain is up to Rs.2 crore, once in a lifetime) residential house in India - purchased 1 year before/2 years after, or constructed within 3 years; exemption capped at Rs.10 CRORE (from FY 2023-24)"},{"key":"D","text":"Gold or any other movable asset, within the Section 54 timelines - purchased 1 year before or 2 years after the transfer, with no monetary cap at all on the exemption"}],"answer":"C","explanation":"Section 54: reinvest the capital gain (not the whole consideration) in residential house(s) within the timelines; the Rs.10 crore cap applies from FY 2023-24.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Section 54 exempts LTCG on sale of a RESIDENTIAL HOUSE if the gain is invested in:","options":["Shares","Any commercial property","ONE (or two, where gain is up to Rs.2 crore, once in a lifetime) residential house in India - purchased 1 year before/2 years after, or constructed within 3 years; exemption capped at Rs.10 CRORE (from FY 2023-24)","Gold"],"answer":2,"explanation":"Section 54: reinvest the capital gain (not the whole consideration) in residential house(s) within the timelines; the Rs.10 crore cap applies from FY 2023-24.","revision":"original","contentSignature":"da9003836ff4312c8b359f020b0fb20d22cb6dece5b3ad36779e812b4a327077"}]},{"id":194,"stem":"Section 54EC exempts LTCG on land/building invested in specified bonds (NHAI, REC, PFC, IRFC) within 6 months, up to:","options":[{"key":"A","text":"Rs.50 LAKH per financial year, with a 5-year lock-in"},{"key":"B","text":"Rs.10 LAKH per financial year, with a 5-year lock-in"},{"key":"C","text":"Rs.5 LAKH per financial year, with a 5-year lock-in"},{"key":"D","text":"Rs.1 CRORE per financial year, with a 5-year lock-in"}],"answer":"A","explanation":"54EC bonds have a Rs.50 lakh annual investment cap, 6-month window and 5-year lock-in; premature redemption makes the exempted gain taxable.","source":"Source label not detected","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Section 54EC exempts LTCG on land/building invested in specified bonds (NHAI, REC, PFC, IRFC) within 6 months, up to:","options":["Rs.50 LAKH per financial year, with a 5-year lock-in","Rs.10 lakh","Rs.5 lakh","Rs.1 crore"],"answer":0,"explanation":"54EC bonds have a Rs.50 lakh annual investment cap, 6-month window and 5-year lock-in; premature redemption makes the exempted gain taxable.","revision":"original","contentSignature":"621795eaa65373f5551d9426ffaca6872c3c88ef22afb1b7c8efa6099b76c0f0"}]},{"id":195,"stem":"Section 54F exempts LTCG (from assets OTHER than a residential house) if:","options":[{"key":"A","text":"Only the CAPITAL GAIN is reinvested in specified bonds under Section 54EC, with the sale consideration otherwise free to be used in any manner, and with no condition about owning other houses at all"},{"key":"B","text":"The gain is below Rs.1 lakh in the year, in which case the whole gain is exempt without any reinvestment at all, and with no condition about owning other houses"},{"key":"C","text":"The assessee buys agricultural land, urban or rural, within 2 years of the transfer, as under Section 54B, and with no condition about owning other houses at all"},{"key":"D","text":"The ENTIRE NET SALE CONSIDERATION is invested in one residential house in India within the 54F timelines (and the assessee does not own more than one other house); capped at Rs.10 crore"}],"answer":"D","explanation":"54F requires investing the net consideration (proportional exemption if partial), subject to the one-house condition and the Rs.10 crore cap from FY 2023-24.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Section 54F exempts LTCG (from assets OTHER than a residential house) if:","options":["The CAPITAL GAIN is reinvested in bonds","The gain is below Rs.1 lakh","The assessee buys agricultural land","The ENTIRE NET SALE CONSIDERATION is invested in one residential house in India within the 54F timelines (and the assessee does not own more than one other house); capped at Rs.10 crore"],"answer":3,"explanation":"54F requires investing the net consideration (proportional exemption if partial), subject to the one-house condition and the Rs.10 crore cap from FY 2023-24.","revision":"original","contentSignature":"e5c6096ee1910e7e05267512504e1348bb06d39a6e5878fded75c440e66f9972"}]},{"id":196,"stem":"Section 54B exempts capital gains on transfer of URBAN AGRICULTURAL LAND used for agriculture for 2 years preceding transfer, if:","options":[{"key":"A","text":"Another AGRICULTURAL LAND (urban or rural) is purchased within 2 years"},{"key":"B","text":"The sale proceeds are deposited in a scheduled bank for 2 years from the transfer"},{"key":"C","text":"The capital gain is below Rs.50 lakh in the year of the transfer"},{"key":"D","text":"A residential house is constructed within 3 years from the transfer"}],"answer":"A","explanation":"54B reinvestment into agricultural land within 2 years exempts the gain; the new land must not be sold within 3 years.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Section 54B exempts capital gains on transfer of URBAN AGRICULTURAL LAND used for agriculture for 2 years preceding transfer, if:","options":["Another AGRICULTURAL LAND (urban or rural) is purchased within 2 years","The proceeds are deposited in a bank","The gain is below Rs.50 lakh","A house is constructed"],"answer":0,"explanation":"54B reinvestment into agricultural land within 2 years exempts the gain; the new land must not be sold within 3 years.","revision":"original","contentSignature":"29155c7efdc45a6aeb1fd1413366ec3350c277d03f3aac5b21debc64d4415b36"}]},{"id":197,"stem":"The Capital Gains Accounts Scheme (CGAS) is used when:","options":[{"key":"A","text":"The asset is inherited, so that no purchase or construction is ever contemplated under those sections, and the due date of filing the return has no bearing on the exemption at all"},{"key":"B","text":"The reinvestment (u/s 54/54B/54F etc.) cannot be made before the DUE DATE OF FILING THE RETURN - the amount is deposited in a CGAS account to keep the exemption alive"},{"key":"C","text":"The assessee wants a refund of tax already paid, so that no purchase or construction is ever contemplated under those sections, and the due date of filing the return has no bearing on the exemption"},{"key":"D","text":"Allowed, whether or not the reinvestment is already made before the return due date"}],"answer":"B","explanation":"Unutilised gains meant for reinvestment must be parked in a CGAS deposit by the s.139(1) due date; unutilised deposits become taxable in the year the period expires.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The Capital Gains Accounts Scheme (CGAS) is used when:","options":["The asset is inherited","The reinvestment (u/s 54/54B/54F etc.) cannot be made before the DUE DATE OF FILING THE RETURN - the amount is deposited in a CGAS account to keep the exemption alive","The assessee wants a refund","Always"],"answer":1,"explanation":"Unutilised gains meant for reinvestment must be parked in a CGAS deposit by the s.139(1) due date; unutilised deposits become taxable in the year the period expires.","revision":"original","contentSignature":"fea79e377380a3aaf4dd28a3ab8110c387b25aa2b4653d1d5073ba8d34e475a2"}]},{"id":198,"stem":"Short-term capital losses can be set off against:","options":[{"key":"A","text":"Both STCG and LTCG (any capital gains head income)"},{"key":"B","text":"Only long-term capital gains, never short-term"},{"key":"C","text":"Only short-term capital gains, never long-term"},{"key":"D","text":"Salary income of the same year, like any other loss"}],"answer":"A","explanation":"Capital losses (short or long) set off only against capital gains, but STCL can absorb both STCG and LTCG; carry forward is 8 years.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Short-term capital losses can be set off against:","options":["Both STCG and LTCG (any capital gains head income)","Only LTCG","Only STCG","Salary income"],"answer":0,"explanation":"Capital losses (short or long) set off only against capital gains, but STCL can absorb both STCG and LTCG; carry forward is 8 years.","revision":"original","contentSignature":"bb8dd6b4e292749a2c6f9ac02153ff16d000ed32391361b0ffafd761ecb23c55"}]},{"id":199,"stem":"A long-term capital loss can be set off against:","options":[{"key":"A","text":"Short-term gains also"},{"key":"B","text":"LONG-TERM capital gains ONLY"},{"key":"C","text":"Other sources"},{"key":"D","text":"Any income"}],"answer":"B","explanation":"LTCL sets off only against LTCG (s.70/74); both types carry forward for 8 assessment years.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified"},{"id":200,"stem":"Capital loss can be carried forward for how many assessment years?","options":[{"key":"A","text":"4"},{"key":"B","text":"10"},{"key":"C","text":"8"},{"key":"D","text":"Indefinitely"}],"answer":"C","explanation":"Section 74: capital losses carry forward for 8 AYs following the year of loss, set off only against capital gains.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified"},{"id":201,"stem":"Transfer of a capital asset in a scheme of AMALGAMATION (Indian companies) is:","options":[{"key":"A","text":"NOT treated as a \"transfer\" for capital gains (s.47(vi)) - tax defers to the ultimate sale"},{"key":"B","text":"Taxed at the flat rate of 30% in the year of the amalgamation, like casual income"},{"key":"C","text":"Taxed as income from other sources in the year of the amalgamation, like interest"},{"key":"D","text":"Fully taxable as a transfer in the year of the amalgamation, with no deferral"}],"answer":"A","explanation":"Section 47 lists non-transfers: amalgamation/demerge between qualifying companies, gifts/inheritance (covered by s.47(iii) read with 49(1)), holding-subsidiary transfers, etc.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Transfer of a capital asset in a scheme of AMALGAMATION (Indian companies) is:","options":["NOT treated as a \"transfer\" for capital gains (s.47(vi)) - tax defers to the ultimate sale","Taxed at 30%","Taxed as other sources","Fully taxable"],"answer":0,"explanation":"Section 47 lists non-transfers: amalgamation/demerge between qualifying companies, gifts/inheritance (covered by s.47(iii) read with 49(1)), holding-subsidiary transfers, etc.","revision":"original","contentSignature":"fc009621844d64c4398bacae3dd8d0e5d13d6dc2813089de3aab979226762394"}]},{"id":202,"stem":"Distribution of capital assets on DISSOLUTION of a firm is:","options":[{"key":"A","text":"Never taxable - a distribution on dissolution is not a transfer at all"},{"key":"B","text":"Treated as a TRANSFER - capital gains arise in the hands of the FIRM (s.45(4))"},{"key":"C","text":"Exempt under Section 47, like a transfer in a scheme of amalgamation"},{"key":"D","text":"Taxed in the partners hands directly, as their salary income of the year of distribution"}],"answer":"B","explanation":"Section 45(4) deems distribution of capital assets on dissolution/reconstitution to be a transfer by the firm; FMV is deemed full value of consideration.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Distribution of capital assets on DISSOLUTION of a firm is:","options":["Never taxable","Treated as a TRANSFER - capital gains arise in the hands of the FIRM (s.45(4))","Exempt","Taxed in partner hands directly as salary"],"answer":1,"explanation":"Section 45(4) deems distribution of capital assets on dissolution/reconstitution to be a transfer by the firm; FMV is deemed full value of consideration.","revision":"original","contentSignature":"25e11a64e2a83cbcaa6fb195cc4274fc63e666e5f117d9176974f471e980bc98"}]},{"id":203,"stem":"The holding period of a SHARE received on DEMERGER includes:","options":[{"key":"A","text":"The period for which the shares were held in the DEMERGED company"},{"key":"B","text":"Only the period after the demerger, from the date of allotment"},{"key":"C","text":"A deemed period of three years counted from the date of the allotment"},{"key":"D","text":"A deemed period of one year"}],"answer":"A","explanation":"Explanation 1 to s.2(42A): for shares received on demerger, the holding period includes the period of holding in the demerged company.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The holding period of a SHARE received on DEMERGER includes:","options":["The period for which the shares were held in the DEMERGED company","Only the post-demerger period","Three years","One year"],"answer":0,"explanation":"Explanation 1 to s.2(42A): for shares received on demerger, the holding period includes the period of holding in the demerged company.","revision":"original","contentSignature":"b57844638e57c9e54507c0a85ca7026ce5a830f2485e8c7fe9acf38b14a4e39d"}]},{"id":204,"stem":"Capital gains on DEPRECIABLE assets (forming part of a block) are:","options":[{"key":"A","text":"Always treated as SHORT-TERM (s.50) - long/short distinction does not apply to block assets"},{"key":"B","text":"Exempt from capital gains altogether, since depreciation was allowed on them, whatever the period for which the assets were held"},{"key":"C","text":"Taxed at 12.5% as long-term capital gains"},{"key":"D","text":"Treated as long-term capital gains if the assets were held for over 24 months, like non-depreciable property"}],"answer":"A","explanation":"Section 50: gains on block assets are always short-term, because WDV already reflects depreciation claims.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Capital gains on DEPRECIABLE assets (forming part of a block) are:","options":["Always treated as SHORT-TERM (s.50) - long/short distinction does not apply to block assets","Exempt","Taxed at 12.5%","Long-term if held 24 months"],"answer":0,"explanation":"Section 50: gains on block assets are always short-term, because WDV already reflects depreciation claims.","revision":"original","contentSignature":"b2ff8a5b9283db6ca3c7856cb4d16c5c2a1ac95a8da492aa9fce262b044de4e1"}]},{"id":205,"stem":"Securities Transaction Tax (STT) paid on sale of shares is:","options":[{"key":"A","text":"Refundable against the capital gains tax payable"},{"key":"B","text":"Added to the cost of acquisition of the shares"},{"key":"C","text":"NOT deductible while computing capital gains on shares"},{"key":"D","text":"Deductible as a transfer expense in computing the capital gains"}],"answer":"C","explanation":"STT is neither a transfer expense nor part of cost for capital-gain purposes (though STT payment is a condition for the 111A/112A concessional rates).","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Securities Transaction Tax (STT) paid on sale of shares is:","options":["Refundable","Added to cost","NOT deductible while computing capital gains on shares","Deductible as transfer expense in capital gains"],"answer":2,"explanation":"STT is neither a transfer expense nor part of cost for capital-gain purposes (though STT payment is a condition for the 111A/112A concessional rates).","revision":"original","contentSignature":"a779616b09234cd1f6fcd066ffbe697bd94b4c9a24043299c33e01cf649a0cdb"}]},{"id":206,"stem":"Conversion of a capital asset into STOCK-IN-TRADE is:","options":[{"key":"A","text":"Taxed as salary income in the year of conversion"},{"key":"B","text":"Exempt, being a mere change of form of the asset, with no transfer at all, and with no tax even when the stock is ultimately sold by the business at a profit"},{"key":"C","text":"Not taxable at all, either on conversion or on the later sale of the stock, the entire profit on the ultimate sale being outside the tax net"},{"key":"D","text":"Taxed as a transfer in the year of conversion, with FMV on the date of conversion as full value of consideration (s.45(2))"}],"answer":"D","explanation":"Section 45(2): conversion into stock is a taxable transfer on conversion-date FMV; the later business sale taxes the FMV-to-sale difference as business income.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Conversion of a capital asset into STOCK-IN-TRADE is:","options":["Taxed as salary","Exempt","Not taxable at all","Taxed as a transfer in the year of conversion, with FMV on the date of conversion as full value of consideration (s.45(2))"],"answer":3,"explanation":"Section 45(2): conversion into stock is a taxable transfer on conversion-date FMV; the later business sale taxes the FMV-to-sale difference as business income.","revision":"original","contentSignature":"a3870d6633a0b3b9dec817f76f529c7379b48cc6738d687cf452cb9583289b24"}]},{"id":207,"stem":"For BONUS shares allotted on/after 1-4-2001, the cost of acquisition is taken as:","options":[{"key":"A","text":"Face value"},{"key":"B","text":"FMV on allotment date"},{"key":"C","text":"Cost of original shares"},{"key":"D","text":"NIL"}],"answer":"D","explanation":"Section 55(2)(aa): bonus shares allotted on or after 1-4-2001 have nil cost; their holding period runs from allotment.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified"},{"id":208,"stem":"Compulsory acquisition of an asset by the Government - capital gains arise in:","options":[{"key":"A","text":"The year of RECEIPT of the compensation (or part of it)"},{"key":"B","text":"Never taxable, being a compulsory acquisition"},{"key":"C","text":"The year in which possession is taken over by the Government"},{"key":"D","text":"The year in which the acquisition order is passed by the Government"}],"answer":"A","explanation":"Section 45(5): compulsory-acquisition gains are taxed in the year the compensation (or part) is first received; enhanced compensation is taxed when received.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Compulsory acquisition of an asset by the Government - capital gains arise in:","options":["The year of RECEIPT of the compensation (or part of it)","Never taxable","The year of possession","The year of the acquisition order"],"answer":0,"explanation":"Section 45(5): compulsory-acquisition gains are taxed in the year the compensation (or part) is first received; enhanced compensation is taxed when received.","revision":"original","contentSignature":"72cd1fa4f260e8e51281e60c3b241d054d59f4a179a95a228dc03cafee9e8aab"}]},{"id":209,"stem":"A depreciable block ceases to exist because all assets are destroyed by fire and insurance compensation EXCEEDS the block WDV. The excess is:","options":[{"key":"A","text":"Revenue income of the business, taxed as business income"},{"key":"B","text":"Exempt, being compensation for destruction"},{"key":"C","text":"Casual income, taxed like lottery winnings"},{"key":"D","text":"Short-term capital GAIN under Section 50"}],"answer":"D","explanation":"Where the block ceases to exist and money received exceeds WDV, the excess is short-term capital gain u/s 50 (the s.45(1A) insurance-compensation rule applies via the block mechanism).","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A depreciable block ceases to exist because all assets are destroyed by fire and insurance compensation EXCEEDS the block WDV. The excess is:","options":["Revenue income","Exempt","Casual income","Short-term capital GAIN under Section 50"],"answer":3,"explanation":"Where the block ceases to exist and money received exceeds WDV, the excess is short-term capital gain u/s 50 (the s.45(1A) insurance-compensation rule applies via the block mechanism).","revision":"original","contentSignature":"f014f23a19054acf79bd98ca061cbc60e5b4eee768ad16fc842f54ae63d92964"}]},{"id":210,"stem":"Exemption under Section 54/54F is withdrawn (the exempted gain becomes taxable) if the NEW residential house is sold within:","options":[{"key":"A","text":"5 YEARS of purchase or construction of the new house"},{"key":"B","text":"2 YEARS of purchase or construction of the new house"},{"key":"C","text":"3 YEARS of purchase/construction"},{"key":"D","text":"1 YEAR of purchase or construction of the new house"}],"answer":"C","explanation":"The new asset has a 3-year lock-in: selling it earlier makes the previously exempted gain taxable in the year of sale.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Exemption under Section 54/54F is withdrawn (the exempted gain becomes taxable) if the NEW residential house is sold within:","options":["5 years","2 years","3 YEARS of purchase/construction","1 year"],"answer":2,"explanation":"The new asset has a 3-year lock-in: selling it earlier makes the previously exempted gain taxable in the year of sale.","revision":"original","contentSignature":"613b3c65a931cf101933493e30bb5d77c804366b219207e648ef5ab0f4fda5f6"}]},{"id":211,"stem":"The residuary head \"Income from other sources\" is charged under Section:","options":[{"key":"A","text":"45"},{"key":"B","text":"56"},{"key":"C","text":"28"},{"key":"D","text":"24"}],"answer":"B","explanation":"Section 56 taxes every income that does not fall under the first four heads and is not exempt.","source":"Original","module":"T5","topic":"Income from Other Sources","reviewStatus":"Source key not independently verified"},{"id":212,"stem":"DIVIDEND received from an Indian company is:","options":[{"key":"A","text":"Fully exempt under Section 10(34) in the shareholder hands, since dividend distribution tax continues to apply, with no TDS under Section 194 whatever the amount of the dividend"},{"key":"B","text":"TAXABLE in the shareholder hands under other sources (DDT abolished from FY 2020-21), with TDS u/s 194 above Rs.10,000"},{"key":"C","text":"Exempt up to Rs.10 lakh per year in the shareholder hands, the excess alone being taxable, with no TDS under Section 194 whatever the amount of the dividend"},{"key":"D","text":"Taxed as capital gains in the shareholder hands, as if the dividend were the price of a transfer, with no TDS under Section 194 whatever the amount of the dividend"}],"answer":"B","explanation":"Since AY 2021-22 dividends are taxable in the investor hands; the company deducts 10% TDS above the Rs.10,000 threshold (raised from Rs.5,000 w.e.f. 1-4-2025).","source":"Original","module":"T5","topic":"Income from Other Sources","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"DIVIDEND received from an Indian company is:","options":["Fully exempt (s.10(34))","TAXABLE in the shareholder hands under other sources (DDT abolished from FY 2020-21), with TDS u/s 194 above Rs.10,000","Exempt up to Rs.10 lakh","Taxed as capital gains"],"answer":1,"explanation":"Since AY 2021-22 dividends are taxable in the investor hands; the company deducts 10% TDS above the Rs.10,000 threshold (raised from Rs.5,000 w.e.f. 1-4-2025).","revision":"original","contentSignature":"675278a9097c64579f17feef7c8b12df7fb885d0ab0591e0b0a2b5c1b2b63f1b"}]},{"id":213,"stem":"Which of the following is NOT taxed under income from other sources?","options":[{"key":"A","text":"Family pension"},{"key":"B","text":"Winnings from lotteries and crossword puzzles"},{"key":"C","text":"RENT FROM A LET-OUT BUILDING"},{"key":"D","text":"Interest on securities/bank deposits"}],"answer":"C","explanation":"Building rent is house-property income (s.22); the other three are classic other-sources items.","source":"Original","module":"T5","topic":"Income from Other Sources","reviewStatus":"Source key not independently verified"},{"id":214,"stem":"Winnings from lotteries, crossword puzzles, races, card games and online games are taxed at a flat rate of:","options":[{"key":"A","text":"30% (plus cess) under Section 115BB, with NO deduction or exemption allowed"},{"key":"B","text":"10% flat (plus cess) under Section 115BB, with no deduction or allowance of any kind"},{"key":"C","text":"20% flat (plus cess) under Section 115BB, with no deduction or allowance of any kind"},{"key":"D","text":"The normal slab rates, with every deduction and exemption allowed"}],"answer":"A","explanation":"Casual income is taxed at a flat 30% u/s 115BB; no expenditure or allowance is deductible and losses cannot be set off.","source":"Original","module":"T5","topic":"Income from Other Sources","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Winnings from lotteries, crossword puzzles, races, card games and online games are taxed at a flat rate of:","options":["30% (plus cess) under Section 115BB, with NO deduction or exemption allowed","10%","20%","Slab rates"],"answer":0,"explanation":"Casual income is taxed at a flat 30% u/s 115BB; no expenditure or allowance is deductible and losses cannot be set off.","revision":"original","contentSignature":"8e5854dedbae944e02590b947b69136b1172f6637d57da1808b2a4d36c836997"}]},{"id":215,"stem":"Family pension received by the widow/legal heir is taxed with a deduction of:","options":[{"key":"A","text":"Nil - the entire family pension is taxed with no deduction"},{"key":"B","text":"50% of the pension, with no monetary ceiling"},{"key":"C","text":"1/3rd of the pension OR Rs.15,000 (old regime) / Rs.25,000 (new regime), whichever is LESS"},{"key":"D","text":"30% of the annual value of the family home"}],"answer":"C","explanation":"Section 57(iia): the family-pension deduction is the lower of one-third or the monetary cap - Rs.15,000 old regime, raised to Rs.25,000 under the new regime (FY 2024-25 onward).","source":"Original","module":"T5","topic":"Income from Other Sources","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Family pension received by the widow/legal heir is taxed with a deduction of:","options":["Nil","50% of pension","1/3rd of the pension OR Rs.15,000 (old regime) / Rs.25,000 (new regime), whichever is LESS","30% of NAV"],"answer":2,"explanation":"Section 57(iia): the family-pension deduction is the lower of one-third or the monetary cap - Rs.15,000 old regime, raised to Rs.25,000 under the new regime (FY 2024-25 onward).","revision":"original","contentSignature":"3305f763df1519a1a334c7106c5bcb0af75b89fe15c70cd21b1b551c75120c8f"}]},{"id":216,"stem":"Gifts of money exceeding Rs.________ in aggregate during the year from non-relatives are taxable under Section 56(2)(x):","options":[{"key":"A","text":"1,00,000"},{"key":"B","text":"50,000"},{"key":"C","text":"5,000"},{"key":"D","text":"25,000"}],"answer":"B","explanation":"Aggregate cash/kind gifts above Rs.50,000 from non-relatives are taxable; gifts from specified relatives, on marriage, by inheritance/will and from local authorities/trusts are exempt.","source":"Original","module":"T5","topic":"Income from Other Sources","reviewStatus":"Source key not independently verified"},{"id":217,"stem":"Which of the following gifts is TAXABLE?","options":[{"key":"A","text":"Gift received on the occasion of marriage"},{"key":"B","text":"Gift under a will"},{"key":"C","text":"Gift from father"},{"key":"D","text":"Gift of Rs.60,000 from a FRIEND"}],"answer":"D","explanation":"Friends are not \"relatives\" for s.56(2)(x); marriage gifts, inheritances and relative gifts are exempt regardless of amount.","source":"Original","module":"T5","topic":"Income from Other Sources","reviewStatus":"Source key not independently verified"},{"id":218,"stem":"Interest on compensation/enhanced compensation (land acquisition) is:","options":[{"key":"A","text":"Fully exempt from tax, being linked to a compulsory acquisition"},{"key":"B","text":"Clubbed with the income of the spouse under Section 64"},{"key":"C","text":"Taxable as other sources, with a 50% DEDUCTION under Section 57(iv)"},{"key":"D","text":"Taxed as capital gains along with the compensation itself"}],"answer":"C","explanation":"Interest on compensation is other-sources income in the year of receipt (s.145B), with a flat 50% deduction u/s 57(iv).","source":"Original","module":"T5","topic":"Income from Other Sources","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Interest on compensation/enhanced compensation (land acquisition) is:","options":["Fully exempt","Clubbed with spouse","Taxable as other sources, with a 50% DEDUCTION under Section 57(iv)","Taxed as capital gains"],"answer":2,"explanation":"Interest on compensation is other-sources income in the year of receipt (s.145B), with a flat 50% deduction u/s 57(iv).","revision":"original","contentSignature":"0545752b2231edc2d9a1ab9f4526e2330ec5c4f6d64f6de2a0c69662b1ede179"}]},{"id":219,"stem":"Interest on FIXED DEPOSITS with a bank is:","options":[{"key":"A","text":"Exempt up to Rs.10,000 a year, and only the excess taxable"},{"key":"B","text":"Taxed at a flat rate of 30%, like lottery winnings"},{"key":"C","text":"Fully taxable under other sources (80TTA/80TTB deductions apply separately)"},{"key":"D","text":"Wholly exempt in the hands of senior citizens"}],"answer":"C","explanation":"Deposit interest is fully taxable; s.80TTA (Rs.10,000, savings interest) and s.80TTB (Rs.50,000, senior citizens) give separate deductions - but only in the OLD regime.","source":"Original","module":"T5","topic":"Income from Other Sources","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Interest on FIXED DEPOSITS with a bank is:","options":["Exempt up to Rs.10,000","Taxed at flat 30%","Fully taxable under other sources (80TTA/80TTB deductions apply separately)","Exempt for senior citizens"],"answer":2,"explanation":"Deposit interest is fully taxable; s.80TTA (Rs.10,000, savings interest) and s.80TTB (Rs.50,000, senior citizens) give separate deductions - but only in the OLD regime.","revision":"original","contentSignature":"0d41e0ecd513d978b85b54b82ce5f127656e0d5875d9665ae5af3722acaf6b5f"}]},{"id":220,"stem":"Interest on NSC (accrued annually) is:","options":[{"key":"A","text":"Taxed only at maturity in all cases, with no yearly accrual taxation, and with no Section 80C benefit for the yearly interest at any time"},{"key":"B","text":"Taxed on ACCRUAL basis as other sources - but eligible for 80C as reinvested (old regime), except in the final year"},{"key":"C","text":"Clubbed with the income of the minor child under Section 64(1A)"},{"key":"D","text":"Wholly exempt from tax, like the interest on PPF"}],"answer":"B","explanation":"NSC interest accrues yearly and is deemed reinvested (80C-eligible) except in the year of maturity.","source":"Original","module":"T5","topic":"Income from Other Sources","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Interest on NSC (accrued annually) is:","options":["Taxed only at maturity in all cases","Taxed on ACCRUAL basis as other sources - but eligible for 80C as reinvested (old regime), except in the final year","Clubbed with minor","Exempt"],"answer":1,"explanation":"NSC interest accrues yearly and is deemed reinvested (80C-eligible) except in the year of maturity.","revision":"original","contentSignature":"edb2201a0f60416147f3734a3152e9d4f24f9a1ce6331d3a68a072468068aad7"}]},{"id":221,"stem":"Lease premium received for letting out premises on lease is split between:","options":[{"key":"A","text":"Fully exempt from tax, both the premium and the rent portions alike, whatever the duration of the lease and the purpose for which the premises are let out"},{"key":"B","text":"Fully capital gains, including the rent portion of the lease receipts, as if the entire receipt were the price of a transfer of the premises"},{"key":"C","text":"Fully salary income, as if it were remuneration for services rendered by the lessor, both the premium and the rent portions alike"},{"key":"D","text":"CAPITAL GAINS (the premium part, as a transfer of rights) and the RENT portion as house-property/other-sources income"}],"answer":"D","explanation":"The premium on a lease is a capital-gains event; periodic lease rent is house-property or other-sources income.","source":"Source label not detected","module":"T5","topic":"Income from Other Sources","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Lease premium received for letting out premises on lease is split between:","options":["Fully exempt","Fully capital gains","Fully salary","CAPITAL GAINS (the premium part, as a transfer of rights) and the RENT portion as house-property/other-sources income"],"answer":3,"explanation":"The premium on a lease is a capital-gains event; periodic lease rent is house-property or other-sources income.","revision":"original","contentSignature":"ca18f0b820666844bb8d462d8d11aea1910fa6a9273f6f760429d8a2ca65ecdb"}]},{"id":222,"stem":"Advance money received and FORFEITED in failed negotiations for transfer of a capital asset is:","options":[{"key":"A","text":"Exempt, since no transfer ever took place between the parties"},{"key":"B","text":"Reduced from the cost of acquisition of the asset in the hands of the payee"},{"key":"C","text":"A capital receipt, and hence wholly outside the charge to income tax"},{"key":"D","text":"Taxable as INCOME FROM OTHER SOURCES under s.56(2)(ix) (from AY 2015-16)"}],"answer":"D","explanation":"Forfeited advance money is now other-sources income; it no longer reduces the cost of the asset.","source":"Original","module":"T5","topic":"Income from Other Sources","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Advance money received and FORFEITED in failed negotiations for transfer of a capital asset is:","options":["Exempt","Reduced from the cost of acquisition","A capital receipt","Taxable as INCOME FROM OTHER SOURCES under s.56(2)(ix) (from AY 2015-16)"],"answer":3,"explanation":"Forfeited advance money is now other-sources income; it no longer reduces the cost of the asset.","revision":"original","contentSignature":"9482a4f2fc6eb4e482e658ecc67204d2e0a1ab9626082ec3c08daf9c518cd589"}]},{"id":223,"stem":"Interest received by a NON-RESIDENT senior citizen on an NRO deposit is subject to TDS at:","options":[{"key":"A","text":"A flat 10%, exactly like the resident rate under Section 194A"},{"key":"B","text":"A flat 5%, exactly like the resident rate under Section 194A"},{"key":"C","text":"Nil - no TDS on NRO deposit interest at all, exactly like the resident rate under Section 194A, whatever the DTAA and whatever the nature of the deposit"},{"key":"D","text":"Rates under Section 195 (DTAA-modified) - higher TDS applies on non-resident payments than the resident 194A rates"}],"answer":"D","explanation":"Non-resident payments attract s.195 TDS at rates in force/DTAA relief; residents face the 194A rates. The exam recall hinges on the resident/non-resident distinction.","source":"Source label not detected","module":"T5","topic":"Income from Other Sources","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Interest received by a NON-RESIDENT senior citizen on an NRO deposit is subject to TDS at:","options":["10% flat always","5%","Nil","Rates under Section 195 (DTAA-modified) - higher TDS applies on non-resident payments than the resident 194A rates"],"answer":3,"explanation":"Non-resident payments attract s.195 TDS at rates in force/DTAA relief; residents face the 194A rates. The exam recall hinges on the resident/non-resident distinction.","revision":"original","contentSignature":"bfeb424bf27689b05222914ae9cb79931501ca0a8c518eb0e665716a62c0597c"}]},{"id":224,"stem":"Agricultural income from land situated in PAKISTAN received by a resident is:","options":[{"key":"A","text":"Clubbed with the income of the spouse under Section 64, and not taxed in her own hands at all, whatever the source of the land and the place where it is situated"},{"key":"B","text":"TAXABLE in India as income from OTHER SOURCES (foreign agricultural income is not \"agricultural income\" under the Act)"},{"key":"C","text":"Agricultural income, and hence exempt under Section 10(1), exactly as if the land were situated in India, whatever the place where it is situated"},{"key":"D","text":"Exempt up to Rs.5,000 per year, only the excess being taxable, whatever the source of the land and the place where it is situated"}],"answer":"B","explanation":"Only income from land in INDIA qualifies as agricultural income; foreign farm income of a resident is taxable as other sources.","source":"Original","module":"T5","topic":"Income from Other Sources","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Agricultural income from land situated in PAKISTAN received by a resident is:","options":["Clubbed with spouse","TAXABLE in India as income from OTHER SOURCES (foreign agricultural income is not \"agricultural income\" under the Act)","Agricultural income - exempt","Exempt up to Rs.5,000"],"answer":1,"explanation":"Only income from land in INDIA qualifies as agricultural income; foreign farm income of a resident is taxable as other sources.","revision":"original","contentSignature":"8d55733f0fe2529fbc0994d7fe3eb419ee8cc8b5c1c365bf5f3bdf82a56b243e"}]},{"id":225,"stem":"Amount received under a KEYMAN INSURANCE POLICY (including bonus) is:","options":[{"key":"A","text":"Exempt up to Rs.1 lakh in aggregate, only the excess being taxable, in the hands of whoever receives the amount"},{"key":"B","text":"Exempt under Section 10(10D), like any other life insurance policy, including the bonus"},{"key":"C","text":"Taxed as salary income, whoever receives the amount"},{"key":"D","text":"TAXABLE - s.10(10D) exemption does not apply to keyman policies; taxed as business income or other sources"}],"answer":"D","explanation":"Keyman insurance policy proceeds are expressly excluded from s.10(10D) exemption.","source":"Original","module":"T5","topic":"Income from Other Sources","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Amount received under a KEYMAN INSURANCE POLICY (including bonus) is:","options":["Exempt up to Rs.1 lakh","Exempt under s.10(10D)","Taxed as salary always","TAXABLE - s.10(10D) exemption does not apply to keyman policies; taxed as business income or other sources"],"answer":3,"explanation":"Keyman insurance policy proceeds are expressly excluded from s.10(10D) exemption.","revision":"original","contentSignature":"025acbc2eedf66dd9274354cf51c7193f220005d8c07c21c21461efa2642aea4"}]},{"id":226,"stem":"Shares received WITHOUT consideration or for inadequate consideration by a firm or closely-held company are taxed under:","options":[{"key":"A","text":"Section 56(2)(x) - fair value above Rs.50,000 taxed in the recipient hands"},{"key":"B","text":"Section 28 - taxed as the business income of the recipient firm or company, whatever the value"},{"key":"C","text":"Section 45 - taxed as capital gains of the recipient firm or company, whatever the value"},{"key":"D","text":"Exempt, since no consideration passed between the parties, whatever the value of the shares"}],"answer":"A","explanation":"Section 56(2)(x) taxes any person (including firms and closely-held companies) receiving shares or other specified property for nil or inadequate consideration, where the fair-value shortfall exceeds Rs.50,000.","source":"Original","module":"T5","topic":"Income from Other Sources","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Shares received WITHOUT consideration or for inadequate consideration by a firm or closely-held company are taxed under:","options":["Section 56(2)(x) - fair value above Rs.50,000 taxed in the recipient hands","Section 28","Section 45","Exempt"],"answer":0,"explanation":"Section 56(2)(x) taxes any person (including firms and closely-held companies) receiving shares or other specified property for nil or inadequate consideration, where the fair-value shortfall exceeds Rs.50,000.","revision":"original","contentSignature":"623b289ceca832f9a74775d539cfeabfb227a2c47f3c7be1df0f9a377806db74"}]},{"id":227,"stem":"A scholarship granted to meet the cost of education is:","options":[{"key":"A","text":"Taxable at a flat rate of 10% in the recipient hands"},{"key":"B","text":"Clubbed with the income of the parent under Section 64(1A)"},{"key":"C","text":"Fully EXEMPT under Section 10(16)"},{"key":"D","text":"Taxable as salary income, as if it were remuneration"}],"answer":"C","explanation":"Section 10(16) exempts scholarships entirely, regardless of amount or recipient.","source":"Original","module":"T5","topic":"Income from Other Sources","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A scholarship granted to meet the cost of education is:","options":["Taxable at 10%","Clubbed with parent","Fully EXEMPT under Section 10(16)","Taxable as salary"],"answer":2,"explanation":"Section 10(16) exempts scholarships entirely, regardless of amount or recipient.","revision":"original","contentSignature":"5b6b898a9d13cec0d68f0109dc7d15be98e298fb1461e660ad5e74c836b95684"}]},{"id":228,"stem":"Interest on REFUND of income tax is:","options":[{"key":"A","text":"Taxed as capital gains in the year of receipt, as if a transfer occurred"},{"key":"B","text":"Part of the refund itself, and hence not taxed separately at all"},{"key":"C","text":"Wholly exempt from tax, being a payment by the Government"},{"key":"D","text":"Taxable as income from OTHER SOURCES in the year of receipt"}],"answer":"D","explanation":"Section 244A interest is taxable as other-sources income in the year the refund is received.","source":"Original","module":"T5","topic":"Income from Other Sources","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Interest on REFUND of income tax is:","options":["Taxed as capital gains","Part of the refund","Exempt","Taxable as income from OTHER SOURCES in the year of receipt"],"answer":3,"explanation":"Section 244A interest is taxable as other-sources income in the year the refund is received.","revision":"original","contentSignature":"2c6dbb5865cc9a2d60e132b1f2389c64f0ddf6111f168b324865f03f01298303"}]},{"id":229,"stem":"The deduction for interest on compensation money u/s 57(iv) is:","options":[{"key":"A","text":"1/3rd"},{"key":"B","text":"50%"},{"key":"C","text":"100%"},{"key":"D","text":"30%"}],"answer":"B","explanation":"A flat 50% deduction is allowed against interest on compensation/enhanced compensation.","source":"Original","module":"T5","topic":"Income from Other Sources","reviewStatus":"Source key not independently verified"},{"id":230,"stem":"Expenses deductible from other-sources income under Section 57 do NOT include:","options":[{"key":"A","text":"PERSONAL expenses of the assessee"},{"key":"B","text":"Collection charges for interest/dividends"},{"key":"C","text":"Repairs, insurance and depreciation on machinery/furniture let out"},{"key":"D","text":"Interest/commission paid to earn the income"}],"answer":"A","explanation":"Section 57 allows only expenses laid out wholly and exclusively for earning the income (and the specified items); personal expenses are barred (s.58(1)(a)(i)).","source":"Original","module":"T5","topic":"Income from Other Sources","reviewStatus":"Source key not independently verified"},{"id":231,"stem":"Clubbing of income (Sections 60-64) is designed to:","options":[{"key":"A","text":"Increase the exemption limits available to the family, by spreading the income across as many hands as possible"},{"key":"B","text":"Bring the foreign income of non-residents within the Indian tax net, however and wherever it is earned"},{"key":"C","text":"Prevent AVOIDANCE of tax by transferring income (without the asset) or assets to related persons while retaining benefit"},{"key":"D","text":"Double the tax payable by the family, as a penalty for transfers between related persons"}],"answer":"C","explanation":"Clubbing provisions attribute diverted income back to the transferor to check tax avoidance through family arrangements.","source":"Original","module":"T6","topic":"Clubbing, Set-off & Carry Forward","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Clubbing of income (Sections 60-64) is designed to:","options":["Increase exemption limits","Tax foreign income","Prevent AVOIDANCE of tax by transferring income (without the asset) or assets to related persons while retaining benefit","Double the tax"],"answer":2,"explanation":"Clubbing provisions attribute diverted income back to the transferor to check tax avoidance through family arrangements.","revision":"original","contentSignature":"37938217c7f6838e69fa16e8462223a50668761a3f86caba67e8c5d8e2d49b7c"}]},{"id":232,"stem":"Where income is transferred WITHOUT transferring the asset, the income is taxed in the hands of:","options":[{"key":"A","text":"Neither the transferor nor the transferee"},{"key":"B","text":"Both the transferor and the transferee equally"},{"key":"C","text":"The TRANSFEREE, who actually receives it"},{"key":"D","text":"The TRANSFEROR (Section 60)"}],"answer":"D","explanation":"Section 60: revocable or asset-less income transfers keep the income taxable in the transferor hands.","source":"Original","module":"T6","topic":"Clubbing, Set-off & Carry Forward","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Where income is transferred WITHOUT transferring the asset, the income is taxed in the hands of:","options":["Neither","Both equally","The transferee","The TRANSFEROR (Section 60)"],"answer":3,"explanation":"Section 60: revocable or asset-less income transfers keep the income taxable in the transferor hands.","revision":"original","contentSignature":"2ea248bd4c4eb54ec2353163cf72428c6b12bebd286b9235c96d9e4eddaafe59"}]},{"id":233,"stem":"A REVOCABLE transfer of assets is taxed in the hands of:","options":[{"key":"A","text":"The TRANSFEROR (Section 61) - the power to revoke keeps the income with him"},{"key":"B","text":"The trust which holds the assets as a separate entity"},{"key":"C","text":"The transferee who holds the assets for the time being"},{"key":"D","text":"The minor child of the transferor"}],"answer":"A","explanation":"Sections 61-63: income from revocable transfers is taxed in the transferor hands; an irrevocable transfer (for life of the transferee or beyond) escapes this rule.","source":"Original","module":"T6","topic":"Clubbing, Set-off & Carry Forward","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A REVOCABLE transfer of assets is taxed in the hands of:","options":["The TRANSFEROR (Section 61) - the power to revoke keeps the income with him","The trust","The transferee","The minor child"],"answer":0,"explanation":"Sections 61-63: income from revocable transfers is taxed in the transferor hands; an irrevocable transfer (for life of the transferee or beyond) escapes this rule.","revision":"original","contentSignature":"0de7db1546cb32b44766e1dc09148a85281681b214522c479bab19fd60104d97"}]},{"id":234,"stem":"Salary/commission received by a SPOUSE from a concern in which the other spouse has a SUBSTANTIAL INTEREST is clubbed with the income of:","options":[{"key":"A","text":"The minor child of the couple - clubbed under s.64(1A) with the parent earning the higher income, whether or not the earning spouse possesses any technical or professional qualification and whether or not the income is attributable to such qualification"},{"key":"B","text":"The employer concern itself - the salary is simply disallowed to it, whether or not the earning spouse possesses any technical or professional qualification and whether or not the income is attributable to such qualification"},{"key":"C","text":"The OTHER spouse - UNLESS the earning spouse possesses technical or professional qualification and the income is solely attributable to that qualification (s.64(1)(ii))"},{"key":"D","text":"The earning spouse, with no exception for technical or professional qualification"}],"answer":"C","explanation":"Substantial interest = 20%+ voting power (company) or profit share (firm); the professional-qualification exception prevents clubbing of genuinely earned pay.","source":"Original","module":"T6","topic":"Clubbing, Set-off & Carry Forward","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Salary/commission received by a SPOUSE from a concern in which the other spouse has a SUBSTANTIAL INTEREST is clubbed with the income of:","options":["The minor child","The employer","The OTHER spouse - UNLESS the earning spouse possesses technical or professional qualification and the income is solely attributable to that qualification (s.64(1)(ii))","The earning spouse always"],"answer":2,"explanation":"Substantial interest = 20%+ voting power (company) or profit share (firm); the professional-qualification exception prevents clubbing of genuinely earned pay.","revision":"original","contentSignature":"a873305176d874c77a5b30c24b7ac12b4b2a8789c57017495081713c488c5ab8"}]},{"id":235,"stem":"Income from assets transferred to the SPOUSE without adequate consideration (not in connection with an agreement to live apart) is:","options":[{"key":"A","text":"Taxed in the transferee spouse hands alone, like any other owner"},{"key":"B","text":"Taxed at the flat rate of 30%, like casual income"},{"key":"C","text":"CLUBBED with the transferor income under s.64(1)(iv)"},{"key":"D","text":"Exempt, being a transfer between spouses"}],"answer":"C","explanation":"Direct transfers to spouse (and to son wife, s.64(1)(vi)) without adequate consideration attract clubbing with the transferor.","source":"Original","module":"T6","topic":"Clubbing, Set-off & Carry Forward","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Income from assets transferred to the SPOUSE without adequate consideration (not in connection with an agreement to live apart) is:","options":["Taxed in the transferee spouse hands","Taxed at 30%","CLUBBED with the transferor income under s.64(1)(iv)","Exempt"],"answer":2,"explanation":"Direct transfers to spouse (and to son wife, s.64(1)(vi)) without adequate consideration attract clubbing with the transferor.","revision":"original","contentSignature":"b8b6910fe9ebc33263a0025d29de3410bc95cce3282cf5bd51bf6fa3c14a49cf"}]},{"id":236,"stem":"Income of a MINOR CHILD is clubbed with:","options":[{"key":"A","text":"The parent whose TOTAL INCOME (before clubbing) is GREATER (s.64(1A)); where the marriage does not subsist, with the parent who maintains the child"},{"key":"B","text":"Nobody - a minor is always separately assessed on his own income, whatever its source, and even where the marriage of the parents subsists and both parents have income of their own"},{"key":"C","text":"The father, whether or not his total income is the greater"},{"key":"D","text":"The guardian appointed by the court"}],"answer":"A","explanation":"Once the higher-income parent is fixed, the choice stays for subsequent years unless the income order changes; exemption of Rs.1,500 per child u/s 10(32).","source":"Original","module":"T6","topic":"Clubbing, Set-off & Carry Forward","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Income of a MINOR CHILD is clubbed with:","options":["The parent whose TOTAL INCOME (before clubbing) is GREATER (s.64(1A)); where the marriage does not subsist, with the parent who maintains the child","Nobody - minors are separately assessed always","The father income always","The guardian appointed by court"],"answer":0,"explanation":"Once the higher-income parent is fixed, the choice stays for subsequent years unless the income order changes; exemption of Rs.1,500 per child u/s 10(32).","revision":"original","contentSignature":"1333d99bac26e5797bf6148feddd87aa3a1a343170aa8d338bd617eb6b912dba"}]},{"id":237,"stem":"Clubbing does NOT apply to income earned by a minor child from:","options":[{"key":"A","text":"Interest on fixed deposits gifted to him by his parents, out of their own funds"},{"key":"B","text":"Gifts in cash received by him from his grandparents on birthdays"},{"key":"C","text":"His OWN manual work or specialised talent/knowledge (e.g. a child artist)"},{"key":"D","text":"Interest on his savings bank account, built up from gifts"}],"answer":"C","explanation":"Proviso to s.64(1A): income from the child personal skill, manual work or specialised knowledge is taxed in the child own assessment.","source":"Original","module":"T6","topic":"Clubbing, Set-off & Carry Forward","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Clubbing does NOT apply to income earned by a minor child from:","options":["Fixed deposits gifted by parents","Gifts from grandparents","His OWN manual work or specialised talent/knowledge (e.g. a child artist)","Savings account interest"],"answer":2,"explanation":"Proviso to s.64(1A): income from the child personal skill, manual work or specialised knowledge is taxed in the child own assessment.","revision":"original","contentSignature":"0f83ebca3ebe5ef3f09e43753f1bd1a40f13e3b62a62ff6981cec73a5b3a673d"}]},{"id":238,"stem":"The exemption for clubbed minor child income under Section 10(32) is:","options":[{"key":"A","text":"Rs.5,000 per child"},{"key":"B","text":"Rs.1,500 per child per year"},{"key":"C","text":"Rs.2,500 per child"},{"key":"D","text":"Rs.10,000 per child"}],"answer":"B","explanation":"Rs.1,500 per minor child (or the clubbed income, if less) is exempt to the parent in whose hands it is clubbed.","source":"Original","module":"T6","topic":"Clubbing, Set-off & Carry Forward","reviewStatus":"Source key not independently verified"},{"id":239,"stem":"Income from property transferred to a HINDU UNDIVIDED FAMILY by a member without consideration, before partition, is:","options":[{"key":"A","text":"CLUBBED with the member income; after partition it is clubbed with the spouse income in the hands of the transferor (s.64(2))"},{"key":"B","text":"Taxed in the HUF hands alone, both before and after any partition of the family, with no clubbing in the hands of the member or his spouse at any time"},{"key":"C","text":"Taxed at the flat rate of 20% in the member hands, both before and after any partition of the family, with no clubbing in the hands of the member or his spouse at any time"},{"key":"D","text":"Exempt altogether, both before and after any partition of the family, with no clubbing in the hands of the member or his spouse at any time"}],"answer":"A","explanation":"Section 64(2): converted property income is deemed to be the individual income of the transferor; post-partition, the spouse share is clubbed.","source":"Original","module":"T6","topic":"Clubbing, Set-off & Carry Forward","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Income from property transferred to a HINDU UNDIVIDED FAMILY by a member without consideration, before partition, is:","options":["CLUBBED with the member income; after partition it is clubbed with the spouse income in the hands of the transferor (s.64(2))","Taxed in the HUF hands","Taxed at 20%","Exempt"],"answer":0,"explanation":"Section 64(2): converted property income is deemed to be the individual income of the transferor; post-partition, the spouse share is clubbed.","revision":"original","contentSignature":"cfa53c683a3b9368dd5bb406cd1d1afc7cbcf12591a16617b251ce183a0ec82e"}]},{"id":240,"stem":"Loss from one SOURCE can be set off against income of another source under the SAME head - this is called:","options":[{"key":"A","text":"Carry forward"},{"key":"B","text":"Inter-head set-off"},{"key":"C","text":"Clubbing"},{"key":"D","text":"INTRA-HEAD set-off (s.70)"}],"answer":"D","explanation":"Section 70 permits intra-head (same-head) set-off; s.71 permits inter-head set-off, subject to exceptions.","source":"Original","module":"T6","topic":"Clubbing, Set-off & Carry Forward","reviewStatus":"Source key not independently verified"},{"id":241,"stem":"Which loss CANNOT be set off against income under any OTHER head in the same year?","options":[{"key":"A","text":"Non-speculation business loss - it can never be set off against any other head in the same year"},{"key":"B","text":"House property loss within Rs.2 lakh - it can never be set off against any other head in the same year"},{"key":"C","text":"Other sources loss - it can never be set off against any other head in the same year"},{"key":"D","text":"SPECULATION loss (only against speculation profits) and CAPITAL loss (only against capital gains)"}],"answer":"D","explanation":"Speculation losses (s.73) and capital losses (s.70(2)/74) are ring-fenced to their own categories.","source":"Original","module":"T6","topic":"Clubbing, Set-off & Carry Forward","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which loss CANNOT be set off against income under any OTHER head in the same year?","options":["Non-speculation business loss","House property loss (within Rs.2 lakh)","Other sources loss","SPECULATION loss (only against speculation profits) and CAPITAL loss (only against capital gains)"],"answer":3,"explanation":"Speculation losses (s.73) and capital losses (s.70(2)/74) are ring-fenced to their own categories.","revision":"original","contentSignature":"c0609a1fcbae10dc2ab8a4ace4d578d574c0f08cfa6280420b27b0fb32c37eea"}]},{"id":242,"stem":"Loss under the head \"Income from house property\" can be set off against other heads in the same year up to:","options":[{"key":"A","text":"Rs.1,50,000"},{"key":"B","text":"No limit"},{"key":"C","text":"Rs.50,000"},{"key":"D","text":"Rs.2,00,000"}],"answer":"D","explanation":"Section 71(3A) caps inter-head set-off of house-property loss at Rs.2 lakh; the balance carries forward 8 years (s.71B).","source":"Original","module":"T6","topic":"Clubbing, Set-off & Carry Forward","reviewStatus":"Source key not independently verified"},{"id":243,"stem":"Business loss (non-speculation) can be carried forward for ________ and set off against ________:","options":[{"key":"A","text":"Carried forward indefinitely, and set off against any head of income"},{"key":"B","text":"8 ASSESSMENT YEARS; profits of any business/profession only"},{"key":"C","text":"4 assessment years, and set off against any income at all"},{"key":"D","text":"8 assessment years, and set off against any head of income"}],"answer":"B","explanation":"Section 72: 8-year carry forward, set off only against business/profession profits; filing the loss return in time is a precondition (s.80).","source":"Original","module":"T6","topic":"Clubbing, Set-off & Carry Forward","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Business loss (non-speculation) can be carried forward for ________ and set off against ________:","options":["Indefinitely; any head","8 ASSESSMENT YEARS; profits of any business/profession only","4 years; any income","8 years; any head"],"answer":1,"explanation":"Section 72: 8-year carry forward, set off only against business/profession profits; filing the loss return in time is a precondition (s.80).","revision":"original","contentSignature":"4717320d856c3abfd35ba61c21d37b5bba7cc51b3f6a26bb3266b48b1c7188cc"}]},{"id":244,"stem":"For carry forward of LOSSES (other than house-property loss), the return must be filed:","options":[{"key":"A","text":"Never required - losses carry forward even without any return at all"},{"key":"B","text":"On or before the DUE DATE under Section 139(1) (Section 80)"},{"key":"C","text":"At any time before the assessment is completed for the year"},{"key":"D","text":"Within 4 years from the end of the relevant previous year"}],"answer":"B","explanation":"Section 80 bars carry forward unless the loss return is filed by the s.139(1) due date; belated filing forfeits carry forward (though current-year set-off survives).","source":"Original","module":"T6","topic":"Clubbing, Set-off & Carry Forward","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"For carry forward of LOSSES (other than house-property loss), the return must be filed:","options":["Never required","On or before the DUE DATE under Section 139(1) (Section 80)","Any time before assessment","Within 4 years"],"answer":1,"explanation":"Section 80 bars carry forward unless the loss return is filed by the s.139(1) due date; belated filing forfeits carry forward (though current-year set-off survives).","revision":"original","contentSignature":"e17be996535cfbe032fefe357dee8fe4cfa44607c4f6decbb4285e9f1f89f7cd"}]},{"id":245,"stem":"Unabsorbed depreciation, in the order of set-off, is treated as:","options":[{"key":"A","text":"A capital loss - carried forward for only 8 years, and claimed AFTER every brought-forward business loss"},{"key":"B","text":"A business loss of the year - carried forward for only 8 years, and claimed AFTER every brought-forward business loss"},{"key":"C","text":"A speculation loss - carried forward for only 4 years, and claimed AFTER every brought-forward business loss"},{"key":"D","text":"CURRENT-YEAR depreciation - carried forward indefinitely, and claimed BEFORE brought-forward business loss"}],"answer":"D","explanation":"Section 32(2): unabsorbed depreciation is deemed depreciation of the following year, with indefinite carry forward and priority over brought-forward business losses.","source":"Original","module":"T6","topic":"Clubbing, Set-off & Carry Forward","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Unabsorbed depreciation, in the order of set-off, is treated as:","options":["A capital loss","A business loss of the year","A speculation loss","CURRENT-YEAR depreciation - carried forward indefinitely, and claimed BEFORE brought-forward business loss"],"answer":3,"explanation":"Section 32(2): unabsorbed depreciation is deemed depreciation of the following year, with indefinite carry forward and priority over brought-forward business losses.","revision":"original","contentSignature":"3d8feae9ceee363aab3cb27f66f146d0a9edc8189ae6d4ebbee4f69b8b1032d8"}]},{"id":246,"stem":"The correct order of set-off is: (1) current depreciation, (2) capital expenditure on scientific research, (3) ________, (4) unabsorbed depreciation:","options":[{"key":"A","text":"Capital losses first, then everything else in any order"},{"key":"B","text":"Donations under Section 80G first, then everything else"},{"key":"C","text":"Current-year losses first, then brought-forward BUSINESS LOSS, then unabsorbed depreciation"},{"key":"D","text":"Brought-forward business loss first, then unabsorbed depreciation, then current-year losses"}],"answer":"C","explanation":"Priority: current depreciation and scientific-research capex, then brought-forward business loss, then unabsorbed depreciation (s.72(2) ordering read with s.35(4) and s.32(2)).","source":"Original","module":"T6","topic":"Clubbing, Set-off & Carry Forward","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The correct order of set-off is: (1) current depreciation, (2) capital expenditure on scientific research, (3) ________, (4) unabsorbed depreciation:","options":["Capital losses","Donations","Current-year losses first, then brought-forward BUSINESS LOSS, then unabsorbed depreciation","Brought-forward business loss"],"answer":2,"explanation":"Priority: current depreciation and scientific-research capex, then brought-forward business loss, then unabsorbed depreciation (s.72(2) ordering read with s.35(4) and s.32(2)).","revision":"original","contentSignature":"c95ed796d441694764a44b47e3d1bd6482705d100b5275080e5835a742fa3dd2"}]},{"id":247,"stem":"Loss from the activity of owning and maintaining RACE HORSES can be set off against:","options":[{"key":"A","text":"House property income of the same year, like any other loss"},{"key":"B","text":"Any business income of the same year, without limit"},{"key":"C","text":"Salary income of the same year, like any other loss"},{"key":"D","text":"Income from the SAME activity only, carried forward 4 years"}],"answer":"D","explanation":"Section 74A: race-horse activity losses are ring-fenced to the same activity with a 4-year carry forward.","source":"Original","module":"T6","topic":"Clubbing, Set-off & Carry Forward","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Loss from the activity of owning and maintaining RACE HORSES can be set off against:","options":["House property","Any business income","Salary","Income from the SAME activity only, carried forward 4 years"],"answer":3,"explanation":"Section 74A: race-horse activity losses are ring-fenced to the same activity with a 4-year carry forward.","revision":"original","contentSignature":"c106c234445a3bc6ab648ed212948695fdca672bab666e3d578dcbe33ea4bda0"}]},{"id":248,"stem":"Loss under \"Capital gains\" can be set off in the same year against:","options":[{"key":"A","text":"Income from other sources, like interest, in the same year"},{"key":"B","text":"Salary income, in the same year"},{"key":"C","text":"Business income, speculative or not, in the same year"},{"key":"D","text":"Capital gains only (intra-head within the capital-gains head)"}],"answer":"D","explanation":"Capital losses cannot move to any other head; within the year they set off against capital gains, with LTCL restricted to LTCG.","source":"Original","module":"T6","topic":"Clubbing, Set-off & Carry Forward","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Loss under \"Capital gains\" can be set off in the same year against:","options":["Other sources","Salary income","Business income","Capital gains only (intra-head within the capital-gains head)"],"answer":3,"explanation":"Capital losses cannot move to any other head; within the year they set off against capital gains, with LTCL restricted to LTCG.","revision":"original","contentSignature":"ef3ac87160388aaab0d7460f34852ec22b08451c54fd01ad6dd2be09d6b4a4b8"}]},{"id":249,"stem":"A HUF suffers a business loss which cannot be set off fully in the year. It can be carried forward by:","options":[{"key":"A","text":"The eldest member"},{"key":"B","text":"Nobody"},{"key":"C","text":"The HUF ITSELF for 8 years"},{"key":"D","text":"The karta personally"}],"answer":"C","explanation":"The same assessment entity carries the loss forward; on partition of the HUF, unabsorbed losses cannot be carried forward by members.","source":"Original","module":"T6","topic":"Clubbing, Set-off & Carry Forward","reviewStatus":"Source key not independently verified"},{"id":250,"stem":"Where an assessee dies leaving an unabsorbed business loss, the loss:","options":[{"key":"A","text":"Transfers to the HUF of which he was a member, and is carried forward in its hands for the remaining years, since the income of the family was always assessed jointly and the loss belongs to the family as much as to the deceased"},{"key":"B","text":"LAPSES - carry forward is personal to the assessee (except unabsorbed depreciation, which also lapses... properly: losses do not pass to heirs; only the deceased own assessment can use them)"},{"key":"C","text":"Transfers to the spouse, who carries it forward in her own hands for the remaining years"},{"key":"D","text":"Carries forward to the legal heir, who sets it off against his own income for the remaining years"}],"answer":"B","explanation":"Carry-forward rights are personal to the assessee; a legal heir cannot claim the deceased brought-forward business losses (s.78(2) permits carry forward to the successor only in specified successions to business, not on inheritance).","source":"Original","module":"T6","topic":"Clubbing, Set-off & Carry Forward","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Where an assessee dies leaving an unabsorbed business loss, the loss:","options":["Transfers to HUF","LAPSES - carry forward is personal to the assessee (except unabsorbed depreciation, which also lapses... properly: losses do not pass to heirs; only the deceased own assessment can use them)","Transfers to spouse","Carries forward to the legal heir"],"answer":1,"explanation":"Carry-forward rights are personal to the assessee; a legal heir cannot claim the deceased brought-forward business losses (s.78(2) permits carry forward to the successor only in specified successions to business, not on inheritance).","revision":"original","contentSignature":"3028e22f4aa2dc5e47e29081179f2da855f183f023efa3112089952dc7508c33"}]},{"id":251,"stem":"Deductions under Chapter VI-A (80C to 80U) are allowed from:","options":[{"key":"A","text":"GROSS TOTAL INCOME - but cannot exceed the GTI"},{"key":"B","text":"Capital gains only, and no other head of income at all"},{"key":"C","text":"Salary income only, and no other head of income at all"},{"key":"D","text":"Total income, after the deductions are given"}],"answer":"A","explanation":"VI-A deductions reduce GTI to arrive at total income; the aggregate cannot exceed GTI (no loss creation).","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Deductions under Chapter VI-A (80C to 80U) are allowed from:","options":["GROSS TOTAL INCOME - but cannot exceed the GTI","Capital gains only","Salary only","Total income"],"answer":0,"explanation":"VI-A deductions reduce GTI to arrive at total income; the aggregate cannot exceed GTI (no loss creation).","revision":"original","contentSignature":"4a25d340abbc8e468c8c5ad59b9d78e5ba0ffb91597280cc399e8698e601b125"}]},{"id":252,"stem":"The maximum deduction under Section 80C (LIC premium, PPF, EPF, NSC, ELSS, tuition fees, home-loan principal, 5-year tax-saver FD, Sukanya Samriddhi etc.) is:","options":[{"key":"A","text":"Rs.1,00,000"},{"key":"B","text":"Rs.2,00,000"},{"key":"C","text":"Rs.1,50,000"},{"key":"D","text":"Rs.50,000"}],"answer":"C","explanation":"Section 80C caps at Rs.1.5 lakh; 80CCC (pension funds) and 80CCD(1) (self NPS) share this ceiling via s.80CCE.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":253,"stem":"The COMBINED ceiling under Section 80CCE (80C + 80CCC + 80CCD(1)) is:","options":[{"key":"A","text":"Rs.2,00,000"},{"key":"B","text":"Rs.1,50,000"},{"key":"C","text":"Rs.2,50,000"},{"key":"D","text":"Rs.1,00,000"}],"answer":"B","explanation":"80CCE caps the trio at Rs.1.5 lakh; the extra NPS benefit of Rs.50,000 comes under 80CCD(1B) outside this cap.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":254,"stem":"An additional deduction for self-contribution to NPS under Section 80CCD(1B), over and above the 80CCE limit, is:","options":[{"key":"A","text":"Rs.50,000"},{"key":"B","text":"Rs.25,000"},{"key":"C","text":"Rs.1,50,000"},{"key":"D","text":"Rs.1,00,000"}],"answer":"A","explanation":"80CCD(1B) gives an extra Rs.50,000 for NPS Tier-I contributions - over and above the Rs.1.5 lakh 80CCE basket.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":255,"stem":"Employer NPS contribution deductible to the employee under 80CCD(2) is capped at:","options":[{"key":"A","text":"10% of basic+DA in old regime; 14% of basic+DA in the NEW regime (private sector included, from FY 2024-25)"},{"key":"B","text":"15% of gross salary in both the regimes alike, private sector included, whatever the year"},{"key":"C","text":"Nil - employer NPS contribution is never deductible to the employee at all"},{"key":"D","text":"A flat Rs.50,000 in both the regimes alike, private sector included, whatever the year"}],"answer":"A","explanation":"80CCD(2) is outside 80CCE; the new-regime limit is 14% of basic+DA for all employees (10% in the old regime for private sector; 14% for Central Government in both).","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Employer NPS contribution deductible to the employee under 80CCD(2) is capped at:","options":["10% of basic+DA in old regime; 14% of basic+DA in the NEW regime (private sector included, from FY 2024-25)","15% of gross salary","Nil","Rs.50,000 flat"],"answer":0,"explanation":"80CCD(2) is outside 80CCE; the new-regime limit is 14% of basic+DA for all employees (10% in the old regime for private sector; 14% for Central Government in both).","revision":"original","contentSignature":"f00c229405f6cf506dafa16ab3d5ae122bcca5ca7065b2f6c91475c2470a9c0c"}]},{"id":256,"stem":"Section 80D deduction for medical insurance premium for SELF, SPOUSE AND DEPENDENT CHILDREN (none a senior citizen) is up to:","options":[{"key":"A","text":"Rs.50,000"},{"key":"B","text":"Rs.1,00,000"},{"key":"C","text":"Rs.25,000"},{"key":"D","text":"Rs.15,000"}],"answer":"C","explanation":"80D: Rs.25,000 for self+spouse+dependent children; an ADDITIONAL Rs.25,000 for parents (Rs.50,000 if parents are senior citizens).","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":257,"stem":"The 80D deduction for a SENIOR CITIZEN (60+) covering his own family premium is up to:","options":[{"key":"A","text":"Rs.30,000"},{"key":"B","text":"Rs.50,000"},{"key":"C","text":"Rs.25,000"},{"key":"D","text":"Rs.75,000"}],"answer":"B","explanation":"Senior citizens get Rs.50,000; a super-senior (80+) without insurance can claim medical EXPENDITURE up to Rs.50,000.","source":"Source label not detected","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":258,"stem":"Preventive health check-up expenditure is deductible under 80D up to:","options":[{"key":"A","text":"Rs.25,000, over and above the overall 80D ceiling (cash payment permitted)"},{"key":"B","text":"Nil - preventive health check-ups get no deduction at all under 80D"},{"key":"C","text":"Rs.5,000, WITHIN the overall 80D ceiling (cash payment permitted)"},{"key":"D","text":"Rs.10,000 separately, over and above the overall 80D ceiling"}],"answer":"C","explanation":"Preventive check-ups get Rs.5,000 within the overall Rs.25,000/Rs.50,000 cap - and may be paid in cash.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Preventive health check-up expenditure is deductible under 80D up to:","options":["Rs.25,000","Nil","Rs.5,000, WITHIN the overall 80D ceiling (cash payment permitted)","Rs.10,000 separately"],"answer":2,"explanation":"Preventive check-ups get Rs.5,000 within the overall Rs.25,000/Rs.50,000 cap - and may be paid in cash.","revision":"original","contentSignature":"8ce09331d3e55bfa20fa734ab188033a9cd37737da7610cbd13fa7aa83e20636"}]},{"id":259,"stem":"Maximum deduction under Section 80D for a person paying premium for self (below 60) AND senior-citizen parents is:","options":[{"key":"A","text":"Rs.1,00,000"},{"key":"B","text":"Rs.75,000"},{"key":"C","text":"Rs.50,000"},{"key":"D","text":"Rs.25,000"}],"answer":"B","explanation":"Rs.25,000 (self family) + Rs.50,000 (senior-citizen parents) = Rs.75,000; if the taxpayer is also a senior citizen, it can reach Rs.1,00,000.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":260,"stem":"80D premiums must be paid by:","options":[{"key":"A","text":"Demand draft only - even cheque, card and electronic payments do not qualify for the 80D deduction at all, and preventive check-ups are no exception"},{"key":"B","text":"Cash only - cheque, card and every kind of electronic payment fail to qualify for the 80D deduction at all, and preventive check-ups are no exception"},{"key":"C","text":"NEFT transfer only - cheque and card payments do not qualify"},{"key":"D","text":"Any mode EXCEPT cash (cheque/card/electronic) - only preventive check-ups can be cash"}],"answer":"D","explanation":"Section 80D(2B) requires non-cash payment for premiums; preventive health check-ups may be paid in cash.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"80D premiums must be paid by:","options":["Demand draft only","Cash","NEFT only","Any mode EXCEPT cash (cheque/card/electronic) - only preventive check-ups can be cash"],"answer":3,"explanation":"Section 80D(2B) requires non-cash payment for premiums; preventive health check-ups may be paid in cash.","revision":"original","contentSignature":"0e10119127fcaaf5d10372a29d5bfcbd610053aef2f66580ea4f37c770b4c403"}]},{"id":261,"stem":"Section 80DD deduction for maintenance including medical treatment of a DEPENDENT with DISABILITY is:","options":[{"key":"A","text":"Rs.75,000 flat - Rs.1,25,000 for SEVERE disability (80%+), regardless of actual expenditure"},{"key":"B","text":"Only the actual expenses incurred, whatever their amount, with no flat deduction"},{"key":"C","text":"Rs.40,000 flat - Rs.75,000 for severe disability (80%+)"},{"key":"D","text":"Rs.25,000 flat - Rs.50,000 for severe disability (80%+)"}],"answer":"A","explanation":"80DD is a flat deduction (not expenditure-linked): Rs.75,000 normal disability, Rs.1,25,000 severe disability, for resident assessees with disabled dependants.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Section 80DD deduction for maintenance including medical treatment of a DEPENDENT with DISABILITY is:","options":["Rs.75,000 flat - Rs.1,25,000 for SEVERE disability (80%+), regardless of actual expenditure","Actual expenses","Rs.40,000","Rs.25,000"],"answer":0,"explanation":"80DD is a flat deduction (not expenditure-linked): Rs.75,000 normal disability, Rs.1,25,000 severe disability, for resident assessees with disabled dependants.","revision":"original","contentSignature":"0d4f45c1676ba7077fdf61672d71c86326950a4db0d21dd27a2274bd3844e71e"}]},{"id":262,"stem":"Section 80DDB (treatment of specified diseases) deduction is:","options":[{"key":"A","text":"Rs.50,000 flat (Rs.75,000 for senior citizens)"},{"key":"B","text":"Rs.75,000 flat (Rs.1,25,000 for senior citizens)"},{"key":"C","text":"Rs.40,000 (Rs.1,00,000 for SENIOR CITIZENS)"},{"key":"D","text":"The actual expenses incurred, without any monetary ceiling"}],"answer":"C","explanation":"80DDB: up to Rs.40,000, raised to Rs.1,00,000 when the patient is a senior citizen; the amount is reduced by any insurance/employer reimbursement.","source":"Source label not detected","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Section 80DDB (treatment of specified diseases) deduction is:","options":["Rs.50,000","Rs.75,000 flat","Rs.40,000 (Rs.1,00,000 for SENIOR CITIZENS)","Actual expenses always"],"answer":2,"explanation":"80DDB: up to Rs.40,000, raised to Rs.1,00,000 when the patient is a senior citizen; the amount is reduced by any insurance/employer reimbursement.","revision":"original","contentSignature":"2850c37f060251b747521eb80c124de903a7a87bf1f5f42e0665fa4c0aeb44b8"}]},{"id":263,"stem":"Section 80E deduction for interest on an EDUCATION LOAN for higher studies is:","options":[{"key":"A","text":"Rs.50,000 per year, for a maximum of 5 years, with that monetary ceiling applying every year"},{"key":"B","text":"Rs.1.5 lakh per year, for a maximum of 8 years, with that monetary ceiling applying every year"},{"key":"C","text":"Up to Rs.40,000 per year, for a maximum of 8 years, with that monetary ceiling applying every year"},{"key":"D","text":"The ENTIRE interest, for a maximum of 8 YEARS, with no monetary ceiling"}],"answer":"D","explanation":"80E covers full interest (no cap) on loans for self/spouse/children/ward higher education, for up to 8 years from the first repayment year.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Section 80E deduction for interest on an EDUCATION LOAN for higher studies is:","options":["Rs.50,000","Rs.1.5 lakh","Up to Rs.40,000","The ENTIRE interest, for a maximum of 8 YEARS, with no monetary ceiling"],"answer":3,"explanation":"80E covers full interest (no cap) on loans for self/spouse/children/ward higher education, for up to 8 years from the first repayment year.","revision":"original","contentSignature":"a44cb4d626921fd37d9cb002492ff945c6c7ffd841d4134c59f66e33bd806cb8"}]},{"id":264,"stem":"Section 80G: donations in CASH qualify for deduction only up to:","options":[{"key":"A","text":"Rs.20,000 per donation"},{"key":"B","text":"Rs.5,000 per donation"},{"key":"C","text":"Rs.2,000 per donation"},{"key":"D","text":"Rs.10,000 per donation"}],"answer":"C","explanation":"Cash donations above Rs.2,000 get no 80G deduction; larger donations must be by cheque/draft/electronic mode.","source":"Source label not detected","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Section 80G: donations in CASH qualify for deduction only up to:","options":["Rs.20,000","Rs.5,000","Rs.2,000 per donation","Rs.10,000"],"answer":2,"explanation":"Cash donations above Rs.2,000 get no 80G deduction; larger donations must be by cheque/draft/electronic mode.","revision":"original","contentSignature":"2c4916e89b56c4d7cafd8ae380d7b45d1311536b358c4214aac1e1856d30153b"}]},{"id":265,"stem":"Donations to the National Defence Fund / Prime Minister National Relief Fund qualify for deduction of:","options":[{"key":"A","text":"100% of the donation WITHOUT any qualifying limit"},{"key":"B","text":"50% of the donation, subject to the qualifying limit of 10% of adjusted gross total income"},{"key":"C","text":"50% of the donation, without any qualifying limit at all"},{"key":"D","text":"Nil - these funds get no deduction under 80G"}],"answer":"A","explanation":"The 100%-without-limit category covers PMNRF, National Defence Fund, PM CARES etc.; the 50%-with-limit category covers most trusts (10% of adjusted GTI cap).","source":"Source label not detected","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Donations to the National Defence Fund / Prime Minister National Relief Fund qualify for deduction of:","options":["100% of the donation WITHOUT any qualifying limit","50% subject to 10% of adjusted GTI","50% of the donation","Nil"],"answer":0,"explanation":"The 100%-without-limit category covers PMNRF, National Defence Fund, PM CARES etc.; the 50%-with-limit category covers most trusts (10% of adjusted GTI cap).","revision":"original","contentSignature":"b0fad3c229e2c828188657bc7df17638c002b12f4e7a82f5f6f9314c3104acb5"}]},{"id":266,"stem":"The qualifying limit for the 50%-category donations under 80G is:","options":[{"key":"A","text":"No limit at all - the entire 50%-category donation qualifies, whatever the adjusted gross total income, the exempt incomes, and the special-rate incomes of the year"},{"key":"B","text":"10% of ADJUSTED GROSS TOTAL INCOME (GTI minus VI-A deductions other than 80G, minus exempt/LTCG/special-rate incomes)"},{"key":"C","text":"A flat Rs.1 lakh per year, whatever the adjusted gross total income, the exempt incomes, and the special-rate incomes of the year"},{"key":"D","text":"20% of the salary income, whatever the adjusted gross total income, the exempt incomes, and the special-rate incomes of the year"}],"answer":"B","explanation":"The 50% category (with limit) is capped at 10% of adjusted GTI; 100%-category funds have no such cap.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The qualifying limit for the 50%-category donations under 80G is:","options":["No limit","10% of ADJUSTED GROSS TOTAL INCOME (GTI minus VI-A deductions other than 80G, minus exempt/LTCG/special-rate incomes)","Rs.1 lakh","20% of salary"],"answer":1,"explanation":"The 50% category (with limit) is capped at 10% of adjusted GTI; 100%-category funds have no such cap.","revision":"original","contentSignature":"1480a0f201be980b264c4fe229b219bccf2866c568a3f10236fcd821b795480e"}]},{"id":267,"stem":"Section 80GG (rent paid by those NOT receiving HRA) deduction is the LEAST of: (i) Rs.5,000 per month, (ii) 25% of adjusted total income, (iii):","options":[{"key":"A","text":"The actual rent paid during the year, in full"},{"key":"B","text":"A flat sum of Rs.60,000 a year"},{"key":"C","text":"Rent paid MINUS 10% of adjusted total income"},{"key":"D","text":"50% of the salary for the year"}],"answer":"C","explanation":"80GG aids self-employed/no-HRA renters: least of Rs.5,000 p.m., 25% of adjusted total income, or rent minus 10% of adjusted total income - provided neither the taxpayer, spouse nor minor child owns a residence at the work place.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Section 80GG (rent paid by those NOT receiving HRA) deduction is the LEAST of: (i) Rs.5,000 per month, (ii) 25% of adjusted total income, (iii):","options":["Actual rent paid","Rs.60,000","Rent paid MINUS 10% of adjusted total income","50% of salary"],"answer":2,"explanation":"80GG aids self-employed/no-HRA renters: least of Rs.5,000 p.m., 25% of adjusted total income, or rent minus 10% of adjusted total income - provided neither the taxpayer, spouse nor minor child owns a residence at the work place.","revision":"original","contentSignature":"71d21bdae097386339688b3402ff6674e5f0abd994b6b8a1cccfa49ba07e5fe6"}]},{"id":268,"stem":"Section 80GGA covers donations for:","options":[{"key":"A","text":"Medical treatment of specified diseases - deductible to every assessee including those with business income, and with no limit at all on cash donations of any size"},{"key":"B","text":"SCIENTIFIC RESEARCH or RURAL DEVELOPMENT - 100% deduction (but NOT for those having business/profession income; CASH donations limited to Rs.2,000)"},{"key":"C","text":"Interest on home loans - deductible to every assessee including those with business income, and with no limit at all on cash donations of any size"},{"key":"D","text":"Contributions to political parties - deductible to every assessee including those with business income, and with no limit at all on cash donations of any size"}],"answer":"B","explanation":"80GGA donations are fully deductible for non-business assessees; business assessees claim them under s.35 instead.","source":"Source label not detected","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Section 80GGA covers donations for:","options":["Medical treatment","SCIENTIFIC RESEARCH or RURAL DEVELOPMENT - 100% deduction (but NOT for those having business/profession income; CASH donations limited to Rs.2,000)","Home loans","Political parties"],"answer":1,"explanation":"80GGA donations are fully deductible for non-business assessees; business assessees claim them under s.35 instead.","revision":"original","contentSignature":"179d4af0520013dbccae1f67346d8c29d142f69b72c3e0cc06fe1c141b9baa16"}]},{"id":269,"stem":"Contributions to registered POLITICAL PARTIES are deductible under:","options":[{"key":"A","text":"Section 80C, within the Rs.1.5 lakh 80CCE ceiling, and cash contributions qualify in full"},{"key":"B","text":"Section 80GGB (companies) and 80GGC (any other person) - 100%, but NO deduction for CASH contributions"},{"key":"C","text":"Section 80D, within the health-insurance ceilings, and cash contributions qualify in full"},{"key":"D","text":"Section 80G, subject to the qualifying limit, and cash contributions qualify in full"}],"answer":"B","explanation":"Political donations are 100% deductible under 80GGB/80GGC, but only by non-cash modes.","source":"Source label not detected","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Contributions to registered POLITICAL PARTIES are deductible under:","options":["80C","Section 80GGB (companies) and 80GGC (any other person) - 100%, but NO deduction for CASH contributions","80D","80G"],"answer":1,"explanation":"Political donations are 100% deductible under 80GGB/80GGC, but only by non-cash modes.","revision":"original","contentSignature":"36098444eb1c2006850c5892397cd199c09914114788a38d4b5057d23c2a02cc"}]},{"id":270,"stem":"Section 80TTA allows deduction of up to Rs.10,000 for:","options":[{"key":"A","text":"All interest of every kind - savings, fixed deposit and loan interest alike - for individuals and HUF of every age, without any age restriction at all"},{"key":"B","text":"Fixed deposit interest with banks - for individuals and HUF of every age, without any age restriction at all"},{"key":"C","text":"SAVINGS ACCOUNT interest (banks/post offices) - NOT fixed deposit interest; individuals/HUF below 60 years"},{"key":"D","text":"Interest on loans taken - for individuals and HUF of every age, without any age restriction at all"}],"answer":"C","explanation":"80TTA covers savings-account interest up to Rs.10,000; FD/RD interest is excluded (senior citizens use the wider 80TTB).","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Section 80TTA allows deduction of up to Rs.10,000 for:","options":["All interest","FD interest","SAVINGS ACCOUNT interest (banks/post offices) - NOT fixed deposit interest; individuals/HUF below 60 years","Loan interest"],"answer":2,"explanation":"80TTA covers savings-account interest up to Rs.10,000; FD/RD interest is excluded (senior citizens use the wider 80TTB).","revision":"original","contentSignature":"a1e3bdffa9422595aaf91ece318c211d7064dd59233676f0cf507d2c87e85f3d"}]},{"id":271,"stem":"Section 80TTB gives SENIOR CITIZENS (60+) a deduction of up to Rs.50,000 for:","options":[{"key":"A","text":"Interest on ALL deposits with banks, co-operative banks and post offices (savings AND fixed deposits)"},{"key":"B","text":"Only savings account interest - fixed deposits never qualify for the 80TTB deduction at all, whatever the age of the depositor and the bank where the deposit is held"},{"key":"C","text":"Pension income of every kind - as if it were interest on deposits, whatever the age of the pensioner and the source of the pension"},{"key":"D","text":"Dividends on shares of every kind - as if they were interest on deposits, whatever the age of the shareholder and the company paying the dividend"}],"answer":"A","explanation":"80TTB is the wider senior-citizen interest deduction; seniors cannot also claim 80TTA.","source":"Source label not detected","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Section 80TTB gives SENIOR CITIZENS (60+) a deduction of up to Rs.50,000 for:","options":["Interest on ALL deposits with banks, co-operative banks and post offices (savings AND fixed deposits)","Only savings interest","Pension","Share dividends"],"answer":0,"explanation":"80TTB is the wider senior-citizen interest deduction; seniors cannot also claim 80TTA.","revision":"original","contentSignature":"0e9e758f4b4a0fd184c09ee11c823f222723e0f14677cbe6c751803e3d077dfd"}]},{"id":272,"stem":"Section 80U deduction for a person WITH DISABILITY (resident individual) is:","options":[{"key":"A","text":"Rs.50,000 flat - Rs.75,000 for severe disability (80%+)"},{"key":"B","text":"Rs.75,000 flat - Rs.1,25,000 for SEVERE disability (80%+)"},{"key":"C","text":"Rs.1,00,000 flat - Rs.1,50,000 for severe disability (80%+)"},{"key":"D","text":"Rs.40,000 flat - Rs.75,000 for severe disability (80%+)"}],"answer":"B","explanation":"80U is for the taxpayer own disability (flat amounts); 80DD is for a dependent. Both are flat deductions.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Section 80U deduction for a person WITH DISABILITY (resident individual) is:","options":["Rs.50,000","Rs.75,000 flat - Rs.1,25,000 for SEVERE disability (80%+)","Rs.1,00,000","Rs.40,000"],"answer":1,"explanation":"80U is for the taxpayer own disability (flat amounts); 80DD is for a dependent. Both are flat deductions.","revision":"original","contentSignature":"6153015e07b5c081e54e8fc16f10f9a72729e68760a08dc1c071cecdddcc394a"}]},{"id":273,"stem":"Section 80C includes tuition fees paid for:","options":[{"key":"A","text":"FULL-TIME education of up to TWO CHILDREN in Indian institutions (not donations, development fees or coaching)"},{"key":"B","text":"Full-time education of the spouse in Indian institutions, and the ceiling covers donations, development fees and private coaching payments made to any institution"},{"key":"C","text":"Any course anywhere in the world, part-time or full-time alike, and the ceiling covers donations, development fees and private coaching payments of every kind"},{"key":"D","text":"Full-time education abroad of up to two children, and the ceiling covers donations, development fees and private coaching payments made to foreign institutions"}],"answer":"A","explanation":"Only full-time tuition fees of the assessee own children (max two) at Indian educational institutions qualify.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Section 80C includes tuition fees paid for:","options":["FULL-TIME education of up to TWO CHILDREN in Indian institutions (not donations, development fees or coaching)","Spouse education","Any course anywhere","Abroad studies"],"answer":0,"explanation":"Only full-time tuition fees of the assessee own children (max two) at Indian educational institutions qualify.","revision":"original","contentSignature":"e237bf181721a564e4decdfa0f0f9a7a0f5f7cf0197d45bdab3b1ed5b1ed1b63"}]},{"id":274,"stem":"Principal repayment of a HOME LOAN qualifies under 80C, and interest under:","options":[{"key":"A","text":"Section 80D (the medical-insurance section - Rs.25,000/Rs.50,000 limits, old regime)"},{"key":"B","text":"Section 24(b) (house-property head - Rs.2 lakh self-occupied, old regime)"},{"key":"C","text":"Section 80G (the donations section - subject to the qualifying limit)"},{"key":"D","text":"Section 80C itself, together with the principal, within the same Rs.1.5 lakh ceiling"}],"answer":"B","explanation":"Principal goes in the 80C basket; interest is claimed under the house-property head s.24(b).","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Principal repayment of a HOME LOAN qualifies under 80C, and interest under:","options":["Section 80D","Section 24(b) (house-property head - Rs.2 lakh self-occupied, old regime)","Section 80G","Section 80C itself"],"answer":1,"explanation":"Principal goes in the 80C basket; interest is claimed under the house-property head s.24(b).","revision":"original","contentSignature":"2dd3bc9ba887f8b556136b6ec322355fe9fda2f21ae34f3bd756f583db968225"}]},{"id":275,"stem":"Deduction under Section 80CCD(1) (self NPS contribution) for an employee is capped at:","options":[{"key":"A","text":"A flat Rs.2 lakh for employees and self-employed alike, outside the 80CCE limit"},{"key":"B","text":"A flat Rs.75,000 for employees and self-employed alike, outside the 80CCE limit"},{"key":"C","text":"10% of salary within the Rs.1.5 lakh 80CCE limit (20% of GTI for self-employed)"},{"key":"D","text":"No limit at all, for employees and self-employed alike"}],"answer":"C","explanation":"Self NPS contributions sit inside the 80CCE basket, capped at 10% of salary (employees) or 20% of GTI (others), plus the 80CCD(1B) extra Rs.50,000.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Deduction under Section 80CCD(1) (self NPS contribution) for an employee is capped at:","options":["Rs.2 lakh","Rs.75,000","10% of salary within the Rs.1.5 lakh 80CCE limit (20% of GTI for self-employed)","No limit"],"answer":2,"explanation":"Self NPS contributions sit inside the 80CCE basket, capped at 10% of salary (employees) or 20% of GTI (others), plus the 80CCD(1B) extra Rs.50,000.","revision":"original","contentSignature":"6b440e24824a39d856657d9d02735cdb44a8c4967fdff912c94c6f2a632aeddd"}]},{"id":276,"stem":"Which VI-A deduction is AVAILABLE under the NEW tax regime (115BAC)?","options":[{"key":"A","text":"80CCD(2) (employer NPS) and 80JJAA (additional employment)"},{"key":"B","text":"80C (life premium, PPF, tuition fees and the like)"},{"key":"C","text":"80G (donations to approved funds and institutions)"},{"key":"D","text":"80D (medical insurance premiums and health check-ups)"}],"answer":"A","explanation":"The new regime keeps only 80CCD(2), 80JJAA and (for specified new manufacturing) 80LA-type deductions; all personal deductions (80C, 80D, 80G, 80TTA etc.) are barred.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which VI-A deduction is AVAILABLE under the NEW tax regime (115BAC)?","options":["80CCD(2) (employer NPS) and 80JJAA (additional employment)","80C","80G","80D"],"answer":0,"explanation":"The new regime keeps only 80CCD(2), 80JJAA and (for specified new manufacturing) 80LA-type deductions; all personal deductions (80C, 80D, 80G, 80TTA etc.) are barred.","revision":"original","contentSignature":"f60c532ba4ec0a45391eb6ab46caf4a97899e41f3643abf7cfa31a37dc3c1904"}]},{"id":277,"stem":"Section 80JJAA (additional employee cost) allows a deduction of:","options":[{"key":"A","text":"50% of the total salaries paid for one year only, available to all businesses including those formed by splitting up or reconstruction of an existing business"},{"key":"B","text":"30% of additional employee cost for 3 consecutive years, for all businesses (except those formed by splitting/reconstruction)"},{"key":"C","text":"100% of additional employee cost for one year only, available to all businesses including those formed by splitting up or reconstruction of an existing business"},{"key":"D","text":"A flat Rs.1 lakh per year for 3 consecutive years, available to all businesses including those formed by splitting up or reconstruction of an existing business"}],"answer":"B","explanation":"80JJAA incentivises employment: 30% of the additional employee cost for three years; new-regime taxpayers can also claim it.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Section 80JJAA (additional employee cost) allows a deduction of:","options":["50% of salaries","30% of additional employee cost for 3 consecutive years, for all businesses (except those formed by splitting/reconstruction)","100% for one year","Rs.1 lakh flat"],"answer":1,"explanation":"80JJAA incentivises employment: 30% of the additional employee cost for three years; new-regime taxpayers can also claim it.","revision":"original","contentSignature":"b0a25dc68d76e72f5e6c28cc9358acb9774d957e44c7abae4107123cd1097e8b"}]},{"id":278,"stem":"Section 80QQB (royalty on books) allows authors a deduction up to:","options":[{"key":"A","text":"Rs.50,000"},{"key":"B","text":"Rs.1 lakh"},{"key":"C","text":"Rs.5 lakh"},{"key":"D","text":"Rs.3 lakh"}],"answer":"D","explanation":"Resident authors of specified literary/artistic/scientific books deduct royalty income up to Rs.3 lakh (80RRB similarly for patents).","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":279,"stem":"Deduction under Section 80D for parents can be claimed even if the parents are:","options":[{"key":"A","text":"Dependent on the assessee - the deduction fails if they are not"},{"key":"B","text":"Senior citizens only - no deduction for younger parents at all"},{"key":"C","text":"NOT DEPENDENT on the assessee - dependency is not a condition"},{"key":"D","text":"Living in India - the deduction fails for parents living abroad"}],"answer":"C","explanation":"80D has no dependency condition for parents; only the premium payment by the assessee matters.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Deduction under Section 80D for parents can be claimed even if the parents are:","options":["Dependent on the assessee","Senior citizens only","NOT DEPENDENT on the assessee - dependency is not a condition","Living abroad"],"answer":2,"explanation":"80D has no dependency condition for parents; only the premium payment by the assessee matters.","revision":"original","contentSignature":"23b9453ff57f281e4b4947339434df2adbbdeec68ac9ed2a2f6ec14b3ca4187a"}]},{"id":280,"stem":"A salaried employee in the OLD regime claims: PPF Rs.1,00,000, LIC premium Rs.30,000, ELSS Rs.40,000, tuition fees Rs.25,000. His 80C deduction is:","options":[{"key":"A","text":"Rs.1,30,000"},{"key":"B","text":"Rs.1,70,000"},{"key":"C","text":"Rs.1,95,000"},{"key":"D","text":"Rs.1,50,000"}],"answer":"D","explanation":"Total investments 1,95,000, but the 80C cap is Rs.1,50,000.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":281,"stem":"An individual (below 60) pays: medical insurance self Rs.18,000, parents (senior citizens) Rs.32,000, preventive check-up (cash) Rs.6,000 (for self). His 80D deduction is:","options":[{"key":"A","text":"Rs.55,000"},{"key":"B","text":"Rs.50,000"},{"key":"C","text":"Rs.56,000"},{"key":"D","text":"Rs.68,000"}],"answer":"A","explanation":"Self: premium 18,000 + check-up capped at 5,000 = 23,000 (within 25,000). Parents: 32,000 (within 50,000). Total = 55,000.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":282,"stem":"Section 80GGB allows a COMPANY to deduct political contributions:","options":[{"key":"A","text":"Up to 10% of its net profits, and cash contributions qualify in full"},{"key":"B","text":"50% of the contribution, and cash contributions qualify in full"},{"key":"C","text":"100% of the contribution - but ONLY by non-cash mode"},{"key":"D","text":"Nil - companies cannot donate to political parties at all"}],"answer":"C","explanation":"Companies deduct 100% of non-cash political contributions under 80GGB; other persons use 80GGC.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Section 80GGB allows a COMPANY to deduct political contributions:","options":["Up to 10% of profits","50%","100% of the contribution - but ONLY by non-cash mode","Nil - companies cannot donate"],"answer":2,"explanation":"Companies deduct 100% of non-cash political contributions under 80GGB; other persons use 80GGC.","revision":"original","contentSignature":"e426a56d87243ea6e9c5f4109e8a6e958d7ad425ed4754c676185eff34e630ce"}]},{"id":283,"stem":"Section 80GG CANNOT be claimed by a taxpayer who:","options":[{"key":"A","text":"Is self-employed, whatever the rent paid, the HRA position, and the ownership of any house at the place of work or residence"},{"key":"B","text":"Receives HRA at any time during the year, or owns a residential house at the place of work/residence"},{"key":"C","text":"Pays rent for his residence, whatever the HRA position and the ownership of any house at the place of work or residence"},{"key":"D","text":"Lives in a metro city, whatever the HRA position and the ownership of any house at the place of work or residence"}],"answer":"B","explanation":"80GG is for those who receive NO HRA and own no house at the place of their employment/residence.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Section 80GG CANNOT be claimed by a taxpayer who:","options":["Is self-employed","Receives HRA at any time during the year, or owns a residential house at the place of work/residence","Pays rent for residence","Lives in a metro"],"answer":1,"explanation":"80GG is for those who receive NO HRA and own no house at the place of their employment/residence.","revision":"original","contentSignature":"c367a1c5567fa4f5afba54b12ef060c0b4a39dca6ac4d4249d299768ee4666ce"}]},{"id":284,"stem":"Sukanya Samriddhi Account deposits (for a girl child) qualify under:","options":[{"key":"A","text":"80TTA - deposits deductible, interest and maturity taxable"},{"key":"B","text":"80D - deposits deductible, interest and maturity taxable"},{"key":"C","text":"80C - deposits deductible, interest and maturity EXEMPT (EEE status)"},{"key":"D","text":"80G - deposits deductible, interest and maturity taxable"}],"answer":"C","explanation":"SSA is an EEE instrument: deposit under 80C, interest and maturity exempt under s.10(11A).","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Sukanya Samriddhi Account deposits (for a girl child) qualify under:","options":["80TTA","80D","80C - deposits deductible, interest and maturity EXEMPT (EEE status)","80G"],"answer":2,"explanation":"SSA is an EEE instrument: deposit under 80C, interest and maturity exempt under s.10(11A).","revision":"original","contentSignature":"59faca71fa423a07a44f5b69f0221c2006208df0d166cfc7fb769b1cbf44f572"}]},{"id":285,"stem":"Deduction for interest on loan taken for RESIDENTIAL house property under s.80EE / 80EEA is:","options":[{"key":"A","text":"Always available - Rs.50,000 under 80EE for every loan, whatever the date of sanction, with no sunset window of any kind applying to these sections now"},{"key":"B","text":"Sections 80EE/80EEA have SUNSET (loans sanctioned in specified past windows) - no new deduction under them for loans sanctioned now"},{"key":"C","text":"Available currently for all loans, whatever the date of sanction, with no sunset window of any kind applying to these sections now"},{"key":"D","text":"Always available - Rs.2 lakh under 80EEA for every loan, whatever the date of sanction, with no sunset window of any kind applying to these sections now"}],"answer":"B","explanation":"80EE applied to loans sanctioned in FY 2016-17 and 80EEA to loans sanctioned during FY 2019-20 to FY 2021-22; neither is available for fresh loans.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Deduction for interest on loan taken for RESIDENTIAL house property under s.80EE / 80EEA is:","options":["Rs.50,000 always","Sections 80EE/80EEA have SUNSET (loans sanctioned in specified past windows) - no new deduction under them for loans sanctioned now","Available currently for all","Rs.2 lakh always"],"answer":1,"explanation":"80EE applied to loans sanctioned in FY 2016-17 and 80EEA to loans sanctioned during FY 2019-20 to FY 2021-22; neither is available for fresh loans.","revision":"original","contentSignature":"aefe545953cc7efdfcf97378b9764ef42c47f5678e3a8a7780add7834b0966dd"}]},{"id":286,"stem":"Under Section 87A, a RESIDENT INDIVIDUAL in the OLD regime gets a rebate of up to Rs.12,500 if total income does not exceed:","options":[{"key":"A","text":"Rs.12,00,000"},{"key":"B","text":"Rs.7,00,000"},{"key":"C","text":"Rs.3,50,000"},{"key":"D","text":"Rs.5,00,000"}],"answer":"D","explanation":"Old regime 87A: rebate up to Rs.12,500 where total income is up to Rs.5 lakh (tax becomes nil); the 2018-era Rs.2,500/Rs.3.5 lakh figures are outdated.","source":"Source label not detected","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":287,"stem":"Under the NEW regime (FY 2025-26), the Section 87A rebate makes tax effectively NIL for total income up to:","options":[{"key":"A","text":"Rs.5 LAKH (maximum rebate Rs.12,500), with marginal relief"},{"key":"B","text":"Rs.12 LAKH (maximum rebate Rs.60,000), with marginal relief"},{"key":"C","text":"Rs.10 LAKH (maximum rebate Rs.30,000), with marginal relief"},{"key":"D","text":"Rs.7 LAKH (maximum rebate Rs.25,000), with marginal relief"}],"answer":"B","explanation":"Finance Act 2025 raised the new-regime rebate to Rs.60,000 for total income up to Rs.12 lakh; marginal relief protects incomes slightly above Rs.12 lakh.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Under the NEW regime (FY 2025-26), the Section 87A rebate makes tax effectively NIL for total income up to:","options":["Rs.5 lakh","Rs.12 LAKH (maximum rebate Rs.60,000), with marginal relief","Rs.10 lakh","Rs.7 lakh"],"answer":1,"explanation":"Finance Act 2025 raised the new-regime rebate to Rs.60,000 for total income up to Rs.12 lakh; marginal relief protects incomes slightly above Rs.12 lakh.","revision":"original","contentSignature":"72ad06cc12d60285637893c9509dc5cc25ed3a05f94670ce781e5d5ad000233f"}]},{"id":288,"stem":"The Rs.60,000 new-regime rebate under 87A is available to:","options":[{"key":"A","text":"Companies only - not individuals, HUF or firms of any kind"},{"key":"B","text":"All assessees alike - individuals, HUF, firms and companies, resident or not"},{"key":"C","text":"All senior citizens only - no one below 60 years of age qualifies"},{"key":"D","text":"RESIDENT INDIVIDUALS only - not HUF, firms, companies or non-residents"}],"answer":"D","explanation":"Section 87A rebates are personal to resident individuals, in both regimes.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The Rs.60,000 new-regime rebate under 87A is available to:","options":["Companies","All assessees","All senior citizens only","RESIDENT INDIVIDUALS only - not HUF, firms, companies or non-residents"],"answer":3,"explanation":"Section 87A rebates are personal to resident individuals, in both regimes.","revision":"original","contentSignature":"c036b4c037e1a04bf70efc5dfe8f787ce501077be47961bb3c8957e570c1b11f"}]},{"id":289,"stem":"Marginal relief under the new-regime 87A rebate means that where total income marginally exceeds Rs.12 lakh, the tax payable cannot exceed:","options":[{"key":"A","text":"A flat Rs.60,000, whatever the excess of income over Rs.12 lakh"},{"key":"B","text":"Nil - the tax payable is fully wiped out, whatever the excess"},{"key":"C","text":"A flat Rs.10,000, whatever the excess of income over Rs.12 lakh"},{"key":"D","text":"The amount by which the total income EXCEEDS Rs.12 lakh"}],"answer":"D","explanation":"Marginal relief caps the tax at the excess of income over Rs.12 lakh - so earning Rs.1,000 above the threshold never costs more than Rs.1,000 in tax.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Marginal relief under the new-regime 87A rebate means that where total income marginally exceeds Rs.12 lakh, the tax payable cannot exceed:","options":["Rs.60,000","Nil","Rs.10,000","The amount by which the total income EXCEEDS Rs.12 lakh"],"answer":3,"explanation":"Marginal relief caps the tax at the excess of income over Rs.12 lakh - so earning Rs.1,000 above the threshold never costs more than Rs.1,000 in tax.","revision":"original","contentSignature":"c5f55d7b24fb77892e272119a121fc56dd5a9ac7450f3a8620aa621c01711249"}]},{"id":290,"stem":"Salaried income up to Rs.12,75,000 (new regime, FY 2025-26) can effectively pay NIL tax because of:","options":[{"key":"A","text":"The HRA exemption, which survives in the new regime for salaried employees at every level of income"},{"key":"B","text":"The agricultural income exemption, which wipes out tax on salary up to this level in the new regime"},{"key":"C","text":"The 80C investments deduction, which survives in the new regime for salaried employees at every level of income"},{"key":"D","text":"STANDARD DEDUCTION of Rs.75,000 plus the 87A rebate up to Rs.12 lakh of total income"}],"answer":"D","explanation":"Salary minus Rs.75,000 standard deduction brings total income to Rs.12 lakh, where the 87A rebate wipes out the tax.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Salaried income up to Rs.12,75,000 (new regime, FY 2025-26) can effectively pay NIL tax because of:","options":["HRA","Agricultural income","80C investments","STANDARD DEDUCTION of Rs.75,000 plus the 87A rebate up to Rs.12 lakh of total income"],"answer":3,"explanation":"Salary minus Rs.75,000 standard deduction brings total income to Rs.12 lakh, where the 87A rebate wipes out the tax.","revision":"original","contentSignature":"52b6813b32f5fc04ffe29f242b38c37cbc8e674efd9b50a93c4017dafb1a4991"}]},{"id":291,"stem":"For FY 2025-26 (AY 2026-27) under the NEW regime (default, Section 115BAC), income above Rs.24 lakh is taxed at:","options":[{"key":"A","text":"25%"},{"key":"B","text":"35%"},{"key":"C","text":"20%"},{"key":"D","text":"30%"}],"answer":"D","explanation":"New-regime slabs: 0-4L nil, 4-8L 5%, 8-12L 10%, 12-16L 15%, 16-20L 20%, 20-24L 25%, above 24L 30%.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified"},{"id":292,"stem":"Under the NEW regime for FY 2025-26, the slab from Rs.4,00,001 to Rs.8,00,000 is taxed at:","options":[{"key":"A","text":"5%"},{"key":"B","text":"10%"},{"key":"C","text":"15%"},{"key":"D","text":"Nil"}],"answer":"A","explanation":"The new-regime ladder from Finance Act 2025: 5% for 4-8L, 10% for 8-12L, 15% for 12-16L.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified"},{"id":293,"stem":"The new tax regime under Section 115BAC is the:","options":[{"key":"A","text":"An optional regime only - the old regime remains the default for every individual and HUF"},{"key":"B","text":"DEFAULT regime for individuals/HUF etc. - the assessee must OPT OUT to use the old regime (by filing Form 10-IEA for business income)"},{"key":"C","text":"The regime available only for senior citizens above 60 years of age"},{"key":"D","text":"A compulsory regime, with no way out for any assessee"}],"answer":"B","explanation":"From FY 2023-24, the new regime is the default; taxpayers with business income must file Form 10-IEA to opt out and get only one switch back.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The new tax regime under Section 115BAC is the:","options":["Optional regime only","DEFAULT regime for individuals/HUF etc. - the assessee must OPT OUT to use the old regime (by filing Form 10-IEA for business income)","Regime only for senior citizens","Compulsory regime with no exit"],"answer":1,"explanation":"From FY 2023-24, the new regime is the default; taxpayers with business income must file Form 10-IEA to opt out and get only one switch back.","revision":"original","contentSignature":"68d8f775098229968cef49cbe024d23d072f00f6e936551d5f848c9297def2d9"}]},{"id":294,"stem":"Under the OLD regime for FY 2025-26, income from Rs.2,50,001 to Rs.5,00,000 (individual below 60) is taxed at:","options":[{"key":"A","text":"5%"},{"key":"B","text":"20%"},{"key":"C","text":"10%"},{"key":"D","text":"Nil"}],"answer":"A","explanation":"Old regime: 0-2.5L nil, 2.5-5L 5%, 5-10L 20%, above 10L 30%; basic exemption is Rs.2.5L (3L for seniors, 5L for super-seniors).","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified"},{"id":295,"stem":"Under the old regime, a SENIOR CITIZEN (60-79 years) enjoys a basic exemption of:","options":[{"key":"A","text":"Rs.2,00,000"},{"key":"B","text":"Rs.3,00,000"},{"key":"C","text":"Rs.2,50,000"},{"key":"D","text":"Rs.5,00,000"}],"answer":"B","explanation":"Old-regime basic exemption: Rs.2.5L (general), Rs.3L (senior citizens 60-79), Rs.5L (super senior 80+). The new regime has a uniform Rs.4L exemption.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified"},{"id":296,"stem":"Health and Education Cess on income tax (including surcharge) is levied at:","options":[{"key":"A","text":"4%"},{"key":"B","text":"3%"},{"key":"C","text":"1%"},{"key":"D","text":"2%"}],"answer":"A","explanation":"A flat 4% Health and Education Cess applies on tax plus surcharge across all regimes and assessees.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified"},{"id":297,"stem":"Surcharge on income tax for an individual with total income exceeding Rs.50 lakh but up to Rs.1 crore is:","options":[{"key":"A","text":"15%"},{"key":"B","text":"Nil"},{"key":"C","text":"25%"},{"key":"D","text":"10%"}],"answer":"D","explanation":"Surcharge ladder: >50L-1Cr 10%, >1-2Cr 15%, >2-5Cr 25%, >5Cr 37% (old regime); the new regime caps surcharge at 25%.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified"},{"id":298,"stem":"The MAXIMUM surcharge rate for individuals under the NEW tax regime is:","options":[{"key":"A","text":"37%"},{"key":"B","text":"15%"},{"key":"C","text":"10%"},{"key":"D","text":"25%"}],"answer":"D","explanation":"The new regime caps surcharge at 25% even above Rs.5 crore; under the old regime it reaches 37% (but capped at 15% for capital gains and dividends).","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified"},{"id":299,"stem":"Marginal relief in respect of SURCHARGE ensures that:","options":[{"key":"A","text":"The deductions under Chapter VI-A double for income slightly above a threshold, so that the effective tax rate falls sharply at that point"},{"key":"B","text":"The TAX INCLUDING SURCHARGE on income slightly above a threshold does not exceed the tax on the threshold plus the EXCESS income"},{"key":"C","text":"No cess applies on income slightly above a threshold, so that the effective tax rate falls sharply at that point"},{"key":"D","text":"The tax is nil for income slightly above a threshold, so that the effective tax rate falls sharply at that point"}],"answer":"B","explanation":"Marginal relief prevents a small income increase from causing a disproportionate surcharge jump at Rs.50L, Rs.1Cr, Rs.2Cr and Rs.5Cr.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Marginal relief in respect of SURCHARGE ensures that:","options":["Deductions double","The TAX INCLUDING SURCHARGE on income slightly above a threshold does not exceed the tax on the threshold plus the EXCESS income","No cess applies","Tax is nil"],"answer":1,"explanation":"Marginal relief prevents a small income increase from causing a disproportionate surcharge jump at Rs.50L, Rs.1Cr, Rs.2Cr and Rs.5Cr.","revision":"original","contentSignature":"26d9adb340af646c53fd705104784cea6052196db2c3c72a7f6a23afe0fe2700"}]},{"id":300,"stem":"Alternative Minimum Tax (Section 115JC) applies to:","options":[{"key":"A","text":"All salaried employees without exception, whether or not they claim any incentive"},{"key":"B","text":"NRIs only, to the exclusion of every resident assessee"},{"key":"C","text":"NON-COMPANY assessees claiming certain incentives (deductions under Part C of Chapter VI-A other than 80P, s.10AA, and 35AD-linked adjustments), at 18.5% of adjusted total income"},{"key":"D","text":"Companies only, to the exclusion of every non-company assessee"}],"answer":"C","explanation":"AMT at 18.5% applies to non-companies claiming specified tax incentives; new-regime taxpayers (no incentives) are out of AMT. Co-operative societies: 15%.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Alternative Minimum Tax (Section 115JC) applies to:","options":["All salaried employees","NRIs only","NON-COMPANY assessees claiming certain incentives (deductions under Part C of Chapter VI-A other than 80P, s.10AA, and 35AD-linked adjustments), at 18.5% of adjusted total income","Companies"],"answer":2,"explanation":"AMT at 18.5% applies to non-companies claiming specified tax incentives; new-regime taxpayers (no incentives) are out of AMT. Co-operative societies: 15%.","revision":"original","contentSignature":"fbfe7be3beb3ec679007b7f4eedd0b16d2fefdbff57a97eff6d17d0aba933f6d"}]},{"id":301,"stem":"Minimum Alternate Tax (MAT) under Section 115JB is levied on:","options":[{"key":"A","text":"Partnership firms only - at 18.5% of adjusted total income"},{"key":"B","text":"Hindu Undivided Families only - at 18.5% of adjusted total income"},{"key":"C","text":"Individuals only - at 15% of their book profit"},{"key":"D","text":"COMPANIES - at 15% of BOOK PROFIT where tax on normal total income is lower"}],"answer":"D","explanation":"MAT ensures companies with low taxable income (due to incentives) pay at least 15% of book profit; MAT credit (115JAA) carries forward 15 years.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Minimum Alternate Tax (MAT) under Section 115JB is levied on:","options":["Partnership firms","HUFs","Individuals at 15%","COMPANIES - at 15% of BOOK PROFIT where tax on normal total income is lower"],"answer":3,"explanation":"MAT ensures companies with low taxable income (due to incentives) pay at least 15% of book profit; MAT credit (115JAA) carries forward 15 years.","revision":"original","contentSignature":"f7de3e7c08607a124e8af3ddf73404147ec020977ac8cbaf343a54022c17a3c8"}]},{"id":302,"stem":"MAT credit under Section 115JAA can be carried forward for:","options":[{"key":"A","text":"10 years"},{"key":"B","text":"8 years"},{"key":"C","text":"15 assessment years"},{"key":"D","text":"Indefinitely"}],"answer":"C","explanation":"MAT credit carries forward 15 assessment years, usable when regular tax exceeds MAT.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified"},{"id":303,"stem":"MAT under Section 115JB does NOT apply to:","options":[{"key":"A","text":"Companies having a book loss in the year, whatever the regime they have opted for"},{"key":"B","text":"All companies without exception, under either regime"},{"key":"C","text":"Foreign companies only, whatever the regime they have opted for"},{"key":"D","text":"Companies opting for Sections 115BAA (22%) or 115BAB (15%) concessional regimes"}],"answer":"D","explanation":"Companies choosing the 115BAA/115BAB concessional rates are exempt from MAT; 115BAB companies also cannot carry forward MAT credit.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"MAT under Section 115JB does NOT apply to:","options":["Loss companies","All companies","Foreign companies","Companies opting for Sections 115BAA (22%) or 115BAB (15%) concessional regimes"],"answer":3,"explanation":"Companies choosing the 115BAA/115BAB concessional rates are exempt from MAT; 115BAB companies also cannot carry forward MAT credit.","revision":"original","contentSignature":"9cbe6ebb2573c1bd2a46bd8fbecc0a1644e62b3a3068fd7b23017aadda87a4f8"}]},{"id":304,"stem":"The concessional rate under Section 115BAA for domestic companies is:","options":[{"key":"A","text":"15% + 10% surcharge + 4% cess (effective about 17.16%), subject to forgoing the specified incentives under the section"},{"key":"B","text":"30% + 10% surcharge + 4% cess (effective about 34.32%), subject to forgoing the specified incentives under the section"},{"key":"C","text":"22% + 10% surcharge + 4% cess (effective about 25.17%), subject to forgoing specified incentives"},{"key":"D","text":"25% + 10% surcharge + 4% cess (effective about 28.60%), subject to forgoing the specified incentives under the section"}],"answer":"C","explanation":"Section 115BAA: 22% flat (25.17% effective) for domestic companies forgoing incentives; 115BAB offers 15% for new manufacturing companies.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The concessional rate under Section 115BAA for domestic companies is:","options":["15%","30%","22% + 10% surcharge + 4% cess (effective about 25.17%), subject to forgoing specified incentives","25%"],"answer":2,"explanation":"Section 115BAA: 22% flat (25.17% effective) for domestic companies forgoing incentives; 115BAB offers 15% for new manufacturing companies.","revision":"original","contentSignature":"fb1e6c9559f4b1677b0b6d4fab302a52ec8c07f9a5ba092ed6bea048fc14dfc9"}]},{"id":305,"stem":"A FIRM (partnership) is taxed at a flat rate of:","options":[{"key":"A","text":"The normal slab rates, like an individual (plus cess and surcharge)"},{"key":"B","text":"25% + 4% cess (plus 12% surcharge above Rs.1 crore)"},{"key":"C","text":"20% + 4% cess (plus 12% surcharge above Rs.1 crore)"},{"key":"D","text":"30% + 4% cess (plus 12% surcharge above Rs.1 crore)"}],"answer":"D","explanation":"Firms and LLPs pay a flat 30%; LLPs have no surcharge; firms get 12% surcharge above Rs.1 crore.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A FIRM (partnership) is taxed at a flat rate of:","options":["Slab rates","25%","20%","30% + 4% cess (plus 12% surcharge above Rs.1 crore)"],"answer":3,"explanation":"Firms and LLPs pay a flat 30%; LLPs have no surcharge; firms get 12% surcharge above Rs.1 crore.","revision":"original","contentSignature":"73e08ca1c3f3b093e3b923e4af6c7d4b483c45031c7ae4cb344707bea44f9153"}]},{"id":306,"stem":"A LOCAL AUTHORITY is taxed at:","options":[{"key":"A","text":"Flat 30%"},{"key":"B","text":"25%"},{"key":"C","text":"30%"},{"key":"D","text":"Slab rates"}],"answer":"C","explanation":"Local authorities pay a flat 30% plus 4% cess (12% surcharge above Rs.1 crore).","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified"},{"id":307,"stem":"Co-operative societies are taxed at:","options":[{"key":"A","text":"SLAB rates: 10% up to Rs.10,000, 20% up to Rs.20,000, 30% above (optional 115BAD at 22%)"},{"key":"B","text":"They are exempt from tax, without conditions"},{"key":"C","text":"A flat 30% on the whole income from the first rupee (optional 115BAD at 22%)"},{"key":"D","text":"A flat 20% on the whole income from the first rupee (optional 115BAD at 22%)"}],"answer":"A","explanation":"Co-operative societies have their own slabs; Section 115BAD offers 22% concession and 115BAE 15% for new manufacturing co-operatives.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Co-operative societies are taxed at:","options":["SLAB rates: 10% up to Rs.10,000, 20% up to Rs.20,000, 30% above (optional 115BAD at 22%)","Exempt","Flat 30%","20% flat"],"answer":0,"explanation":"Co-operative societies have their own slabs; Section 115BAD offers 22% concession and 115BAE 15% for new manufacturing co-operatives.","revision":"original","contentSignature":"e0645105be73b612c3e3c11979bd65ac4fe60751a913e8f48f8f7c83e43ef747"}]},{"id":308,"stem":"An individual with total income of Rs.8,00,000 (NEW regime, FY 2025-26) pays tax (before rebate/cess) of:","options":[{"key":"A","text":"Rs.20,000"},{"key":"B","text":"Rs.40,000"},{"key":"C","text":"Rs.25,000"},{"key":"D","text":"Rs.30,000"}],"answer":"A","explanation":"Nil to 4L; 5% of 4L (4-8L) = 20,000. Under 8L total income, new-regime tax is simply 5% of the excess over Rs.4 lakh.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified"},{"id":309,"stem":"A resident individual (age 45) with total income of Rs.10,00,000 in the OLD regime (before cess) pays tax of:","options":[{"key":"A","text":"Rs.1,12,500"},{"key":"B","text":"Rs.1,25,000"},{"key":"C","text":"Rs.85,000"},{"key":"D","text":"Rs.1,17,500"}],"answer":"A","explanation":"Old regime: nil to 2.5L; 5% of 2.5L = 12,500 (2.5-5L); 20% of 5L = 1,00,000 (5-10L). Total = 1,12,500.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified"},{"id":310,"stem":"A resident individual (age 45) with total income of Rs.10,00,000 in the NEW regime (before cess) pays tax of:","options":[{"key":"A","text":"Rs.40,000"},{"key":"B","text":"Rs.60,000"},{"key":"C","text":"Rs.1,12,500"},{"key":"D","text":"Rs.50,000"}],"answer":"A","explanation":"New regime: 5% of Rs.4L (4-8L) = 20,000; 10% of Rs.2L (8-10L within the 8-12L slab) = 20,000. Total Rs.40,000.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified"},{"id":311,"stem":"Health and Education Cess of 4% applies on:","options":[{"key":"A","text":"The total income of the year, directly"},{"key":"B","text":"Income tax AS INCREASED BY SURCHARGE"},{"key":"C","text":"The Chapter VI-A deductions of the year, directly"},{"key":"D","text":"The gross total income of the year, directly"}],"answer":"B","explanation":"Cess is computed on the tax-plus-surcharge amount, not on the income.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Health and Education Cess of 4% applies on:","options":["Total income","Income tax AS INCREASED BY SURCHARGE","Deductions","Gross total income"],"answer":1,"explanation":"Cess is computed on the tax-plus-surcharge amount, not on the income.","revision":"original","contentSignature":"15127f9a0cd3e6601f4b4c66a20e854e22419bd6c435f75257b0eeb849577059"}]},{"id":312,"stem":"In the NEW regime, an individual with total income of exactly Rs.12,00,000 (FY 2025-26) pays income tax of:","options":[{"key":"A","text":"Rs.1,00,000 - the 87A rebate does not apply at this income level at all"},{"key":"B","text":"NIL - the 87A rebate (up to Rs.60,000) wipes out the entire tax"},{"key":"C","text":"Rs.36,000 - the 87A rebate only halves the tax at this level"},{"key":"D","text":"Rs.60,000 - the 87A rebate does not apply at this income level at all"}],"answer":"B","explanation":"Tax at Rs.12L = 20,000 (4-8L at 5%) + 40,000 (8-12L at 10%) = 60,000, fully rebated under 87A.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"In the NEW regime, an individual with total income of exactly Rs.12,00,000 (FY 2025-26) pays income tax of:","options":["Rs.1,00,000","NIL - the 87A rebate (up to Rs.60,000) wipes out the entire tax","Rs.36,000","Rs.60,000"],"answer":1,"explanation":"Tax at Rs.12L = 20,000 (4-8L at 5%) + 40,000 (8-12L at 10%) = 60,000, fully rebated under 87A.","revision":"original","contentSignature":"0f98e71f3370cb1c56f1e10e6ee6ab6e61f6b193e95d5d8fad1d961cc2565875"}]},{"id":313,"stem":"In the OLD regime, an individual with total income of Rs.5,00,000 pays tax of:","options":[{"key":"A","text":"Rs.25,000 - the 87A rebate does not apply at this income level at all"},{"key":"B","text":"NIL - rebate under 87A (up to Rs.12,500) applies for total income up to Rs.5 lakh"},{"key":"C","text":"Rs.12,500 - the 87A rebate only halves the tax at this level"},{"key":"D","text":"Rs.10,000 - the 87A rebate does not apply at this income level at all"}],"answer":"B","explanation":"Old regime: 5% of Rs.2.5L = Rs.12,500, fully rebated by 87A at the Rs.5-lakh threshold.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"In the OLD regime, an individual with total income of Rs.5,00,000 pays tax of:","options":["Rs.25,000","NIL - rebate under 87A (up to Rs.12,500) applies for total income up to Rs.5 lakh","Rs.12,500","Rs.10,000"],"answer":1,"explanation":"Old regime: 5% of Rs.2.5L = Rs.12,500, fully rebated by 87A at the Rs.5-lakh threshold.","revision":"original","contentSignature":"3b7954f1ab666927658e7e251239194d175a5afdfe0553d2d333ab46f2b20f49"}]},{"id":314,"stem":"For special rates: STCG on equity (111A) is taxed at 20%, LTCG on equity (112A) at 12.5% above Rs.1.25 lakh, and listed-bond/unlisted gains under 112 at:","options":[{"key":"A","text":"10% WITHOUT indexation, with no option preserved for any asset"},{"key":"B","text":"12.5% WITHOUT indexation (20%-with-indexation option preserved only for resident individuals/HUF on land/building acquired before 23-7- 2024)"},{"key":"C","text":"30% WITHOUT indexation"},{"key":"D","text":"20% WITH indexation for every assessee and every asset"}],"answer":"B","explanation":"Finance (No. 2) Act 2024 reworked capital-gains rates: flat 12.5% without indexation for most long-term assets, with a grandfathering choice for pre-July-2024 land/building.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"For special rates: STCG on equity (111A) is taxed at 20%, LTCG on equity (112A) at 12.5% above Rs.1.25 lakh, and listed-bond/unlisted gains under 112 at:","options":["10%","12.5% WITHOUT indexation (20%-with-indexation option preserved only for resident individuals/HUF on land/building acquired before 23-7- 2024)","30%","20% with indexation always"],"answer":1,"explanation":"Finance (No. 2) Act 2024 reworked capital-gains rates: flat 12.5% without indexation for most long-term assets, with a grandfathering choice for pre-July-2024 land/building.","revision":"original","contentSignature":"b11f0dbd73cbdc4e63e96d4ba5b415e8927bd2c2e9063f83f11d890be6f3283e"}]},{"id":315,"stem":"The holding period for LONG-TERM capital asset status is now:","options":[{"key":"A","text":"24 months for all assets alike, listed or unlisted, securities or property, from FY 2024-25 - the 12-month tier was removed altogether and no asset now qualifies earlier"},{"key":"B","text":"48 months for all the assets alike"},{"key":"C","text":"36 months for all assets alike, listed or unlisted, securities or property, from FY 2024-25 - the 12-month and 24-month tiers were removed altogether"},{"key":"D","text":"12 months (listed securities/listed units) or 24 months (other assets) - the 36-month tier was removed from FY 2024-25"}],"answer":"D","explanation":"Post-23-7-2024, only two holding tiers survive: 12 months for listed securities and units of equity-oriented funds/business trusts, 24 months for everything else.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The holding period for LONG-TERM capital asset status is now:","options":["24 months for all","48 months","36 months for all assets","12 months (listed securities/listed units) or 24 months (other assets) - the 36-month tier was removed from FY 2024-25"],"answer":3,"explanation":"Post-23-7-2024, only two holding tiers survive: 12 months for listed securities and units of equity-oriented funds/business trusts, 24 months for everything else.","revision":"original","contentSignature":"7485f08a0d46dfa4953dc4e30b164bc7bea5790c9acdeca62ac99375996371a4"}]},{"id":316,"stem":"Short-term capital gains on debt mutual funds and unlisted debentures are taxed:","options":[{"key":"A","text":"At a flat 10% as concessional short-term capital gains"},{"key":"B","text":"Exempt from tax altogether, being mutual fund income, whatever the date of acquisition of the units"},{"key":"C","text":"At a flat 12.5% as concessional short-term capital gains"},{"key":"D","text":"At SLAB rates - as ordinary income (specified mutual funds acquired after 1-4-2023 lose LTCG/indexation entirely)"}],"answer":"D","explanation":"Specified mutual funds (<=35% domestic equity) and market-linked debentures are deemed short-term regardless of holding period.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Short-term capital gains on debt mutual funds and unlisted debentures are taxed:","options":["At 10%","Exempt","At 12.5%","At SLAB rates - as ordinary income (specified mutual funds acquired after 1-4-2023 lose LTCG/indexation entirely)"],"answer":3,"explanation":"Specified mutual funds (<=35% domestic equity) and market-linked debentures are deemed short-term regardless of holding period.","revision":"original","contentSignature":"dd2c876f0535f420974755cf8d5a136c0ba4b030108d66521303d902435de6f3"}]},{"id":317,"stem":"Lottery winnings, crossword puzzles and race winnings are taxed at:","options":[{"key":"A","text":"A FLAT 20% (plus surcharge and cess) under Section 115BB, with no expenditure deduction"},{"key":"B","text":"A FLAT 30% (plus surcharge and cess) under Section 115BB, with no expenditure deduction"},{"key":"C","text":"A FLAT 10% (plus surcharge and cess) under Section 115BB, with no expenditure deduction"},{"key":"D","text":"The normal slab rates, with full expenditure deduction under Section 57"}],"answer":"B","explanation":"Casual income under 115BB carries a flat 30% rate, no deductions, no basic exemption benefit.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Lottery winnings, crossword puzzles and race winnings are taxed at:","options":["20%","A FLAT 30% (plus surcharge and cess) under Section 115BB, with no expenditure deduction","10%","Slab rates"],"answer":1,"explanation":"Casual income under 115BB carries a flat 30% rate, no deductions, no basic exemption benefit.","revision":"original","contentSignature":"740d8145786f17e20fb177102ae0c0d0c12a5c7b84bfa92e6b0df784e9bc482b"}]},{"id":318,"stem":"Income of a political party is exempt under Section 13A provided it:","options":[{"key":"A","text":"Maintains books, accepts no donation above Rs.2,000 other than by account-payee means, and files a return in time"},{"key":"B","text":"Pays tax at 30% on its entire income like a company, whether or not it keeps any books, however it collects its donations, and whether or not it ever files a return of income for the year"},{"key":"C","text":"Registers with the Reserve Bank of India, whether or not it keeps any books, however it collects its donations, and whether or not it ever files a return of income for the year"},{"key":"D","text":"Holds internal elections every year, whether or not it keeps any books, however it collects its donations, and whether or not it ever files a return of income for the year"}],"answer":"A","explanation":"Section 13A exemption is conditional on books of account, the Rs.2,000 non-cash donation limit, audited accounts and a timely return.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Income of a political party is exempt under Section 13A provided it:","options":["Maintains books, accepts no donation above Rs.2,000 other than by account-payee means, and files a return in time","Pays 30% tax","Registers with RBI","Holds elections"],"answer":0,"explanation":"Section 13A exemption is conditional on books of account, the Rs.2,000 non-cash donation limit, audited accounts and a timely return.","revision":"original","contentSignature":"b5ccc340ca6ebf3f168e82c5f6ed1a8dfce3185ca4430fc51cc738253b286ef7"}]},{"id":319,"stem":"For an individual, the ADVANCE TAX liability arises if the estimated tax payable (after TDS) is:","options":[{"key":"A","text":"Rs.10,000 or more - except RESIDENT SENIOR CITIZENS without business/profession income"},{"key":"B","text":"Rs.50,000 or more - and the exception for resident senior citizens without business income does not exist at all"},{"key":"C","text":"Rs.5,000 or more - and the exception for resident senior citizens without business income does not exist at all"},{"key":"D","text":"Any amount at all - and the exception for resident senior citizens without business income does not exist at all"}],"answer":"A","explanation":"Advance tax is payable in four instalments where net tax liability reaches Rs.10,000; resident seniors (60+) without business income are exempt.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"For an individual, the ADVANCE TAX liability arises if the estimated tax payable (after TDS) is:","options":["Rs.10,000 or more - except RESIDENT SENIOR CITIZENS without business/profession income","Rs.50,000 or more","Rs.5,000 or more","Any amount"],"answer":0,"explanation":"Advance tax is payable in four instalments where net tax liability reaches Rs.10,000; resident seniors (60+) without business income are exempt.","revision":"original","contentSignature":"37523a349f5c52bc4a2d0e0ca4afd272f37898da9db2e9517b9a11a91ad646ef"}]},{"id":320,"stem":"Advance tax instalments (non-44AD/44ADA) are: 15% by ________, 45% by ________, 75% by ________, 100% by 15 March:","options":[{"key":"A","text":"15 June, 15 September, 15 December"},{"key":"B","text":"15 July, 15 October, 15 January"},{"key":"C","text":"1 June, 1 September, 1 December"},{"key":"D","text":"30 June, 30 September, 31 December"}],"answer":"A","explanation":"The quarterly ladder is cumulative: 15% (15 Jun), 45% (15 Sep), 75% (15 Dec), 100% (15 Mar). Presumptive taxpayers (44AD/44ADA) pay 100% by 15 March only.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified"},{"id":321,"stem":"Presumptive taxpayers under Sections 44AD/44ADA pay their entire advance tax:","options":[{"key":"A","text":"Not at all"},{"key":"B","text":"In four instalments"},{"key":"C","text":"On 31 March"},{"key":"D","text":"In ONE instalment by 15 MARCH"}],"answer":"D","explanation":"The single 15-March instalment replaces the four-instalment schedule for presumptive-business and presumptive-profession taxpayers.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified"},{"id":322,"stem":"A domestic company opting out of 115BAA/115BAB with turnover up to Rs.400 crore (FY 2023-24) is taxed at:","options":[{"key":"A","text":"22%"},{"key":"B","text":"15%"},{"key":"C","text":"30%"},{"key":"D","text":"25%"}],"answer":"D","explanation":"The 25% rate applies to domestic companies with turnover/gross receipts up to Rs.400 crore in FY 2023-24; others pay 30%.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified"},{"id":323,"stem":"Foreign companies are taxed on royalty/FTS income from approved Indian agreements at:","options":[{"key":"A","text":"15% flat on royalty/FTS from every such agreement, whatever the date of the agreement and without reference to any DTAA"},{"key":"B","text":"10% flat on royalty/FTS from every such agreement, whatever the date of the agreement and without reference to any DTAA"},{"key":"C","text":"30% flat on royalty/FTS from every such agreement, whatever the date of the agreement and without reference to any DTAA"},{"key":"D","text":"40% on other income; specified royalty/FTS at 20% (agreements after 1-4-1976) under the Act, subject to DTAA"}],"answer":"D","explanation":"Foreign companies pay 40% base rate (surcharge 2%/5%) with special 20% rates for specified royalty and fees for technical services, subject to treaties.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Foreign companies are taxed on royalty/FTS income from approved Indian agreements at:","options":["15%","10%","30%","40% on other income; specified royalty/FTS at 20% (agreements after 1-4-1976) under the Act, subject to DTAA"],"answer":3,"explanation":"Foreign companies pay 40% base rate (surcharge 2%/5%) with special 20% rates for specified royalty and fees for technical services, subject to treaties.","revision":"original","contentSignature":"7c246ebdabc30b371bdccfd83de169630a7400b9c5551cb544996165753cef99"}]},{"id":324,"stem":"TDS on SALARY (Section 192) is deducted:","options":[{"key":"A","text":"At a flat rate of 10% on every salary payment, whatever the estimated income and the deductions declared by the employee for the year"},{"key":"B","text":"Only for government employees - private-sector salaries suffer no TDS at all, whatever the estimated income of the employee for the year"},{"key":"C","text":"At a flat rate of 20% on every salary payment, whatever the estimated income and the deductions declared by the employee for the year"},{"key":"D","text":"At the AVERAGE RATE of tax on the estimated salary income for the year, after allowing deductions declared by the employee"}],"answer":"D","explanation":"The employer computes the full-year tax on estimated salary (considering regime choice and declared deductions) and deducts evenly across months.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"TDS on SALARY (Section 192) is deducted:","options":["At a flat 10%","Only for government employees","At 20%","At the AVERAGE RATE of tax on the estimated salary income for the year, after allowing deductions declared by the employee"],"answer":3,"explanation":"The employer computes the full-year tax on estimated salary (considering regime choice and declared deductions) and deducts evenly across months.","revision":"original","contentSignature":"f459fb1d59f048582db21e120d143648428fa58aebf900365b1683644763416c"}]},{"id":325,"stem":"Section 192A covers TDS on:","options":[{"key":"A","text":"Salary income chargeable under Section 192, whatever the amount of the payment and the length of the service of the employee with the employer concerned"},{"key":"B","text":"Rent payments chargeable under Section 194-I, whatever the amount of the payment and the length of the service of the payee with the payer concerned"},{"key":"C","text":"Interest payments chargeable under Section 194A, whatever the amount of the payment and the length of the deposit of the payee with the payer concerned"},{"key":"D","text":"Premature withdrawal from the RECOGNISED PROVIDENT FUND - 10% if payment is Rs.50,000 or more and service is under 5 years"}],"answer":"D","explanation":"Taxable premature EPF withdrawals of Rs.50,000+ attract 10% TDS (20% if PAN is not furnished).","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Section 192A covers TDS on:","options":["Salary","Rent","Interest","Premature withdrawal from the RECOGNISED PROVIDENT FUND - 10% if payment is Rs.50,000 or more and service is under 5 years"],"answer":3,"explanation":"Taxable premature EPF withdrawals of Rs.50,000+ attract 10% TDS (20% if PAN is not furnished).","revision":"original","contentSignature":"5bed36ed65d27d5f21e115bd2717157f0c4c3381f9ac2fe3f91b5c6fd7d88c1c"}]},{"id":326,"stem":"TDS under Section 193 applies to:","options":[{"key":"A","text":"RENT - at 10%, with a threshold of Rs.10,000 a month"},{"key":"B","text":"INTEREST ON SECURITIES - 10%, with a threshold of Rs.10,000 (interest on listed debentures paid by account payee cheque: threshold Rs.5,000)"},{"key":"C","text":"COMMISSION or BROKERAGE - at 10%, with a threshold of Rs.10,000"},{"key":"D","text":"SALARY - at 10%, with a threshold of Rs.10,000"}],"answer":"B","explanation":"193 covers interest on securities at 10%; the Rs.10,000 threshold was aligned by Finance Act 2025.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"TDS under Section 193 applies to:","options":["Rent","INTEREST ON SECURITIES - 10%, with a threshold of Rs.10,000 (interest on listed debentures paid by account payee cheque: threshold Rs.5,000)","Commission","Salary"],"answer":1,"explanation":"193 covers interest on securities at 10%; the Rs.10,000 threshold was aligned by Finance Act 2025.","revision":"original","contentSignature":"e9b1928654860ea3270f4028dfdc0e6f885eff7f54aff844037abd9edac29b30"}]},{"id":327,"stem":"TDS on DIVIDEND (Section 194) for a resident shareholder is:","options":[{"key":"A","text":"10% where the dividend exceeds Rs.10,000 in the year (Rs.5,000 earlier - raised 1-4-2025)"},{"key":"B","text":"5% where the dividend exceeds Rs.10,000 in the year, for a resident shareholder"},{"key":"C","text":"20% where the dividend exceeds Rs.10,000 in the year, for a resident shareholder"},{"key":"D","text":"Nil - no TDS on dividend at all, for a resident shareholder"}],"answer":"A","explanation":"Dividend TDS is 10% above Rs.10,000; dividend income itself is taxable in the shareholder hands since FY 2020-21.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"TDS on DIVIDEND (Section 194) for a resident shareholder is:","options":["10% where the dividend exceeds Rs.10,000 in the year (Rs.5,000 earlier - raised 1-4-2025)","5%","20%","Nil"],"answer":0,"explanation":"Dividend TDS is 10% above Rs.10,000; dividend income itself is taxable in the shareholder hands since FY 2020-21.","revision":"original","contentSignature":"40fc6c5146fea9b53502c86b1f674c7c0da18c6a384194a9da1b5b59f0c89a31"}]},{"id":328,"stem":"TDS under Section 194A (interest other than on securities) is:","options":[{"key":"A","text":"5%, with the same thresholds of Rs.50,000 and Rs.10,000"},{"key":"B","text":"10% with no threshold at all - every rupee of interest suffers TDS, whether the payer is a bank, a post office or any other person, and whether the payee is a senior citizen or not, from the first rupee credited"},{"key":"C","text":"20% flat, with the same thresholds of Rs.50,000 and Rs.10,000"},{"key":"D","text":"10% - threshold Rs.50,000 (Rs.1,00,000 for SENIOR CITIZENS) for banks/post offices/co-operative banks, and Rs.10,000 for others (raised from 1-4-2025)"}],"answer":"D","explanation":"194A: 10% TDS; Finance Act 2025 raised the bank interest threshold to Rs.50,000 (Rs.1 lakh for seniors) and the others threshold to Rs.10,000.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"TDS under Section 194A (interest other than on securities) is:","options":["5%","10% with no threshold","20% flat","10% - threshold Rs.50,000 (Rs.1,00,000 for SENIOR CITIZENS) for banks/post offices/co-operative banks, and Rs.10,000 for others (raised from 1-4-2025)"],"answer":3,"explanation":"194A: 10% TDS; Finance Act 2025 raised the bank interest threshold to Rs.50,000 (Rs.1 lakh for seniors) and the others threshold to Rs.10,000.","revision":"original","contentSignature":"ce64b483f83e5907d2051874478afff5f14c88a1314751c4844901c3334e56a7"}]},{"id":329,"stem":"Section 194C covers TDS on payments to:","options":[{"key":"A","text":"CONTRACTORS and sub-contractors - 1% for individuals/HUF, 2% for others; single payment threshold Rs.30,000, annual aggregate Rs.1,00,000"},{"key":"B","text":"DOCTORS and other medical professionals - 1% for individuals and HUF, 2% for others, with the same single-payment and annual-aggregate thresholds applying to every such payment in the year"},{"key":"C","text":"EMPLOYEES on the payroll - 1% for individuals and HUF, 2% for others, with the same single-payment and annual-aggregate thresholds applying to every such payment in the year"},{"key":"D","text":"LANDLORDS receiving rent - 1% for individuals and HUF, 2% for others, with the same single-payment and annual-aggregate thresholds applying to every such payment in the year"}],"answer":"A","explanation":"194C: 1%/2% on contract payments; thresholds Rs.30,000 single and Rs.1,00,000 aggregate per financial year.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Section 194C covers TDS on payments to:","options":["CONTRACTORS and sub-contractors - 1% for individuals/HUF, 2% for others; single payment threshold Rs.30,000, annual aggregate Rs.1,00,000","Doctors","Employees","Landlords"],"answer":0,"explanation":"194C: 1%/2% on contract payments; thresholds Rs.30,000 single and Rs.1,00,000 aggregate per financial year.","revision":"original","contentSignature":"d37734f04c54cdfcc4135229d475965389de03be72846e38c6a96195e1b30bbe"}]},{"id":330,"stem":"A TRANSPORT contractor holding 10 or fewer goods carriages and furnishing PAN is:","options":[{"key":"A","text":"Taxed at 5% under 194C, even with the PAN declaration furnished"},{"key":"B","text":"Taxed at 2% under 194C, even with the PAN declaration furnished"},{"key":"C","text":"EXEMPT from TDS under 194C (declaration with PAN required)"},{"key":"D","text":"Taxed at 10% under 194C, even with the PAN declaration furnished"}],"answer":"C","explanation":"Small transporters (up to 10 goods carriages) escape 194C TDS on furnishing PAN and a declaration.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A TRANSPORT contractor holding 10 or fewer goods carriages and furnishing PAN is:","options":["Taxed at 5%","Taxed at 2%","EXEMPT from TDS under 194C (declaration with PAN required)","Taxed at 10%"],"answer":2,"explanation":"Small transporters (up to 10 goods carriages) escape 194C TDS on furnishing PAN and a declaration.","revision":"original","contentSignature":"a4f4cb670dc0f11d499c006989f88e796fe339e1d271c5b58de36f38d180fe63"}]},{"id":331,"stem":"TDS under Section 194-I on RENT is:","options":[{"key":"A","text":"2% for every kind of rent, with a threshold of Rs.50,000 a month"},{"key":"B","text":"10% for land/building/furniture/fittings; 2% for plant & machinery - threshold Rs.50,000 PER MONTH (monthly basis from 1-4-2025)"},{"key":"C","text":"20% for land/building/furniture and 10% for plant and machinery"},{"key":"D","text":"10% for every kind of rent, with a threshold of Rs.50,000 a month"}],"answer":"B","explanation":"194-I: 2% on plant/machinery rent, 10% on land/building/furniture; from April 2025 the threshold is Rs.50,000 per month (replacing the Rs.2.4-lakh annual test).","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"TDS under Section 194-I on RENT is:","options":["2% for everything","10% for land/building/furniture/fittings; 2% for plant & machinery - threshold Rs.50,000 PER MONTH (monthly basis from 1-4-2025)","20%","10% for everything"],"answer":1,"explanation":"194-I: 2% on plant/machinery rent, 10% on land/building/furniture; from April 2025 the threshold is Rs.50,000 per month (replacing the Rs.2.4-lakh annual test).","revision":"original","contentSignature":"57c363bcc9386a4224ff3597cecd02ce56b242c56af72c1130d4f1cf877cca76"}]},{"id":332,"stem":"Section 194-IA covers TDS on purchase of IMMOVABLE PROPERTY (other than agricultural land):","options":[{"key":"A","text":"5% where the consideration (or SDV) is Rs.50 lakh or more - the buyer deducts, no TAN needed (Form 26QB)"},{"key":"B","text":"2% where the consideration (or SDV) is Rs.20 lakh or more - the buyer deducts, no TAN needed (Form 26QB)"},{"key":"C","text":"1% where consideration (or SDV) is Rs.50 LAKH or more - buyer deducts, no TAN needed (Form 26QB)"},{"key":"D","text":"10% where the consideration (or SDV) is Rs.50 lakh or more - the buyer deducts, no TAN needed (Form 26QB)"}],"answer":"C","explanation":"194-IA: the buyer deducts 1% on transfers of Rs.50 lakh+, deposited via Form 26QB using only PANs.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Section 194-IA covers TDS on purchase of IMMOVABLE PROPERTY (other than agricultural land):","options":["5%","2% above Rs.20 lakh","1% where consideration (or SDV) is Rs.50 LAKH or more - buyer deducts, no TAN needed (Form 26QB)","10%"],"answer":2,"explanation":"194-IA: the buyer deducts 1% on transfers of Rs.50 lakh+, deposited via Form 26QB using only PANs.","revision":"original","contentSignature":"0b52d437e3159d501955ea7845bbbac286a2d7440a35db15b52cbdadd8311dfe"}]},{"id":333,"stem":"Section 194J (fees for professional or technical services) is deducted at:","options":[{"key":"A","text":"10% - but 2% for technical services, call centres, and royalty for sale/distribution/exhibition of cinematographic films; threshold Rs.50,000 (raised from 1-4-2025)"},{"key":"B","text":"5% flat for every payment covered by the section, with no distinction"},{"key":"C","text":"1% flat for every payment covered by the section - professional services, technical services, call centres and the specified royalties alike - with no distinction of rates at all"},{"key":"D","text":"20% flat for every payment covered by the section - professional services, technical services, call centres and the specified royalties alike - with no distinction of rates at all"}],"answer":"A","explanation":"194J: 10% general, 2% for technical services/call centres/specified royalty; the Rs.50,000 threshold applies from April 2025.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Section 194J (fees for professional or technical services) is deducted at:","options":["10% - but 2% for technical services, call centres, and royalty for sale/distribution/exhibition of cinematographic films; threshold Rs.50,000 (raised from 1-4-2025)","5% flat","1%","20%"],"answer":0,"explanation":"194J: 10% general, 2% for technical services/call centres/specified royalty; the Rs.50,000 threshold applies from April 2025.","revision":"original","contentSignature":"34649292884da9c21766fcf6078dbbe4e22cdeee1196ae2d923a16e019b4285a"}]},{"id":334,"stem":"TDS on INSURANCE COMMISSION (Section 194D) is:","options":[{"key":"A","text":"5%, with a threshold of Rs.20,000"},{"key":"B","text":"1%, with a threshold of Rs.20,000"},{"key":"C","text":"2% - threshold Rs.20,000 (rate halved from 5% with effect from 1-4-2025; threshold raised from Rs.15,000)"},{"key":"D","text":"10%, with a threshold of Rs.20,000"}],"answer":"C","explanation":"194D: 2% on insurance commission above Rs.20,000 (Finance (No.2) Act 2024 cut it from 5% w.e.f. 1-4-2025); 194G (lottery tickets commission) is 2% above Rs.20,000; 194H (commission/brokerage) is 2% above Rs.20,000.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"TDS on INSURANCE COMMISSION (Section 194D) is:","options":["5%","1%","2% - threshold Rs.20,000 (rate halved from 5% with effect from 1-4-2025; threshold raised from Rs.15,000)","10%"],"answer":2,"explanation":"194D: 2% on insurance commission above Rs.20,000 (Finance (No.2) Act 2024 cut it from 5% w.e.f. 1-4-2025); 194G (lottery tickets commission) is 2% above Rs.20,000; 194H (commission/brokerage) is 2% above Rs.20,000.","revision":"original","contentSignature":"e13792015247bbae9b02163251d0266fe943f7b33069383c13bd2f99eaa897f3"}]},{"id":335,"stem":"Section 194H (commission or brokerage other than insurance commission) is deducted at:","options":[{"key":"A","text":"2% above Rs.20,000 (rates recast 1-10-2024; threshold raised 1-4-2025)"},{"key":"B","text":"10% above the threshold of Rs.20,000"},{"key":"C","text":"5% above the threshold of Rs.20,000"},{"key":"D","text":"1% above the threshold of Rs.20,000"}],"answer":"A","explanation":"194H is 2% (reduced from 5% in October 2024) with a Rs.20,000 threshold.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Section 194H (commission or brokerage other than insurance commission) is deducted at:","options":["2% above Rs.20,000 (rates recast 1-10-2024; threshold raised 1-4-2025)","10%","5%","1%"],"answer":0,"explanation":"194H is 2% (reduced from 5% in October 2024) with a Rs.20,000 threshold.","revision":"original","contentSignature":"0620dcd936ca5ea41b17aa67a90c7fc8fdfa022de03145a308011e671c83c462"}]},{"id":336,"stem":"Section 194Q (buyer of GOODS) requires TDS of:","options":[{"key":"A","text":"10% on purchases exceeding Rs.50 lakh in the year - where the buyer turnover exceeded Rs.10 crore in the preceding year"},{"key":"B","text":"0.1% on purchases exceeding Rs.50 LAKH in the year - where the buyer turnover exceeded Rs.10 CRORE in the preceding year"},{"key":"C","text":"1% on every purchase, with no threshold at all - where the buyer turnover exceeded Rs.10 crore in the preceding year"},{"key":"D","text":"5% on purchases exceeding Rs.50 lakh in the year - where the buyer turnover exceeded Rs.10 crore in the preceding year"}],"answer":"B","explanation":"194Q: 0.1% on the excess over Rs.50 lakh of goods purchases, applicable to buyers with prior-year turnover above Rs.10 crore.","source":"Source label not detected","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Section 194Q (buyer of GOODS) requires TDS of:","options":["10%","0.1% on purchases exceeding Rs.50 LAKH in the year - where the buyer turnover exceeded Rs.10 CRORE in the preceding year","1% on everything","5%"],"answer":1,"explanation":"194Q: 0.1% on the excess over Rs.50 lakh of goods purchases, applicable to buyers with prior-year turnover above Rs.10 crore.","revision":"original","contentSignature":"1bec1f75ee3ab2fa5e3119ccff28b15702dbbd99a3174624c344479de75ebabd"}]},{"id":337,"stem":"Section 194-T (NEW, from 1-4-2025) requires a FIRM to deduct TDS on payments to its PARTNERS (salary, remuneration, commission, bonus, interest) at:","options":[{"key":"A","text":"12% where the aggregate exceeds Rs.1 lakh in the year"},{"key":"B","text":"5% where the aggregate exceeds Rs.20,000 in the year"},{"key":"C","text":"10% where the aggregate exceeds Rs.20,000 in the year"},{"key":"D","text":"No TDS at all on payments to partners, whatever the amount"}],"answer":"C","explanation":"194T plugs the partner-payment gap: 10% TDS by the firm on aggregate partner payments above Rs.20,000 per year.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Section 194-T (NEW, from 1-4-2025) requires a FIRM to deduct TDS on payments to its PARTNERS (salary, remuneration, commission, bonus, interest) at:","options":["12% above Rs.1 lakh","5%","10% where the aggregate exceeds Rs.20,000 in the year","No TDS on partner payments"],"answer":2,"explanation":"194T plugs the partner-payment gap: 10% TDS by the firm on aggregate partner payments above Rs.20,000 per year.","revision":"original","contentSignature":"dc0cb4d7b35dfb256648acaf056a8b0d23fc02bc737ac8b2d9bae28f21454753"}]},{"id":338,"stem":"TDS on payment to a person WITHOUT PAN (Section 206AA) is:","options":[{"key":"A","text":"5% flat, irrespective of the rate in force or the rate specified"},{"key":"B","text":"The HIGHER of: 20%, the rate in force, or the rate specified in the Act"},{"key":"C","text":"Only the normal rate - the PAN status of the payee makes no difference"},{"key":"D","text":"Nil - no TDS at all where the PAN is not furnished by the payee concerned"}],"answer":"B","explanation":"206AA penalises non-furnishing of PAN: deduction at 20% or the applicable rate, whichever is higher.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"TDS on payment to a person WITHOUT PAN (Section 206AA) is:","options":["5%","The HIGHER of: 20%, the rate in force, or the rate specified in the Act","The normal rate","Nil"],"answer":1,"explanation":"206AA penalises non-furnishing of PAN: deduction at 20% or the applicable rate, whichever is higher.","revision":"original","contentSignature":"0e66a4e5a06337631702a2cd4ebc423491532d954c73dbfd708625657ba12f9a"}]},{"id":339,"stem":"Sections 206AB and 206CCA (higher TDS/TCS for non-filers of returns) are:","options":[{"key":"A","text":"OMITTED with effect from 1-4-2025 (Finance Act 2025) - but 206AA/206CC (no PAN) continue"},{"key":"B","text":"Fully applicable at a flat 10% from 1-4-2025 - and 206AA/206CC (no PAN) stand omitted instead"},{"key":"C","text":"Fully applicable at a flat 5% from 1-4-2025 - and 206AA/206CC (no PAN) stand omitted instead"},{"key":"D","text":"Newly introduced by the Finance Act 2025, with effect from 1-4-2025"}],"answer":"A","explanation":"The Finance Act 2025 removed the 206AB/206CCA higher-rate provisions for non-filers, easing compliance.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Sections 206AB and 206CCA (higher TDS/TCS for non-filers of returns) are:","options":["OMITTED with effect from 1-4-2025 (Finance Act 2025) - but 206AA/206CC (no PAN) continue","Applicable at 10%","Applicable at 5%","Newly introduced in 2025"],"answer":0,"explanation":"The Finance Act 2025 removed the 206AB/206CCA higher-rate provisions for non-filers, easing compliance.","revision":"original","contentSignature":"f027a746ab64574a18c5c0a6f5b9e4d23011b5dd2955b80be47c4bffa5b09887"}]},{"id":340,"stem":"TDS under Section 194N on CASH WITHDRAWALS is:","options":[{"key":"A","text":"1% on withdrawals exceeding Rs.50 lakh in the year"},{"key":"B","text":"10% on withdrawals exceeding Rs.1 crore in the year"},{"key":"C","text":"5% on withdrawals exceeding Rs.20 lakh in the year"},{"key":"D","text":"2% on withdrawals exceeding Rs.1 crore in the year (bank/post office; co-operative banks: Rs.3 crore threshold)"}],"answer":"D","explanation":"194N: 2% on cash withdrawals above Rs.1 crore per year; 2%/5% (above Rs.20 lakh/Rs.1 crore) for those who have not filed returns for 3 years.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"TDS under Section 194N on CASH WITHDRAWALS is:","options":["1% above Rs.50 lakh","10%","5% above Rs.20 lakh","2% on withdrawals exceeding Rs.1 crore in the year (bank/post office; co-operative banks: Rs.3 crore threshold)"],"answer":3,"explanation":"194N: 2% on cash withdrawals above Rs.1 crore per year; 2%/5% (above Rs.20 lakh/Rs.1 crore) for those who have not filed returns for 3 years.","revision":"original","contentSignature":"9443c8e76e23a9d6557a9854e7012b1564d88b70e63c6242ff840e23d7a91241"}]},{"id":341,"stem":"Section 195 covers TDS on payments to:","options":[{"key":"A","text":"Banks and financial institutions only, on their interest income (other than salary) - at rates in force, on the income portion chargeable to tax"},{"key":"B","text":"The Central and State Governments, on their receipts (other than salary) - at rates in force, on the income portion chargeable to tax"},{"key":"C","text":"RESIDENTS of every kind, on all payments made to them (other than salary) - at rates in force, on the income portion chargeable to tax"},{"key":"D","text":"NON-RESIDENTS (other than salary) - at rates in force, on the income portion chargeable to tax"}],"answer":"D","explanation":"195 requires deduction on any sum (other than salary) chargeable to tax paid to a non-resident or foreign company; certificates u/s 197 can lower it.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Section 195 covers TDS on payments to:","options":["Banks","Government","Residents","NON-RESIDENTS (other than salary) - at rates in force, on the income portion chargeable to tax"],"answer":3,"explanation":"195 requires deduction on any sum (other than salary) chargeable to tax paid to a non-resident or foreign company; certificates u/s 197 can lower it.","revision":"original","contentSignature":"cc3cab153dbf09ad4c06d40ca8ba3cea4b7bdc9330e20b7dc0d467f3bed6a2e5"}]},{"id":342,"stem":"An assessee can apply for LOWER or NIL TDS deduction under:","options":[{"key":"A","text":"Section 206AA - certificate from the Assessing Officer permitting deduction at the lower of the specified rates"},{"key":"B","text":"Section 194 - certificate from the Assessing Officer; also Form 15G/15H declarations"},{"key":"C","text":"Section 195 - certificate from the Assessing Officer; also Form 15G/15H declarations"},{"key":"D","text":"Section 197 - certificate from the Assessing Officer; also Form 15G/15H declarations for no-deduction by eligible persons"}],"answer":"D","explanation":"Section 197 certificates (online Form 13) authorise lower/nil deduction; 15G (individuals) and 15H (senior citizens) are self-declarations of nil tax liability.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"An assessee can apply for LOWER or NIL TDS deduction under:","options":["Section 206AA","Section 194","Section 195","Section 197 - certificate from the Assessing Officer; also Form 15G/15H declarations for no-deduction by eligible persons"],"answer":3,"explanation":"Section 197 certificates (online Form 13) authorise lower/nil deduction; 15G (individuals) and 15H (senior citizens) are self-declarations of nil tax liability.","revision":"original","contentSignature":"6aea43b5f31389ff0fb6108dc53728ce939db8e89d5d97f2fdfff9f7da87d160"}]},{"id":343,"stem":"Form 15H can be filed by:","options":[{"key":"A","text":"A RESIDENT INDIVIDUAL aged 60 or more whose tax on estimated total income is NIL"},{"key":"B","text":"Non-resident individuals of any age whose tax on estimated total income is NIL"},{"key":"C","text":"Any taxpayer at all, of any age, any residential status and any entity form"},{"key":"D","text":"Companies whose tax on estimated total income for the year is NIL"}],"answer":"A","explanation":"15H is the senior-citizen self-declaration for nil TDS; 15G is for others below the taxable threshold.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Form 15H can be filed by:","options":["A RESIDENT INDIVIDUAL aged 60 or more whose tax on estimated total income is NIL","NRIs","Any taxpayer","Companies"],"answer":0,"explanation":"15H is the senior-citizen self-declaration for nil TDS; 15G is for others below the taxable threshold.","revision":"original","contentSignature":"42ce3fe98cddbb91ef98c303578af41830b785cddae35688b8a8692c3f5d83cf"}]},{"id":344,"stem":"TCS under Section 206C(1) applies to sellers of:","options":[{"key":"A","text":"Specified services of every kind - professional, technical and contractual alike - at 1% to 5%, with no goods of any description covered by the section at all"},{"key":"B","text":"Shares and securities of every company, listed or unlisted alike - at 1% to 5%, with no goods of any description covered by the section at all"},{"key":"C","text":"Specified goods: alcoholic liquor, tendu leaves, timber, other forest produce, scrap, minerals (coal/lignite/iron ore) - 1% to 5%"},{"key":"D","text":"All goods of every description without exception"}],"answer":"C","explanation":"206C(1) lists the traditional TCS goods with rates from 1% (scrap, minerals) to 5% (timber under forest lease 2.5%).","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"TCS under Section 206C(1) applies to sellers of:","options":["Services","Shares","Specified goods: alcoholic liquor, tendu leaves, timber, other forest produce, scrap, minerals (coal/lignite/iron ore) - 1% to 5%","All goods"],"answer":2,"explanation":"206C(1) lists the traditional TCS goods with rates from 1% (scrap, minerals) to 5% (timber under forest lease 2.5%).","revision":"original","contentSignature":"a90eb961d355d6d7ffd31ef38bf7d8cc06cfa3e81763146806707e3cfefc157e"}]},{"id":345,"stem":"TCS on sale of MOTOR VEHICLES under 206C(1F) is:","options":[{"key":"A","text":"5% where the value exceeds Rs.10 lakh"},{"key":"B","text":"Nil - no TCS on motor vehicles at all"},{"key":"C","text":"1% where the value exceeds Rs.10 lakh"},{"key":"D","text":"2% where the value exceeds Rs.10 lakh"}],"answer":"C","explanation":"Motor-vehicle TCS: 1% on sale value above Rs.10 lakh, collected by the seller.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"TCS on sale of MOTOR VEHICLES under 206C(1F) is:","options":["5%","Nil","1% where the value exceeds Rs.10 lakh","2%"],"answer":2,"explanation":"Motor-vehicle TCS: 1% on sale value above Rs.10 lakh, collected by the seller.","revision":"original","contentSignature":"14d3b1ec46ea26bf49099c95cc51094ebb9d5e00a46595f1ae842044edba8a24"}]},{"id":346,"stem":"TCS under 206C(1G) on overseas tour packages and LRS remittances is:","options":[{"key":"A","text":"Nil - none of these remittances suffers any TCS"},{"key":"B","text":"A flat 10% on every such remittance above Rs.10 lakh - education funded by a specified loan included, and tour packages at the same flat rate whatever the amount"},{"key":"C","text":"A flat 2% on every such remittance above Rs.10 lakh - education funded by a specified loan included, and tour packages at the same flat rate whatever the amount"},{"key":"D","text":"20% above Rs.10 lakh (LRS); education funded by a SPECIFIED LOAN: NIL (from 1-4-2025); education/medical otherwise 5% above Rs.10 lakh; tour packages 5% up to Rs.10 lakh and 20% above"}],"answer":"D","explanation":"Budget 2025: LRS threshold raised to Rs.10 lakh, and TCS on education remittances funded by a financial-institution loan REMOVED; tour packages 5%/20% around Rs.10 lakh.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"TCS under 206C(1G) on overseas tour packages and LRS remittances is:","options":["Nil","10% flat","2% flat","20% above Rs.10 lakh (LRS); education funded by a SPECIFIED LOAN: NIL (from 1-4-2025); education/medical otherwise 5% above Rs.10 lakh; tour packages 5% up to Rs.10 lakh and 20% above"],"answer":3,"explanation":"Budget 2025: LRS threshold raised to Rs.10 lakh, and TCS on education remittances funded by a financial-institution loan REMOVED; tour packages 5%/20% around Rs.10 lakh.","revision":"original","contentSignature":"7f69647c8a3cb820a7f9a55cf7147d8b462192234c6baa2acf938fd46a8c659f"}]},{"id":347,"stem":"TCS on sale of GOODS under Section 206C(1H) is:","options":[{"key":"A","text":"1% on sale consideration above Rs.50 lakh - the provision fully operates from 1-4-2025"},{"key":"B","text":"OMITTED with effect from 1-4-2025 (Finance Act 2025) - the provision no longer operates"},{"key":"C","text":"5% on sale consideration above Rs.50 lakh - the provision fully operates from 1-4-2025"},{"key":"D","text":"0.1% on sale consideration above Rs.50 lakh - the provision fully operates from 1-4-2025"}],"answer":"B","explanation":"206C(1H) (goods-sale TCS, overlapping with 194Q) was omitted from April 2025 to cut compliance burden.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"TCS on sale of GOODS under Section 206C(1H) is:","options":["1%","OMITTED with effect from 1-4-2025 (Finance Act 2025) - the provision no longer operates","5%","0.1% above Rs.50 lakh"],"answer":1,"explanation":"206C(1H) (goods-sale TCS, overlapping with 194Q) was omitted from April 2025 to cut compliance burden.","revision":"original","contentSignature":"effb7f3ba46f391dd177567d6ca42563a68886a15d034784fe5400dc25aba14d"}]},{"id":348,"stem":"TDS on winnings from LOTTERY, crossword puzzles, horse races (Section 194B/194BB) is:","options":[{"key":"A","text":"5% - with an annual Rs.10,000 aggregate threshold for 194B/194BB, exactly as the law stands after the 1-4-2025 change to an annual aggregate threshold in place of the single-transaction threshold"},{"key":"B","text":"30% - with an annual Rs.10,000 aggregate threshold for 194B/194BB (single-transaction threshold replaced by annual aggregate from 1-4- 2025)"},{"key":"C","text":"10% - with an annual Rs.10,000 aggregate threshold for 194B/194BB, exactly as the law stands after the 1-4-2025 change to an annual aggregate threshold in place of the single-transaction threshold"},{"key":"D","text":"20% - with an annual Rs.10,000 aggregate threshold for 194B/194BB, exactly as the law stands after the 1-4-2025 change to an annual aggregate threshold in place of the single-transaction threshold"}],"answer":"B","explanation":"Winnings TDS is 30%; from April 2025 the Rs.10,000 test applies to the annual aggregate rather than per transaction. Online games (194BA) are 30% on net winnings with no threshold.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"TDS on winnings from LOTTERY, crossword puzzles, horse races (Section 194B/194BB) is:","options":["5%","30% - with an annual Rs.10,000 aggregate threshold for 194B/194BB (single-transaction threshold replaced by annual aggregate from 1-4- 2025)","10%","20%"],"answer":1,"explanation":"Winnings TDS is 30%; from April 2025 the Rs.10,000 test applies to the annual aggregate rather than per transaction. Online games (194BA) are 30% on net winnings with no threshold.","revision":"original","contentSignature":"eac440a1ec948337ef5651b07746b947dc7873b2ae0a8424ac3dcff36f844fdc"}]},{"id":349,"stem":"Section 194DA covers TDS on:","options":[{"key":"A","text":"INTEREST payments of every kind - 2% on the entire amount above Rs.1 lakh, with no reference to any insurance policy, any exemption under s.10(10D), or any income component at all"},{"key":"B","text":"Payment of LIFE INSURANCE policy proceeds not exempt under s.10(10D) - 2% (reduced from 5% on 1-10-2024) on the INCOME component above Rs.1 lakh"},{"key":"C","text":"SALARY payments of every kind - 2% on the entire amount above Rs.1 lakh, with no reference to any insurance policy, any exemption under s.10(10D), or any income component at all"},{"key":"D","text":"RENT payments of every kind - 2% on the entire amount above Rs.1 lakh, with no reference to any insurance policy, any exemption under s.10(10D), or any income component at all"}],"answer":"B","explanation":"194DA: 2% on the income part of taxable life-insurance payouts exceeding Rs.1 lakh.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Section 194DA covers TDS on:","options":["Interest","Payment of LIFE INSURANCE policy proceeds not exempt under s.10(10D) - 2% (reduced from 5% on 1-10-2024) on the INCOME component above Rs.1 lakh","Salary","Rent"],"answer":1,"explanation":"194DA: 2% on the income part of taxable life-insurance payouts exceeding Rs.1 lakh.","revision":"original","contentSignature":"820b0c89ec69ee1476f44f91c69d7e79c8ef28eb317eed7118123ceb42e209fc"}]},{"id":350,"stem":"Every person deducting TDS (except under 194-IA/194-IB/194M cases using challan-cum-statement) must obtain:","options":[{"key":"A","text":"TAN - Tax Deduction Account Number under Section 203A"},{"key":"B","text":"DIN - Director Identification Number, under the company law"},{"key":"C","text":"GSTIN - the GST registration number of the deductor"},{"key":"D","text":"PAN only - no separate deduction number is needed"}],"answer":"A","explanation":"TAN is mandatory for deductors; the specified property/rent/large-payment sections allow PAN-based challan-cum-statements instead.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Every person deducting TDS (except under 194-IA/194-IB/194M cases using challan-cum-statement) must obtain:","options":["TAN - Tax Deduction Account Number under Section 203A","DIN","GSTIN","PAN only"],"answer":0,"explanation":"TAN is mandatory for deductors; the specified property/rent/large-payment sections allow PAN-based challan-cum-statements instead.","revision":"original","contentSignature":"7ecf95dee183f8110db1da2dfd97044a3e96d6aa89db4caa9332a4816f683a9c"}]},{"id":351,"stem":"Quarterly TDS statement for SALARY is filed in:","options":[{"key":"A","text":"Form 26Q, with Form 16A issued from it by 15 June"},{"key":"B","text":"Form 27Q, with Form 16A issued from it by 15 June"},{"key":"C","text":"Form 24Q (Form 16 issued from it to employees by 15 June)"},{"key":"D","text":"Form 16A itself, filed as the quarterly statement"}],"answer":"C","explanation":"24Q covers salary TDS and generates Form 16; 26Q covers resident non-salary payments (Form 16A); 27Q covers non-resident payments.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Quarterly TDS statement for SALARY is filed in:","options":["Form 26Q","Form 27Q","Form 24Q (Form 16 issued from it to employees by 15 June)","Form 16A"],"answer":2,"explanation":"24Q covers salary TDS and generates Form 16; 26Q covers resident non-salary payments (Form 16A); 27Q covers non-resident payments.","revision":"original","contentSignature":"6e0ec0b88a80590d0fd0c935cdb8680f7c8b9ad03bfa1b7bfb9f7aac8966f611"}]},{"id":352,"stem":"The due date for depositing TDS (other than March deductions) is:","options":[{"key":"A","text":"15th of the SAME month in which the deduction is made (15 April for March deductions)"},{"key":"B","text":"7th of the FOLLOWING month (30 April for March deductions)"},{"key":"C","text":"10th of the following month (30 April for March deductions)"},{"key":"D","text":"The last day of the same month (30 April for March deductions)"}],"answer":"B","explanation":"Government deductors deposit the same day (without challan); others by the 7th of the next month; March TDS can go up to 30 April.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The due date for depositing TDS (other than March deductions) is:","options":["15th of the same month","7th of the FOLLOWING month (30 April for March deductions)","10th of next month","Last day of the month"],"answer":1,"explanation":"Government deductors deposit the same day (without challan); others by the 7th of the next month; March TDS can go up to 30 April.","revision":"original","contentSignature":"57b5c8c13b365f6aba4fd15b74f4c02ba11da1b0712e83fe3deaa9e8ffbc9c2b"}]},{"id":353,"stem":"Interest for LATE DEDUCTION of TDS is ________, and for late DEPOSIT after deduction is ________ (Section 201(1A)):","options":[{"key":"A","text":"2% per month; 2% per month, respectively"},{"key":"B","text":"1% per month; 1.5% per month"},{"key":"C","text":"1.5% per month; 1% per month, respectively"},{"key":"D","text":"1% per month; 1% per month, respectively"}],"answer":"B","explanation":"201(1A): 1% per month for failure to deduct, 1.5% per month for deduction without deposit - each part-month counts as a full month.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Interest for LATE DEDUCTION of TDS is ________, and for late DEPOSIT after deduction is ________ (Section 201(1A)):","options":["2%; 2%","1% per month; 1.5% per month","1.5%; 1%","1%; 1%"],"answer":1,"explanation":"201(1A): 1% per month for failure to deduct, 1.5% per month for deduction without deposit - each part-month counts as a full month.","revision":"original","contentSignature":"d60ef9ea2417610afe153dce2e97111e6be802a65df6023e18c9d3ad54370baf"}]},{"id":354,"stem":"Fee for late filing of the TDS STATEMENT under Section 234E is:","options":[{"key":"A","text":"A flat Rs.1,000 per statement, whatever the delay"},{"key":"B","text":"Rs.500 per day, capped at the TDS amount"},{"key":"C","text":"Rs.200 per day, capped at the TDS amount"},{"key":"D","text":"Rs.100 per day, capped at the TDS amount"}],"answer":"C","explanation":"234E levies Rs.200 per day of delay in furnishing TDS/TCS statements, capped at the tax amount.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Fee for late filing of the TDS STATEMENT under Section 234E is:","options":["Rs.1,000 flat","Rs.500 per day","Rs.200 per day, capped at the TDS amount","Rs.100 per day"],"answer":2,"explanation":"234E levies Rs.200 per day of delay in furnishing TDS/TCS statements, capped at the tax amount.","revision":"original","contentSignature":"8f0d60785e49fa0138e1a8688b8659e1c9c0e8d295ca2f2627f265429478e345"}]},{"id":355,"stem":"Section 194R requires TDS on:","options":[{"key":"A","text":"DIVIDEND payments to resident shareholders - 10% where the aggregate value exceeds Rs.20,000 in the year, whatever the nature of the payment and the status of the payee under the Act"},{"key":"B","text":"RENT payments of every kind - 10% where the aggregate value exceeds Rs.20,000 in the year, whatever the nature of the payment and the status of the payee under the Act"},{"key":"C","text":"SALARY payments to employees - 10% where the aggregate value exceeds Rs.20,000 in the year, whatever the nature of the payment and the status of the payee under the Act"},{"key":"D","text":"Any BENEFIT OR PERQUISITE arising from business or profession - 10% where the aggregate value exceeds Rs.20,000 in the year"}],"answer":"D","explanation":"194R (from FY 2022-23) taxes business/profession benefits and perquisites in kind at 10% above Rs.20,000.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Section 194R requires TDS on:","options":["Dividend","Rent","Salary","Any BENEFIT OR PERQUISITE arising from business or profession - 10% where the aggregate value exceeds Rs.20,000 in the year"],"answer":3,"explanation":"194R (from FY 2022-23) taxes business/profession benefits and perquisites in kind at 10% above Rs.20,000.","revision":"original","contentSignature":"3b441cc179f45e7c2d48dfda5bff052eb1cd96ec38c3b20e37f72b68b28a18db"}]},{"id":356,"stem":"Section 194S covers TDS on transfer of:","options":[{"key":"A","text":"SHARES and securities of every listed company - 1% above Rs.50,000 for specified persons and Rs.10,000 for others, exactly as the threshold structure stands for the covered assets under the section"},{"key":"B","text":"IMMOVABLE PROPERTY of every kind - 1% above Rs.50,000 for specified persons and Rs.10,000 for others, exactly as the threshold structure stands for the covered assets under the section"},{"key":"C","text":"GOODS of every description - 1% above Rs.50,000 for specified persons and Rs.10,000 for others, exactly as the threshold structure stands for the covered assets under the section"},{"key":"D","text":"VIRTUAL DIGITAL ASSETS (cryptocurrency, NFTs) - 1% above Rs.50,000 for specified persons (individuals/HUF within limits) and Rs.10,000 for others"}],"answer":"D","explanation":"194S: 1% TDS on VDA transfers; thresholds Rs.50,000 for specified persons (individuals/HUF within limits) and Rs.10,000 for others. VDA gains are taxed at 30% under 115BBH.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Section 194S covers TDS on transfer of:","options":["Shares","Immovable property","Goods","VIRTUAL DIGITAL ASSETS (cryptocurrency, NFTs) - 1% above Rs.50,000 for specified persons (individuals/HUF within limits) and Rs.10,000 for others"],"answer":3,"explanation":"194S: 1% TDS on VDA transfers; thresholds Rs.50,000 for specified persons (individuals/HUF within limits) and Rs.10,000 for others. VDA gains are taxed at 30% under 115BBH.","revision":"original","contentSignature":"cd7a9403ff1f288306d7108d8a97de39e23e3147f10c863206edee8088d1e88f"}]},{"id":357,"stem":"The due date for filing the return of income under Section 139(1) for an INDIVIDUAL (non-audit) is:","options":[{"key":"A","text":"31 October of the assessment year"},{"key":"B","text":"31 JULY of the assessment year"},{"key":"C","text":"31 March of the assessment year"},{"key":"D","text":"30 September of the assessment year"}],"answer":"B","explanation":"Individuals/HUF (non-audit): 31 July; companies and audit cases: 31 October; transfer-pricing reports: 30 November.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The due date for filing the return of income under Section 139(1) for an INDIVIDUAL (non-audit) is:","options":["31 October","31 JULY of the assessment year","31 March","30 September"],"answer":1,"explanation":"Individuals/HUF (non-audit): 31 July; companies and audit cases: 31 October; transfer-pricing reports: 30 November.","revision":"original","contentSignature":"6cf4ffe40d31a84cb4706ff9a82553b5d29e8e8b82d677c7279a7b2ac13181a1"}]},{"id":358,"stem":"A BELATED return under Section 139(4) can be filed:","options":[{"key":"A","text":"Within one year from the due date of filing the return, whatever the date of completion of the assessment for the year and without any late fee of any kind being attracted"},{"key":"B","text":"At any time within 4 years from the end of the assessment year, whatever the date of completion of the assessment for the year and without any late fee of any kind being attracted"},{"key":"C","text":"Never - a return once not filed by the due date can never be filed at all, whatever the circumstances"},{"key":"D","text":"Up to 31 DECEMBER of the assessment year (or before completion of assessment, whichever is earlier), with a late fee under 234F"}],"answer":"D","explanation":"Belated and revised returns share the same outer limit: 31 December of the AY (9 months after the end of the relevant FY).","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A BELATED return under Section 139(4) can be filed:","options":["Within one year of the due date","Any time within 4 years","Never","Up to 31 DECEMBER of the assessment year (or before completion of assessment, whichever is earlier), with a late fee under 234F"],"answer":3,"explanation":"Belated and revised returns share the same outer limit: 31 December of the AY (9 months after the end of the relevant FY).","revision":"original","contentSignature":"bbe6888aab222fb73f9e13d6d15bc7395498d19cb2d4a97f7db1de15aca78e6f"}]},{"id":359,"stem":"A REVISED return under Section 139(5) can be filed:","options":[{"key":"A","text":"Any number of times up to 31 December of the assessment year (or before assessment completion), to correct omissions or wrong statements"},{"key":"B","text":"Only once - a return can be revised just a single time, within 30 days of the original filing, and only with the prior permission of the Assessing Officer recorded in writing for that year"},{"key":"C","text":"Within 30 days of the original filing only, whatever the number of revisions needed to correct the omissions or wrong statements in the return for that year"},{"key":"D","text":"Only with the prior permission of the Assessing Officer, whatever the number of revisions needed to correct the omissions or wrong statements in the return for that year"}],"answer":"A","explanation":"Revised returns replace the original entirely and can be filed repeatedly before the time limit expires.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A REVISED return under Section 139(5) can be filed:","options":["Any number of times up to 31 December of the assessment year (or before assessment completion), to correct omissions or wrong statements","Only once","Within 30 days of filing","Only with permission"],"answer":0,"explanation":"Revised returns replace the original entirely and can be filed repeatedly before the time limit expires.","revision":"original","contentSignature":"efe61a70d6e9f79f7048efa871f0c47dbb5ba38bbbfd6eba57b35677901e0469"}]},{"id":360,"stem":"An UPDATED return under Section 139(8A) can be filed within ________ from the end of the relevant assessment year:","options":[{"key":"A","text":"24 months from the end of the relevant assessment year, with additional tax of 25%/50%/60%/70%"},{"key":"B","text":"60 months from the end of the relevant assessment year, with additional tax of 25%/50%/60%/70%"},{"key":"C","text":"12 months from the end of the relevant assessment year, with additional tax of 25%/50%/60%/70%"},{"key":"D","text":"48 MONTHS (Finance Act 2025 raised it from 24 months, effective 1-4-2025), with ADDITIONAL TAX of 25%/50%/60%/70%"}],"answer":"D","explanation":"Updated returns extend to 48 months from the end of the AY; additional tax is 25% (year 1), 50% (year 2), 60% (year 3) and 70% (year 4) of tax-plus-interest.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"An UPDATED return under Section 139(8A) can be filed within ________ from the end of the relevant assessment year:","options":["24 months","60 months","12 months","48 MONTHS (Finance Act 2025 raised it from 24 months, effective 1-4-2025), with ADDITIONAL TAX of 25%/50%/60%/70%"],"answer":3,"explanation":"Updated returns extend to 48 months from the end of the AY; additional tax is 25% (year 1), 50% (year 2), 60% (year 3) and 70% (year 4) of tax-plus-interest.","revision":"original","contentSignature":"a24c5e53b91feadc67df95f0f0769c9c8a8ceeb7d576b0405c860551130a10f8"}]},{"id":361,"stem":"An updated return under 139(8A) CANNOT be filed:","options":[{"key":"A","text":"If it is filed without a digital signature - and it is freely permitted even where it reduces the tax liability, claims or increases a refund, or results in a loss, and even where an assessment or reassessment is pending or completed for that year"},{"key":"B","text":"If it is filed by a company - and it is freely permitted even where it reduces the tax liability, claims or increases a refund, or results in a loss, and even where an assessment or reassessment is pending or completed for that year"},{"key":"C","text":"If it is filed after 31 December of the assessment year - and it is freely permitted even where it reduces the tax liability, claims or increases a refund, or results in a loss, and even where an assessment or reassessment is pending or completed for that year"},{"key":"D","text":"If it REDUCES tax liability, claims or increases a REFUND, or results in a loss - nor where assessment/reassessment is pending or completed for that year"}],"answer":"D","explanation":"The updated return is only for paying MORE tax - not for reducing liability, claiming refunds or reporting losses.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"An updated return under 139(8A) CANNOT be filed:","options":["Without digital signature","By companies","After 31 December of the AY","If it REDUCES tax liability, claims or increases a REFUND, or results in a loss - nor where assessment/reassessment is pending or completed for that year"],"answer":3,"explanation":"The updated return is only for paying MORE tax - not for reducing liability, claiming refunds or reporting losses.","revision":"original","contentSignature":"c1e38809ac92ed681af9b587a83afb7c42368c030e3b19f72ab98f90311a20b3"}]},{"id":362,"stem":"Late fee under Section 234F for a belated return is:","options":[{"key":"A","text":"Rs.5,000 - REDUCED to Rs.1,000 where total income does not exceed Rs.5 lakh; NIL if return filed on time"},{"key":"B","text":"Rs.10,000 flat, irrespective of the total income"},{"key":"C","text":"Rs.500 per day of delay, capped at the tax payable, whatever the total income of the year"},{"key":"D","text":"Rs.1,000 flat, irrespective of the total income"}],"answer":"A","explanation":"234F: Rs.5,000 late fee (Rs.1,000 for incomes up to Rs.5 lakh), payable for returns filed after the 139(1) due date.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Late fee under Section 234F for a belated return is:","options":["Rs.5,000 - REDUCED to Rs.1,000 where total income does not exceed Rs.5 lakh; NIL if return filed on time","Rs.10,000 flat","Rs.500 per day","Rs.1,000 always"],"answer":0,"explanation":"234F: Rs.5,000 late fee (Rs.1,000 for incomes up to Rs.5 lakh), payable for returns filed after the 139(1) due date.","revision":"original","contentSignature":"5ddb2848a9eec38095d05653d5e76454ec83d59448346cde8b03864d41b90cd4"}]},{"id":363,"stem":"A person whose total income exceeds the basic exemption must file a return; in addition, filing is COMPULSORY (seventh proviso to 139(1)) for those who:","options":[{"key":"A","text":"Own a motor car of any value in the year - the deposit, foreign-travel and electricity-bill thresholds are wholly beside the point under the seventh proviso to Section 139(1), and none of those tests applies at all"},{"key":"B","text":"Own a residential house of any value in the year - the deposit, foreign-travel and electricity-bill thresholds are wholly beside the point under the seventh proviso to Section 139(1), and none of those tests applies at all"},{"key":"C","text":"Hold a PAN allotted under the Act - the deposit, foreign-travel and electricity-bill thresholds are wholly beside the point under the seventh proviso to Section 139(1), and none of those tests applies at all"},{"key":"D","text":"Have deposited Rs.1 CRORE or more in current accounts, spent over Rs.2 LAKH on foreign travel, or paid electricity bills over Rs.1 LAKH in the year"}],"answer":"D","explanation":"Specified high-value transactions trigger mandatory filing even below the exemption limit; also applies to professionals/businesses crossing specified turnover/receipt thresholds.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A person whose total income exceeds the basic exemption must file a return; in addition, filing is COMPULSORY (seventh proviso to 139(1)) for those who:","options":["Own a car","Own a house","Have a PAN","Have deposited Rs.1 CRORE or more in current accounts, spent over Rs.2 LAKH on foreign travel, or paid electricity bills over Rs.1 LAKH in the year"],"answer":3,"explanation":"Specified high-value transactions trigger mandatory filing even below the exemption limit; also applies to professionals/businesses crossing specified turnover/receipt thresholds.","revision":"original","contentSignature":"82334b94cc5c158e71416e912aab6123e27c39ad66a4916426ff7fd6540319e9"}]},{"id":364,"stem":"Every return must be VERIFIED. A company return must be signed by:","options":[{"key":"A","text":"The MANAGING DIRECTOR - or any director where there is no MD (or by a designated person in specified cases)"},{"key":"B","text":"Any employee of the company, whatever his designation and whether or not he holds any directorship"},{"key":"C","text":"The chartered accountant who audits the company's accounts, as the person best acquainted with its financial affairs"},{"key":"D","text":"The statutory auditor of the company"}],"answer":"A","explanation":"Section 140: individual - himself; HUF - karta; company - MD/director; firm - managing partner; and e-verification applies to e-returns.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Every return must be VERIFIED. A company return must be signed by:","options":["The MANAGING DIRECTOR - or any director where there is no MD (or by a designated person in specified cases)","Any employee","The CA","The auditor"],"answer":0,"explanation":"Section 140: individual - himself; HUF - karta; company - MD/director; firm - managing partner; and e-verification applies to e-returns.","revision":"original","contentSignature":"992752042954e79148737d6bab8a4c5e550773180f56c8d01f66a9a4db703b74"}]},{"id":365,"stem":"A return showing a LOSS (other than house-property loss) filed AFTER the due date:","options":[{"key":"A","text":"Is valid but the ASSESSEE LOSES THE RIGHT TO CARRY FORWARD the loss (Section 80)"},{"key":"B","text":"Is invalid altogether - the return is treated as never filed at all, whatever the section under which the loss arises"},{"key":"C","text":"Attracts prosecution for the assessee"},{"key":"D","text":"Is fully valid for all purposes, including carry forward of the loss"}],"answer":"A","explanation":"Section 80: carry forward of business/capital/speculation losses requires a return filed within the 139(1) due date; house-property loss (71B) survives belated filing.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A return showing a LOSS (other than house-property loss) filed AFTER the due date:","options":["Is valid but the ASSESSEE LOSES THE RIGHT TO CARRY FORWARD the loss (Section 80)","Is invalid","Attracts prosecution","Is fully valid for all purposes"],"answer":0,"explanation":"Section 80: carry forward of business/capital/speculation losses requires a return filed within the 139(1) due date; house-property loss (71B) survives belated filing.","revision":"original","contentSignature":"68d7f8723ab49c88673acba32b8450736fdb5190d8240f6ec3ed4c750fafa4e3"}]},{"id":366,"stem":"Defective return notice under Section 139(9) gives the assessee ________ to remove the defect:","options":[{"key":"A","text":"15 days (extendable by the Assessing Officer)"},{"key":"B","text":"30 days (not extendable by any authority)"},{"key":"C","text":"7 days (extendable by the Assessing Officer)"},{"key":"D","text":"60 days (not extendable by any authority)"}],"answer":"A","explanation":"Failure to cure the defect within 15 days (or extended time) renders the return invalid - treated as if no return was filed.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Defective return notice under Section 139(9) gives the assessee ________ to remove the defect:","options":["15 days (extendable by the Assessing Officer)","30 days","7 days","60 days"],"answer":0,"explanation":"Failure to cure the defect within 15 days (or extended time) renders the return invalid - treated as if no return was filed.","revision":"original","contentSignature":"168d02b938b3a6b0ec8156dd293a99f671d1507d6502e829a8e8e2ed9b879cd4"}]},{"id":367,"stem":"Summary processing of returns under Section 143(1) involves:","options":[{"key":"A","text":"An automatic refund without any checks of any kind - no arithmetical verification, no examination of incorrect claims apparent from the return, and no disallowance of any description, with the intimation sent whenever the system happens to process the return, without any time limit at all"},{"key":"B","text":"A detailed scrutiny of every return with a full hearing"},{"key":"C","text":"Centralised adjustments for arithmetical errors, incorrect claims apparent from the return, and disallowances - with intimation sent within 9 MONTHS of the end of the FY in which the return is filed"},{"key":"D","text":"A physical hearing of the assessee in every single case"}],"answer":"C","explanation":"143(1) is the CPC Bangalore automated processing; adjustments need prior intimation and the assessee gets 30 days to respond.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Summary processing of returns under Section 143(1) involves:","options":["Refund without checks","Detailed scrutiny","Centralised adjustments for arithmetical errors, incorrect claims apparent from the return, and disallowances - with intimation sent within 9 MONTHS of the end of the FY in which the return is filed","Physical hearing"],"answer":2,"explanation":"143(1) is the CPC Bangalore automated processing; adjustments need prior intimation and the assessee gets 30 days to respond.","revision":"original","contentSignature":"1191f4d623fcdc70a9161b62a396179cead10df0fe48a1abdc1067650d10440c"}]},{"id":368,"stem":"A scrutiny notice under Section 143(2) must be served within ________ from the end of the financial year in which the return is furnished:","options":[{"key":"A","text":"6 months from the end of the financial year in which the return is furnished"},{"key":"B","text":"12 months from the end of the financial year in which the return is furnished"},{"key":"C","text":"18 months from the end of the financial year in which the return is furnished"},{"key":"D","text":"3 MONTHS (reduced from 6 months by the Finance Act 2021, applicable from AY 2021-22)"}],"answer":"D","explanation":"The 143(2) time bar of 3 months from the end of the FY of filing keeps scrutiny selection time-bound.","source":"Source label not detected","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A scrutiny notice under Section 143(2) must be served within ________ from the end of the financial year in which the return is furnished:","options":["6 months","12 months","18 months","3 MONTHS (reduced from 6 months by the Finance Act 2021, applicable from AY 2021-22)"],"answer":3,"explanation":"The 143(2) time bar of 3 months from the end of the FY of filing keeps scrutiny selection time-bound.","revision":"original","contentSignature":"120f4bd2df6ca3376bc6a7ff26143439c90fc953b92b4586243b41db500ffd3e"}]},{"id":369,"stem":"Section 143(3) refers to:","options":[{"key":"A","text":"Best judgment assessment under Section 144, without any hearing"},{"key":"B","text":"Self assessment under Section 140A, without any hearing"},{"key":"C","text":"Summary assessment under Section 143(1), without any hearing"},{"key":"D","text":"A REGULAR/scrutiny assessment after hearing the assessee on evidence"}],"answer":"D","explanation":"143(3) is the full scrutiny assessment order passed after examination of accounts and evidence.","source":"Source label not detected","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Section 143(3) refers to:","options":["Best judgment assessment","Self assessment","Summary assessment","A REGULAR/scrutiny assessment after hearing the assessee on evidence"],"answer":3,"explanation":"143(3) is the full scrutiny assessment order passed after examination of accounts and evidence.","revision":"original","contentSignature":"c4566b6602f60e6e626fa269361dc51baeae42b9f68364256f4f3c0efbdba85c"}]},{"id":370,"stem":"Section 144 (best judgment assessment) is made when the assessee:","options":[{"key":"A","text":"Pays his advance tax on the due dates, files his return in time, complies with every notice issued under Section 142(1) and Section 143(2), and gets the special audit done wherever directed by the Assessing Officer"},{"key":"B","text":"Fails to file a return, fails to comply with notices under 142(1)/143(2), or fails to get special audit done"},{"key":"C","text":"Claims a refund in his return, files it in time, complies with every notice issued under Section 142(1) and Section 143(2), and gets the special audit done wherever directed by the Assessing Officer"},{"key":"D","text":"Files his return on time, complies with every notice issued under Section 142(1) and Section 143(2), and gets the special audit done wherever directed by the Assessing Officer"}],"answer":"B","explanation":"Best-judgment assessments proceed ex parte on available material after the assessee defaults on statutory obligations.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Section 144 (best judgment assessment) is made when the assessee:","options":["Pays advance tax","Fails to file a return, fails to comply with notices under 142(1)/143(2), or fails to get special audit done","Claims refund","Files a return on time"],"answer":1,"explanation":"Best-judgment assessments proceed ex parte on available material after the assessee defaults on statutory obligations.","revision":"original","contentSignature":"b89624ceabdc4543dcb46feef6e942f657f53f6c79dca0148a460426d9d4679f"}]},{"id":371,"stem":"Income ESCAPING assessment is reassessed under Section:","options":[{"key":"A","text":"147 - with notices under 148 (and 148A show-cause before notice)"},{"key":"B","text":"Section 144 - with notices under 148 (and 148A show-cause before notice)"},{"key":"C","text":"Section 139(9) - with notices under 148 (and 148A show-cause before notice)"},{"key":"D","text":"Section 143(3) - with notices under 148 (and 148A show-cause before notice)"}],"answer":"A","explanation":"The reassessment regime: s.147 power, s.148 notice, s.148A pre-notice show-cause procedure, s.149 time limits.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Income ESCAPING assessment is reassessed under Section:","options":["147 - with notices under 148 (and 148A show-cause before notice)","144","139(9)","143(3)"],"answer":0,"explanation":"The reassessment regime: s.147 power, s.148 notice, s.148A pre-notice show-cause procedure, s.149 time limits.","revision":"original","contentSignature":"ada8e0f63628f590420747b699ba093ac40f00d5cae1d99ece2518ce2c01a806"}]},{"id":372,"stem":"Under Section 149, reassessment notice can generally be issued within ________ from the end of the relevant assessment year; up to ________ where escaped income is Rs.50 lakh or more:","options":[{"key":"A","text":"1 year 3 months; 3 years 3 months, respectively"},{"key":"B","text":"3 years 3 months; 5 years 3 months"},{"key":"C","text":"4 years 3 months; 6 years 3 months, respectively"},{"key":"D","text":"2 years 3 months; 4 years 3 months, respectively"}],"answer":"B","explanation":"Current regime (Finance (No.2) Act 2024, w.e.f. 1-9-2024): notice under s.148 within 3 years 3 months from the end of the AY; beyond that, up to 5 years 3 months only where escaped income is Rs.50 lakh or more.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Under Section 149, reassessment notice can generally be issued within ________ from the end of the relevant assessment year; up to ________ where escaped income is Rs.50 lakh or more:","options":["1 year; 3 years","3 years 3 months; 5 years 3 months","4 years; 6 years","2 years; 4 years"],"answer":1,"explanation":"Current regime (Finance (No.2) Act 2024, w.e.f. 1-9-2024): notice under s.148 within 3 years 3 months from the end of the AY; beyond that, up to 5 years 3 months only where escaped income is Rs.50 lakh or more.","revision":"original","contentSignature":"72c4bd895927c302b63c8abb258e74b2772132160f77d44fe0cddf0a48e783ac"}]},{"id":373,"stem":"Self-assessment tax under Section 140A is payable:","options":[{"key":"A","text":"Only on a notice of demand under Section 156, after the assessment is completed - and never at the time of filing the return itself, whatever the tax due on the returned income"},{"key":"B","text":"Within one year from the end of the assessment year, whenever the assessee chooses - and never at the time of filing the return itself, whatever the tax due on the returned income"},{"key":"C","text":"BEFORE filing the return - for the tax due on the returned income after TDS, advance tax and reliefs"},{"key":"D","text":"Only after the assessment is completed under Section 143(3) - and never at the time of filing the return itself, whatever the tax due on the returned income"}],"answer":"C","explanation":"140A tax (with interest under 234A/234B/234C) must be paid before the return is filed; the return is defective otherwise.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Self-assessment tax under Section 140A is payable:","options":["Only on demand","Within one year","BEFORE filing the return - for the tax due on the returned income after TDS, advance tax and reliefs","After assessment"],"answer":2,"explanation":"140A tax (with interest under 234A/234B/234C) must be paid before the return is filed; the return is defective otherwise.","revision":"original","contentSignature":"23a520476ac56e488835cc09a9dfd701b3b413bc7ba6578e38ca99fab9e6d1e1"}]},{"id":374,"stem":"Interest under Section 234A (late filing of return) is charged at:","options":[{"key":"A","text":"1% per month or part of a month on the tax due"},{"key":"B","text":"12% per annum flat, computed on a yearly basis only"},{"key":"C","text":"2% per month or part of a month on the tax due"},{"key":"D","text":"0.5% per month or part of a month on the tax due"}],"answer":"A","explanation":"All three deferment interests - 234A (late filing), 234B (short advance tax), 234C (instalment deferment) - run at 1% per month or part.","source":"Source label not detected","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Interest under Section 234A (late filing of return) is charged at:","options":["1% per month or part of a month on the tax due","12% per annum flat","2% per month","0.5% per month"],"answer":0,"explanation":"All three deferment interests - 234A (late filing), 234B (short advance tax), 234C (instalment deferment) - run at 1% per month or part.","revision":"original","contentSignature":"28a571f52fae6780b8cf6574b3ac4013d5044054d97da50038248d14eff2dae8"}]},{"id":375,"stem":"Section 234B interest applies when advance tax paid is less than ________ of the assessed tax:","options":[{"key":"A","text":"90%"},{"key":"B","text":"50%"},{"key":"C","text":"100%"},{"key":"D","text":"75%"}],"answer":"A","explanation":"234B: 1% per month from 1 April of the AY until payment, where advance tax falls short of 90% of assessed tax.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified"},{"id":376,"stem":"Section 234C charges interest for:","options":[{"key":"A","text":"DEFERMENT of advance-tax instalments (shortfall below 15%/45%/75%/100% schedule) - 1% per month for 3 months (1 month for the last instalment)"},{"key":"B","text":"Quoting a wrong PAN in the return - 1% per month for 3 months on the tax due, exactly as the instalment schedule operates for the covered default under the section"},{"key":"C","text":"Late filing of the return - 1% per month for 3 months on the tax due, exactly as the instalment schedule operates for the covered default under the section"},{"key":"D","text":"Non-deduction of TDS by the assessee - 1% per month for 3 months on the tax due, exactly as the instalment schedule operates for the covered default under the section"}],"answer":"A","explanation":"234C targets instalment-level shortfalls, with relief where shortfalls arise from capital gains, winnings, or new business income paid in later instalments.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Section 234C charges interest for:","options":["DEFERMENT of advance-tax instalments (shortfall below 15%/45%/75%/100% schedule) - 1% per month for 3 months (1 month for the last instalment)","Wrong PAN","Late filing","Non-deduction of TDS"],"answer":0,"explanation":"234C targets instalment-level shortfalls, with relief where shortfalls arise from capital gains, winnings, or new business income paid in later instalments.","revision":"original","contentSignature":"b67fd7241a735b3807d2b7be6d17cce30df6d0b4db2d600e0dc640133e6dd459"}]},{"id":377,"stem":"Fee under Section 234F is distinct from interest under 234A: 234F applies even when:","options":[{"key":"A","text":"Income is below exemption and no return is due"},{"key":"B","text":"Refund is due"},{"key":"C","text":"TDS is deducted"},{"key":"D","text":"Tax is fully paid but the RETURN IS FILED LATE"}],"answer":"D","explanation":"234F is a filing-delay fee independent of tax payment; 234A is interest on unpaid tax.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified"},{"id":378,"stem":"Section 245 permits:","options":[{"key":"A","text":"REASSESSMENT of escaped income, after intimation to the assessee concerned"},{"key":"B","text":"WAIVER of penalties, after intimation to the assessee concerned"},{"key":"C","text":"SET-OFF of REFUNDS against tax remaining payable, after intimation to the assessee"},{"key":"D","text":"The FILING of appeals, after intimation to the assessee concerned"}],"answer":"C","explanation":"245 requires prior intimation before adjusting a refund against outstanding demands.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Section 245 permits:","options":["Reassessment","Penalty waiver","SET-OFF of REFUNDS against tax remaining payable, after intimation to the assessee","Appeal filing"],"answer":2,"explanation":"245 requires prior intimation before adjusting a refund against outstanding demands.","revision":"original","contentSignature":"58ca98d82f3e210d19624e0eeb124c2ab2fa555bcc9c3a90d4f319b0a802711a"}]},{"id":379,"stem":"Interest on REFUNDS under Section 244A is paid at:","options":[{"key":"A","text":"1.5% per month (18% per annum) - for the period of delay attributable to the department"},{"key":"B","text":"0.5% PER MONTH (6% per annum) - for the period of delay attributable to the department"},{"key":"C","text":"1% per month (12% per annum) - for the period of delay attributable to the department"},{"key":"D","text":"12% per annum flat - for the period of delay attributable to the department"}],"answer":"B","explanation":"244A: 0.5% per month on refunds; no interest for delay caused by the assessee. Refund below Rs.100 is not paid.","source":"Source label not detected","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Interest on REFUNDS under Section 244A is paid at:","options":["1.5% per month","0.5% PER MONTH (6% per annum) - for the period of delay attributable to the department","1% per month","12% per annum"],"answer":1,"explanation":"244A: 0.5% per month on refunds; no interest for delay caused by the assessee. Refund below Rs.100 is not paid.","revision":"original","contentSignature":"385e97ce6b4a5dfc627c7dbfd8d19d967ab449f2991b0627e8235a43f8f479e0"}]},{"id":380,"stem":"No refund is granted under Section 237 if the amount is less than:","options":[{"key":"A","text":"Rs.10"},{"key":"B","text":"Rs.1,000"},{"key":"C","text":"Rs.100"},{"key":"D","text":"Rs.500"}],"answer":"C","explanation":"Section 237 read with the rules: refunds below Rs.100 are not issued.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified"},{"id":381,"stem":"Section 156 requires that tax, interest, penalty or other sums demanded be served through:","options":[{"key":"A","text":"An intimation under Section 143(1) alone, without any notice of demand - payable within 30 days of its receipt"},{"key":"B","text":"A phone call from the Assessing Officer, payable within 30 days of the call"},{"key":"C","text":"A NOTICE OF DEMAND in the prescribed form - payable within 30 days of service"},{"key":"D","text":"An email alone, in any form, payable within 30 days of its receipt"}],"answer":"C","explanation":"The 156 demand notice is the trigger for collection; default within 30 days makes the assessee an assessee in default (s.220).","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Section 156 requires that tax, interest, penalty or other sums demanded be served through:","options":["An intimation under 143(1)","A phone call","A NOTICE OF DEMAND in the prescribed form - payable within 30 days of service","An email only"],"answer":2,"explanation":"The 156 demand notice is the trigger for collection; default within 30 days makes the assessee an assessee in default (s.220).","revision":"original","contentSignature":"133557d6f69ad4e677474e0f16bc0207975aab332bf772f0c4dbd3cec41b3f48"}]},{"id":382,"stem":"The first appeal against an assessment order lies to:","options":[{"key":"A","text":"The JOINT COMMISSIONER (APPEALS) or COMMISSIONER (APPEALS) under Section 246A - filed in Form 35 within 30 days"},{"key":"B","text":"The Income-tax Appellate Tribunal directly - the appeal is filed in Form 35 within 30 days of the order"},{"key":"C","text":"The Supreme Court of India directly - the appeal is filed in Form 35 within 30 days of the order"},{"key":"D","text":"The jurisdictional High Court directly - the appeal is filed in Form 35 within 30 days of the order"}],"answer":"A","explanation":"Appeal ladder: JCIT(A)/CIT(A) → ITAT (s.253) → High Court on substantial questions of law (s.260A) → Supreme Court (s.261).","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The first appeal against an assessment order lies to:","options":["The JOINT COMMISSIONER (APPEALS) or COMMISSIONER (APPEALS) under Section 246A - filed in Form 35 within 30 days","ITAT","Supreme Court","High Court"],"answer":0,"explanation":"Appeal ladder: JCIT(A)/CIT(A) → ITAT (s.253) → High Court on substantial questions of law (s.260A) → Supreme Court (s.261).","revision":"original","contentSignature":"ece6bc7a04c2fbbf15fcf6d628cb38eb54ef0587eb2976b9f5be38a864f0f023"}]},{"id":383,"stem":"The second appeal (against the CIT(A)/JCIT(A) order) lies to the ITAT within ________ of receipt of the order:","options":[{"key":"A","text":"90 days"},{"key":"B","text":"120 days"},{"key":"C","text":"60 days"},{"key":"D","text":"30 days"}],"answer":"C","explanation":"Section 253: ITAT appeal within 60 days; the ITAT is the final fact-finding authority. Fee: Rs.500 to Rs.10,000 by assessed income.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified"},{"id":384,"stem":"An appeal to the HIGH COURT under Section 260A lies only on:","options":[{"key":"A","text":"Penalty orders only - and only within 120 days of the order"},{"key":"B","text":"A SUBSTANTIAL QUESTION OF LAW, within 120 days of the ITAT order"},{"key":"C","text":"Any grievance at all, of fact or of law, within 120 days"},{"key":"D","text":"Substantial questions of FACT, within 120 days of the order"}],"answer":"B","explanation":"High Court and Supreme Court jurisdiction under the Act is confined to questions of law; ITAT is final on facts.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"An appeal to the HIGH COURT under Section 260A lies only on:","options":["Penalty orders only","A SUBSTANTIAL QUESTION OF LAW, within 120 days of the ITAT order","Any grievance","Questions of fact"],"answer":1,"explanation":"High Court and Supreme Court jurisdiction under the Act is confined to questions of law; ITAT is final on facts.","revision":"original","contentSignature":"d1549b5f1d5a0484507bfd065e3b044863b2023586a0de167244ba74c85ea5c1"}]},{"id":385,"stem":"Section 264 gives the assessee a remedy of:","options":[{"key":"A","text":"An APPEAL to the Income-tax Appellate Tribunal as of right - with the appellate order required to be passed within 1 year from the end of the financial year in which the order appealed against was passed"},{"key":"B","text":"RECTIFICATION of mistakes apparent from the record by the assessing authority itself - with the rectification order required to be passed within 1 year from the end of the financial year in which the order sought to be rectified was passed"},{"key":"C","text":"A REFUND claim made directly to the refund wing - with the refund required to be issued within 1 year from the end of the financial year in which the claim was made"},{"key":"D","text":"REVISION by the Principal Commissioner/Commissioner in favour of the assessee (s.264) - the revisional order must be passed within 1 year from the end of the FY of the order revised"}],"answer":"D","explanation":"264 revision is an alternative (not cumulative) remedy; the Commissioner may make any inquiry and pass any order in the assessee's favour.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Section 264 gives the assessee a remedy of:","options":["Appeal to ITAT","Rectification","Refund claim","REVISION by the Principal Commissioner/Commissioner in favour of the assessee (s.264) - the revisional order must be passed within 1 year from the end of the FY of the order revised"],"answer":3,"explanation":"264 revision is an alternative (not cumulative) remedy; the Commissioner may make any inquiry and pass any order in the assessee's favour.","revision":"original","contentSignature":"df638c49471d8fa7c107cb9dc5dcbdf3f0e145a9b1e42d0aaf751225c703663a"}]},{"id":386,"stem":"RECTIFICATION of mistakes apparent from the record is done under Section:","options":[{"key":"A","text":"Section 147 - by the authority concerned, within 4 years from the end of the financial year in which the order was passed"},{"key":"B","text":"Section 263 - by the authority concerned, within 4 years from the end of the financial year in which the order was passed"},{"key":"C","text":"Section 143(1) - by the authority concerned, within 4 years from the end of the financial year in which the order was passed"},{"key":"D","text":"154 - by the authority concerned, within 4 years from the end of the financial year in which the order was passed"}],"answer":"D","explanation":"154 rectification covers only mistakes apparent from the record; debatable issues need appeal, not rectification.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"RECTIFICATION of mistakes apparent from the record is done under Section:","options":["147","263","143(1)","154 - by the authority concerned, within 4 years from the end of the financial year in which the order was passed"],"answer":3,"explanation":"154 rectification covers only mistakes apparent from the record; debatable issues need appeal, not rectification.","revision":"original","contentSignature":"881c7db1dffc355a31e8384e8185dabcd5b38968587425fdb2f15f2d30a34a8d"}]},{"id":387,"stem":"Section 263 empowers the Principal Commissioner/Commissioner to REVISE an order that is:","options":[{"key":"A","text":"ERRONEOUS AND PREJUDICIAL TO THE INTERESTS OF THE REVENUE, within 2 years from the end of the FY of the order"},{"key":"B","text":"ERRONEOUS AND PREJUDICIAL TO THE INTERESTS OF THE ASSESSEE, within 2 years from the end of the FY of the order"},{"key":"C","text":"Passed by the ITAT itself, within 2 years from the end of the FY of the order"},{"key":"D","text":"Time-barred under the Act, within 2 years from the end of the FY of the order"}],"answer":"A","explanation":"263 revision requires BOTH error and prejudice to revenue; a mere difference of opinion is not enough.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Section 263 empowers the Principal Commissioner/Commissioner to REVISE an order that is:","options":["ERRONEOUS AND PREJUDICIAL TO THE INTERESTS OF THE REVENUE, within 2 years from the end of the FY of the order","Prejudicial to the assessee","Passed by ITAT","Time-barred"],"answer":0,"explanation":"263 revision requires BOTH error and prejudice to revenue; a mere difference of opinion is not enough.","revision":"original","contentSignature":"f41973a866db5370b911418346c9503681778d4dfab74c34df88bbb54af9b303"}]},{"id":388,"stem":"Penalty under Section 270A for UNDER-REPORTING of income is ________; for MISREPORTING it is ________:","options":[{"key":"A","text":"10% of tax; 50% of tax, respectively"},{"key":"B","text":"100% of tax; 300% of tax, respectively"},{"key":"C","text":"200% of tax; 50% of tax, respectively"},{"key":"D","text":"50% of tax; 200% of tax"}],"answer":"D","explanation":"270A (from AY 2017-18) replaced the old 271(1)(c): 50% of tax on under-reported income, 200% where the under-reporting is by misreporting.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Penalty under Section 270A for UNDER-REPORTING of income is ________; for MISREPORTING it is ________:","options":["10%; 50%","100%; 300%","200%; 50%","50% of tax; 200% of tax"],"answer":3,"explanation":"270A (from AY 2017-18) replaced the old 271(1)(c): 50% of tax on under-reported income, 200% where the under-reporting is by misreporting.","revision":"original","contentSignature":"4ebdaada0e5f854ff99914bd1cf4ca1bb11a02364f0b56ceee104bb31dec4004"}]},{"id":389,"stem":"Penalty for failure to get ACCOUNTS AUDITED under Section 44AB (Section 271B) is:","options":[{"key":"A","text":"A flat Rs.10,000, whatever the turnover of the business"},{"key":"B","text":"Rs.5,000 per day of default, without any cap at all"},{"key":"C","text":"0.5% of turnover/gross receipts, capped at Rs.1,50,000"},{"key":"D","text":"A flat Rs.1 lakh, whatever the turnover of the business"}],"answer":"C","explanation":"271B: half a per cent of total sales/turnover/gross receipts, maximum Rs.1,50,000.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Penalty for failure to get ACCOUNTS AUDITED under Section 44AB (Section 271B) is:","options":["Rs.10,000","Rs.5,000 per day","0.5% of turnover/gross receipts, capped at Rs.1,50,000","Rs.1 lakh flat"],"answer":2,"explanation":"271B: half a per cent of total sales/turnover/gross receipts, maximum Rs.1,50,000.","revision":"original","contentSignature":"a2da12ccda3ad432b94f24a42def1d949e6ce112266780d377c1df1cfa215ef8"}]},{"id":390,"stem":"Penalty under Section 271AAC applies to income determined under Sections 68-69D (cash credits, unexplained investments etc.):","options":[{"key":"A","text":"Tax at 30% (normal rates) PLUS 10% of the TAX payable (i.e. 3% of income) as penalty"},{"key":"B","text":"Tax at 60% (115BBE) with no penalty of any kind at all"},{"key":"C","text":"Tax at 60% (115BBE) PLUS 10% of the TAX payable (i.e. 6% of income) as penalty"},{"key":"D","text":"Tax at 30% (normal rates) PLUS 10% of the INCOME itself as penalty"}],"answer":"C","explanation":"Unexplained income under ss.68-69D is taxed at 60% (plus surcharge/cess) under 115BBE with a 10%-of-tax penalty under 271AAC; no basic exemption or set-off.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Penalty under Section 271AAC applies to income determined under Sections 68-69D (cash credits, unexplained investments etc.):","options":["10% of tax","Nil","Tax at 60% (115BBE) PLUS 10% of the TAX payable (i.e. 6% of income) as penalty","30%"],"answer":2,"explanation":"Unexplained income under ss.68-69D is taxed at 60% (plus surcharge/cess) under 115BBE with a 10%-of-tax penalty under 271AAC; no basic exemption or set-off.","revision":"original","contentSignature":"acc5e621960ecb61f383254b8d5e19d4c058824656c81364c2f212185d8ef5e1"}]},{"id":391,"stem":"The time limit for completing a scrutiny assessment under Section 153 for AY 2022-23 onwards is:","options":[{"key":"A","text":"21 months from the end of the assessment year in which the income was first assessable"},{"key":"B","text":"9 months from the end of the assessment year in which the income was first assessable"},{"key":"C","text":"12 months from the end of the ASSESSMENT YEAR in which the income was first assessable"},{"key":"D","text":"18 months from the end of the assessment year in which the income was first assessable"}],"answer":"C","explanation":"Section 153: regular assessment within 12 months of the end of the relevant AY (was 18/21 months in earlier years).","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The time limit for completing a scrutiny assessment under Section 153 for AY 2022-23 onwards is:","options":["21 months","9 months","12 months from the end of the ASSESSMENT YEAR in which the income was first assessable","18 months"],"answer":2,"explanation":"Section 153: regular assessment within 12 months of the end of the relevant AY (was 18/21 months in earlier years).","revision":"original","contentSignature":"e1485be512d3c1c3198e08c0d16c6ff399110bac09ffac3ac582f2d4c3ded2d5"}]},{"id":392,"stem":"The Income-tax Act, 2025 (replacing the Income-tax Act, 1961) received Presidential assent on:","options":[{"key":"A","text":"15 AUGUST 2025 - as Act No. 30 of 2025"},{"key":"B","text":"21 AUGUST 2025 - as Act No. 30 of 2025"},{"key":"C","text":"1 APRIL 2025 - as Act No. 30 of 2025"},{"key":"D","text":"31 MARCH 2025 - as Act No. 30 of 2025"}],"answer":"B","explanation":"The Income-tax Act 2025 was passed by Parliament in August 2025 and assented on 21-8-2025; it is a simplification rewrite, not a change in tax policy.","source":"Original","module":"T11","topic":"Income-tax Act, 2025 - Awareness Block","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The Income-tax Act, 2025 (replacing the Income-tax Act, 1961) received Presidential assent on:","options":["15 August 2025","21 AUGUST 2025 - as Act No. 30 of 2025","1 April 2025","31 March 2025"],"answer":1,"explanation":"The Income-tax Act 2025 was passed by Parliament in August 2025 and assented on 21-8-2025; it is a simplification rewrite, not a change in tax policy.","revision":"original","contentSignature":"1cb477b4218cf2e1cad3c99d4c6aeb3bad6ae79ba72cd4e14af2e93a18c043dc"}]},{"id":393,"stem":"The Income-tax Act, 2025 comes into force from:","options":[{"key":"A","text":"Immediately on assent"},{"key":"B","text":"1 August 2025"},{"key":"C","text":"1 APRIL 2026"},{"key":"D","text":"1 January 2026"}],"answer":"C","explanation":"The new Act applies from 1-4-2026 (i.e. to \"tax year\" 2026-27 onwards); AY 2026-27 still runs under the 1961 Act.","source":"Original","module":"T11","topic":"Income-tax Act, 2025 - Awareness Block","reviewStatus":"Source key not independently verified"},{"id":394,"stem":"The Income-tax Act, 2025 contains approximately:","options":[{"key":"A","text":"About 64 SECTIONS and 2 schedules - roughly one-tenth the size of the 1961 Act, though with denser language than before"},{"key":"B","text":"About 1000 SECTIONS and 40 schedules - nearly twice the size of the 1961 Act, with even denser language than before"},{"key":"C","text":"About 298 SECTIONS and 8 schedules - roughly 40% of the size of the 1961 Act, though with denser language than before"},{"key":"D","text":"536 SECTIONS and 16 SCHEDULES - nearly half the size of the 1961 Act's 700+ sections, with far simpler language"}],"answer":"D","explanation":"The 2025 Act has 536 sections in 23 chapters plus 16 schedules - nearly half the length of the 1961 Act, with provisos and explanations folded into the text.","source":"Original","module":"T11","topic":"Income-tax Act, 2025 - Awareness Block","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The Income-tax Act, 2025 contains approximately:","options":["64 sections","1000 sections","298 sections","536 SECTIONS and 16 SCHEDULES - nearly half the size of the 1961 Act's 700+ sections, with far simpler language"],"answer":3,"explanation":"The 2025 Act has 536 sections in 23 chapters plus 16 schedules - nearly half the length of the 1961 Act, with provisos and explanations folded into the text.","revision":"original","contentSignature":"473e7af115e9b6eb55afdb3832cd83e9e3463ba560f78964e1fae42d935d88c4"}]},{"id":395,"stem":"Under the Income-tax Act, 2025, the terms \"previous year\" and \"assessment year\" are replaced by:","options":[{"key":"A","text":"A single concept: \"TAX YEAR\""},{"key":"B","text":"Assessment period"},{"key":"C","text":"Accounting period"},{"key":"D","text":"Financial year"}],"answer":"A","explanation":"The dual PY/AY structure collapses into one \"tax year\" (1 April to 31 March), removing a long-standing source of confusion.","source":"Original","module":"T11","topic":"Income-tax Act, 2025 - Awareness Block","reviewStatus":"Source key not independently verified"},{"id":396,"stem":"The Income-tax Act, 2025 is best described as:","options":[{"key":"A","text":"A new tax altogether, with higher rates, fresh slabs, redrawn exemptions and a wholly new structure replacing the 1961 Act - nothing in the rates, slabs, exemptions or overall structure of the 1961 Act as amended up to Finance Act 2025 survives in it"},{"key":"B","text":"A LANGUAGE-SIMPLIFICATION and consolidation exercise - rates, slabs, exemptions and structure remain the SAME as the 1961 Act as amended up to Finance Act 2025"},{"key":"C","text":"An amendment of the GST law, with no effect on direct taxes"},{"key":"D","text":"A revival of the wealth tax, abolished in 2016"}],"answer":"B","explanation":"The government stated no policy change is intended: the rewrite shortens sentences, removes obsolete provisions, and uses tables/formulas for clarity.","source":"Original","module":"T11","topic":"Income-tax Act, 2025 - Awareness Block","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The Income-tax Act, 2025 is best described as:","options":["A new tax with higher rates","A LANGUAGE-SIMPLIFICATION and consolidation exercise - rates, slabs, exemptions and structure remain the SAME as the 1961 Act as amended up to Finance Act 2025","A GST amendment","A wealth-tax revival"],"answer":1,"explanation":"The government stated no policy change is intended: the rewrite shortens sentences, removes obsolete provisions, and uses tables/formulas for clarity.","revision":"original","contentSignature":"82290ab045a899b52742f450e2bf3025effdc649e4119fed7e24adbcba80424c"}]},{"id":397,"stem":"For the JVVNL Junior Accountant exam (Part A), the Income-tax Act 2025 matters mainly because:","options":[{"key":"A","text":"It ABOLISHES TDS entirely - and the exam focuses on that change, to the exclusion of the Act number (30 of 2025), the assent date, the commencement on 1-4-2026, the \"tax year\" terminology, and the section renumbering, none of which is ever tested"},{"key":"B","text":"It REMOVES PAN from the system entirely - and the exam focuses on that change, to the exclusion of the Act number (30 of 2025), the assent date, the commencement on 1-4-2026, the \"tax year\" terminology, and the section renumbering"},{"key":"C","text":"Examiners may test AWARENESS items: Act number (30 of 2025), assent date, commencement 1-4-2026, \"tax year\" terminology, and section renumbering"},{"key":"D","text":"It CHANGES the slab rates themselves - and the exam focuses on that change, to the exclusion of the Act number (30 of 2025), the assent date, the commencement on 1-4-2026, the \"tax year\" terminology, and the section renumbering"}],"answer":"C","explanation":"Rates and rules are unchanged, so MCQs will focus on structural facts - terminology, section count, and commencement - rather than new computations.","source":"Original","module":"T11","topic":"Income-tax Act, 2025 - Awareness Block","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"For the JVVNL Junior Accountant exam (Part A), the Income-tax Act 2025 matters mainly because:","options":["It abolishes TDS","It removes PAN","Examiners may test AWARENESS items: Act number (30 of 2025), assent date, commencement 1-4-2026, \"tax year\" terminology, and section renumbering","It changes slab rates"],"answer":2,"explanation":"Rates and rules are unchanged, so MCQs will focus on structural facts - terminology, section count, and commencement - rather than new computations.","revision":"original","contentSignature":"25540dd8c0d8f44cd667a1ce3a02853483bc684bf106fbd755306a6d62899db3"}]},{"id":398,"stem":"Under the 2025 Act, the definition structure and obsolete provisions (like deductions no longer operative) are:","options":[{"key":"A","text":"Retained exactly as they stood - obsolete sections kept in force, definitions left scattered across the Act, and no tables used anywhere for rates or TDS provisions at all"},{"key":"B","text":"Left entirely to the rules to sort out, with the Act itself making no change of any kind to the definition structure or the obsolete provisions"},{"key":"C","text":"REMOVED or consolidated - obsolete sections repealed, scattered definitions unified, and tables used for rates/TDS provisions"},{"key":"D","text":"Converted into schedules only, with no repeal of obsolete sections, no unification of scattered definitions, and no tables used anywhere for rates or TDS provisions"}],"answer":"C","explanation":"Simplification features: removal of 300+ obsolete provisions, tables for TDS rates, formulas for computations, and virtual digital assets brought within \"undisclosed income\" search provisions.","source":"Original","module":"T11","topic":"Income-tax Act, 2025 - Awareness Block","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Under the 2025 Act, the definition structure and obsolete provisions (like deductions no longer operative) are:","options":["Retained as-is","Left to rules","REMOVED or consolidated - obsolete sections repealed, scattered definitions unified, and tables used for rates/TDS provisions","Converted to schedules only"],"answer":2,"explanation":"Simplification features: removal of 300+ obsolete provisions, tables for TDS rates, formulas for computations, and virtual digital assets brought within \"undisclosed income\" search provisions.","revision":"original","contentSignature":"184afa65fb055ba5acd9ff45fcaa6d704fba549a93308b40fe3f3d25b2503fac"}]},{"id":399,"stem":"Which is TRUE about the transition to the Income-tax Act, 2025?","options":[{"key":"A","text":"All assessments made under the 1961 Act become void the moment the 2025 Act commences - nothing of the old law continues for any period, no rules or notifications are ever issued under the new Act, and the two laws never coexist for any purpose"},{"key":"B","text":"1961 Act provisions CONTINUE for periods up to tax year 2025-26 (AY 2026-27); the 2025 Act governs from tax year 2026-27; rules/notifications follow"},{"key":"C","text":"The 1961 Act is repealed with retrospective effect from 1961 itself, voiding all past assessments"},{"key":"D","text":"Both Acts apply simultaneously to the same income forever"}],"answer":"B","explanation":"Transitional provisions preserve assessments, appeals and proceedings for earlier years under the 1961 Act; the 2025 Act applies prospectively from 1-4-2026.","source":"Original","module":"T11","topic":"Income-tax Act, 2025 - Awareness Block","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which is TRUE about the transition to the Income-tax Act, 2025?","options":["Old assessments become void","1961 Act provisions CONTINUE for periods up to tax year 2025-26 (AY 2026-27); the 2025 Act governs from tax year 2026-27; rules/notifications follow","1961 Act repealed with retrospective effect","Both apply simultaneously forever"],"answer":1,"explanation":"Transitional provisions preserve assessments, appeals and proceedings for earlier years under the 1961 Act; the 2025 Act applies prospectively from 1-4-2026.","revision":"original","contentSignature":"68837b0d6da6603334e7262a124441c3abd7af2a402128267faeddd23987f09e"}]},{"id":400,"stem":"The methods of depreciation prescribed by Section 32 of the Income-tax Act, 1961 are: (i) Units of production method (ii) Written down value method (iii) Sum of years digits method:","options":[{"key":"A","text":"(i), (ii) and (iii)"},{"key":"B","text":"Only (ii)"},{"key":"C","text":"Only (i) and (ii)"},{"key":"D","text":"Only (i)"}],"answer":"B","explanation":"Only the WDV method is prescribed generally; the straight-line option exists only for power-generating undertakings. Units-of-production and SYD are accounting methods, not tax methods.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":401,"stem":"Mr. X is entitled to transport allowance of Rs.1,800 p.m. for commuting between residence and office and spends Rs.1,400 p.m. The exemption allowed (current law) is:","options":[{"key":"A","text":"Rs.1,400 p.m. - the transport-allowance exemption continues at Rs.1,400 p.m. for every employee from AY 2019-20 (with no special rate of any kind for blind, deaf or orthopedically handicapped employees at any time)"},{"key":"B","text":"NIL - the transport-allowance exemption was withdrawn from AY 2019-20 (it survives only as Rs.3,200 p.m. for blind/deaf/orthopedically handicapped employees)"},{"key":"C","text":"Rs.1,800 p.m. - the full allowance received"},{"key":"D","text":"Rs.1,600 p.m. - the old capped exemption"}],"answer":"B","explanation":"The general transport-allowance exemption ended when standard deduction was introduced; the exam-era key (Rs.1,800) is outdated. Handicapped employees still get Rs.3,200 p.m.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Mr. X is entitled to transport allowance of Rs.1,800 p.m. for commuting between residence and office and spends Rs.1,400 p.m. The exemption allowed (current law) is:","options":["Rs.1,400 p.m.","NIL - the transport-allowance exemption was withdrawn from AY 2019-20 (it survives only as Rs.3,200 p.m. for blind/deaf/orthopedically handicapped employees)","Rs.1,800 p.m.","Rs.1,600 p.m."],"answer":1,"explanation":"The general transport-allowance exemption ended when standard deduction was introduced; the exam-era key (Rs.1,800) is outdated. Handicapped employees still get Rs.3,200 p.m.","revision":"original","contentSignature":"31f1b2cc7dff489a7526feab4dd2cf3d3555b2312a1eea5db1b6352cb47db689"}]},{"id":402,"stem":"As per Section 80G, the maximum deduction allowed for any CASH donation is up to:","options":[{"key":"A","text":"Rs.5,000"},{"key":"B","text":"Rs.10,000"},{"key":"C","text":"Rs.2,000"},{"key":"D","text":"Rs.1,000"}],"answer":"C","explanation":"Cash donations above Rs.2,000 earn no 80G deduction; larger donations must be by cheque, draft or electronic mode.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":403,"stem":"Arrange the e-filing procedure for an income-tax return: I. Login II. Register III. Verification IV. Downloading utility and preparing return V. e-filing the return:","options":[{"key":"A","text":"II, I, V, IV, III"},{"key":"B","text":"II, I, IV, V, III"},{"key":"C","text":"I, III, II, V, IV"},{"key":"D","text":"I, II, III, IV, V"}],"answer":"B","explanation":"Register first, then login, download the utility and prepare the return, e-file it, and finally verify (e-verify).","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":404,"stem":"If the assessee is engaged in the business of growing and manufacturing TEA in India, the AGRICULTURAL income in that case is:","options":[{"key":"A","text":"60% of such business income"},{"key":"B","text":"75% of such business income"},{"key":"C","text":"25% of such business income"},{"key":"D","text":"40% of such business income"}],"answer":"A","explanation":"Rule 8: 60% of tea growing-and-manufacturing income is agricultural (exempt), 40% is business income. For coffee: 65%/75% agricultural by stage; rubber 65%.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":405,"stem":"AMT (Alternate Minimum Tax) provisions are applicable on:","options":[{"key":"A","text":"NON-CORPORATE assessees"},{"key":"B","text":"HUF only"},{"key":"C","text":"Corporate assessees"},{"key":"D","text":"An individual only"}],"answer":"A","explanation":"Section 115JC AMT applies to non-corporates claiming specified incentives; companies face MAT under 115JB instead.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":406,"stem":"X, an employee of a PRIVATE company, gets Rs.30,000 p.m. basic salary and Rs.1,500 p.m. entertainment allowance. The deduction u/s 16(ii) for entertainment allowance is:","options":[{"key":"A","text":"Rs.5,000 - the 16(ii) deduction is available to private employees up to this cap"},{"key":"B","text":"NIL - the 16(ii) deduction is available ONLY to GOVERNMENT employees"},{"key":"C","text":"Rs.72,000 - the full years entertainment allowance is deductible"},{"key":"D","text":"Rs.18,000 - one-fifth of basic salary is deductible"}],"answer":"B","explanation":"Entertainment-allowance deduction (least of Rs.5,000, 20% of salary, actual) is exclusively for government employees; private employees get no deduction.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"X, an employee of a PRIVATE company, gets Rs.30,000 p.m. basic salary and Rs.1,500 p.m. entertainment allowance. The deduction u/s 16(ii) for entertainment allowance is:","options":["Rs.5,000","NIL - the 16(ii) deduction is available ONLY to GOVERNMENT employees","Rs.72,000","Rs.18,000"],"answer":1,"explanation":"Entertainment-allowance deduction (least of Rs.5,000, 20% of salary, actual) is exclusively for government employees; private employees get no deduction.","revision":"original","contentSignature":"29c848806f57574a38ea3e5eeae8c4ebc1f3f7775f45b57073ab169365446883"}]},{"id":407,"stem":"Which of the following persons CANNOT use ITR-4 (Sugam)? 1. A director of a company 2. One who has held unlisted equity shares 3. One who has assets located outside India 4. A resident firm (other than LLP) 5. One having income from other sources:","options":[{"key":"A","text":"2, 4 and 5 only"},{"key":"B","text":"1, 2 and 4 only"},{"key":"C","text":"3, 4 and 5 only"},{"key":"D","text":"1, 2 and 3 only"}],"answer":"D","explanation":"Directors, unlisted-share holders and foreign-asset holders are barred from ITR-4 (and ITR-1); a resident non-LLP firm CAN use ITR-4 for presumptive income, and other-sources income is permitted.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":408,"stem":"A, a resident aged 60, earned agricultural income of Rs.5,00,000 and non-agricultural income of Rs.3,00,000 (PY 2019-20). His tax liability is:","options":[{"key":"A","text":"Rs.2,000"},{"key":"B","text":"NIL"},{"key":"C","text":"Rs.72,100"},{"key":"D","text":"Rs.72,000"}],"answer":"B","explanation":"Partial integration: tax on (agri + non-agri = 8L) at senior-citizen rates = 70,000; tax on (agri + basic exemption 3L = 8L) = 70,000. Difference = NIL. Agricultural income only raises the rate, never the base.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":409,"stem":"The due date of the FIRST instalment of advance tax (for all assessees) is:","options":[{"key":"A","text":"15 September"},{"key":"B","text":"15 April"},{"key":"C","text":"15 June"},{"key":"D","text":"15 December"}],"answer":"C","explanation":"Instalments: 15% by 15 June, 45% by 15 September, 75% by 15 December, 100% by 15 March.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":410,"stem":"Match: (a) Section 10(1) (b) Section 10(10C) (c) Section 10(13A) (d) Section 10(10AA) with: (i) Voluntary retirement compensation (ii) Agricultural income (iii) Leave encashment (iv) House rent allowance:","options":[{"key":"A","text":"a-ii, b-i, c-iii, d-iv"},{"key":"B","text":"a-ii, b-i, c-iv, d-iii"},{"key":"C","text":"a-iv, b-ii, c-i, d-iii"},{"key":"D","text":"a-iv, b-iii, c-i, d-ii"}],"answer":"B","explanation":"10(1)-agricultural income; 10(10C)-VRS compensation (up to Rs.5 lakh); 10(13A)-HRA; 10(10AA)-leave encashment.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":411,"stem":"Statement I: An assessee is always a person, but a person may or may not be an assessee. Statement II: \"Person\" includes an individual, HUF, company, firm, AOP/BOI, local authority and every artificial juridical person:","options":[{"key":"A","text":"Both statements are correct"},{"key":"B","text":"Only I is correct"},{"key":"C","text":"Only II is correct"},{"key":"D","text":"Both are incorrect"}],"answer":"A","explanation":"Section 2(7) defines assessee as a person by whom tax or any other sum is payable (etc.) - so every assessee is a person; s.2(31) lists the seven person categories.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":412,"stem":"Residential status under the Indian Income-tax Act is determined for which period?","options":[{"key":"A","text":"The assessment year"},{"key":"B","text":"Both previous and assessment years"},{"key":"C","text":"The PREVIOUS YEAR"},{"key":"D","text":"The accounting year"}],"answer":"C","explanation":"Residential status is always determined with reference to each previous year (s.6); it can differ from year to year.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":413,"stem":"Which losses are allowed to be CARRIED FORWARD and set off in subsequent assessment years? (a) House property loss (b) Business loss (c) Speculation loss (d) Capital loss (e) Loss from owning and maintaining race horses:","options":[{"key":"A","text":"b, c, d and e only - a can never be carried forward"},{"key":"B","text":"a, b, c, d AND e - ALL are carry-forwardable"},{"key":"C","text":"a, b, c and d only - e can never be carried forward"},{"key":"D","text":"a and e only - b, c and d can never be carried forward"}],"answer":"B","explanation":"All five carry forward (subject to conditions): HP loss 8 years (71B), business loss 8 years (72), speculation loss 4 years (73), capital loss 8 years (74), race-horse loss 4 years (74A). The printed key omitting (a) is wrong.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which losses are allowed to be CARRIED FORWARD and set off in subsequent assessment years? (a) House property loss (b) Business loss (c) Speculation loss (d) Capital loss (e) Loss from owning and maintaining race horses:","options":["b, c, d, e only","a, b, c, d AND e - ALL are carry-forwardable","a, b, c, d only","a, e only"],"answer":1,"explanation":"All five carry forward (subject to conditions): HP loss 8 years (71B), business loss 8 years (72), speculation loss 4 years (73), capital loss 8 years (74), race-horse loss 4 years (74A). The printed key omitting (a) is wrong.","revision":"original","contentSignature":"64388cd498b0e4bfe91e3dc4a53fce408738ec4e58671db072ab7a85fe7e2422"}]},{"id":414,"stem":"Presumptive taxation involves:","options":[{"key":"A","text":"Use of INDIRECT METHODS to calculate tax liability, differing from accounts-based computation"},{"key":"B","text":"Transfer of tax liability from the State to the Centre, differing from accounts-based computation in every respect"},{"key":"C","text":"Calculation of the rebate under Section 89, differing from accounts-based computation in every respect"},{"key":"D","text":"Calculation of short-term capital gains, differing from accounts-based computation in every respect"}],"answer":"A","explanation":"Presumptive schemes (44AD/44ADA/44AE etc.) deem income as a fixed percentage of turnover/receipts, bypassing regular books.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Presumptive taxation involves:","options":["Use of INDIRECT METHODS to calculate tax liability, differing from accounts-based computation","Transfer of tax liability from State to Centre","Calculation of rebate u/s 89","Calculation of short-term capital gains"],"answer":0,"explanation":"Presumptive schemes (44AD/44ADA/44AE etc.) deem income as a fixed percentage of turnover/receipts, bypassing regular books.","revision":"original","contentSignature":"e148bf8786051f7b6c05bfac5f5ffb2a37f79d3a39e1860a7e9f606d4f755d72"}]},{"id":415,"stem":"Arm length price computation methods under Section 92C do NOT include which of the following?","options":[{"key":"A","text":"Transaction net margin method"},{"key":"B","text":"Comparable uncontrolled price method"},{"key":"C","text":"Resale price method"},{"key":"D","text":"SLUMP SALE price method"}],"answer":"D","explanation":"92C lists CUP, resale price, cost plus, profit split, transactional net margin, and any other prescribed method - there is no \"slump sale price method\".","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":416,"stem":"\"Tax holiday\" under the Income-tax Act has been used in the context of which section?","options":[{"key":"A","text":"Section 80D"},{"key":"B","text":"Section 80CCC"},{"key":"C","text":"Section 80-IA"},{"key":"D","text":"Section 10(5)"}],"answer":"C","explanation":"Tax holidays are the profit-linked deductions of ss.80-IA/80-IB/80-IC etc. for infrastructure and specified businesses (largely sunset now).","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":417,"stem":"Rates of income tax under the NEW REGIME applicable for FY 2021-22 included: (a) 5% (b) 10% (c) 12% (d) 15% (e) 20%:","options":[{"key":"A","text":"a, b, d only"},{"key":"B","text":"a, b, c only"},{"key":"C","text":"a, b, d, e only"},{"key":"D","text":"b, c, d, e only"}],"answer":"C","explanation":"The 115BAC ladder runs 5/10/15/20/25/30 - there is no 12% slab (and the FY 2025-26 ladder now runs 5/10/15/20/25/30 with a Rs.4L nil band).","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":418,"stem":"Which are included in \"Salary\" under Section 17(1)? A. Wages B. Any pension or annuity C. Any interest from Government securities D. Any gratuity E. Any advance of salary:","options":[{"key":"A","text":"A, B, C and D only"},{"key":"B","text":"A, B, D and E only"},{"key":"C","text":"A, B, C, D and E"},{"key":"D","text":"C and E only"}],"answer":"B","explanation":"Interest on Government securities is taxed under \"Income from other sources\", never as salary; all the others are within s.17(1).","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":419,"stem":"A is entitled to children education allowance of Rs.80 per month per child for THREE children (Rs.240 p.m.). The exemption is:","options":[{"key":"A","text":"Rs.300 per month"},{"key":"B","text":"Rs.160 per month"},{"key":"C","text":"Rs.240 per month"},{"key":"D","text":"Rs.200 per month"}],"answer":"D","explanation":"Exemption is Rs.100 p.m. per child up to a MAXIMUM OF TWO children = Rs.200 p.m.; the third child allowance is fully taxable.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":420,"stem":"The amount UNUTILISED in the Capital Gains Accounts Scheme (exemption claimed u/s 54) is treated as long-term capital gain in the previous year:","options":[{"key":"A","text":"In which 2 years expire from the date of TRANSFER"},{"key":"B","text":"In which 3 years expire from the date of deposit"},{"key":"C","text":"In which 2 years expire from the date of deposit"},{"key":"D","text":"In which 3 YEARS EXPIRE FROM THE DATE OF TRANSFER"}],"answer":"D","explanation":"The unutilised deposit becomes taxable when the 3-year window (2 years for purchase) from the original transfer lapses.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":421,"stem":"Under Section 80TTB, the benefit available to SENIOR CITIZENS on interest from deposits with banks, post offices or co-operative banks is up to:","options":[{"key":"A","text":"Rs.1,50,000"},{"key":"B","text":"Rs.1,00,000"},{"key":"C","text":"Rs.75,000"},{"key":"D","text":"Rs.50,000"}],"answer":"D","explanation":"80TTB: Rs.50,000 for resident senior citizens on all deposit interest (savings + FD); it replaces 80TTA for them.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":422,"stem":"The fee for LATE FILING of the income-tax return by an individual (current law, Section 234F) is up to a maximum of:","options":[{"key":"A","text":"Rs.5,000 - reduced to Rs.1,000 where total income does not exceed Rs.5 lakh"},{"key":"B","text":"10% of the gross total income of the year, with no reduction for smaller incomes"},{"key":"C","text":"2% of the tax liability of the year, with no reduction for smaller incomes"},{"key":"D","text":"A flat Rs.10,000, irrespective of the total income"}],"answer":"A","explanation":"Finance Act 2021 cut the 234F fee from Rs.10,000 to Rs.5,000 (Rs.1,000 for incomes up to Rs.5 lakh); the older Rs.10,000 key is outdated.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The fee for LATE FILING of the income-tax return by an individual (current law, Section 234F) is up to a maximum of:","options":["Rs.5,000 - reduced to Rs.1,000 where total income does not exceed Rs.5 lakh","10% of gross total income","2% of tax liability","Rs.10,000"],"answer":0,"explanation":"Finance Act 2021 cut the 234F fee from Rs.10,000 to Rs.5,000 (Rs.1,000 for incomes up to Rs.5 lakh); the older Rs.10,000 key is outdated.","revision":"original","contentSignature":"d13b0bc8629e9b49c014d272fd4626b906b814774da610f1856d947ca70aada3"}]},{"id":423,"stem":"Statement I: Long-term capital loss can be set off ONLY against long-term capital gains. Statement II: Long-term capital gains on listed equity above Rs.1 lakh are taxed at 10% WITH indexation and 20% WITHOUT indexation:","options":[{"key":"A","text":"Statement II CORRECT, Statement I INCORRECT - long-term capital loss can be set off against both long-term and short-term gains, and 112A gains were always 20% WITH indexation above Rs.1 lakh (unchanged even from FY 2024-25)"},{"key":"B","text":"Statement I CORRECT, Statement II INCORRECT - 112A gains were 10% WITHOUT indexation above Rs.1 lakh (now 12.5% above Rs.1.25 lakh from FY 2024-25)"},{"key":"C","text":"Both statements INCORRECT - the set-off rule and the 112A rate history are both exactly the reverse of what the statements assert"},{"key":"D","text":"Both statements CORRECT - the set-off rule and the 112A rate history are both exactly as the statements assert"}],"answer":"B","explanation":"LTCL is ring-fenced to LTCG; Statement II inverts the indexation position and is additionally outdated on rate and threshold.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Statement I: Long-term capital loss can be set off ONLY against long-term capital gains. Statement II: Long-term capital gains on listed equity above Rs.1 lakh are taxed at 10% WITH indexation and 20% WITHOUT indexation:","options":["Statement II correct, I incorrect","Statement I CORRECT, Statement II INCORRECT - 112A gains were 10% WITHOUT indexation above Rs.1 lakh (now 12.5% above Rs.1.25 lakh from FY 2024-25)","Both incorrect","Both correct"],"answer":1,"explanation":"LTCL is ring-fenced to LTCG; Statement II inverts the indexation position and is additionally outdated on rate and threshold.","revision":"original","contentSignature":"f3eed4f54a8552f2768e7baf60630bba8b3a0db7dc29cf45aad4d180f840fb77"}]},{"id":424,"stem":"Which is NOT correct for the Tonnage Tax Scheme?","options":[{"key":"A","text":"It applies to income from shipping activities"},{"key":"B","text":"It applies to BOTH Indian AND foreign companies"},{"key":"C","text":"Tonnage income computation is covered u/s 115VG"},{"key":"D","text":"It is a presumptive taxation scheme"}],"answer":"B","explanation":"Tonnage tax (ss.115V-115VZC) is available to QUALIFYING INDIAN COMPANIES operating qualifying ships - not foreign companies.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":425,"stem":"Which of the following is NOT related to income tax in India?","options":[{"key":"A","text":"Leave Travel Allowance (LTA)"},{"key":"B","text":"Dearness Allowance (DA)"},{"key":"C","text":"Taxpayer Identification Number (TIN)"},{"key":"D","text":"Tax Deduction and Collection Account Number (TAN)"}],"answer":"C","explanation":"TIN belonged to the state VAT system (now subsumed in GSTIN); DA and LTA are salary components, and TAN is the TDS/TCS account number under s.203A.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":426,"stem":"Match: (A) ITR-2 (B) ITR-6 (C) ITR-7 (D) ITR-4 (Sugam) with: (I) Companies other than those claiming exemption u/s 11 (II) Presumptive business income u/s 44AD/44ADA/44AE (III) Persons required to file u/s 139(4A)/(4B)/(4C)/(4D) (IV) Individuals/HUF without business or professional income:","options":[{"key":"A","text":"A-IV, B-I, C-III, D-II"},{"key":"B","text":"A-I, B-IV, C-II, D-III"},{"key":"C","text":"A-III, B-II, C-IV, D-I"},{"key":"D","text":"A-II, B-III, C-I, D-IV"}],"answer":"A","explanation":"ITR-2: individuals/HUF (no PGBP); ITR-4: presumptive; ITR-6: companies (not s.11-exempt); ITR-7: trusts/political parties/institutions under 139(4A)-(4D).","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":427,"stem":"X was appointed on 1 July 2022 as a university lecturer and continued up to 30 April 2023. The PREVIOUS YEAR for AY 2023-24 for his salary income is:","options":[{"key":"A","text":"1 July 2022 to 30 April 2023"},{"key":"B","text":"1 July 2022 to 31 March 2023"},{"key":"C","text":"1 April 2022 to 31 March 2023"},{"key":"D","text":"1 April 2022 to 30 April 2023"}],"answer":"B","explanation":"For a NEW source of income, the first previous year begins when the source comes into existence (1 July 2022) and ends on the immediately following 31 March (s.3).","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":428,"stem":"For AY 2025-26, Health and Education Cess is levied at:","options":[{"key":"A","text":"4% on income tax"},{"key":"B","text":"3% on income tax"},{"key":"C","text":"2% on income tax"},{"key":"D","text":"1% on income tax"}],"answer":"A","explanation":"4% cess on tax (plus surcharge) - unchanged since FY 2018-19.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":429,"stem":"Match TDS provisions: (A) Fees for professional/technical services (B) Payment of life-insurance policy (C) Winnings from lotteries/crossword puzzles (D) Interest other than on securities:","options":[{"key":"A","text":"A-194A, B-194B, C-194DA, D-194J"},{"key":"B","text":"A-194J, B-194DA, C-194B, D-194A"},{"key":"C","text":"A-194B, B-194J, C-194A, D-194DA"},{"key":"D","text":"A-194DA, B-194A, C-194J, D-194B"}],"answer":"B","explanation":"194J professional/technical fees; 194DA life-insurance payouts; 194B lottery/crossword winnings; 194A interest other than on securities.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":430,"stem":"Match: (A) Standard deduction u/s 16(ia) (B) Standard deduction u/s 24 (C) Depreciation u/s 32 (D) Exemption u/s 54 with heads: (I) Capital gains (II) PGBP (III) House property (IV) Salaries:","options":[{"key":"A","text":"A-IV, B-III, C-II, D-I"},{"key":"B","text":"A-I, B-II, C-III, D-IV"},{"key":"C","text":"A-II, B-I, C-IV, D-III"},{"key":"D","text":"A-III, B-IV, C-I, D-II"}],"answer":"A","explanation":"16(ia)-salaries (Rs.75,000 new regime / Rs.50,000 old); 24(a)-30% house property; 32-depreciation under PGBP; 54-residential-house rollover under capital gains.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":431,"stem":"Mr. A, resident aged 60, earned agricultural income Rs.5,00,000 and non-agricultural income Rs.3,80,000 (AY 2025-26), NOT opting for the old regime. His tax liability is:","options":[{"key":"A","text":"NIL"},{"key":"B","text":"Rs.3,640"},{"key":"C","text":"Rs.38,000"},{"key":"D","text":"Rs.8,000"}],"answer":"A","explanation":"Non-agricultural income (Rs.3.8L) is below the new-regime basic exemption (Rs.4L, FY 2024-25), so partial integration is not even triggered; tax is nil.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Explanation flagged: AY 2025-26 new-regime nil slab was ₹3 lakh, not ₹4 lakh. Rebate must be applied after partial integration; the NIL key may still be correct, but the given reasoning is not."},{"id":432,"stem":"Arm length price under Section 92F is the price applied or proposed to be applied when:","options":[{"key":"A","text":"Two RELATED persons transact in uncontrolled conditions"},{"key":"B","text":"Two unrelated persons transact in controlled conditions"},{"key":"C","text":"Two related persons transact in controlled conditions"},{"key":"D","text":"Two UNRELATED persons transact in UNCONTROLLED conditions"}],"answer":"D","explanation":"The ALP benchmarks a controlled (associated-enterprise) transaction against what unrelated parties would agree in uncontrolled conditions.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":433,"stem":"An assessee (other than one under 44AD/44ADA) must pay up to 75% of advance tax payable:","options":[{"key":"A","text":"On or before 15 June"},{"key":"B","text":"On or before 15 DECEMBER"},{"key":"C","text":"On or before 15 September"},{"key":"D","text":"On or before 15 March"}],"answer":"B","explanation":"The cumulative schedule: 15% by 15 June, 45% by 15 September, 75% by 15 December, 100% by 15 March.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":434,"stem":"Which statements are correct? A. If a company is an Indian company, it is automatically a domestic company. B. A foreign company means a company which is not a domestic company. C. An Indian company can be non-resident in India. D. A foreign company can never be resident in India:","options":[{"key":"A","text":"A and B only"},{"key":"B","text":"All four"},{"key":"C","text":"B and D only"},{"key":"D","text":"A, B and C only"}],"answer":"A","explanation":"An Indian company is always domestic and ALWAYS RESIDENT (s.6(3)); a foreign company CAN be resident if its POEM is in India - so C and D are false.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":435,"stem":"Which section deals with deduction for interest on deposits in SAVINGS ACCOUNTS (below-60 individuals/HUF)?","options":[{"key":"A","text":"Section 80TTA"},{"key":"B","text":"Section 80RRB"},{"key":"C","text":"Section 80U"},{"key":"D","text":"Section 80TTB"}],"answer":"A","explanation":"80TTA: up to Rs.10,000 savings interest for individuals/HUF below 60; 80TTB is the wider senior-citizen provision.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":436,"stem":"Exemption under Section 54EC (capital gains invested in specified bonds - NHAI/REC etc.) is capped at:","options":[{"key":"A","text":"Rs.10 LAKH in a financial year, with a 5-year lock-in"},{"key":"B","text":"Rs.1 CRORE in a financial year, with a 5-year lock-in"},{"key":"C","text":"Rs.25 LAKH in a financial year, with a 5-year lock-in"},{"key":"D","text":"Rs.50 LAKH in a financial year, with a 5-YEAR lock-in"}],"answer":"D","explanation":"54EC: investment within 6 months in notified bonds, maximum Rs.50 lakh, 5-year lock-in (earlier 3 years).","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Exemption under Section 54EC (capital gains invested in specified bonds - NHAI/REC etc.) is capped at:","options":["Rs.10 lakh","Rs.1 crore","Rs.25 lakh","Rs.50 LAKH in a financial year, with a 5-YEAR lock-in"],"answer":3,"explanation":"54EC: investment within 6 months in notified bonds, maximum Rs.50 lakh, 5-year lock-in (earlier 3 years).","revision":"original","contentSignature":"12207f0922a9a7e25f10e6d5163041bc8e99871504a9be1f189e3e798fe4d8b3"}]},{"id":437,"stem":"Relief for salary ARREARS or advance salary under Section 89(1) requires filing:","options":[{"key":"A","text":"FORM 10E - before claiming the relief in the return"},{"key":"B","text":"FORM 26AS - before claiming the relief in the return"},{"key":"C","text":"FORM 15G - before claiming the relief in the return"},{"key":"D","text":"FORM 16 - before claiming the relief in the return"}],"answer":"A","explanation":"Section 89 relief spreads arrears to the years they relate to; Form 10E must be furnished online, else the relief is denied in processing.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Relief for salary ARREARS or advance salary under Section 89(1) requires filing:","options":["FORM 10E - before claiming the relief in the return","Form 26AS","Form 15G","Form 16"],"answer":0,"explanation":"Section 89 relief spreads arrears to the years they relate to; Form 10E must be furnished online, else the relief is denied in processing.","revision":"original","contentSignature":"6ada5e20029e0f555935f76088b9c75a703283633b3befe40a0b87f407e87719"}]}];
